import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpRequestActionBuilder;

import java.net.URI;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.UUID;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
    private static final String ORIGIN = "http://127.0.0.1:8000";

    public ModelSimulation() {
        var accounts = List.<Map<String, Object>>of(
            Map.of("username", "bench-1"),
            Map.of("username", "bench-2")
        ).iterator();

        var users = scenario("Shop journey")
            .feed(accounts)
            .repeat(2).on(journey());

        setUp(users.injectOpen(atOnceUsers(2)))
            .protocols(http.baseUrl(baseUrl()).disableFollowRedirect().disableCaching());
    }

    private static String baseUrl() {
        String configured = System.getenv("BASE_URL");
        if (configured == null || configured.isBlank()) {
            return ORIGIN;
        }
        if (!configured.equals(ORIGIN) && !configured.equals(ORIGIN + "/")) {
            throw new IllegalArgumentException("BASE_URL must target " + ORIGIN);
        }
        return configured;
    }

    private static String loginLocation(String location) {
        URI target = URI.create(ORIGIN + "/v2/login").resolve(location);
        if (!"http".equalsIgnoreCase(target.getScheme())
            || !"127.0.0.1".equals(target.getHost())
            || target.getPort() != 8000
            || target.getRawUserInfo() != null) {
            throw new IllegalArgumentException("Login redirect must stay on the shop origin");
        }
        return target.toASCIIString();
    }

    private static boolean jsonObject(String body) {
        return body.stripLeading().startsWith("{");
    }

    private static ChainBuilder login() {
        return exec(flushCookieJar())
            .exec(s -> s.remove("csrf").remove("formCsrf").remove("preferredFormCsrf")
                .remove("loginStatus").remove("loginLocation"))
            .exec(http("Login form").get("/v2/login-form")
                .check(status().is(200),
                    css("input[type=hidden][name=csrf]", "value").saveAs("formCsrf"),
                    css("form[action='/v2/login'] input[type=hidden][name=csrf]", "value")
                        .optional().saveAs("preferredFormCsrf")))
            .exitHereIfFailed()
            .exec(s -> s.contains("preferredFormCsrf")
                ? s.set("formCsrf", s.getString("preferredFormCsrf")) : s)
            .exec(http("Log in").post("/v2/login").asJson()
                .body(StringBody("{\"username\":#{username.jsonStringify()},"
                    + "\"password\":\"bench\",\"csrf\":#{formCsrf.jsonStringify()}}"))
                .check(status().in(200, 302), status().saveAs("loginStatus"))
                .checkIf((r, s) -> r.status().code() == 200)
                    .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((r, s) -> r.status().code() == 302)
                    .then(header("Location").transform(ModelSimulation::loginLocation)
                        .saveAs("loginLocation"))
                .checkIf((r, s) -> r.status().code() == 302 && jsonObject(r.body().string()))
                    .then(jsonPath("$.csrf").optional().saveAs("csrf")))
            .exitHereIfFailed()
            .doIf(s -> s.getInt("loginStatus") == 302).then(
                exec(http("Follow login redirect").get("#{loginLocation}")
                    .check(status().is(200))
                    .checkIf((r, s) -> s.contains("csrf") && jsonObject(r.body().string()))
                        .then(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                    .checkIf((r, s) -> !s.contains("csrf"))
                        .then(jsonPath("$.csrf").saveAs("csrf")))
                    .exitHereIfFailed()
                    .exec(keepCsrf())
            );
    }

    private static ChainBuilder keepCsrf() {
        return exec(s -> s.contains("newCsrf")
            ? s.set("csrf", s.getString("newCsrf")).remove("newCsrf") : s);
    }

    private static ChainBuilder recoverSession() {
        return doIfOrElse(s -> "expired".equals(s.getString("opError")))
            .then(exec(http("Renew session").post("/v2/session/renew").asJson()
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .check(status().is(200), jsonPath("$.csrf").saveAs("csrf")))
                .exitHereIfFailed())
            .orElse(login())
            .doIf(s -> s.contains("cartId")).then(
                exec(s -> s.remove("newCsrf").remove("recoveredEtag"))
                    .exec(http("Recover cart").post("/v2/carts/#{cartId}/recover").asJson()
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}"))
                        .check(status().in(200, 204),
                            header("ETag").optional().saveAs("recoveredEtag"))
                        .checkIf((r, s) -> r.status().code() == 200 && jsonObject(r.body().string()))
                            .then(jsonPath("$.csrf").optional().saveAs("newCsrf")))
                    .exitHereIfFailed()
                    .exec(keepCsrf())
                    .exec(s -> s.contains("recoveredEtag")
                        ? s.set("cartEtag", s.getString("recoveredEtag")).remove("recoveredEtag")
                        : s)
            );
    }

    private static ChainBuilder authenticated(
        HttpRequestActionBuilder request, String recoveryFlag, Integer... terminalStatuses
    ) {
        Integer[] initialStatuses = Arrays.copyOf(terminalStatuses, terminalStatuses.length + 1);
        initialStatuses[terminalStatuses.length] = 401;

        return exec(s -> s.remove("newCsrf").remove("opStatus").remove("opError"))
            .exec(request
                .check(status().in(initialStatuses), status().saveAs("opStatus"))
                .checkIf((r, s) -> r.status().code() == 401)
                    .then(jsonPath("$.error").in("expired", "session").saveAs("opError"))
                .checkIf((r, s) -> r.status().code() == 401
                    && recoveryFlag != null && s.getBoolean(recoveryFlag))
                    .then(status().in(terminalStatuses)))
            .exitHereIfFailed()
            .doIf(s -> s.getInt("opStatus") == 401).then(
                exec(s -> recoveryFlag == null ? s : s.set(recoveryFlag, true))
                    .exec(recoverSession())
                    .exec(s -> s.remove("newCsrf").remove("opStatus").remove("opError"))
                    .exec(request.check(status().in(terminalStatuses), status().saveAs("opStatus")))
                    .exitHereIfFailed()
            )
            .exec(keepCsrf());
    }

    private static ChainBuilder readCart(String name) {
        return authenticated(http(name).get("/v2/carts/#{cartId}")
            .checkIf((r, s) -> r.status().code() == 200)
                .then(header("ETag").saveAs("cartEtag")), null, 200);
    }

    private static HttpRequestActionBuilder patchCart(String name) {
        return http(name).patch("/v2/carts/#{cartId}").asJson()
            .header("X-CSRF-Token", "#{csrf}")
            .header("If-Match", "#{cartEtag}")
            .body(StringBody("{\"quantity\":2}"))
            .checkIf((r, s) -> r.status().code() == 200 && jsonObject(r.body().string()))
                .then(jsonPath("$.csrf").optional().saveAs("newCsrf"));
    }

    private static ChainBuilder journey() {
        return exec(s -> s.remove("cartId").remove("cartEtag").remove("orderKey")
                .remove("orderId").remove("productId").remove("variantId").remove("newCsrf"))
            .exec(login())
            .exec(authenticated(http("Catalog").get("/v2/catalog")
                .checkIf((r, s) -> r.status().code() == 200)
                    .then(
                        jmesPath("data.products[?variants[?in_stock == `true`]] | [0].id")
                            .saveAs("productId"),
                        jmesPath("data.products[?variants[?in_stock == `true`]]"
                            + " | [0].variants[?in_stock == `true`] | [0].id")
                            .saveAs("variantId")), null, 200))
            .exec(authenticated(http("Create cart").post("/v2/carts").asJson()
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{\"product_id\":#{productId.jsonStringify()},"
                    + "\"variant_id\":#{variantId.jsonStringify()}}"))
                .checkIf((r, s) -> r.status().code() == 201)
                    .then(jsonPath("$.id").saveAs("cartId"), header("ETag").saveAs("cartEtag"),
                        jsonPath("$.csrf").optional().saveAs("newCsrf")), null, 201))
            .exec(s -> s.set("orderKey", UUID.randomUUID().toString())
                .set("patchRecovered", false))
            .exec(authenticated(patchCart("Update quantity"), "patchRecovered", 200, 204, 412))
            .doIf(s -> s.getInt("opStatus") == 412).then(
                readCart("Refresh cart after precondition failure")
                    .exec(authenticated(patchCart("Retry quantity update"), "patchRecovered", 200, 204))
            )
            .exec(readCart("Read cart for checkout"))
            .exec(authenticated(http("Commit order").post("/v2/orders").asJson()
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{orderKey}")
                .header("If-Match", "#{cartEtag}")
                .body(StringBody("{\"cart_id\":#{cartId.jsonStringify()}}"))
                .checkIf((r, s) -> r.status().code() == 201)
                    .then(jsonPath("$.accepted").ofBoolean().is(true),
                        jsonPath("$.id").saveAs("orderId"),
                        jsonPath("$.csrf").optional().saveAs("newCsrf")), null, 201));
    }
}

import http from 'k6/http';
import { check, fail } from 'k6';
import exec from 'k6/execution';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
if (BASE !== 'http://127.0.0.1:8000') {
  throw new Error('BASE_URL must be http://127.0.0.1:8000');
}

export const options = {
  scenarios: {
    shop: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '1m',
    },
  },
  noCookiesReset: false,
  thresholds: { checks: ['rate==1'] },
};

function requireCheck(name, condition) {
  if (!check(condition, { [name]: (value) => value === true })) fail(name);
}

function json(response) {
  try {
    return response.json() || {};
  } catch (_) {
    return {};
  }
}

function header(response, name) {
  const key = Object.keys(response.headers).find(
    (key) => key.toLowerCase() === name.toLowerCase()
  );
  return key ? response.headers[key] : '';
}

function pathFor(reference, source) {
  if (typeof reference !== 'string' || !reference.trim()) return null;
  let path = reference.trim().split('#')[0];
  if (path.startsWith(BASE + '/')) path = path.slice(BASE.length);
  if (path.startsWith('//') || path.includes('\\') ||
      /^[a-z][a-z0-9+.-]*:/i.test(path)) return null;

  const from = source.split('?')[0];
  if (path.startsWith('?')) path = from + path;
  if (!path.startsWith('/')) path = from.slice(0, from.lastIndexOf('/') + 1) + path;

  const queryAt = path.indexOf('?');
  const pathname = queryAt < 0 ? path : path.slice(0, queryAt);
  const query = queryAt < 0 ? '' : path.slice(queryAt);
  const segments = [];
  for (const segment of pathname.slice(1).split('/')) {
    if (segment === '..') segments.pop();
    else if (segment !== '.') segments.push(segment);
  }
  return '/' + segments.join('/') + query;
}

function request(method, path, payload, extraHeaders = {}) {
  const headers = { ...extraHeaders };
  if (payload !== undefined) headers['Content-Type'] = 'application/json';
  return http.request(
    method,
    BASE + path,
    payload === undefined ? null : JSON.stringify(payload),
    { headers, redirects: 0 }
  );
}

function successful(response) {
  return response.status >= 200 && response.status < 300;
}

function rememberCsrf(state, response) {
  const token = json(response).csrf;
  if (typeof token === 'string' && token.length > 0) state.csrf = token;
}

function hiddenCsrf(scope, values) {
  scope.find('input[name="csrf"]:not([disabled])').each((_, input) => {
    const type = (input.attr('type') || '').toLowerCase();
    const value = input.attr('value');
    if (type === 'hidden' && typeof value === 'string' && value.length > 0) {
      values.push(value);
    }
  });
}

function login(state) {
  const formPath = '/v2/login-form';
  const loginPath = '/v2/login';
  const page = request('GET', formPath);
  requireCheck('login form returned HTTP 200', page.status === 200);

  const document = page.html();
  const loginFields = [];
  const passwordFormFields = [];
  document.find('form').each((_, form) => {
    const action = pathFor(form.attr('action'), formPath);
    if (action && action.split('?')[0] === loginPath) {
      hiddenCsrf(form, loginFields);
    } else if (form.find('input[type="password"]').size() > 0) {
      hiddenCsrf(form, passwordFormFields);
    }
  });

  const candidates = loginFields.length > 0 ? loginFields : passwordFormFields;
  if (candidates.length === 0) hiddenCsrf(document, candidates);
  requireCheck('login form has one nonempty hidden csrf value', candidates.length === 1);

  state.csrf = '';
  let response = request('POST', loginPath, {
    username: state.username,
    password: 'bench',
    csrf: candidates[0],
  });
  if (response.status === 302) {
    rememberCsrf(state, response);
    const target = pathFor(header(response, 'Location'), loginPath);
    requireCheck('login redirect has a local Location', target !== null);
    response = request('GET', target);
  }

  requireCheck('login succeeded', response.status === 200);
  rememberCsrf(state, response);
  requireCheck('login supplied an authenticated CSRF token', state.csrf.length > 0);
}

function restoreSession(state, reason) {
  if (reason === 'expired') {
    const renewal = request('POST', '/v2/session/renew', {}, {
      'X-CSRF-Token': state.csrf,
    });
    if (renewal.status === 401 && json(renewal).error === 'session') {
      login(state);
    } else {
      requireCheck('expired session renewed', successful(renewal));
      rememberCsrf(state, renewal);
    }
  } else {
    login(state);
  }

  if (state.cartPath) {
    const recovered = request('POST', state.cartPath + '/recover', {}, {
      'X-CSRF-Token': state.csrf,
    });
    requireCheck('existing cart recovered', successful(recovered));
    rememberCsrf(state, recovered);
  }
}

function refreshETag(state, allowRecovery = true) {
  const response = authenticated(state, 'GET', state.cartPath, undefined, { allowRecovery });
  requireCheck('existing cart returned HTTP 200', response.status === 200);
  state.etag = header(response, 'ETag');
  requireCheck('existing cart supplied an ETag', state.etag.length > 0);
}

function authenticated(state, method, path, payload, config = {}) {
  let recovered = false;
  let reread = false;

  for (;;) {
    const headers = {};
    if (method !== 'GET') headers['X-CSRF-Token'] = state.csrf;
    if (config.ifMatch) headers['If-Match'] = state.etag;
    if (config.key) headers['Idempotency-Key'] = config.key;

    const response = request(method, path, payload, headers);
    if (response.status === 401 && config.allowRecovery !== false && !recovered) {
      const reason = json(response).error;
      if (reason === 'expired' || reason === 'session') {
        recovered = true;
        restoreSession(state, reason);
        if (config.ifMatch) refreshETag(state, false);
        continue;
      }
    }

    if (response.status === 412 && config.ifMatch && !reread) {
      reread = true;
      refreshETag(state);
      continue;
    }

    if (method !== 'GET' && successful(response)) rememberCsrf(state, response);
    return response;
  }
}

function hasId(value) {
  return (typeof value === 'string' && value.length > 0) || Number.isFinite(value);
}

function selectStock(state) {
  let path = '/v2/catalog';
  for (let page = 0; page < 3; page += 1) {
    const response = authenticated(state, 'GET', path);
    requireCheck('catalog returned HTTP 200', response.status === 200);

    const body = json(response);
    const data = body.data || {};
    const products = Array.isArray(data.products)
      ? data.products
      : [data.product || body.product || data];

    for (const product of products) {
      if (!product || !hasId(product.id) || !Array.isArray(product.variants)) continue;
      const variant = product.variants.find(
        (item) => item && item.in_stock === true && hasId(item.id)
      );
      if (variant) return { product_id: product.id, variant_id: variant.id };
    }

    if (!body.next || page === 2) break;
    path = pathFor(body.next, path);
    requireCheck('catalog next link is local', path !== null);
  }
  requireCheck('catalog supplied an in-stock variant', false);
}

export default function () {
  const state = {
    username: 'bench-' + exec.vu.idInTest,
    csrf: '',
    cartPath: '',
    etag: '',
  };

  login(state);
  const selection = selectStock(state);
  const created = authenticated(state, 'POST', '/v2/carts', selection);
  requireCheck('cart created with HTTP 201', created.status === 201);

  const cartId = json(created).id;
  requireCheck('cart creation supplied an ID', hasId(cartId));
  state.cartPath = '/v2/carts/' + encodeURIComponent(String(cartId));
  refreshETag(state);

  const updated = authenticated(state, 'PATCH', state.cartPath, { quantity: 1 }, {
    ifMatch: true,
  });
  requireCheck('cart quantity updated', successful(updated));
  state.etag = header(updated, 'ETag');
  if (!state.etag) refreshETag(state);

  const order = authenticated(state, 'POST', '/v2/orders', { cart_id: cartId }, {
    key: 'shop-order-' + state.username + '-' + encodeURIComponent(String(cartId)),
    ifMatch: true,
  });
  const result = json(order);
  requireCheck('order committed with HTTP 201 and accepted true',
    order.status === 201 && result.accepted === true && hasId(result.id));
}

import os
from html.parser import HTMLParser
from urllib.parse import quote, urljoin, urlsplit, urlunsplit
from uuid import uuid4

from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


ORIGIN = "http://127.0.0.1:8000"
BASE_URL = os.environ.get("BASE_URL", ORIGIN).rstrip("/")
if BASE_URL != ORIGIN:
    raise ValueError("BASE_URL must be http://127.0.0.1:8000")

USERS = 2
ITERATIONS = 2


class JourneyFailed(Exception):
    pass


def local_url(reference, base=BASE_URL + "/"):
    if not isinstance(reference, str) or not reference.strip():
        raise ValueError("Missing URL")
    url = urlsplit(urljoin(base, reference.strip()))
    if (url.scheme, url.netloc) != ("http", "127.0.0.1:8000"):
        raise ValueError("URL is outside the shop origin")
    return urlunsplit((url.scheme, url.netloc, url.path or "/", url.query, ""))


class LoginForm(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = {}
        self.form = None
        self.inputs = []
        self.template_depth = 0

    def handle_starttag(self, tag, attrs):
        if tag == "template":
            self.template_depth += 1
        if self.template_depth:
            return
        attrs = dict(attrs)
        if tag == "form":
            self.form = attrs
            if attrs.get("id"):
                self.forms.setdefault(attrs["id"], attrs)
        elif (
            tag == "input"
            and attrs.get("name") == "csrf"
            and (attrs.get("type") or "").strip().lower() == "hidden"
            and "disabled" not in attrs
            and (attrs.get("value") or "").strip()
        ):
            self.inputs.append((attrs, self.form))

    def handle_endtag(self, tag):
        if tag == "template" and self.template_depth:
            self.template_depth -= 1
        elif not self.template_depth and tag == "form":
            self.form = None

    def token(self, page_url):
        candidates = []
        for attrs, owner in self.inputs:
            if "form" in attrs:
                owner = self.forms.get(attrs["form"])
            score = 1
            if owner is not None:
                action = (owner.get("action") or "").strip()
                post = (owner.get("method") or "").strip().lower() == "post"
                if action:
                    try:
                        target = urlsplit(local_url(action, page_url))
                        login_action = target.path.rstrip("/") == "/v2/login"
                    except ValueError:
                        login_action = False
                    score = 4 + int(post) if login_action else 0
                else:
                    score = 2 + int(post)
            candidates.append((score, attrs["value"]))
        if not candidates:
            raise ValueError("Login form has no enabled hidden csrf input")
        best = max(score for score, _ in candidates)
        values = {value for score, value in candidates if score == best}
        if len(values) != 1:
            raise ValueError("Login form has ambiguous hidden csrf inputs")
        return values.pop()


def form_token(response):
    parser = LoginForm()
    parser.feed(response.text)
    parser.close()
    return parser.token(response.url)


def json_object(response):
    data = response.json()
    if not isinstance(data, dict):
        raise ValueError("Expected a JSON object")
    return data


def optional_object(response):
    return json_object(response) if response.content.strip() else {}


def required_csrf(data):
    value = data.get("csrf")
    if not isinstance(value, str) or not value.strip():
        raise ValueError("Missing or invalid response csrf")
    return value


def login_result(response):
    if response.status_code == 302:
        return local_url(response.headers.get("Location"), response.url)
    data = json_object(response)
    required_csrf(data)
    return data


def valid_id(value):
    return type(value) is int or (isinstance(value, str) and bool(value.strip()))


def stocked_item(response):
    data = json_object(response).get("data")
    products = data.get("products") if isinstance(data, dict) else None
    if not isinstance(products, list):
        raise ValueError("Catalog is missing its products list")
    for product in products:
        if not isinstance(product, dict) or not valid_id(product.get("id")):
            continue
        variants = product.get("variants")
        if not isinstance(variants, list):
            continue
        for variant in variants:
            if (
                isinstance(variant, dict)
                and variant.get("in_stock") is True
                and valid_id(variant.get("id"))
            ):
                return product["id"], variant["id"]
    raise ValueError("Catalog contains no in-stock variant with an ID")


def response_etag(response):
    value = response.headers.get("ETag")
    if not value:
        raise ValueError("Cart response is missing ETag")
    return value


def created_cart(response):
    data = json_object(response)
    if not valid_id(data.get("id")):
        raise ValueError("Created cart has no ID")
    response_etag(response)
    return data


def accepted_order(response):
    data = json_object(response)
    if data.get("accepted") is not True or not valid_id(data.get("id")):
        raise ValueError("Order was not accepted with an ID")
    return data


class ShopUser(HttpUser):
    host = BASE_URL

    def on_start(self):
        number = getattr(self.environment, "shop_started", 0) + 1
        self.environment.shop_started = number
        self.username = f"bench-{number}"
        self.iterations = 0

    def on_stop(self):
        if self.iterations == ITERATIONS:
            self.environment.shop_finished = (
                getattr(self.environment, "shop_finished", 0) + 1
            )

    def request(
        self,
        method,
        path,
        *,
        name,
        body=None,
        auth=True,
        statuses=(200,),
        decode=json_object,
        recover=True,
        match=False,
        retry_stale=False,
        idempotency_key=None,
    ):
        url = local_url(path)
        recovered = False
        reread = False
        while True:
            headers = {}
            if auth and method != "GET":
                headers["X-CSRF-Token"] = self.csrf
            if match and self.etag:
                headers["If-Match"] = self.etag
            if idempotency_key is not None:
                headers["Idempotency-Key"] = idempotency_key

            retry = None
            with self.client.request(
                method,
                url,
                name=name,
                json=body,
                headers=headers,
                allow_redirects=False,
                timeout=5,
                catch_response=True,
            ) as response:
                status = response.status_code
                if status == 401 and auth and recover and not recovered:
                    try:
                        error = json_object(response).get("error")
                    except ValueError:
                        error = None
                    if error in ("expired", "session"):
                        retry = error
                elif status == 412 and retry_stale and not reread:
                    retry = "stale"

                if retry is not None:
                    response.success()
                elif status not in statuses:
                    response.failure(f"{method} {name}: unexpected HTTP {status}")
                else:
                    try:
                        data = decode(response)
                        if auth and method != "GET" and "csrf" in data:
                            self.csrf = required_csrf(data)
                    except ValueError as exc:
                        response.failure(str(exc))
                    else:
                        response.success()
                        return data, response.headers

            if retry == "stale":
                reread = True
                self.read_cart()
            elif retry in ("expired", "session"):
                recovered = True
                self.recover_session(retry)
            else:
                raise JourneyFailed()

    def login(self):
        self.client.cookies.clear()
        self.csrf = None
        token, _ = self.request(
            "GET", "/v2/login-form", name="/v2/login-form",
            auth=False, decode=form_token,
        )
        result, _ = self.request(
            "POST", "/v2/login", name="/v2/login", auth=False,
            body={"username": self.username, "password": "bench", "csrf": token},
            statuses=(200, 302), decode=login_result,
        )
        if isinstance(result, str):
            result, _ = self.request(
                "GET", result, name="/v2/login [redirect]",
                auth=False, decode=login_result,
            )
        self.csrf = result["csrf"]

    def cart_path(self):
        return "/v2/carts/" + quote(str(self.cart_id), safe="")

    def read_cart(self):
        self.etag, _ = self.request(
            "GET", self.cart_path(), name="/v2/carts/{id}", decode=response_etag,
        )

    def recover_session(self, error):
        if error == "session":
            self.login()
        else:
            def renewed(response):
                data = json_object(response)
                required_csrf(data)
                return data

            self.request(
                "POST", "/v2/session/renew", name="/v2/session/renew",
                body={}, recover=False, decode=renewed,
            )
        if self.cart_id is not None:
            _, headers = self.request(
                "POST", self.cart_path() + "/recover", name="/v2/carts/{id}/recover",
                body={}, statuses=(200, 204), decode=optional_object, recover=False,
            )
            self.etag = headers.get("ETag") or self.etag

    def journey(self):
        self.cart_id = None
        self.etag = None
        self.login()

        (product_id, variant_id), _ = self.request(
            "GET", "/v2/catalog", name="/v2/catalog", decode=stocked_item,
        )
        cart, headers = self.request(
            "POST", "/v2/carts", name="/v2/carts",
            body={"product_id": product_id, "variant_id": variant_id},
            statuses=(201,), decode=created_cart,
        )
        self.cart_id = cart["id"]
        self.etag = headers["ETag"]

        self.read_cart()
        _, headers = self.request(
            "PATCH", self.cart_path(), name="/v2/carts/{id}",
            body={"quantity": 2}, statuses=(200, 204), decode=optional_object,
            match=True, retry_stale=True,
        )
        self.etag = headers.get("ETag")
        if not self.etag:
            self.read_cart()

        self.request(
            "POST", "/v2/orders", name="/v2/orders",
            body={"cart_id": self.cart_id}, statuses=(201,), decode=accepted_order,
            match=True, idempotency_key=uuid4().hex,
        )

    @task
    def shop(self):
        if self.iterations >= ITERATIONS:
            raise StopUser()
        self.iterations += 1
        try:
            self.journey()
        except JourneyFailed:
            pass
        if self.iterations == ITERATIONS:
            raise StopUser()


class ShopShape(LoadTestShape):
    def tick(self):
        if getattr(self.runner.environment, "shop_finished", 0) >= USERS:
            return None
        if self.get_run_time() >= 45:
            return None
        return USERS, USERS

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.net.URI;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicInteger;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
    private static final String ORIGIN = "http://127.0.0.1:8000";
    private static final String CSRF_HEADER = "X-CSRF-Token";
    private static final String PICK =
        "data.products[].{product_id: id, variant_id: variants[?in_stock == `true`].id | [0]}"
        + " | [?product_id != `null` && variant_id != `null`] | [0]";

    private final AtomicInteger nextAccount = new AtomicInteger();

    private static String json(Object value) {
        if (value == null) {
            return "null";
        }
        if (value instanceof Number || value instanceof Boolean) {
            return value.toString();
        }
        String text = value.toString();
        StringBuilder out = new StringBuilder("\"");
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c == '"' || c == '\\') {
                out.append('\\').append(c);
            } else if (c < 0x20) {
                out.append("\\u00")
                    .append(Character.forDigit(c >>> 4, 16))
                    .append(Character.forDigit(c & 15, 16));
            } else {
                out.append(c);
            }
        }
        return out.append('"').toString();
    }

    private static String loginLocation(String location) {
        URI target = URI.create(ORIGIN + "/v2/login").resolve(location);
        if (!"http".equalsIgnoreCase(target.getScheme())
                || !"127.0.0.1".equals(target.getHost())
                || target.getPort() != 8000
                || target.getUserInfo() != null) {
            throw new IllegalArgumentException("Login redirect is not on the shop origin");
        }
        return target.toString();
    }

    private static ChainBuilder login() {
        return exec(flushCookieJar())
            .exec(s -> s.remove("formCsrf").remove("csrf").remove("loginLocation"))
            .exec(http("Login form").get("/v2/login-form")
                .check(status().is(200),
                    css("input[name='csrf'][value]", "value").saveAs("formCsrf")))
            .exitHereIfFailed()
            .exec(http("Login").post("/v2/login").asJson()
                .body(StringBody(s -> "{\"username\":" + json(s.getString("account"))
                    + ",\"password\":\"bench\",\"csrf\":" + json(s.getString("formCsrf")) + "}"))
                .check(status().in(200, 302).saveAs("loginStatus"))
                .checkIf((response, session) -> response.status().code() == 200)
                    .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((response, session) -> response.status().code() == 302)
                    .then(header("Location").transform(ModelSimulation::loginLocation)
                        .saveAs("loginLocation")))
            .exitHereIfFailed()
            .doIf(s -> s.getInt("loginStatus") == 302).then(
                exec(http("Follow login location").get("#{loginLocation}")
                    .check(status().is(200), jsonPath("$.csrf").saveAs("csrf")))
                    .exitHereIfFailed()
            );
    }

    private static ChainBuilder renew() {
        return exec(http("Renew session").post("/v2/session/renew").asJson()
                .header(CSRF_HEADER, "#{csrf}").body(StringBody("{}"))
                .check(status().in(200, 401).saveAs("renewStatus"))
                .checkIf((response, session) -> response.status().code() == 200)
                    .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((response, session) -> response.status().code() == 401)
                    .then(jsonPath("$.error").is("session")))
            .exitHereIfFailed()
            .doIf(s -> s.getInt("renewStatus") == 401).then(login());
    }

    private static ChainBuilder restoreSession() {
        return doIfOrElse(s -> "session".equals(s.getString("authError")))
            .then(login())
            .orElse(renew())
            .doIf(s -> s.contains("cartPath")).then(
                exec(http("Recover existing cart").post("#{cartPath}/recover").asJson()
                    .header(CSRF_HEADER, "#{csrf}").body(StringBody("{}"))
                    .check(status().in(200, 204))
                    .checkIf((response, session) -> response.status().code() == 200)
                        .then(jsonPath("$.csrf").optional().saveAs("csrf")))
                    .exitHereIfFailed()
                    .exec(http("Read recovered cart version").get("#{cartPath}")
                        .check(status().is(200), header("ETag").saveAs("cartEtag")))
                    .exitHereIfFailed()
            );
    }

    private static ChainBuilder operation(
            HttpRequestActionBuilder request, int successStatus, CheckBuilder... successChecks) {
        return exec(request
                .check(status().in(successStatus, 401).saveAs("operationStatus"))
                .checkIf((response, session) -> response.status().code() == successStatus)
                    .then(successChecks)
                .checkIf((response, session) -> response.status().code() == 401)
                    .then(jsonPath("$.error").in("expired", "session").saveAs("authError")))
            .exitHereIfFailed()
            .doIf(s -> s.getInt("operationStatus") == 401).then(
                restoreSession(),
                exec(request.check(status().is(successStatus)).check(successChecks))
                    .exitHereIfFailed()
            );
    }

    private static ChainBuilder journey() {
        return exec(s -> s.remove("selection").remove("cart").remove("cartPath")
                .remove("cartEtag").remove("orderKey").remove("authError"))
            .exec(login())
            .exec(operation(
                http("Select in-stock catalog variant").get("/v2/catalog"), 200,
                jmesPath(PICK).ofMap().exists().saveAs("selection")))
            .exec(operation(
                http("Create cart").post("/v2/carts").asJson()
                    .header(CSRF_HEADER, "#{csrf}")
                    .body(StringBody(s -> {
                        Map<?, ?> selection = s.getMap("selection");
                        return "{\"product_id\":" + json(selection.get("product_id"))
                            + ",\"variant_id\":" + json(selection.get("variant_id")) + "}";
                    })),
                201,
                jmesPath("id != `null`").ofBoolean().is(true),
                jmesPath("{id: id}").ofMap().saveAs("cart"),
                header("ETag").saveAs("cartEtag"),
                jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(s -> {
                String cartId = String.valueOf(s.getMap("cart").get("id"));
                String segment = URLEncoder.encode(cartId, StandardCharsets.UTF_8)
                    .replace("+", "%20");
                return s.set("cartPath", "/v2/carts/" + segment)
                    .set("orderKey", UUID.randomUUID().toString());
            })
            .exec(operation(
                http("Commit order").post("/v2/orders").asJson()
                    .header(CSRF_HEADER, "#{csrf}")
                    .header("If-Match", "#{cartEtag}")
                    .header("Idempotency-Key", "#{orderKey}")
                    .body(StringBody(s -> "{\"cart_id\":" + json(s.getMap("cart").get("id")) + "}")),
                201,
                jsonPath("$.accepted").ofBoolean().is(true),
                jmesPath("id != `null`").ofBoolean().is(true),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    public ModelSimulation() {
        String configuredBase = System.getenv("BASE_URL");
        String baseUrl = ORIGIN.equals(configuredBase) ? configuredBase : ORIGIN;
        ScenarioBuilder shop = scenario("In-stock product checkout")
            .exec(s -> s.set("account", "bench-" + nextAccount.incrementAndGet()))
            .repeat(2).on(journey());

        setUp(shop.injectOpen(atOnceUsers(2)))
            .protocols(http.baseUrl(baseUrl).disableFollowRedirect());
    }
}

import http from 'k6/http';
import { check, fail } from 'k6';
import exec from 'k6/execution';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
    },
  },
  thresholds: { checks: ['rate==1'] },
};

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
if (BASE !== 'http://127.0.0.1:8000') {
  throw new Error('BASE_URL must be http://127.0.0.1:8000');
}

function requireCheck(name, condition) {
  if (!check(Boolean(condition), { [name]: (ok) => ok })) fail(name);
}

function json(response) {
  try {
    return response.json();
  } catch (_) {
    return null;
  }
}

function header(response, name) {
  const key = Object.keys(response.headers).find(
    (candidate) => candidate.toLowerCase() === name.toLowerCase()
  );
  return key === undefined ? undefined : response.headers[key];
}

function successful(response) {
  return response.status >= 200 && response.status < 300;
}

function retainCsrf(state, body) {
  if (body && typeof body.csrf === 'string' && body.csrf.length > 0) {
    state.csrf = body.csrf;
  }
}

function send(state, method, path, payload, authenticated = true, extraHeaders = {}) {
  const headers = { ...extraHeaders };
  if (method !== 'GET') {
    headers['Content-Type'] = 'application/json';
    if (authenticated) headers['X-CSRF-Token'] = state.csrf;
  }
  return http.request(
    method,
    BASE + path,
    payload === undefined ? null : JSON.stringify(payload),
    { headers, redirects: 0, jar: state.jar }
  );
}

function loginRedirectPath(location) {
  requireCheck('login redirect supplies a local Location',
    typeof location === 'string' && location.length > 0 &&
    !/[\s\\]/.test(location) &&
    (location.startsWith(BASE + '/') ||
      (!location.startsWith('//') && !/^[a-z][a-z0-9+.-]*:/i.test(location))));
  if (location.startsWith(BASE + '/')) return location.slice(BASE.length);
  if (location.startsWith('/')) return location;
  if (location.startsWith('?')) return '/v2/login' + location;
  return '/v2/' + location;
}

function login(state) {
  state.csrf = undefined;
  const form = send(state, 'GET', '/v2/login-form', undefined, false);
  requireCheck('login form loaded', form.status === 200);

  const csrf = form.html().find('input[name="csrf"]').first().attr('value');
  requireCheck('login form contains a CSRF value', typeof csrf === 'string' && csrf.length > 0);

  let response = send(state, 'POST', '/v2/login', {
    username: state.username,
    password: 'bench',
    csrf,
  }, false);

  if (response.status === 302) {
    retainCsrf(state, json(response));
    const path = loginRedirectPath(header(response, 'Location'));
    response = send(state, 'GET', path, undefined, false);
  }

  requireCheck('login succeeded', successful(response));
  retainCsrf(state, json(response));
  requireCheck('authenticated CSRF token received', Boolean(state.csrf));
}

function authenticatedOperation(state, operation) {
  let response = operation();
  let body = json(response);
  const error = body && body.error;

  if (response.status === 401 && (error === 'expired' || error === 'session')) {
    const renewal = send(state, 'POST', '/v2/session/renew', {});
    const renewalBody = json(renewal);
    if (successful(renewal)) {
      retainCsrf(state, renewalBody);
    } else if (error === 'session' ||
               (renewal.status === 401 && renewalBody && renewalBody.error === 'session')) {
      login(state);
    } else {
      requireCheck('expired session renewed', false);
    }

    if (state.cartId !== undefined) {
      const recovered = send(
        state, 'POST', '/v2/carts/' + encodeURIComponent(state.cartId) + '/recover', {}
      );
      requireCheck('existing cart recovered', successful(recovered));
      retainCsrf(state, json(recovered));
      state.etag = header(recovered, 'ETag') || state.etag;
    }

    response = operation();
    body = json(response);
  }

  if (successful(response)) retainCsrf(state, body);
  return { response, body };
}

function hasId(id) {
  return (typeof id === 'string' && id.length > 0) ||
    (typeof id === 'number' && Number.isFinite(id));
}

function selectInStock(products) {
  for (const product of products) {
    if (!product || !hasId(product.id) || !Array.isArray(product.variants)) continue;
    for (const variant of product.variants) {
      if (variant && variant.in_stock === true && hasId(variant.id)) {
        return { product_id: product.id, variant_id: variant.id };
      }
    }
  }
  return null;
}

export default function () {
  const state = {
    jar: new http.CookieJar(),
    username: 'bench-' + exec.vu.idInTest,
    csrf: undefined,
    cartId: undefined,
    etag: undefined,
  };
  login(state);

  const catalog = authenticatedOperation(state, () => send(state, 'GET', '/v2/catalog'));
  requireCheck('catalog loaded', catalog.response.status === 200);
  const products = catalog.body && catalog.body.data && catalog.body.data.products;
  requireCheck('catalog contains a product array', Array.isArray(products));

  const selection = selectInStock(products);
  requireCheck('selected an in-stock variant from its own parent', selection !== null);

  const cart = authenticatedOperation(state, () => send(state, 'POST', '/v2/carts', selection));
  requireCheck('cart created for the selected product and variant', cart.response.status === 201);
  requireCheck('cart creation returned an ID', cart.body && hasId(cart.body.id));
  state.cartId = cart.body.id;
  state.etag = header(cart.response, 'ETag');

  const orderPayload = { cart_id: state.cartId };
  const orderKey = `order-${exec.vu.idInTest}-${exec.vu.iterationInScenario}-${encodeURIComponent(state.cartId)}`;
  const order = authenticatedOperation(state, () => {
    const headers = { 'Idempotency-Key': orderKey };
    if (state.etag) headers['If-Match'] = state.etag;
    return send(state, 'POST', '/v2/orders', orderPayload, true, headers);
  });
  requireCheck('checkout committed one accepted order',
    order.response.status === 201 && order.body &&
    order.body.accepted === true && hasId(order.body.id));
}

import os
from html.parser import HTMLParser
from urllib.parse import quote, urljoin, urlsplit
from uuid import uuid4

from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
if BASE_URL != "http://127.0.0.1:8000":
    raise ValueError("BASE_URL must be http://127.0.0.1:8000")

USERS = 2
ITERATIONS = 2


class CheckFailed(Exception):
    pass


class JourneyFailed(Exception):
    pass


class LoginFormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.login_form = False
        self.tokens = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "form":
            try:
                action = urljoin(BASE_URL + "/v2/login-form", attrs.get("action") or "")
                self.login_form = urlsplit(action).path == "/v2/login"
            except ValueError:
                self.login_form = False
        elif tag == "input" and attrs.get("name") == "csrf" and "disabled" not in attrs:
            value = attrs.get("value")
            if value:
                hidden = (attrs.get("type") or "").lower() == "hidden"
                self.tokens.append(((self.login_form, hidden), value))

    def handle_endtag(self, tag):
        if tag == "form":
            self.login_form = False


def login_form_token(response, _):
    parser = LoginFormParser()
    parser.feed(response.text)
    parser.close()
    if not parser.tokens:
        raise CheckFailed("Login form has no usable input[name=csrf]")
    return max(parser.tokens, key=lambda entry: entry[0])[1]


def csrf_token(data, fallback=None):
    value = data.get("csrf", fallback) if isinstance(data, dict) else fallback
    if not isinstance(value, str) or not value:
        raise CheckFailed("Missing or invalid CSRF token")
    return value


def valid_id(value):
    return type(value) is int or (isinstance(value, str) and bool(value.strip()))


def select_pair(_, data):
    nested = data.get("data") if isinstance(data, dict) else None
    products = nested.get("products") if isinstance(nested, dict) else None
    if not isinstance(products, list):
        raise CheckFailed("Catalog is missing data.products")
    for product in products:
        if not isinstance(product, dict) or not valid_id(product.get("id")):
            continue
        variants = product.get("variants")
        if not isinstance(variants, list):
            continue
        for variant in variants:
            if (
                isinstance(variant, dict)
                and variant.get("in_stock") is True
                and valid_id(variant.get("id"))
            ):
                return product["id"], variant["id"]
    raise CheckFailed("No product has an in-stock variant with an ID")


def login_reply(response, data):
    if response.status_code == 200:
        return None, csrf_token(data)
    location = response.headers.get("Location")
    if not location:
        raise CheckFailed("Login redirect is missing Location")
    try:
        target = urlsplit(urljoin(BASE_URL + "/v2/login", location))
    except ValueError as exc:
        raise CheckFailed("Invalid login redirect Location") from exc
    if (target.scheme, target.netloc) != ("http", "127.0.0.1:8000"):
        raise CheckFailed("Login redirect leaves the shop origin")
    path = target.path or "/"
    if target.query:
        path += "?" + target.query
    return path, data.get("csrf") if isinstance(data, dict) else None


def cart_reply(response, data):
    if not isinstance(data, dict) or not valid_id(data.get("id")):
        raise CheckFailed("Cart creation did not return a cart ID")
    return data["id"], response.headers.get("ETag")


def order_reply(response, data):
    if not isinstance(data, dict) or data.get("accepted") is not True:
        raise CheckFailed("Checkout did not accept the order")
    if response.status_code != 201 or not valid_id(data.get("id")):
        raise CheckFailed("Checkout did not return a committed order ID with HTTP 201")
    return data["id"]


def read_etag(response, _):
    etag = response.headers.get("ETag")
    if not etag:
        raise CheckFailed("Cart read did not return an ETag")
    return etag


class ShopUser(HttpUser):
    host = BASE_URL

    def on_start(self):
        self.run_shape = self.environment.shape_class
        self.run_shape.started += 1
        self.username = f"bench-{self.run_shape.started}"
        self.iterations_started = 0

    def on_stop(self):
        self.run_shape.finished += 1

    def send(
        self, method, path, statuses, check, *, body=None, authenticated=False,
        headers_for_attempt=None, recover_on=(), name=None,
    ):
        headers = headers_for_attempt() if headers_for_attempt else {}
        if authenticated and method != "GET":
            headers["X-CSRF-Token"] = self.csrf
        with self.client.request(
            method,
            BASE_URL + path,
            json=body,
            headers=headers,
            name=name or path,
            allow_redirects=False,
            catch_response=True,
            timeout=8,
        ) as response:
            try:
                data = response.json()
            except ValueError:
                data = None
            error = data.get("error") if isinstance(data, dict) else None
            if response.status_code == 401 and error in recover_on:
                response.success()
                return None, error
            if response.status_code not in statuses:
                detail = f" ({error})" if isinstance(error, str) else ""
                response.failure(f"Unexpected HTTP {response.status_code}{detail}")
            else:
                try:
                    result = check(response, data)
                    if authenticated and method != "GET":
                        self.csrf = csrf_token(data, fallback=self.csrf)
                except CheckFailed as exc:
                    response.failure(str(exc))
                else:
                    response.success()
                    return result, None
        raise JourneyFailed()

    def login(self):
        form_token, _ = self.send("GET", "/v2/login-form", (200,), login_form_token)
        (location, token), _ = self.send(
            "POST", "/v2/login", (200, 302), login_reply,
            body={"username": self.username, "password": "bench", "csrf": form_token},
        )
        if location is not None:
            token, _ = self.send(
                "GET", location, (200,), lambda _, data: csrf_token(data, fallback=token),
                name="/v2/login [redirect]",
            )
        self.csrf = token

    def recover(self, reason):
        if reason == "expired":
            _, reason = self.send(
                "POST", "/v2/session/renew", (200,), lambda _, data: csrf_token(data),
                body={}, authenticated=True, recover_on=("session",),
            )
        if reason == "session":
            self.login()

        if self.cart_id is not None:
            path = "/v2/carts/" + quote(str(self.cart_id), safe="")
            recovered_etag, _ = self.send(
                "POST", path + "/recover", (200, 204),
                lambda response, _: response.headers.get("ETag"),
                body={}, authenticated=True, name="/v2/carts/{id}/recover",
            )
            if recovered_etag is None and self.cart_etag is not None:
                recovered_etag, _ = self.send(
                    "GET", path, (200,), read_etag, name="/v2/carts/{id}",
                )
            self.cart_etag = recovered_etag

    def operation(self, method, path, statuses, check, **kwargs):
        result, reason = self.send(
            method, path, statuses, check, authenticated=True,
            recover_on=("expired", "session"), **kwargs,
        )
        if reason is not None:
            self.recover(reason)
            result, _ = self.send(
                method, path, statuses, check, authenticated=True, **kwargs,
            )
        return result

    def checkout_headers(self, order_key):
        headers = {"Idempotency-Key": order_key}
        if self.cart_etag is not None:
            headers["If-Match"] = self.cart_etag
        return headers

    @task
    def journey(self):
        if self.iterations_started >= ITERATIONS:
            raise StopUser()
        self.iterations_started += 1
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        try:
            self.login()
            product_id, variant_id = self.operation(
                "GET", "/v2/catalog", (200,), select_pair,
            )
            self.cart_id, self.cart_etag = self.operation(
                "POST", "/v2/carts", (201,), cart_reply,
                body={"product_id": product_id, "variant_id": variant_id},
            )
            order_key = uuid4().hex
            self.operation(
                "POST", "/v2/orders", (200, 201), order_reply,
                body={"cart_id": self.cart_id},
                headers_for_attempt=lambda: self.checkout_headers(order_key),
            )
        except JourneyFailed:
            pass
        if self.iterations_started >= ITERATIONS:
            raise StopUser()


class CheckoutShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.started = 0
        self.finished = 0

    def tick(self):
        if self.finished >= USERS:
            return None
        return USERS, USERS

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpRequestActionBuilder;

import java.net.URI;
import java.util.function.Function;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
    private static final String BASE = baseUrl();
    private static final int MAX_PAGES = 3;
    private static final String PRODUCT_ID = "$.data.products[0].id";
    private static final String IN_STOCK_ID =
            "$.data.products[0].variants[?(@.in_stock == true)].id";

    private static String baseUrl() {
        String local = "http://127.0.0.1:8000";
        String configured = System.getenv("BASE_URL");
        if (configured == null || configured.isBlank()
                || configured.equals(local) || configured.equals(local + "/")) {
            return local;
        }
        throw new IllegalArgumentException("BASE_URL must target the local fixture");
    }

    private static String follow(String current, String link) {
        URI source = URI.create(current);
        // A query-only reference keeps the current path.
        URI target = source.resolve(link.startsWith("?") ? source.getRawPath() + link : link);
        if (!"http".equalsIgnoreCase(target.getScheme())
                || !"127.0.0.1".equals(target.getHost())
