                        jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    public ModelSimulation() {
        ChainBuilder journey = exec(s -> s.remove("productId").remove("variantId")
                        .remove("cartId").remove("cartEtag").remove("orderId").remove("orderKey"))
                .exec(login())
                .exec(findEligibleVariant())
                .exec(withRecovery(ModelSimulation::createCart, false))
                .exec(s -> s.set("orderKey", "checkout-" + s.getString("cartId")))
                .exec(withRecovery(ModelSimulation::placeOrder, true));

        setUp(scenario("Paginated checkout")
                .exec(s -> s.set("username", "bench-" + (1 + Math.floorMod(s.userId() - 1, 16))))
                .repeat(2).on(journey)
                .injectOpen(atOnceUsers(2)))
                .protocols(http.baseUrl(BASE).disableFollowRedirect());
    }
}

import http from 'k6/http';
import exec from 'k6/execution';
import { check, fail } from 'k6';

const ORIGIN = 'http://127.0.0.1:8000';
const BASE = (__ENV.BASE_URL || ORIGIN).replace(/\/+$/, '');
if (BASE !== ORIGIN) throw new Error('BASE_URL must be http://127.0.0.1:8000');

export const options = {
  maxRedirects: 0,
  scenarios: {
    pagination: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '1m',
    },
  },
};

function requireCheck(name, condition) {
  if (!check(Boolean(condition), { [name]: (passed) => passed })) fail(name);
}

function json(response) {
  try {
    return response.json();
  } catch (_) {
    return null;
  }
}

function header(response, name) {
  const key = Object.keys(response.headers).find(
    (candidate) => candidate.toLowerCase() === name.toLowerCase(),
  );
  return key === undefined ? undefined : response.headers[key];
}

function token(value) {
  return typeof value === 'string' && value.length > 0;
}

function validId(value) {
  return token(value) || (typeof value === 'number' && Number.isFinite(value));
}

function successful(response) {
  return response.status >= 200 && response.status < 300;
}

function linkedURL(current, value) {
  if (!token(value)) return null;
  let link = value.trim().split('#', 1)[0];
  if (!link || /[\x00-\x20\x7f\\]/.test(link)) return null;

  if (link.startsWith('//')) link = `http:${link}`;
  if (/^[a-z][a-z0-9+.-]*:/i.test(link)) {
    if (link === BASE) return `${BASE}/`;
    if (link.startsWith(`${BASE}/`)) return link;
    if (link.startsWith(`${BASE}?`)) return `${BASE}/${link.slice(BASE.length)}`;
    return null;
  }

  const currentPath = current.slice(BASE.length).split('?', 1)[0] || '/';
  if (link.startsWith('?')) return `${BASE}${currentPath}${link}`;

  const queryIndex = link.indexOf('?');
  const query = queryIndex < 0 ? '' : link.slice(queryIndex);
  const targetPath = queryIndex < 0 ? link : link.slice(0, queryIndex);
  const path = targetPath.startsWith('/')
    ? targetPath
    : currentPath.slice(0, currentPath.lastIndexOf('/') + 1) + targetPath;

  const segments = path.slice(1).split('/');
  const resolved = [];
  for (let i = 0; i < segments.length; i++) {
    const segment = segments[i];
    if (segment === '.' || segment === '..') {
      if (segment === '..') resolved.pop();
      if (i === segments.length - 1) resolved.push('');
    } else {
      resolved.push(segment);
    }
  }
  return `${BASE}/${resolved.join('/')}${query}`;
}

function send(method, url, payload, name, headers = {}) {
  return http.request(
    method,
    url,
    payload === undefined ? null : JSON.stringify(payload),
    {
      redirects: 0,
      timeout: '10s',
      headers: payload === undefined ? headers : {
        ...headers,
        'Content-Type': 'application/json',
      },
      tags: { name },
    },
  );
}

function readLoginCSRF(response, formURL) {
  const doc = response.html();
  const selector = 'input[name="csrf"][value]:not([disabled])';
  let best;
  let bestRank = -1;
  doc.find('form').each((_, form) => {
    const action = linkedURL(formURL, form.attr('action'));
    const rank = (action && action.split('?', 1)[0] === `${BASE}/v2/login` ? 4 : 0)
      + (form.find('input[type="password"]').size() > 0 ? 2 : 0)
      + (String(form.attr('method')).toLowerCase() === 'post' ? 1 : 0);
    form.find(selector).each((__, input) => {
      const value = input.attr('value');
      if (token(value) && rank > bestRank) {
        best = value;
        bestRank = rank;
      }
    });
  });
  if (token(best)) return best;
  doc.find(selector).each((_, input) => {
    const value = input.attr('value');
    if (!token(best) && token(value)) best = value;
  });
  return best;
}

function login(state) {
  const formURL = `${BASE}/v2/login-form`;
  const form = send('GET', formURL, undefined, 'GET /v2/login-form');
  requireCheck('login form returned HTTP 200', form.status === 200);
  const csrf = readLoginCSRF(form, formURL);
  requireCheck('login form contains a CSRF input value', token(csrf));

  const loginURL = `${BASE}/v2/login`;
  const response = send('POST', loginURL, {
    username: state.username,
    password: 'bench',
    csrf,
  }, 'POST /v2/login');

  requireCheck('login returned HTTP 200 or 302',
    response.status === 200 || response.status === 302);
  const posted = json(response);
  let authenticatedCSRF = posted && posted.csrf;
  if (response.status === 302) {
    const destination = linkedURL(loginURL, header(response, 'Location'));
    requireCheck('login redirect has a same-origin Location', destination !== null);
    const landed = send('GET', destination, undefined, 'GET login Location');
    requireCheck('login redirect destination succeeded', successful(landed));
    const body = json(landed);
    if (body && token(body.csrf)) authenticatedCSRF = body.csrf;
  }

  requireCheck('login supplied an authenticated CSRF token', token(authenticatedCSRF));
  state.csrf = authenticatedCSRF;
}

function rawAuthenticated(state, method, url, payload, name, extra = {}) {
  const headers = { ...extra };
  if (method !== 'GET') headers['X-CSRF-Token'] = state.csrf;
  const response = send(method, url, payload, name, headers);
  const body = json(response);
  if (method !== 'GET' && successful(response) && body && token(body.csrf)) {
    state.csrf = body.csrf;
  }
  return { response, body };
}

function authError(result) {
  return result.response.status === 401 && result.body ? result.body.error : null;
}

function repairSession(state, reason) {
  if (reason === 'session') {
    login(state);
  } else {
    const renewed = rawAuthenticated(
      state, 'POST', `${BASE}/v2/session/renew`, {}, 'POST /v2/session/renew',
    );
    if (authError(renewed) === 'session') {
      login(state);
    } else {
      requireCheck('expired session was renewed', successful(renewed.response));
    }
  }

  if (state.cartURL) {
    const recovered = rawAuthenticated(
      state, 'POST', `${state.cartURL}/recover`, {}, 'POST /v2/carts/:id/recover',
    );
    requireCheck('existing cart was recovered', successful(recovered.response));
    const etag = header(recovered.response, 'ETag');
    if (token(etag)) state.etag = etag;
  }
}

function authenticated(state, method, url, payload, name, makeHeaders, refresh) {
  let repaired = false;
  let refreshed = false;
  for (;;) {
    const result = rawAuthenticated(
      state, method, url, payload, name, makeHeaders ? makeHeaders() : {},
    );
    const reason = authError(result);
    if (!repaired && (reason === 'expired' || reason === 'session')) {
      repaired = true;
      repairSession(state, reason);
      continue;
    }
    if (!refreshed && refresh && result.response.status === 412) {
      refreshed = true;
      refresh();
      continue;
    }
    return result;
  }
}

function pageProducts(page) {
  if (!page || typeof page !== 'object') return [];
  const data = page.data;
  if (data && Array.isArray(data.products)) return data.products;
  if (Array.isArray(page.products)) return page.products;
  if (Array.isArray(data)) return data;
  const product = (data && data.product) || page.product || data || page;
  return Array.isArray(product.variants) ? [product] : [];
}

function findEligibleVariant(state) {
  let url = `${BASE}/v2/catalog/page`;
  const visited = Object.create(null);
  for (let pageNumber = 0; pageNumber < 3; pageNumber++) {
    requireCheck('catalog cursor does not revisit a page', !visited[url]);
    visited[url] = true;

    const { response, body } = authenticated(
      state, 'GET', url, undefined, 'GET /v2/catalog/page',
    );
    requireCheck('catalog page returned HTTP 200 with JSON',
      response.status === 200 && body !== null && typeof body === 'object');

    for (const product of pageProducts(body)) {
      if (!product || !validId(product.id) || !Array.isArray(product.variants)) continue;
      for (const variant of product.variants) {
        if (variant && variant.in_stock === true && validId(variant.id)) {
          return { product_id: product.id, variant_id: variant.id };
        }
      }
    }

    if (body.next === null || pageNumber === 2) break;
    const next = linkedURL(url, body.next);
    requireCheck('catalog next provides a usable same-origin cursor', next !== null);
    url = next;
  }
  requireCheck('an eligible variant was found within three catalog pages', false);
}

function refreshCartETag(state) {
  const { response } = authenticated(
    state, 'GET', state.cartURL, undefined, 'GET /v2/carts/:id',
  );
  requireCheck('cart read returned HTTP 200', response.status === 200);
  const etag = header(response, 'ETag');
  requireCheck('cart read supplied an ETag', token(etag));
  state.etag = etag;
}

export default function () {
  const state = { username: `bench-${exec.vu.idInTest}` };
  login(state);
  const selection = findEligibleVariant(state);

  const created = authenticated(state, 'POST', `${BASE}/v2/carts`, selection, 'POST /v2/carts');
  requireCheck('cart creation returned HTTP 201', created.response.status === 201);
  requireCheck('cart creation supplied a cart ID', created.body && validId(created.body.id));
  const cartId = created.body.id;
  state.cartURL = `${BASE}/v2/carts/${encodeURIComponent(String(cartId))}`;
  state.etag = header(created.response, 'ETag');
  if (!token(state.etag)) refreshCartETag(state);

  const refresh = () => refreshCartETag(state);
  const patched = authenticated(
    state, 'PATCH', state.cartURL, { quantity: 2 }, 'PATCH /v2/carts/:id',
    () => ({ 'If-Match': state.etag }), refresh,
  );
  requireCheck('cart quantity update succeeded', successful(patched.response));
  const updatedETag = header(patched.response, 'ETag');
  if (token(updatedETag)) state.etag = updatedETag;
  else refresh();

  const key = `pagination-${state.username}-${exec.vu.iterationInScenario}-${encodeURIComponent(String(cartId))}`;
  const ordered = authenticated(
    state, 'POST', `${BASE}/v2/orders`, { cart_id: cartId }, 'POST /v2/orders',
    () => ({ 'Idempotency-Key': key, 'If-Match': state.etag }), refresh,
  );
  requireCheck('checkout returned HTTP 201 and accepted the order',
    ordered.response.status === 201 && ordered.body && ordered.body.accepted === true);
  requireCheck('accepted checkout supplied an order ID', validId(ordered.body.id));
  const orderId = ordered.body.id;
  return { cart_id: cartId, order_id: orderId };
}

import os
from html.parser import HTMLParser
from urllib.parse import quote, urldefrag, urljoin, urlsplit
from uuid import uuid4

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
if BASE_URL != "http://127.0.0.1:8000":
    raise ValueError("BASE_URL must be http://127.0.0.1:8000")

USERS = 2
ITERATIONS = 2
MAX_PAGES = 3
STALE = object()


class InvalidResponse(ValueError):
    pass


class JourneyFailed(Exception):
    pass


class Reauthenticate:
    def __init__(self, reason):
        self.reason = reason


def local_url(base, link):
    if not isinstance(link, str) or not link.strip():
        raise InvalidResponse("Missing URL")
    url = urldefrag(urljoin(base, link)).url
    parts = urlsplit(url)
    if parts.scheme != "http" or parts.netloc != "127.0.0.1:8000":
        raise InvalidResponse("URL points outside the shop")
    return url


def json_object(response):
    try:
        data = response.json()
    except ValueError as exc:
        raise InvalidResponse("Expected a JSON response") from exc
    if not isinstance(data, dict):
        raise InvalidResponse("Expected a JSON object")
    return data


def record_id(record, kind):
    value = record.get("id")
    if type(value) is int or (isinstance(value, str) and value.strip()):
        return value
    raise InvalidResponse(f"Missing or invalid {kind} ID")


class LoginForm(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.form = None
        self.forms = {}
        self.inputs = []
        self.template_depth = 0

    def handle_starttag(self, tag, attrs):
        if tag == "template":
            self.template_depth += 1
        if self.template_depth:
            return
        attrs = dict(attrs)
        if tag == "form":
            self.form = attrs
            if attrs.get("id"):
                self.forms[attrs["id"]] = attrs
        elif tag == "input" and attrs.get("name") == "csrf":
            kind = (attrs.get("type") or "").lower()
            if "disabled" not in attrs and kind not in (
                "submit", "button", "reset", "image", "file"
            ) and attrs.get("value"):
                self.inputs.append((attrs, self.form, kind))

    def handle_endtag(self, tag):
        if tag == "template" and self.template_depth:
            self.template_depth -= 1
        elif tag == "form" and not self.template_depth:
            self.form = None

    def token(self):
        candidates = []
        for attrs, enclosing_form, kind in self.inputs:
            form = self.forms.get(attrs["form"]) if attrs.get("form") else enclosing_form
            action = (form or {}).get("action") or ""
            method = ((form or {}).get("method") or "").lower()
            login_action = False
            if action:
                try:
                    target = local_url(BASE_URL + "/v2/login-form", action)
                    login_action = urlsplit(target).path == "/v2/login"
                except ValueError:
                    continue
            rank = (login_action, form is not None, method == "post", kind == "hidden")
            candidates.append((rank, attrs["value"]))
        if not candidates:
            raise InvalidResponse("Login form has no usable csrf input")
        best = max(rank for rank, _ in candidates)
        tokens = {value for rank, value in candidates if rank == best}
        if len(tokens) != 1:
            raise InvalidResponse("Login form has ambiguous csrf inputs")
        return tokens.pop()


class PaginationUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        number = getattr(self.environment, "_pagination_assigned", 0) + 1
        self.environment._pagination_assigned = number
        self.username = f"bench-{number}"
        self.iterations = 0

    def _raw(
        self, method, path, name, statuses, read, *, payload=None,
        authenticated=False, match=False, key=None, auth_errors=(), allow_stale=False
    ):
        url = local_url(BASE_URL + "/", path)
        headers = {}
        if authenticated and method != "GET":
            headers["X-CSRF-Token"] = self.csrf
        if match:
            headers["If-Match"] = self.etag
        if key is not None:
            headers["Idempotency-Key"] = key

        kwargs = {"json": payload} if payload is not None else {}
        with self.client.request(
            method, url, name=name, headers=headers, catch_response=True,
            allow_redirects=False, timeout=5, **kwargs
        ) as response:
            try:
                status = response.status_code
                if status == 401:
                    reason = json_object(response).get("error")
                    if reason in auth_errors:
                        response.success()
                        return Reauthenticate(reason)
                    raise InvalidResponse(f"Unrecoverable HTTP 401: {reason!r}")
                if status == 412 and allow_stale:
                    response.success()
                    return STALE
                if status not in statuses:
                    raise InvalidResponse(f"Expected HTTP {statuses}, got {status}")
                return read(response)
            except ValueError as exc:
                response.failure(str(exc))
        raise JourneyFailed()

    def _capture_csrf(self, data, required=False):
        if required or "csrf" in data:
            token = data.get("csrf")
            if not isinstance(token, str) or not token.strip():
                raise InvalidResponse("Missing or invalid csrf token")
            self.csrf = token

    def _read_login(self, response):
        self._capture_csrf(json_object(response), required=True)

    def _login(self):
        def read_form(response):
            parser = LoginForm()
            parser.feed(response.text)
            parser.close()
            return parser.token()

        form_token = self._raw(
            "GET", "/v2/login-form", "/v2/login-form", (200,), read_form
        )

        def read_login_post(response):
            if response.status_code == 302:
                return local_url(response.url, response.headers.get("Location"))
            self._read_login(response)
            return None

        location = self._raw(
            "POST", "/v2/login", "/v2/login", (200, 302), read_login_post,
            payload={"username": self.username, "password": "bench", "csrf": form_token},
        )
        if location is not None:
            self._raw("GET", location, "/v2/login redirect", (200,), self._read_login)

    def _mutation_etag(self, response):
        if response.content:
            self._capture_csrf(json_object(response))
        return response.headers.get("ETag")

    @staticmethod
    def _read_etag(response):
        etag = response.headers.get("ETag")
        if not etag:
            raise InvalidResponse("Cart read did not supply ETag")
        return etag

    def _restore_session(self, reason):
        if reason == "expired":
            result = self._raw(
                "POST", "/v2/session/renew", "/v2/session/renew", (200,),
                self._read_login, payload={}, authenticated=True, auth_errors=("session",),
            )
            if isinstance(result, Reauthenticate):
                self._login()
        else:
            self._login()

        if self.cart_id is not None:
            self.etag = self._raw(
                "POST", self.cart_path + "/recover", "/v2/carts/{id}/recover",
                (200, 204), self._mutation_etag, payload={}, authenticated=True,
            )

    def _authorized(
        self, method, path, name, statuses, read, *, payload=None, match=False,
        key=None, allow_stale=False, recovery=None
    ):
        if recovery is None:
            recovery = [False]

        def send(auth_errors):
            return self._raw(
                method, path, name, statuses, read, payload=payload,
                authenticated=True, match=match, key=key,
                auth_errors=auth_errors, allow_stale=allow_stale,
            )

        result = send(()) if recovery[0] else send(("expired", "session"))
        if not isinstance(result, Reauthenticate):
            return result

        recovery[0] = True
        self._restore_session(result.reason)
        if match and not self.etag:
            self._refresh_etag(recovery)
        return send(())

    def _refresh_etag(self, recovery=None):
        self.etag = self._authorized(
            "GET", self.cart_path, "/v2/carts/{id}", (200,), self._read_etag,
            recovery=recovery,
        )

    def _eligible_item(self):
        url = BASE_URL + "/v2/catalog/page"
        seen = set()
        for page_number in range(1, MAX_PAGES + 1):
            seen.add(url)

            def read_page(response):
                body = json_object(response)
                data = body.get("data", body)
                if not isinstance(data, dict):
                    raise InvalidResponse("Invalid catalog page data")
                products = data.get("products")
                if products is None and "product" in data:
                    products = [data["product"]]
                if products is None and "variants" in data:
                    products = [data]
                if not isinstance(products, list):
                    raise InvalidResponse("Catalog page did not supply products")

                for product in products:
                    if not isinstance(product, dict) or not isinstance(
                        product.get("variants"), list
                    ):
                        raise InvalidResponse("Invalid catalog product")
                    for variant in product["variants"]:
                        if not isinstance(variant, dict):
                            raise InvalidResponse("Invalid catalog variant")
                        if variant.get("in_stock") is True:
                            return (
                                record_id(product, "product"),
                                record_id(variant, "variant"),
                            ), None

                link = body.get("next")
                if link is None:
                    raise InvalidResponse("Catalog ended without an in-stock variant")
                if page_number == MAX_PAGES:
                    raise InvalidResponse("No in-stock variant within three catalog pages")
                next_url = local_url(response.url, link)
                if next_url in seen:
                    raise InvalidResponse("Catalog cursor repeated a page")
                return None, next_url

            item, url = self._authorized(
                "GET", url, "/v2/catalog/page", (200,), read_page
            )
            if item is not None:
                return item
        raise JourneyFailed()

    def _create_cart(self, product_id, variant_id):
        def read_cart(response):
            data = json_object(response)
            self._capture_csrf(data)
            return record_id(data, "cart"), response.headers.get("ETag")

        self.cart_id, self.etag = self._authorized(
            "POST", "/v2/carts", "/v2/carts", (201,), read_cart,
            payload={"product_id": product_id, "variant_id": variant_id},
        )
        self.cart_path = "/v2/carts/" + quote(str(self.cart_id), safe="")

    def _set_quantity(self):
        if not self.etag:
            self._refresh_etag()
        payload = {"quantity": 1}
        recovery = [False]
        result = self._authorized(
            "PATCH", self.cart_path, "/v2/carts/{id}", (200, 204),
            self._mutation_etag, payload=payload, match=True,
            allow_stale=True, recovery=recovery,
        )
        if result is STALE:
            self._refresh_etag(recovery)
            result = self._authorized(
                "PATCH", self.cart_path, "/v2/carts/{id}", (200, 204),
                self._mutation_etag, payload=payload, match=True, recovery=recovery,
            )
        self.etag = result

    def _commit_order(self):
        if not self.etag:
            self._refresh_etag()

        def read_order(response):
            data = json_object(response)
            if data.get("accepted") is not True:
                raise InvalidResponse("Order was not accepted")
            if response.status_code != 201:
                raise InvalidResponse("Accepted order did not return HTTP 201")
            order_id = record_id(data, "order")
            self._capture_csrf(data)
            return order_id

        self.order_id = self._authorized(
            "POST", "/v2/orders", "/v2/orders", (200, 201), read_order,
            payload={"cart_id": self.cart_id}, match=True, key=uuid4().hex,
        )

    @task
    def journey(self):
        if self.iterations >= ITERATIONS:
            raise StopUser()

        self.csrf = None
        self.cart_id = None
        self.cart_path = None
        self.order_id = None
        self.etag = None
        try:
            self._login()
            product_id, variant_id = self._eligible_item()
            self._create_cart(product_id, variant_id)
            self._set_quantity()
            self._commit_order()
        except JourneyFailed:
            pass
        finally:
            self.iterations += 1
            if self.iterations == ITERATIONS:
                env = self.environment
                env._pagination_finished = getattr(env, "_pagination_finished", 0) + 1

        if self.iterations == ITERATIONS:
            raise StopUser()


class PaginationShape(LoadTestShape):
    def tick(self):
        if getattr(self.runner.environment, "_pagination_finished", 0) >= USERS:
            return None
        if self.get_run_time() >= 60:
            return None
        return USERS, USERS

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpRequestActionBuilder;

import java.net.URI;
import java.util.Arrays;
import java.util.UUID;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
    private static final String SHOP = "http://127.0.0.1:8000";
    private static final String PATCH_BODY = "{\"quantity\":2}";
    private static final String AVAILABLE_PRODUCT =
        "data.products[?variants[?in_stock == `true`]] | [0]";
    private static final String CART_BODY = AVAILABLE_PRODUCT
        + " | to_string({product_id: id, "
        + "variant_id: (variants[?in_stock == `true`] | [0].id)})";

    private static String baseUrl() {
        String configured = System.getenv("BASE_URL");
        if (configured == null || configured.isEmpty()) {
            return SHOP;
        }
        if (!configured.equals(SHOP) && !configured.equals(SHOP + "/")) {
            throw new IllegalArgumentException("BASE_URL must target " + SHOP);
        }
        return configured;
    }

    private static String loginRedirect(String location) {
        URI target = URI.create(SHOP + "/v2/login").resolve(location);
        if (!"http".equals(target.getScheme())
            || !"127.0.0.1".equals(target.getHost())
            || target.getPort() != 8000
            || target.getRawUserInfo() != null) {
            throw new IllegalArgumentException("Login redirect must stay on the shop origin");
        }
        return target.toASCIIString();
    }

    private static String jsonString(String value) {
        StringBuilder out = new StringBuilder().append('"');
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c == '"' || c == '\\') {
                out.append('\\').append(c);
            } else if (c < 0x20) {
                out.append(String.format("\\u%04x", (int) c));
            } else {
                out.append(c);
            }
        }
        return out.append('"').toString();
    }

    private static ChainBuilder login() {
        return exec(
            http("Get login form")
                .get("/v2/login-form")
                .check(status().is(200),
                    css("input[name=csrf][value]", "value").saveAs("loginCsrf"))
        ).exitHereIfFailed().exec(
            http("Log in")
                .post("/v2/login")
                .asJson()
                .body(StringBody(session ->
                    "{\"username\":" + jsonString(session.getString("owner"))
                    + ",\"password\":\"bench\",\"csrf\":"
                    + jsonString(session.getString("loginCsrf")) + "}"))
                .check(status().in(200, 302), status().saveAs("loginStatus"))
                .checkIf((response, session) -> response.status().code() == 200)
                .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((response, session) -> response.status().code() == 302)
                .then(header("Location")
                    .transform(ModelSimulation::loginRedirect).saveAs("loginLocation"))
        ).exitHereIfFailed().doIf(session -> session.getInt("loginStatus") == 302).then(
            exec(http("Follow login redirect")
                .get("#{loginLocation}")
                .check(status().is(200), jsonPath("$.csrf").saveAs("csrf")))
                .exitHereIfFailed()
        );
    }

    private static ChainBuilder recoverSession() {
        return doIfOrElse(session -> "session".equals(session.getString("authError")))
            .then(login())
            .orElse(
                exec(http("Renew expired session")
                    .post("/v2/session/renew")
                    .header("X-CSRF-Token", "#{csrf}")
                    .asJson()
                    .body(StringBody("{}"))
                    .check(status().is(200), jsonPath("$.csrf").saveAs("csrf")))
                    .exitHereIfFailed()
            )
            .doIf(session -> session.contains("cartId")).then(
                exec(http("Recover existing cart")
                    .post("/v2/carts/#{cartId}/recover")
                    .header("X-CSRF-Token", "#{csrf}")
                    .asJson()
                    .body(StringBody("{}"))
                    .check(status().in(200, 201, 204),
                        header("ETag").optional().saveAs("cartETag"))
                    .checkIf((response, session) -> response.status().code() != 204
                        && (response.status().code() == 200 || response.status().code() == 201))
                    .then(jsonPath("$.csrf").optional().saveAs("csrf")))
                    .exitHereIfFailed()
            );
    }

    private static ChainBuilder authenticated(HttpRequestActionBuilder request, Integer... expected) {
        Integer[] firstStatuses = Arrays.copyOf(expected, expected.length + 1);
        firstStatuses[expected.length] = 401;

        return exec(request
            .check(status().in(firstStatuses), status().saveAs("operationStatus"))
            .checkIf((response, session) -> response.status().code() == 401)
            .then(jsonPath("$.error").in("expired", "session").saveAs("authError"))
        ).exitHereIfFailed().doIf(session -> session.getInt("operationStatus") == 401).then(
            recoverSession(),
            exec(request.check(status().in(expected))).exitHereIfFailed()
        );
    }

    private static ChainBuilder readRevision(String name) {
        return authenticated(
            http(name).get("/v2/carts/#{cartId}")
                .checkIf((response, session) -> response.status().code() == 200)
                .then(header("ETag").saveAs("cartETag")),
            200
        );
    }

    private static HttpRequestActionBuilder patchQuantity(String name) {
        return http(name)
            .patch("/v2/carts/#{cartId}")
            .header("X-CSRF-Token", "#{csrf}")
            .header("If-Match", "#{cartETag}")
            .asJson()
            .body(StringBody(PATCH_BODY))
            .check(status().saveAs("patchStatus"))
            .checkIf((response, session) -> {
                int code = response.status().code();
                return code == 200 || code == 204;
            })
            .then(header("ETag").optional().saveAs("patchedETag"))
            .checkIf((response, session) -> response.status().code() == 200)
            .then(jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    public ModelSimulation() {
        ChainBuilder catalog = authenticated(
            http("Find an in-stock catalog variant")
                .get("/v2/catalog")
                .checkIf((response, session) -> response.status().code() == 200)
                .then(
                    jmesPath("(" + AVAILABLE_PRODUCT + " | id) != `null`")
                        .ofBoolean().is(true),
                    jmesPath(CART_BODY).saveAs("cartBody")
                ),
            200
        );

        ChainBuilder createCart = authenticated(
            http("Create cart and capture initial revision")
                .post("/v2/carts")
                .header("X-CSRF-Token", "#{csrf}")
                .asJson()
                .body(StringBody("#{cartBody}"))
                .checkIf((response, session) -> response.status().code() == 201)
                .then(
                    jmesPath("id != `null`").ofBoolean().is(true),
                    jmesPath("to_string(id)").saveAs("cartId"),
                    jmesPath("to_string({cart_id: id})").saveAs("orderBody"),
                    header("ETag").saveAs("cartETag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")
                ),
            201
        );

        ChainBuilder updateCart = authenticated(patchQuantity("Set cart quantity"), 200, 204, 412)
            .doIf(session -> session.getInt("patchStatus") == 412).then(
                readRevision("Re-read cart after revision conflict"),
                authenticated(patchQuantity("Retry the same quantity with the current revision"),
                    200, 204)
            )
            .doIfOrElse(session -> session.contains("patchedETag")).then(
                exec(session -> session.set("cartETag", session.getString("patchedETag")))
            ).orElse(
                readRevision("Read committed revision for checkout")
            );

        ChainBuilder checkout = authenticated(
            http("Commit one order")
                .post("/v2/orders")
                .header("X-CSRF-Token", "#{csrf}")
                .header("If-Match", "#{cartETag}")
                .header("Idempotency-Key", "#{orderKey}")
                .asJson()
                .body(StringBody("#{orderBody}"))
                .checkIf((response, session) -> response.status().code() == 201)
                .then(
                    jsonPath("$.accepted").ofBoolean().is(true),
                    jmesPath("id != `null`").ofBoolean().is(true),
                    jsonPath("$.csrf").optional().saveAs("csrf")
                ),
            201
        );

        ChainBuilder journey = exec(session -> session
            .remove("cartId")
            .remove("cartETag")
            .remove("patchedETag")
            .set("orderKey", UUID.randomUUID().toString()))
            .exec(login(), catalog, createCart, updateCart, checkout);

        setUp(
            scenario("Conditional cart update and checkout")
                .exec(session -> session.set(
                    "owner", "bench-" + (1 + Math.floorMod(session.userId(), 16L))))
                .repeat(2).on(journey)
                .injectOpen(atOnceUsers(2))
        ).protocols(http.baseUrl(baseUrl()).disableFollowRedirect().disableCaching());
    }
}

import http from 'k6/http';
import exec from 'k6/execution';
import { check, fail } from 'k6';
import { parseHTML } from 'k6/html';

const ORIGIN = 'http://127.0.0.1:8000';
const BASE = (__ENV.BASE_URL || ORIGIN).replace(/\/+$/, '');
if (BASE !== ORIGIN) throw new Error('BASE_URL must point to the local shop');

export const options = {
  scenarios: {
    etag: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '1m',
    },
  },
  maxRedirects: 0,
  noCookiesReset: true,
  thresholds: {
    checks: ['rate==1'],
    iterations: ['count==4'],
  },
};

function requireCheck(name, condition) {
  if (!check(Boolean(condition), { [name]: (ok) => ok })) fail(name);
}

function nonempty(value) {
  return typeof value === 'string' && value.trim().length > 0;
}

function hasId(value) {
  return nonempty(value) || (typeof value === 'number' && Number.isFinite(value));
}

function json(response) {
  try {
    return response.json() || {};
  } catch (_) {
    return {};
  }
}

function header(response, name) {
  const wanted = name.toLowerCase();
  for (const key of Object.keys(response.headers)) {
    if (key.toLowerCase() === wanted) return response.headers[key];
  }
  return undefined;
}

function continuation(location, from) {
  requireCheck('login redirect supplies a Location', nonempty(location));
  if (location.startsWith(BASE + '/')) location = location.slice(BASE.length);

  requireCheck(
    'login redirect stays on the local shop',
    !location.startsWith('//') &&
      !/^[a-z][a-z0-9+.-]*:/i.test(location) &&
      !/[\s\\]/.test(location)
  );

  if (location.startsWith('/')) return location;
  if (location.startsWith('?')) return from + location;
  return from.slice(0, from.lastIndexOf('/') + 1) + location;
}

function send(method, path, body, headers, expected) {
  return http.request(method, BASE + path, body, {
    headers,
    redirects: 0,
    responseCallback: http.expectedStatuses(...expected),
  });
}

function login(state) {
  const form = send('GET', '/v2/login-form', null, {}, [200]);
  requireCheck('login form returned 200', form.status === 200);

  const page = parseHTML(form.body);
  const selector = 'input[name="csrf"]';
  const scoped = page.find('form[action="/v2/login"] ' + selector).first().attr('value');
  const csrf = nonempty(scoped) ? scoped : page.find(selector).first().attr('value');
  requireCheck('login form CSRF extracted', nonempty(csrf));

  const response = send(
    'POST',
    '/v2/login',
    JSON.stringify({ username: state.username, password: 'bench', csrf }),
    { 'Content-Type': 'application/json' },
    [200, 302]
  );
  requireCheck('login returned 200 or 302', response.status === 200 || response.status === 302);

  let token = json(response).csrf;
  if (response.status === 302) {
    const path = continuation(header(response, 'Location'), '/v2/login');
    const landing = send('GET', path, null, {}, [200]);
    requireCheck('login redirect returned 200', landing.status === 200);
    const landingToken = json(landing).csrf;
    if (nonempty(landingToken)) token = landingToken;
  }
  requireCheck('authenticated CSRF received', nonempty(token));
  state.csrf = token;
}

function cartPath(state) {
  return '/v2/carts/' + encodeURIComponent(String(state.cartId));
}

function authHeaders(state) {
  return {
    'Content-Type': 'application/json',
    'X-CSRF-Token': state.csrf,
  };
}

function retainCsrf(state, response) {
  const token = json(response).csrf;
  if (nonempty(token)) state.csrf = token;
}

function restoreSession(state, error) {
  if (error === 'expired') {
    const renew = send('POST', '/v2/session/renew', '{}', authHeaders(state), [200, 401]);
    if (renew.status === 401 && json(renew).error === 'session') {
      login(state);
    } else {
      requireCheck('session renewal returned 200', renew.status === 200);
      const token = json(renew).csrf;
      requireCheck('session renewal supplied CSRF', nonempty(token));
      state.csrf = token;
    }
  } else {
    login(state);
  }

  if (hasId(state.cartId)) {
    const recovery = send(
      'POST', cartPath(state) + '/recover', '{}', authHeaders(state),
      [{ min: 200, max: 299 }]
    );
    requireCheck('existing cart recovered', recovery.status >= 200 && recovery.status < 300);
    retainCsrf(state, recovery);
    const tag = header(recovery, 'ETag');
    if (nonempty(tag)) state.etag = tag;
  }
}

function authenticated(state, method, path, body, expected, extraHeaders) {
  const attempt = () => {
    const headers = method === 'GET' ? {} : authHeaders(state);
    if (extraHeaders) Object.assign(headers, extraHeaders());
    return send(method, path, body, headers, expected.concat(401));
  };

  let response = attempt();
  if (response.status === 401) {
    const error = json(response).error;
    if (error === 'expired' || error === 'session') {
      restoreSession(state, error);
      response = attempt();
    }
  }

  if (method !== 'GET' && response.status >= 200 && response.status < 300) {
    retainCsrf(state, response);
  }
  return response;
}

function availableItem(products) {
  if (!Array.isArray(products)) return null;
  for (const product of products) {
    if (!product || !hasId(product.id) || !Array.isArray(product.variants)) continue;
    for (const variant of product.variants) {
      if (variant && variant.in_stock === true && hasId(variant.id)) {
        return { product_id: product.id, variant_id: variant.id };
      }
    }
  }
  return null;
}

function readCartTag(state) {
  const response = authenticated(state, 'GET', cartPath(state), null, [200]);
  requireCheck('cart revision read returned 200', response.status === 200);
  const tag = header(response, 'ETag');
  requireCheck('cart revision read supplied an ETag', nonempty(tag));
  return tag;
}

export default function () {
  const state = {
    username: 'bench-' + exec.vu.idInTest,
    csrf: null,
    cartId: null,
    etag: null,
  };
  login(state);

  const catalog = authenticated(state, 'GET', '/v2/catalog', null, [200]);
  requireCheck('catalog returned 200', catalog.status === 200);
  const item = availableItem((json(catalog).data || {}).products);
  requireCheck('catalog supplied an in-stock variant', item !== null);

  const created = authenticated(state, 'POST', '/v2/carts', JSON.stringify(item), [201]);
  requireCheck('cart creation returned 201', created.status === 201);
  state.cartId = json(created).id;
  requireCheck('cart creation supplied an ID', hasId(state.cartId));
  state.etag = header(created, 'ETag');
  requireCheck('initial cart ETag extracted', nonempty(state.etag));

  const quantityBody = JSON.stringify({ quantity: 2 });
  const patch = () => authenticated(
    state,
    'PATCH',
    cartPath(state),
    quantityBody,
    [200, 204, 412],
    () => ({ 'If-Match': state.etag })
  );

  let updated = patch();
  if (updated.status === 412) {
    state.etag = readCartTag(state);
    updated = patch();
  }
  requireCheck('conditional quantity update committed', updated.status === 200 || updated.status === 204);

  const committedTag = header(updated, 'ETag');
  state.etag = nonempty(committedTag) ? committedTag : readCartTag(state);

  const orderBody = JSON.stringify({ cart_id: state.cartId });
  const orderKey = 'etag-order-' + encodeURIComponent(String(state.cartId));
  const order = authenticated(
    state,
    'POST',
    '/v2/orders',
    orderBody,
    [201],
    () => ({ 'If-Match': state.etag, 'Idempotency-Key': orderKey })
  );
  const receipt = json(order);
  requireCheck(
    'checkout returned 201 with an accepted order ID',
    order.status === 201 && receipt.accepted === true && hasId(receipt.id)
  );
}

import os
from html.parser import HTMLParser
from itertools import count
from urllib.parse import quote, urljoin, urlsplit
from uuid import uuid4

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


ORIGIN = "http://127.0.0.1:8000"
USERS = 2
ITERATIONS = 2
QUANTITY = 2

accounts = count(1)
finished_users = 0


class JourneyFailed(Exception):
    pass


def shop_url(base, reference):
    if not reference:
        raise JourneyFailed("Missing request URL or redirect Location")
    try:
        url = urljoin(base, reference)
        parts = urlsplit(url)
    except ValueError as exc:
        raise JourneyFailed("Malformed shop URL") from exc
    if (parts.scheme, parts.netloc) != ("http", "127.0.0.1:8000"):
        raise JourneyFailed("URL is outside the shop origin")
    return url


class LoginFormParser(HTMLParser):
    def __init__(self, url):
        super().__init__(convert_charrefs=True)
        self.url = url
        self.form = None
        self.inert = []
        self.candidates = []

    def handle_starttag(self, tag, attributes):
        if tag in ("script", "style", "template", "noscript"):
            self.inert.append(tag)
            return
        if self.inert:
            return

        attrs = dict(attributes)
        if tag == "form":
            self.form = attrs
        elif (
            tag == "input"
            and attrs.get("name") == "csrf"
            and attrs.get("value")
            and "disabled" not in attrs
        ):
            form = self.form or {}
            try:
                action = urlsplit(urljoin(self.url, form.get("action") or ""))
                login_action = (
                    action.netloc == "127.0.0.1:8000" and action.path == "/v2/login"
                )
            except ValueError:
                login_action = False
            rank = (
                login_action,
                (form.get("method") or "").lower() == "post",
                self.form is not None,
                (attrs.get("type") or "").lower() == "hidden",
            )
            self.candidates.append((rank, attrs["value"]))

    def handle_endtag(self, tag):
        if self.inert:
            if tag == self.inert[-1]:
                self.inert.pop()
        elif tag == "form":
            self.form = None


def login_form_token(response, body):
    parser = LoginFormParser(response.url)
    parser.feed(response.text)
    parser.close()
    if not parser.candidates:
        raise JourneyFailed("Login form has no usable input[name=csrf]")
    return max(parser.candidates, key=lambda candidate: candidate[0])[1]


def csrf_token(body):
    value = body.get("csrf")
    return value if isinstance(value, str) and value else None


def require_csrf(response, body):
    token = csrf_token(body)
    if token is None:
        raise JourneyFailed("Successful session response omitted csrf")
    return token


def require_etag(response, body):
    etag = response.headers.get("ETag")
    if not etag or not etag.strip():
        raise JourneyFailed("Cart response omitted ETag")
    return etag


def valid_id(value):
    return (isinstance(value, str) and bool(value)) or type(value) is int


def select_stock(response, body):
    data = body.get("data")
    products = data.get("products") if isinstance(data, dict) else None
    for product in products if isinstance(products, list) else ():
        if not isinstance(product, dict) or not valid_id(product.get("id")):
            continue
        variants = product.get("variants")
        for variant in variants if isinstance(variants, list) else ():
            if (
                isinstance(variant, dict)
                and variant.get("in_stock") is True
                and valid_id(variant.get("id"))
            ):
                return product["id"], variant["id"]
    raise JourneyFailed("Catalog has no selectable in-stock variant")


def created_cart(response, body):
    if not valid_id(body.get("id")):
        raise JourneyFailed("Cart creation omitted its id")
    return body["id"], require_etag(response, body)


def accepted_order(response, body):
    if body.get("accepted") is not True or not valid_id(body.get("id")):
        raise JourneyFailed("Order was not accepted with an order id")


class CheckoutUser(HttpUser):
    host = os.environ.get("BASE_URL", ORIGIN).rstrip("/")
    wait_time = constant(0)

    def on_start(self):
        self.username = f"bench-{next(accounts)}"
        self.iterations = 0

    def on_stop(self):
        global finished_users
        finished_users += 1

    def request_once(
        self, method, path, *, name, expected=(200,), check=None, payload=None,
        headers=None, authenticated=False, recoverable=(), conditional=False
    ):
        request_headers = dict(headers or {})
        if authenticated and method != "GET":
            request_headers["X-CSRF-Token"] = self.csrf
        if conditional:
            request_headers["If-Match"] = self.etag

        url = shop_url(self.host + "/", path)
        kwargs = {"json": payload} if payload is not None else {}
        failure = None
        value = None
        with self.client.request(
            method, url, name=name, headers=request_headers, catch_response=True,
            allow_redirects=False, timeout=10, **kwargs
        ) as response:
            status = response.status_code
            try:
                body = response.json()
            except ValueError:
                body = {}
            if not isinstance(body, dict):
                body = {}
            error = body.get("error")

            try:
                if status == 401 and error in recoverable:
                    pass
                elif status not in expected:
                    if method == "POST" and name == "/v2/orders" and body.get("accepted") is False:
                        raise JourneyFailed("Order was rejected")
                    suffix = f" ({error})" if isinstance(error, str) else ""
                    raise JourneyFailed(f"Unexpected HTTP {status}{suffix}")
                else:
                    if check is not None:
                        value = check(response, body)
                    if 200 <= status < 400:
                        fresh_csrf = csrf_token(body)
                        if fresh_csrf is not None:
                            self.csrf = fresh_csrf
            except JourneyFailed as exc:
                response.failure(str(exc))
                failure = exc
            else:
                response.success()

        if failure is not None:
            raise failure
        return status, error, value

    def login(self):
        self.csrf = None
        _, _, form_csrf = self.request_once(
            "GET", "/v2/login-form", name="/v2/login-form", check=login_form_token
        )

        def check_login(response, body):
            if response.status_code == 302:
                return shop_url(response.url, response.headers.get("Location"))
            require_csrf(response, body)
            return None

        _, _, location = self.request_once(
            "POST", "/v2/login", name="/v2/login", expected=(200, 302),
            payload={"username": self.username, "password": "bench", "csrf": form_csrf},
            check=check_login,
        )
        if location is not None:
            self.request_once(
                "GET", location, name="/v2/login [follow]",
                check=require_csrf if self.csrf is None else None,
            )

    def recover_session(self, error):
        if error == "expired":
            status, _, _ = self.request_once(
                "POST", "/v2/session/renew", name="/v2/session/renew", payload={},
                authenticated=True, recoverable=("session",), check=require_csrf,
            )
            if status == 401:
                self.login()
        else:
            self.login()

        if self.cart_path is not None:
            _, _, recovered_etag = self.request_once(
                "POST", self.cart_path + "/recover", name="/v2/carts/[id]/recover",
                expected=(200, 201, 204), payload={}, authenticated=True,
                check=lambda response, body: response.headers.get("ETag"),
            )
            if recovered_etag:
                self.etag = recovered_etag

    def operation(self, method, path, **kwargs):
        status, error, value = self.request_once(
            method, path, authenticated=True, recoverable=("expired", "session"), **kwargs
        )
        if status == 401:
            self.recover_session(error)
            status, _, value = self.request_once(
                method, path, authenticated=True, **kwargs
            )
        return status, value

    def read_cart_etag(self):
        _, self.etag = self.operation(
            "GET", self.cart_path, name="/v2/carts/[id]", check=require_etag
        )

    def checkout(self):
        self.cart_path = None
        self.etag = None
        self.login()

        _, (product_id, variant_id) = self.operation(
            "GET", "/v2/catalog", name="/v2/catalog", check=select_stock
        )
        _, (cart_id, self.etag) = self.operation(
            "POST", "/v2/carts", name="/v2/carts", expected=(201,),
            payload={"product_id": product_id, "variant_id": variant_id},
            check=created_cart,
        )
        self.cart_path = "/v2/carts/" + quote(str(cart_id), safe="")
        order_key = uuid4().hex
        update = {"quantity": QUANTITY}

        def patch(expected):
            return self.operation(
                "PATCH", self.cart_path, name="/v2/carts/[id]", expected=expected,
                payload=update, conditional=True,
                check=lambda response, body: response.headers.get("ETag"),
            )

        status, updated_etag = patch((200, 204, 412))
        if status == 412:
            self.read_cart_etag()
            _, updated_etag = patch((200, 204))

        if updated_etag:
            self.etag = updated_etag
        else:
            self.read_cart_etag()

        self.operation(
            "POST", "/v2/orders", name="/v2/orders", expected=(201,),
            payload={"cart_id": cart_id}, headers={"Idempotency-Key": order_key},
            conditional=True, check=accepted_order,
        )

    @task
    def journey(self):
        try:
            self.checkout()
        except JourneyFailed:
            pass
        self.iterations += 1
        if self.iterations >= ITERATIONS:
            raise StopUser()


class CheckoutShape(LoadTestShape):
    def tick(self):
        if finished_users >= USERS:
            return None
        return USERS, USERS

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpRequestActionBuilder;

import java.net.URI;
import java.util.List;
import java.util.Map;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
    private static final String ORIGIN = "http://127.0.0.1:8000";
    private static final String CSRF = "X-CSRF-Token";
    private static final String STOCK_PRODUCT =
        "data.products[?variants[?in_stock == `true`]] | [0]";

    private static String baseUrl() {
        String value = System.getenv("BASE_URL");
        if (value == null || ORIGIN.equals(value) || (ORIGIN + "/").equals(value)) {
            return ORIGIN;
        }
        throw new IllegalArgumentException("BASE_URL must point to " + ORIGIN);
    }

    private static String loginRedirect(String location) {
        URI target = URI.create(ORIGIN + "/v2/login").resolve(location);
        if (!"http".equalsIgnoreCase(target.getScheme())
                || !"127.0.0.1".equals(target.getHost())
                || target.getPort() != 8000
                || target.getRawUserInfo() != null) {
            throw new IllegalArgumentException("Login redirect is outside the shop origin");
        }
        return target.toASCIIString();
    }

    private static ChainBuilder login() {
        return exec(
            http("Get login form")
                .get("/v2/login-form")
                .check(status().is(200), css("input[name=csrf]", "value").saveAs("loginCsrf"))
        ).exitHereIfFailed()
         .exec(
            http("Log in")
                .post("/v2/login")
                .body(StringBody(
                    "{\"username\":#{username.jsonStringify()},"
                        + "\"password\":\"bench\",\"csrf\":#{loginCsrf.jsonStringify()}}"))
                .asJson()
                .check(status().in(200, 302).saveAs("loginStatus"))
                .checkIf((response, session) -> response.status().code() == 200)
                .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((response, session) -> response.status().code() == 302)
                .then(header("Location").saveAs("loginLocation"))
         ).exitHereIfFailed()
          .doIf(session -> session.getInt("loginStatus") == 302).then(
              exec(
                  http("Follow login redirect")
                      .get(session -> loginRedirect(session.getString("loginLocation")))
                      .check(status().is(200), jsonPath("$.csrf").saveAs("csrf"))
              ).exitHereIfFailed()
          );
    }

    private static ChainBuilder renew() {
        return exec(
            http("Renew expired session")
                .post("/v2/session/renew")
                .header(CSRF, "#{csrf}")
                .body(StringBody("{}"))
                .asJson()
                .check(status().is(200), jsonPath("$.csrf").saveAs("csrf"))
        );
    }

    private static ChainBuilder recoverCart() {
        return exec(
            http("Recover existing cart")
                .post("/v2/carts/#{cartId}/recover")
                .header(CSRF, "#{csrf}")
                .body(StringBody("{}"))
                .asJson()
                .check(
                    status().in(200, 204),
                    header("ETag").optional().saveAs("cartEtag")
                )
                .checkIf((response, session) -> response.status().code() == 200)
                .then(jsonPath("$.csrf").optional().saveAs("csrf"))
        );
    }

    private static HttpRequestActionBuilder operationStatus(
            HttpRequestActionBuilder request, int successStatus, boolean mayRecover) {
        if (!mayRecover) {
            return request.check(status().is(successStatus));
        }
        return request
            .check(status().in(successStatus, 401).saveAs("operationStatus"))
            .checkIf((response, session) -> response.status().code() == 401)
            .then(jsonPath("$.error").in("expired", "session").saveAs("authError"));
    }

    private static ChainBuilder withRecovery(
            HttpRequestActionBuilder initial, HttpRequestActionBuilder retry) {
        return exec(initial)
            .exitHereIfFailed()
            .doIf(session -> session.getInt("operationStatus") == 401).then(
                doIfOrElse(session -> "expired".equals(session.getString("authError")))
                    .then(renew())
                    .orElse(login())
                    .exitHereIfFailed()
                    .doIf(session -> session.contains("cartId")).then(recoverCart())
                    .exitHereIfFailed()
                    .exec(retry)
                    .exitHereIfFailed()
            );
    }

    private static HttpRequestActionBuilder catalog(String name, boolean mayRecover) {
        return operationStatus(http(name).get("/v2/catalog"), 200, mayRecover)
            .checkIf((response, session) -> response.status().code() == 200)
            .then(
                jmesPath(STOCK_PRODUCT + ".id").saveAs("productId"),
                jmesPath(STOCK_PRODUCT + ".variants[?in_stock == `true`] | [0].id")
                    .saveAs("variantId")
            );
    }

    private static HttpRequestActionBuilder createCart(String name, boolean mayRecover) {
        return operationStatus(
            http(name)
                .post("/v2/carts")
                .header(CSRF, "#{csrf}")
                .body(StringBody(
                    "{\"product_id\":#{productId.jsonStringify()},"
                        + "\"variant_id\":#{variantId.jsonStringify()}}"))
                .asJson(),
            201, mayRecover
        ).checkIf((response, session) -> response.status().code() == 201)
         .then(
             jsonPath("$.id").saveAs("cartId"),
             header("ETag").saveAs("cartEtag"),
             jsonPath("$.csrf").optional().saveAs("csrf")
         );
    }

    private static HttpRequestActionBuilder checkout(String name, boolean mayRecover) {
        return operationStatus(
            http(name)
                .post("/v2/orders")
                .header(CSRF, "#{csrf}")
                .header("If-Match", "#{cartEtag}")
                .header("Idempotency-Key", "checkout-#{cartId}")
                .body(StringBody("{\"cart_id\":#{cartId.jsonStringify()}}"))
                .asJson(),
            201, mayRecover
        ).checkIf((response, session) -> response.status().code() == 201)
         .then(
             jsonPath("$.accepted").ofBoolean().is(true),
             jsonPath("$.id").saveAs("orderId"),
             jsonPath("$.csrf").optional().saveAs("csrf")
         );
    }

    public ModelSimulation() {
        ScenarioBuilder users = scenario("Checkout with session expiry recovery")
            .feed(List.<Map<String, Object>>of(
                Map.of("username", "bench-1"),
                Map.of("username", "bench-2")
            ).iterator())
            .repeat(2).on(
                exec(flushCookieJar())
                    .exec(session -> session.remove("cartId").remove("cartEtag").remove("csrf"))
                    .exec(login())
                    .exec(withRecovery(
                        catalog("Read catalog", true),
                        catalog("Retry catalog read", false)))
                    .exec(withRecovery(
                        createCart("Create cart", true),
                        createCart("Retry cart creation", false)))
                    .exec(withRecovery(
                        checkout("Checkout", true),
                        checkout("Retry checkout with recovered cart", false)))
            );

        setUp(users.injectOpen(atOnceUsers(2)))
            .protocols(http.baseUrl(baseUrl()).disableFollowRedirect())
            .assertions(global().failedRequests().count().is(0L));
    }
}

import http from 'k6/http';
import { check } from 'k6';
import exec from 'k6/execution';

const ORIGIN = 'http://127.0.0.1:8000';
const BASE = (__ENV.BASE_URL || ORIGIN).replace(/\/+$/, '');
if (BASE !== ORIGIN) {
  throw new Error('BASE_URL must target http://127.0.0.1:8000');
}

export const options = {
  scenarios: {
    expiry: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '1m',
    },
  },
  maxRedirects: 0,
  noCookiesReset: true,
  thresholds: { checks: ['rate==1'] },
};

function verify(name, condition) {
  return check(Boolean(condition), { [name]: (ok) => ok });
}

function json(response) {
  try {
    return response ? JSON.parse(response.body) || {} : {};
  } catch (_) {
    return {};
  }
}

function header(response, name) {
  if (!response) return '';
  const wanted = name.toLowerCase();
  const key = Object.keys(response.headers).find((k) => k.toLowerCase() === wanted);
  return key ? response.headers[key] : '';
}

function nonempty(value) {
  return typeof value === 'string' && value.trim().length > 0;
}

function validId(value) {
  return nonempty(value) || Number.isSafeInteger(value);
}

function successful(response) {
  return response && response.status >= 200 && response.status < 300;
}

function loginRedirect(location) {
  if (!nonempty(location) || /[\s\\]/.test(location)) return null;
  if (location.startsWith(BASE + '/')) return location;
  if (location.startsWith('/') && !location.startsWith('//')) return BASE + location;
  if (/^[^:/?#][^:]*$/.test(location)) return BASE + '/v2/' + location;
  return null;
}

function login(state) {
  const form = http.get(BASE + '/v2/login-form');
  if (!verify('login form returned HTTP 200', form.status === 200)) return false;

  const doc = form.html();
  const loginFields = doc.find(
    'form[action="/v2/login"] input[name="csrf"], form[action="login"] input[name="csrf"]'
  );
  const fields = loginFields.size() ? loginFields : doc.find('input[name="csrf"]');
  let csrf;
  fields.each((_, field) => {
    const value = field.attr('value');
    if (!nonempty(csrf) && nonempty(value) && field.attr('disabled') === undefined) {
      csrf = value;
    }
  });
  if (!verify('login form supplied a CSRF token', nonempty(csrf))) return false;

  const submitted = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: state.username, password: 'bench', csrf }),
    { headers: { 'Content-Type': 'application/json' } }
  );

  let response = submitted;
  if (submitted.status === 302) {
    const location = loginRedirect(header(submitted, 'Location'));
    if (!verify('login redirect stayed on the fixture origin', location)) return false;
    response = http.get(location, { tags: { name: 'GET login redirect' } });
  }

  const redirectedToken = json(response).csrf;
  const token = nonempty(redirectedToken) ? redirectedToken : json(submitted).csrf;
  if (!verify('fresh login supplied a session CSRF token', successful(response) && nonempty(token))) {
    return false;
  }
  state.csrf = token;
  return true;
}

function post(state, path, payload, name, extraHeaders = {}) {
  return http.post(BASE + path, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
      ...extraHeaders,
    },
    tags: { name },
  });
}

function retainCsrf(state, body) {
  if (nonempty(body.csrf)) state.csrf = body.csrf;
}

function sessionLoss(response) {
  if (response.status !== 401) return null;
  const error = json(response).error;
  return error === 'expired' || error === 'session' ? error : null;
}

function restoreSession(state, reason) {
  if (reason === 'expired') {
    const renewal = post(state, '/v2/session/renew', {}, 'POST /v2/session/renew');
    if (sessionLoss(renewal) === 'session') {
      if (!login(state)) return false;
    } else {
      const body = json(renewal);
      if (!verify('session renewal supplied a fresh CSRF token', successful(renewal) && nonempty(body.csrf))) {
        return false;
      }
      state.csrf = body.csrf;
    }
  } else if (!login(state)) {
    return false;
  }

  if (state.cartPath !== null) {
    const recovery = post(state, state.cartPath + '/recover', {}, 'POST /v2/carts/:id/recover');
    if (!verify('existing cart recovered in the fresh session', successful(recovery))) return false;
    retainCsrf(state, json(recovery));
    state.etag = header(recovery, 'ETag') || state.etag;
  }
  return true;
}

function onceWithRecovery(state, send) {
  const response = send();
  const reason = sessionLoss(response);
  if (!reason) return response;

  if (reason === 'expired' && state.cartPath !== null) {
    state.cartExpiryObserved = true;
  }

  if (!restoreSession(state, reason)) return null;
  return send();
}

export default function () {
  const state = {
    username: `bench-${exec.vu.idInTest}`,
    csrf: '',
    cartPath: null,
    etag: '',
    cartExpiryObserved: false,
  };

  if (!login(state)) return;

  const catalog = onceWithRecovery(state, () => http.get(BASE + '/v2/catalog'));
  const data = json(catalog).data;
  const products = data && data.products;
  if (!verify('catalog returned products', catalog && catalog.status === 200 && Array.isArray(products))) {
    return;
  }

  let selection;
  for (const product of products) {
    if (!product || !validId(product.id) || !Array.isArray(product.variants)) continue;
    const variant = product.variants.find((v) => v && validId(v.id) && v.in_stock === true);
    if (variant) {
      selection = { product_id: product.id, variant_id: variant.id };
      break;
    }
  }
  if (!verify('an in-stock catalog variant was selected', selection)) return;

  const created = onceWithRecovery(state, () =>
    post(state, '/v2/carts', selection, 'POST /v2/carts')
  );
  const cart = json(created);
  if (!verify('cart creation returned HTTP 201 and a cart ID', created && created.status === 201 && validId(cart.id))) {
    return;
  }

  retainCsrf(state, cart);
  state.cartPath = '/v2/carts/' + encodeURIComponent(String(cart.id));
  state.etag = header(created, 'ETag');

  try {
    const current = onceWithRecovery(state, () =>
      http.get(BASE + state.cartPath, { tags: { name: 'GET /v2/carts/:id' } })
    );
    const etag = header(current, 'ETag');
    if (!verify('existing cart read returned its ETag', current && current.status === 200 && nonempty(etag))) {
      return;
    }
    state.etag = etag;

    const payload = { cart_id: cart.id };
    const key = `checkout-${state.username}-${encodeURIComponent(String(cart.id))}`;
    const order = onceWithRecovery(state, () => {
      const headers = { 'Idempotency-Key': key };
      if (state.etag) headers['If-Match'] = state.etag;
      return post(state, '/v2/orders', payload, 'POST /v2/orders', headers);
    });

    const result = json(order);
    if (verify('checkout committed one accepted order', order && order.status === 201 &&
        result.accepted === true && validId(result.id))) {
      retainCsrf(state, result);
    }
  } finally {
    verify('session expiry was recognized after cart creation', state.cartExpiryObserved);
  }
}

import os
from html.parser import HTMLParser
from itertools import count
from urllib.parse import quote, urljoin, urlsplit, urlunsplit
from uuid import uuid4

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


LOCAL_URL = "http://127.0.0.1:8000"
BASE_URL = os.environ.get("BASE_URL", LOCAL_URL).rstrip("/")
if BASE_URL != LOCAL_URL:
    raise ValueError("BASE_URL must target http://127.0.0.1:8000")

USERS = 2
ITERATIONS = 2
SESSION_ERRORS = ("expired", "session")
SUCCESS_STATUSES = range(200, 300)


class JourneyFailed(Exception):
    pass


def require(condition, message):
    if not condition:
        raise ValueError(message)


def json_object(response):
    body = response.json()
    require(isinstance(body, dict), "Expected a JSON object")
    return body


def csrf_token(body, required=False):
    if "csrf" not in body and not required:
        return None
    token = body.get("csrf")
    require(isinstance(token, str) and bool(token), "Missing or invalid CSRF token")
    return token


def valid_id(value):
    return (isinstance(value, str) and bool(value)) or type(value) is int


class LoginFormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.action = None
        self.tokens = []

    def handle_starttag(self, tag, attrs):
        fields = dict(attrs)
        if tag == "form":
            self.action = fields.get("action")
        elif (
            tag == "input"
            and fields.get("name") == "csrf"
            and "disabled" not in fields
            and fields.get("value")
        ):
            self.tokens.append((self.action, fields["value"]))

    def handle_endtag(self, tag):
        if tag == "form":
            self.action = None


def parse_login_form(response):
    parser = LoginFormParser()
    parser.feed(response.text)
    parser.close()
    preferred = {
        token
        for action, token in parser.tokens
        if action
        and urlsplit(urljoin(BASE_URL + "/v2/login-form", action)).path == "/v2/login"
    }
    candidates = preferred or {token for _, token in parser.tokens}
    require(len(candidates) == 1, "Login form must contain an unambiguous CSRF input")
    return next(iter(candidates))


def parse_login(response):
    if response.status_code != 302:
        return None, csrf_token(json_object(response), required=True)

    location = response.headers.get("Location")
    require(bool(location), "Login redirect is missing Location")
    target = urlsplit(urljoin(BASE_URL + "/v2/login", location))
    require(
        (target.scheme, target.netloc) == ("http", "127.0.0.1:8000"),
        "Login redirect is outside the shop origin",
    )
    return urlunsplit(("", "", target.path or "/", target.query, "")), None


def select_item(response):
    products = json_object(response)["data"]["products"]
    require(isinstance(products, list), "Catalog products must be a list")
    for product in products:
        for variant in product["variants"]:
            if variant.get("in_stock") is True:
                product_id, variant_id = product.get("id"), variant.get("id")
                require(valid_id(product_id) and valid_id(variant_id), "Missing catalog IDs")
                return product_id, variant_id
    raise ValueError("Catalog has no in-stock variant")


def parse_cart(response):
    body = json_object(response)
    cart_id = body.get("id")
    etag = response.headers.get("ETag")
    require(valid_id(cart_id), "Cart creation did not return a cart ID")
    require(bool(etag), "Cart creation did not return an ETag")
    return cart_id, etag, csrf_token(body)


def parse_recovery(response):
    body = json_object(response) if response.content else {}
    return response.headers.get("ETag"), csrf_token(body)


def parse_order(response):
    body = json_object(response)
    require(body.get("accepted") is True, "Checkout rejected the order")
    require(response.status_code == 201, "Accepted order did not return HTTP 201")
    require(valid_id(body.get("id")), "Accepted order is missing its ID")
    return csrf_token(body)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)
    account_numbers = count(1)
    finished = 0

    def on_start(self):
        self.username = f"bench-{next(self.account_numbers)}"
        self.iteration = 0

    def on_stop(self):
        ShopUser.finished += 1

    def send(
        self, method, path, *, statuses, parse, payload=None, authenticated=False,
        name=None, handled_errors=(), checkout_key=None
    ):
        headers = {}
        if authenticated and method != "GET":
            headers["X-CSRF-Token"] = self.csrf
        if checkout_key is not None:
            headers["Idempotency-Key"] = checkout_key
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag

        kwargs = {"json": payload} if payload is not None else {}
        with self.client.request(
            method, BASE_URL + path, name=name or path, headers=headers,
            allow_redirects=False, timeout=5, catch_response=True, **kwargs
        ) as response:
            error = None
            if response.status_code == 401:
                try:
                    error = json_object(response).get("error")
                except ValueError:
                    pass
                if error in handled_errors:
                    response.success()
                    return error, None

            if response.status_code not in statuses:
                detail = f": {error}" if error is not None else ""
                response.failure(f"Unexpected HTTP {response.status_code}{detail}")
            else:
                try:
                    value = parse(response)
                except (ValueError, TypeError, KeyError, AttributeError) as exc:
                    response.failure(f"Invalid response: {exc}")
                else:
                    response.success()
                    return None, value

        raise JourneyFailed()

    def keep_csrf(self, token):
        if token is not None:
            self.csrf = token

    def login(self):
        _, form_token = self.send(
            "GET", "/v2/login-form", statuses=(200,), parse=parse_login_form
        )
        _, (redirect, token) = self.send(
            "POST", "/v2/login", statuses=(200, 302), parse=parse_login,
            payload={"username": self.username, "password": "bench", "csrf": form_token},
        )
        if redirect is not None:
            _, token = self.send(
                "GET", redirect, name="/v2/login [redirect]", statuses=(200,),
                parse=lambda response: csrf_token(json_object(response), required=True),
            )
        self.csrf = token

    def restore_session(self, reason):
        if reason == "expired":
            revoked, token = self.send(
                "POST", "/v2/session/renew", statuses=SUCCESS_STATUSES,
                parse=lambda response: csrf_token(json_object(response), required=True),
                payload={}, authenticated=True, handled_errors=("session",),
            )
            if revoked == "session":
                self.login()
            else:
                self.csrf = token
        else:
            self.login()

        if self.cart_id is not None:
            cart_segment = quote(str(self.cart_id), safe="")
            _, (etag, token) = self.send(
                "POST", f"/v2/carts/{cart_segment}/recover",
                name="/v2/carts/{id}/recover", statuses=SUCCESS_STATUSES,
                parse=parse_recovery, payload={}, authenticated=True,
            )
            self.keep_csrf(token)
            if etag:
                self.cart_etag = etag

    def operation(self, method, path, **kwargs):
        reason, value = self.send(
            method, path, authenticated=True, handled_errors=SESSION_ERRORS, **kwargs
        )
        if reason is not None:
            self.restore_session(reason)
            _, value = self.send(method, path, authenticated=True, **kwargs)
        return value

    def journey(self):
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.login()

        product_id, variant_id = self.operation(
            "GET", "/v2/catalog", statuses=(200,), parse=select_item
        )
        self.cart_id, self.cart_etag, token = self.operation(
            "POST", "/v2/carts", statuses=(201,), parse=parse_cart,
            payload={"product_id": product_id, "variant_id": variant_id},
        )
        self.keep_csrf(token)

        checkout_key = uuid4().hex
        token = self.operation(
            "POST", "/v2/orders", statuses=(200, 201), parse=parse_order,
            payload={"cart_id": self.cart_id}, checkout_key=checkout_key,
        )
        self.keep_csrf(token)

    @task
    def run_journey(self):
        if self.iteration >= ITERATIONS:
            raise StopUser()
        self.iteration += 1
        try:
            self.journey()
        except JourneyFailed:
            pass
        if self.iteration >= ITERATIONS:
            raise StopUser()


class ExpiryShape(LoadTestShape):
    def tick(self):
        if ShopUser.finished >= USERS or self.get_run_time() >= 60:
            return None
        return USERS, USERS

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.CheckBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;
import io.gatling.javaapi.http.HttpRequestActionBuilder;

import java.net.URI;
import java.time.Duration;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
    private static final String ORIGIN = "http://127.0.0.1:8000";
    private static final int MAX_POLLS = 5;
    private static final Duration POLL_PAUSE = Duration.ofMillis(60);

    private static String baseUrl() {
        String configured = System.getenv("BASE_URL");
        if (configured == null || configured.isEmpty() || configured.equals(ORIGIN + "/")) {
            return ORIGIN;
        }
        if (!configured.equals(ORIGIN)) {
            throw new IllegalArgumentException("BASE_URL must target " + ORIGIN);
        }
        return configured;
    }

    private static String localUrl(String location) {
        URI uri = URI.create(ORIGIN + "/").resolve(location);
        if (!"http".equals(uri.getScheme())
                || !"127.0.0.1".equals(uri.getHost())
                || uri.getPort() != 8000
                || uri.getRawUserInfo() != null) {
            throw new IllegalArgumentException("Unexpected URL outside the shop origin");
        }
        return uri.toASCIIString();
    }

    private static String quote(String value) {
        StringBuilder result = new StringBuilder("\"");
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c == '"' || c == '\\') {
                result.append('\\').append(c);
            } else if (c < 0x20) {
                result.append(String.format("\\u%04x", (int) c));
            } else {
                result.append(c);
            }
        }
        return result.append('"').toString();
    }

    private static ChainBuilder login() {
        return exec(flushCookieJar())
            .exec(http("Login form").get("/v2/login-form")
                .check(status().is(200), css("input[name='csrf']", "value").saveAs("formCsrf")))
            .exec(http("Login").post("/v2/login").asJson()
                .body(StringBody(s -> "{\"username\":" + quote(s.getString("username"))
                    + ",\"password\":\"bench\",\"csrf\":" + quote(s.getString("formCsrf")) + "}"))
                .check(status().in(200, 302), status().saveAs("loginStatus"))
                .checkIf((response, s) -> response.status().code() == 200)
                .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((response, s) -> response.status().code() == 302)
                .then(header("Location").saveAs("loginLocation")))
            .doIf(s -> s.getInt("loginStatus") == 302).then(
                exec(http("Login continuation").get(s -> localUrl(s.getString("loginLocation")))
                    .check(status().is(200), jsonPath("$.csrf").saveAs("csrf")))
            );
    }

    private static ChainBuilder recoverSession() {
        return exec(s -> s.set("renewStatus", 401))
            .doIf(s -> "expired".equals(s.getString("authError"))).then(
                exec(http("Renew session").post("/v2/session/renew").asJson()
                    .header("X-CSRF-Token", "#{csrf}").body(StringBody("{}"))
                    .check(status().in(200, 401), status().saveAs("renewStatus"))
                    .checkIf((response, s) -> response.status().code() == 200)
                    .then(jsonPath("$.csrf").saveAs("csrf"))
                    .checkIf((response, s) -> response.status().code() == 401)
                    .then(jsonPath("$.error").in("expired", "session")))
            )
            .doIf(s -> s.getInt("renewStatus") == 401).then(login())
            .doIf(s -> s.contains("cartId")).then(
                exec(http("Recover cart").post("/v2/carts/#{cartId}/recover").asJson()
                    .header("X-CSRF-Token", "#{csrf}").body(StringBody("{}"))
                    .check(status().is(200), jsonPath("$.csrf").optional().saveAs("csrf")))
                .exec(http("Read recovered cart").get("/v2/carts/#{cartId}")
                    .check(status().is(200), header("ETag").saveAs("cartEtag")))
            );
    }

    private static ChainBuilder send(HttpRequestActionBuilder request, boolean poll) {
        if (!poll) {
            return exec(request);
        }
        return exec(pause(POLL_PAUSE))
            .exec(s -> s.set("pollCount", s.getInt("pollCount") + 1))
            .exec(request);
    }

    private static ChainBuilder authenticated(
            HttpRequestActionBuilder request, int expectedStatus, boolean poll,
            CheckBuilder... successChecks) {
        HttpRequestActionBuilder checked = request
            .checkIf((response, s) -> response.status().code() == expectedStatus)
            .then(successChecks);

        HttpRequestActionBuilder firstAttempt = checked
            .check(status().in(expectedStatus, 401), status().saveAs("operationStatus"))
            .checkIf((response, s) -> response.status().code() == 401)
            .then(jsonPath("$.error").in("expired", "session").saveAs("authError"));

        if (poll) {
            firstAttempt = firstAttempt
                .checkIf(s -> s.getInt("pollCount") == MAX_POLLS)
                .then(status().is(expectedStatus));
        }

        return send(firstAttempt, poll)
            .doIf(s -> s.getInt("operationStatus") == 401).then(
                recoverSession()
                    .exec(send(checked.check(status().is(expectedStatus)), poll))
            );
    }

    private static ChainBuilder catalog() {
        String stocked = "data.products[?variants[?in_stock == `true`]] | [0]";
        return authenticated(http("Read catalog").get("/v2/catalog"), 200, false,
            jmesPath(stocked + ".id").saveAs("productId"),
            jmesPath(stocked + ".variants[?in_stock == `true`] | [0].id").saveAs("variantId"));
    }

    private static ChainBuilder createCart() {
        return authenticated(http("Create cart").post("/v2/carts").asJson()
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(s -> "{\"product_id\":" + quote(s.getString("productId"))
                    + ",\"variant_id\":" + quote(s.getString("variantId")) + "}")),
            201, false,
            jsonPath("$.id").saveAs("cartId"),
            header("ETag").saveAs("cartEtag"),
            jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    private static Session correlateJob(Session s) {
        String url = localUrl(s.getString("statusUrl"));
        String jobId = s.getString("responseJobId");
        if (jobId == null) {
            jobId = s.getString("responseId");
        }
        if (jobId == null) {
            URI uri = URI.create(url);
            String query = uri.getRawQuery();
            if (query != null) {
                for (String parameter : query.split("&")) {
                    if (parameter.startsWith("job_id=")) {
                        jobId = parameter.substring("job_id=".length());
                        break;
                    }
                }
            }
            if (jobId == null) {
                String path = uri.getRawPath().replaceFirst("/+$", "");
                if (path.endsWith("/status")) {
                    path = path.substring(0, path.length() - "/status".length());
                }
                jobId = path.substring(path.lastIndexOf('/') + 1);
            }
        }
        return s.set("jobId", jobId).set("pollUrl", url)
            .set("pollCount", 0).set("jobState", "pending");
    }

    private static ChainBuilder startReservation() {
        return authenticated(http("Start reservation job").post("/v2/reservations").asJson()
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(s -> "{\"cart_id\":" + quote(s.getString("cartId")) + "}")),
            202, false,
            jsonPath("$.job_id").optional().saveAs("responseJobId"),
            jsonPath("$.id").optional().saveAs("responseId"),
            jsonPath("$.status_url").saveAs("statusUrl"),
            jsonPath("$.csrf").optional().saveAs("csrf"))
            .exec(ModelSimulation::correlateJob);
    }

    private static ChainBuilder pollReservation() {
        HttpRequestActionBuilder poll = http("Poll reservation job").get("#{pollUrl}")
            .checkIf((response, s) ->
                response.status().code() == 200 && s.getInt("pollCount") == MAX_POLLS)
            .then(jsonPath("$.status").is("ready"));

        return authenticated(poll, 200, true,
            jsonPath("$.status").in("pending", "ready").saveAs("jobState"),
            jmesPath("(status == 'pending' || (status == 'ready' && reservation_id))"
                + " && 'valid' || 'invalid'").is("valid"),
            jsonPath("$.reservation_id").optional().saveAs("reservationId"));
    }

    private static ChainBuilder checkout() {
        return authenticated(http("Checkout reservation").post("/v2/orders").asJson()
                .header("X-CSRF-Token", "#{csrf}")
                .header("If-Match", "#{cartEtag}")
                .header("Idempotency-Key", "order-#{cartId}")
                .body(StringBody(s -> "{\"cart_id\":" + quote(s.getString("cartId"))
                    + ",\"reservation_id\":" + quote(s.getString("reservationId")) + "}")),
            201, false,
            jmesPath("accepted == `true` && 'accepted' || 'rejected'").is("accepted"),
            jsonPath("$.id").saveAs("orderId"),
            jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    private static Session newJourney(Session s) {
        for (String key : new String[] {
                "csrf", "formCsrf", "loginLocation", "authError", "cartId", "cartEtag",
                "responseJobId", "responseId", "jobId", "statusUrl", "pollUrl",
                "pollCount", "jobState", "reservationId", "orderId"
        }) {
            s = s.remove(key);
        }
        return s.markAsSucceeded();
    }

    public ModelSimulation() {
        HttpProtocolBuilder protocol = http.baseUrl(baseUrl()).disableFollowRedirect();

        ChainBuilder journey = login()
            .exec(catalog())
            .exec(createCart())
            .exec(startReservation())
            .repeat(MAX_POLLS).on(
                doIf(s -> "pending".equals(s.getString("jobState"))
                    && s.getInt("pollCount") < MAX_POLLS).then(pollReservation())
            )
            .doIf(s -> "ready".equals(s.getString("jobState"))
                && s.contains("reservationId")).then(checkout());

        ScenarioBuilder reservation = scenario("Reservation")
            .exec(s -> s.set("username", "bench-" + (1 + Math.floorMod(s.userId() - 1, 16))))
            .repeat(2).on(
                exec(ModelSimulation::newJourney)
                    .exitBlockOnFail().on(journey)
            );

        setUp(reservation.injectOpen(atOnceUsers(2))).protocols(protocol);
    }
}

import http from 'k6/http';
import { check, fail, sleep } from 'k6';
import exec from 'k6/execution';

const LOCAL_ORIGIN = 'http://127.0.0.1:8000';
const BASE = (__ENV.BASE_URL || LOCAL_ORIGIN).replace(/\/+$/, '');
if (BASE !== LOCAL_ORIGIN) {
  throw new Error('BASE_URL must target http://127.0.0.1:8000');
}

const LOGIN_FORM = `${BASE}/v2/login-form`;
const LOGIN = `${BASE}/v2/login`;
const CATALOG = `${BASE}/v2/catalog`;
const CARTS = `${BASE}/v2/carts`;
const RESERVATIONS = `${BASE}/v2/reservations`;
const ORDERS = `${BASE}/v2/orders`;

export const options = {
  noCookiesReset: true,
  scenarios: {
    reservation: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      exec: 'reservation',
    },
  },
};

function assertCheck(name, condition, detail) {
  if (!check(Boolean(condition), { [name]: (passed) => passed })) {
    fail(detail || name);
  }
}

function isId(value) {
  return (typeof value === 'string' && value.trim().length > 0) ||
    (typeof value === 'number' && Number.isFinite(value));
}

function isToken(value) {
  return typeof value === 'string' && value.length > 0;
}

function resolveLocal(ref, from) {
  if (typeof ref !== 'string' || !ref || /[\s\\]/.test(ref)) return null;
  const path = ref.split('#', 1)[0];
  if (!path) return null;
  if (path === BASE || path.startsWith(`${BASE}/`) || path.startsWith(`${BASE}?`)) {
    return path;
  }
  if (/^[a-z][a-z0-9+.-]*:/i.test(path) || path.startsWith('//')) return null;
  if (path.startsWith('/')) return BASE + path;

  const current = from.split('?', 1)[0];
  if (path.startsWith('?')) return current + path;
  const directory = current === BASE ? `${BASE}/` : current.slice(0, current.lastIndexOf('/') + 1);
  return directory + path;
}

function header(response, name) {
  const key = Object.keys(response.headers).find((k) => k.toLowerCase() === name.toLowerCase());
  return key === undefined ? undefined : response.headers[key];
}

function send(method, url, payload, name, headers = {}) {
  const hasPayload = payload !== null;
  const response = http.request(method, url, hasPayload ? JSON.stringify(payload) : null, {
    headers: hasPayload ? { ...headers, 'Content-Type': 'application/json' } : headers,
    redirects: 0,
    timeout: '10s',
    tags: { name },
  });
  let data = {};
  try {
    const value = response.json();
    if (value && typeof value === 'object') data = value;
  } catch (_) {
    // Login forms and redirect responses need not contain JSON.
  }
  return { response, status: response.status, data };
}

function success(reply) {
  return reply !== null && reply.status >= 200 && reply.status < 300;
}

function captureCsrf(state, reply) {
  if (isToken(reply.data.csrf)) state.csrf = reply.data.csrf;
}

function csrfInputs(selection) {
  return selection.find('input[name="csrf"]').toArray().filter((input) =>
    input.attr('disabled') == null && isToken(input.attr('value'))
  );
}

function loginToken(response) {
  const document = response.html();
  const forms = document.find('form').toArray();
  let candidates = [];
  for (const form of forms) {
    const action = resolveLocal(form.attr('action'), LOGIN_FORM);
    if (action && action.split('?', 1)[0] === LOGIN) {
      candidates = candidates.concat(csrfInputs(form));
    }
  }
  if (!candidates.length) {
    for (const form of forms) {
      if (form.find('input[type="password"]').size() > 0) {
        candidates = candidates.concat(csrfInputs(form));
      }
    }
  }
  if (!candidates.length) candidates = csrfInputs(document);
  if (candidates.length === 1) return candidates[0].attr('value');
  const hidden = candidates.filter((input) => (input.attr('type') || '').toLowerCase() === 'hidden');
  return hidden.length === 1 ? hidden[0].attr('value') : null;
}

function login(state) {
  const form = send('GET', LOGIN_FORM, null, 'GET /v2/login-form');
  assertCheck('login form returned', form.status === 200);
  const csrf = loginToken(form.response);
  assertCheck('login form supplies CSRF', isToken(csrf));

  state.csrf = null;
  const reply = send('POST', LOGIN, {
    username: state.username,
    password: 'bench',
    csrf,
  }, 'POST /v2/login');

  assertCheck('login succeeds or redirects', success(reply) || reply.status === 302);
  captureCsrf(state, reply);
  if (reply.status === 302) {
    const destination = resolveLocal(header(reply.response, 'Location'), LOGIN);
    assertCheck('login redirect supplies a local Location', destination !== null);
    const redirected = send('GET', destination, null, 'GET login Location');
    assertCheck('login redirect succeeds', success(redirected));
    captureCsrf(state, redirected);
  }
  assertCheck('authenticated CSRF received', isToken(state.csrf));
}

function recoverSession(state, reason) {
  if (reason === 'session') {
    login(state);
  } else {
    const renewed = send('POST', `${BASE}/v2/session/renew`, {}, 'POST /v2/session/renew', {
      'X-CSRF-Token': state.csrf,
    });
    if (renewed.status === 401 && renewed.data.error === 'session') {
      login(state);
    } else {
      assertCheck('expired session renews', success(renewed));
      captureCsrf(state, renewed);
    }
  }

  if (state.cartUrl) {
    const recovered = send('POST', `${state.cartUrl}/recover`, {}, 'POST /v2/carts/:id/recover', {
      'X-CSRF-Token': state.csrf,
    });
    assertCheck('cart recovers under the current session', success(recovered));
    captureCsrf(state, recovered);
    state.etag = header(recovered.response, 'ETag') || state.etag;
  }
}

function authenticated(state, method, url, payload, name, config = {}) {
  const recovery = config.recovery || { used: false };
  const pollBudget = config.pollBudget;

  function attempt() {
    if (pollBudget) {
      if (pollBudget.remaining === 0) return null;
      pollBudget.remaining -= 1;
      // The protocol's 50 ms minimum is stricter than both profile intervals.
      sleep(0.06);
    }
    const headers = config.headers ? config.headers() : {};
    if (method !== 'GET') headers['X-CSRF-Token'] = state.csrf;
    const reply = send(method, url, payload, name, headers);
    if (method !== 'GET' && success(reply)) captureCsrf(state, reply);
    return reply;
  }

  let reply = attempt();
  if (reply && reply.status === 401 &&
      (reply.data.error === 'expired' || reply.data.error === 'session') &&
      !recovery.used && (!pollBudget || pollBudget.remaining > 0)) {
    recovery.used = true;
    recoverSession(state, reply.data.error);
    reply = attempt();
  }
  return reply;
}

function stockSelection(state) {
  let url = CATALOG;
  for (let page = 0; page < 3; page += 1) {
    const reply = authenticated(state, 'GET', url, null, 'GET catalog');
    assertCheck('catalog request succeeds', success(reply));
    const body = reply.data;
    const data = body.data || body;
    const products = Array.isArray(data.products)
      ? data.products
      : [data.product || body.product || data];

    for (const product of products) {
      if (!product || !isId(product.id) || !Array.isArray(product.variants)) continue;
      const variant = product.variants.find((v) => v && v.in_stock === true && isId(v.id));
      if (variant) return { product_id: product.id, variant_id: variant.id };
    }

    if (body.next == null || page === 2) break;
    url = resolveLocal(body.next, url);
    assertCheck('catalog next URL is local', url !== null);
  }
  return null;
}

function identifyJob(data, statusUrl) {
  if (isId(data.job_id)) return data.job_id;
  if (isId(data.id)) return data.id;

  // A response without a separate ID can identify the job in the status URL.
  const parts = statusUrl.slice(BASE.length).split('?');
  const queryId = (parts[1] || '').match(/(?:^|&)(?:job_id|job|id)=([^&]+)/);
  if (queryId) return queryId[1];

  const segments = parts[0].split('/').filter(Boolean);
  if (segments[segments.length - 1] === 'status') segments.pop();
  const last = segments[segments.length - 1];
  return last && last !== 'jobs' && last !== 'reservations' ? last : null;
}

function awaitReservation(state, job) {
  const pollBudget = { remaining: 5 };
  let reservationId = null;
  while (pollBudget.remaining > 0) {
    const reply = authenticated(state, 'GET', job.url, null, 'GET reservation job status', {
      pollBudget,
    });
    if (!check(reply, { 'reservation poll returns a successful HTTP status': success })) break;
    if (reply.data.status === 'ready') {
      reservationId = reply.data.reservation_id;
      break;
    }
    if (reply.data.status !== 'pending') break;
  }

  assertCheck(
    'reservation job becomes ready with a reservation ID',
    isId(reservationId),
    `Reservation job ${job.id} did not become ready with a reservation ID`
  );
  return reservationId;
}

function readCart(state) {
  const reply = authenticated(state, 'GET', state.cartUrl, null, 'GET /v2/carts/:id');
  assertCheck('cart read succeeds', success(reply));
  state.etag = header(reply.response, 'ETag') || state.etag;
}

export function reservation() {
  const state = {
    username: `bench-${exec.vu.idInTest}`,
    csrf: null,
    cartUrl: null,
    etag: null,
  };

  login(state);
  const selected = stockSelection(state);
  assertCheck('an in-stock catalog variant is available', selected !== null);

  const created = authenticated(state, 'POST', CARTS, selected, 'POST /v2/carts');
  assertCheck('cart created with an ID', created.status === 201 && isId(created.data.id));
  const cartId = created.data.id;
  state.cartUrl = `${CARTS}/${encodeURIComponent(String(cartId))}`;
  state.etag = header(created.response, 'ETag');

  const accepted = authenticated(state, 'POST', RESERVATIONS, { cart_id: cartId }, 'POST /v2/reservations');
  assertCheck('reservation submitted as a 202 job', accepted.status === 202);
  const statusUrl = resolveLocal(accepted.data.status_url, RESERVATIONS);
  assertCheck('202 supplies a local job status URL', statusUrl !== null);
  const jobId = identifyJob(accepted.data, statusUrl);
  assertCheck('202 job ID is correlated with its status URL', isId(jobId));
  const reservationId = awaitReservation(state, { id: jobId, url: statusUrl });

  readCart(state);
  const orderPayload = { cart_id: cartId, reservation_id: reservationId };
  const idempotencyKey = `reservation-order-${encodeURIComponent(String(cartId))}`;
  const orderConfig = {
    recovery: { used: false },
    headers: () => {
      const headers = { 'Idempotency-Key': idempotencyKey };
      if (state.etag) headers['If-Match'] = state.etag;
      return headers;
    },
  };

  let order = authenticated(state, 'POST', ORDERS, orderPayload, 'POST /v2/orders', orderConfig);
  if (order.status === 412) {
    readCart(state);
    order = authenticated(state, 'POST', ORDERS, orderPayload, 'POST /v2/orders', orderConfig);
  }

  assertCheck(
    'checkout commits the order with the ready reservation',
    order.status === 201 && order.data.accepted === true && isId(order.data.id)
  );
}

export default reservation;

import os
from html.parser import HTMLParser
from itertools import count
from time import monotonic
from urllib.parse import parse_qs, quote, unquote, urljoin, urlsplit
from uuid import uuid4

from gevent import sleep
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


ORIGIN = "http://127.0.0.1:8000"
USERS = 2
ITERATIONS = 2
MAX_POLLS = 5
POLL_INTERVAL = max(0.050, 0.020)


class ProtocolError(Exception):
    pass


class JourneyFailed(Exception):
    pass


def require(condition, message):
    if not condition:
        raise ProtocolError(message)


def local_url(reference, base=ORIGIN + "/"):
    require(isinstance(reference, str) and reference.strip(), "Missing URL")
    try:
        url = urljoin(base, reference)
        parts = urlsplit(url)
    except ValueError as exc:
        raise ProtocolError("Malformed URL") from exc
    require(
        parts.scheme == "http" and parts.netloc == "127.0.0.1:8000",
        "URL is outside the fixture origin",
    )
    return url


def is_id(value):
    return (isinstance(value, str) and bool(value.strip())) or type(value) is int


def json_object(response):
    try:
        body = response.json()
    except ValueError as exc:
        raise ProtocolError("Expected a JSON response") from exc
    require(isinstance(body, dict), "Expected a JSON object")
    return body


def auth_error(response):
    if response.status_code == 401:
        try:
            return json_object(response).get("error")
        except ProtocolError:
            pass
    return None


def expect(response, *statuses):
    if response.status_code == 401:
        raise ProtocolError("Unauthorized: " + str(auth_error(response)))
    require(
        response.status_code in statuses,
        f"Expected HTTP {' or '.join(map(str, statuses))}, got {response.status_code}",
    )


class LoginForm(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.actions = []
        self.fields = []

    def handle_starttag(self, tag, attributes):
        attrs = dict(attributes)
        if tag == "form":
            self.actions.append(attrs.get("action") or "")
        elif tag == "input" and attrs.get("name") == "csrf" and "disabled" not in attrs:
            value = attrs.get("value")
            if value:
                action = self.actions[-1] if self.actions else ""
                try:
                    path = urlsplit(action).path
                except ValueError:
                    path = ""
                score = (
                    path.rstrip("/") in ("/v2/login", "v2/login", "login"),
                    (attrs.get("type") or "").lower() == "hidden",
                )
                self.fields.append((score, value))

    def handle_endtag(self, tag):
        if tag == "form" and self.actions:
            self.actions.pop()

    def csrf(self):
        require(self.fields, "Login form has no CSRF input")
        best = max(score for score, _ in self.fields)
        values = {value for score, value in self.fields if score == best}
        require(len(values) == 1, "Login form has ambiguous CSRF inputs")
        return values.pop()


class ReservationJob:
    def __init__(self, body, submission_url):
        self.url = local_url(body.get("status_url"), submission_url)
        self.id = body.get("job_id", body.get("id"))
        if not is_id(self.id):
            parts = urlsplit(self.url)
            query = parse_qs(parts.query)
            segments = [unquote(segment) for segment in parts.path.split("/") if segment]
            if segments and segments[-1] in ("status", "poll"):
                segments.pop()
            self.id = (query.get("job_id") or query.get("id") or segments[-1:] or [None])[0]
        require(is_id(self.id), "202 response has no reservation job ID")
        self.polls = 0
        self.next_poll_at = monotonic() + POLL_INTERVAL

    def before_poll(self):
        if self.polls >= MAX_POLLS:
            raise JourneyFailed()
        while True:
            delay = self.next_poll_at - monotonic()
            if delay <= 0:
                break
            sleep(delay)
        self.polls += 1

    def after_poll(self):
        self.next_poll_at = monotonic() + POLL_INTERVAL


class ShopUser(HttpUser):
    host = os.environ.get("BASE_URL", ORIGIN)
    accounts = count(1)
    finished = 0

    def on_start(self):
        self.username = f"bench-{next(ShopUser.accounts)}"

    def call(
        self, method, url, name, check, *, payload=None, auth=False,
        allow_recovery=True, job=None, order_key=None,
    ):
        for attempt in range(2):
            headers = {}
            if auth and method != "GET":
                headers["X-CSRF-Token"] = self.csrf
            if order_key is not None:
                headers["Idempotency-Key"] = order_key
                if self.etag:
                    headers["If-Match"] = self.etag
            kwargs = {} if payload is None else {"json": payload}
            if job is not None:
                job.before_poll()
            with self.client.request(
                method, url, name=name, headers=headers, catch_response=True,
                allow_redirects=False, timeout=10, **kwargs,
            ) as response:
                if job is not None:
                    job.after_poll()
                reason = auth_error(response) if auth else None
                retry = (
                    attempt == 0 and allow_recovery and reason in ("expired", "session")
                    and (job is None or job.polls < MAX_POLLS)
                )
                if retry:
                    response.success()
                else:
                    try:
                        result = check(response)
                    except ProtocolError as exc:
                        response.failure(str(exc))
                    else:
                        response.success()
                        return result
            if not retry:
                raise JourneyFailed()
            self.restore_session(reason)
        raise JourneyFailed()

    def remember_csrf(self, body):
        token = body.get("csrf")
        if isinstance(token, str) and token:
            self.csrf = token

    def login(self):
        def read_form(response):
            expect(response, 200)
            form = LoginForm()
            form.feed(response.text)
            form.close()
            return form.csrf()

        def read_session(response):
            expect(response, 200)
            token = json_object(response).get("csrf")
            require(isinstance(token, str) and token, "Login did not return a CSRF token")
            self.csrf = token

        login_url = local_url("/v2/login")

        def read_login(response):
            if response.status_code == 302:
                return local_url(response.headers.get("Location"), login_url)
            read_session(response)
            return None

        form_token = self.call(
            "GET", local_url("/v2/login-form"), "/v2/login-form", read_form,
        )
        location = self.call(
            "POST", login_url, "/v2/login", read_login,
            payload={"username": self.username, "password": "bench", "csrf": form_token},
        )
        if location is not None:
            self.call("GET", location, "/v2/login redirect", read_session)

    def restore_session(self, reason):
        if reason == "expired":
            def read_renewal(response):
                if auth_error(response) == "session":
                    return False
                expect(response, 200, 201)
                token = json_object(response).get("csrf")
                require(isinstance(token, str) and token, "Renewal did not return a CSRF token")
                self.csrf = token
                return True

            renewed = self.call(
                "POST", local_url("/v2/session/renew"), "/v2/session/renew",
                read_renewal, payload={}, auth=True, allow_recovery=False,
            )
        else:
            renewed = False
        if not renewed:
            self.login()
        if self.cart_url is not None:
            def read_recovery(response):
                expect(response, 200, 201, 204)
                if response.content:
                    self.remember_csrf(json_object(response))
                self.etag = response.headers.get("ETag") or self.etag

            self.call(
                "POST", self.cart_url + "/recover", "/v2/carts/:id/recover",
                read_recovery, payload={}, auth=True, allow_recovery=False,
            )

    def select_variant(self):
        url = local_url("/v2/catalog")
        seen = set()
        for page in range(1, 4):
            seen.add(url)

            def read_catalog(response):
                expect(response, 200)
                body = json_object(response)
                data = body.get("data", body)
                require(isinstance(data, dict), "Invalid catalog data")
                products = data.get("products")
                if products is None:
                    product = data.get("product", data if "variants" in data else None)
                    products = [] if product is None else [product]
                require(isinstance(products, list), "Invalid catalog products")
                for product in products:
                    require(isinstance(product, dict), "Invalid catalog product")
                    variants = product.get("variants")
                    require(isinstance(variants, list), "Invalid product variants")
                    for variant in variants:
                        require(isinstance(variant, dict), "Invalid catalog variant")
                        if variant.get("in_stock") is True:
                            product_id, variant_id = product.get("id"), variant.get("id")
                            require(is_id(product_id) and is_id(variant_id), "Missing catalog IDs")
                            return (product_id, variant_id), None
                next_page = body.get("next", data.get("next"))
                require(next_page is not None and page < 3, "No in-stock catalog variant")
                next_url = local_url(next_page, url)
                require(next_url not in seen, "Catalog pagination loop")
                return None, next_url

            variant, next_url = self.call(
                "GET", url, "/v2/catalog" if page == 1 else "/v2/catalog/page",
                read_catalog, auth=True,
            )
            if variant is not None:
                return variant
            url = next_url
        raise JourneyFailed()

    def journey(self):
        self.csrf = None
        self.cart_url = None
        self.etag = None
        self.login()
        product_id, variant_id = self.select_variant()

        def read_cart(response):
            expect(response, 201)
            body = json_object(response)
            cart_id = body.get("id")
            require(is_id(cart_id), "Cart creation did not return a cart ID")
            self.remember_csrf(body)
            self.etag = response.headers.get("ETag")
            return cart_id

        cart_id = self.call(
            "POST", local_url("/v2/carts"), "/v2/carts", read_cart,
            payload={"product_id": product_id, "variant_id": variant_id}, auth=True,
        )
        self.cart_url = local_url("/v2/carts/" + quote(str(cart_id), safe=""))
        reservation_url = local_url("/v2/reservations")

        def read_submission(response):
            expect(response, 202)
            body = json_object(response)
            job = ReservationJob(body, reservation_url)
            self.remember_csrf(body)
            return job

        job = self.call(
            "POST", reservation_url, "/v2/reservations", read_submission,
            payload={"cart_id": cart_id}, auth=True,
        )

        def read_status(response):
            expect(response, 200)
            body = json_object(response)
            if "job_id" in body:
                require(str(body["job_id"]) == str(job.id), "Polling returned a different job")
            status = body.get("status")
            if status == "ready":
                reservation_id = body.get("reservation_id")
                require(is_id(reservation_id), "Ready job did not return a reservation ID")
                return reservation_id
            require(status != "failed", "Reservation job failed")
            require(status == "pending", "Unexpected reservation job status")
            require(job.polls < MAX_POLLS, "Reservation is still pending after five polls")
            return None

        reservation_id = None
        while reservation_id is None:
            reservation_id = self.call(
                "GET", job.url, "/v2/reservations status", read_status, auth=True, job=job,
            )

        if not self.etag:
            def read_etag(response):
                expect(response, 200)
                self.etag = response.headers.get("ETag")
                require(self.etag, "Cart response did not return an ETag")

            self.call("GET", self.cart_url, "/v2/carts/:id", read_etag, auth=True)

        def read_order(response):
            if response.status_code == 200:
                require(json_object(response).get("accepted") is not False, "Checkout rejected")
            expect(response, 201)
            body = json_object(response)
            require(body.get("accepted") is True, "Checkout was not accepted")
            require(is_id(body.get("id")), "Checkout did not return an order ID")
            self.remember_csrf(body)

        self.call(
            "POST", local_url("/v2/orders"), "/v2/orders", read_order,
            payload={"cart_id": cart_id, "reservation_id": reservation_id},
            auth=True, order_key=uuid4().hex,
        )

    @task
    def run_journeys(self):
        try:
            for _ in range(ITERATIONS):
                try:
                    self.journey()
                except JourneyFailed:
                    continue
        finally:
            ShopUser.finished += 1
        raise StopUser()


class ReservationShape(LoadTestShape):
    def tick(self):
        if ShopUser.finished >= USERS:
            return None
        return USERS, USERS

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.Simulation;

import java.net.URI;
import java.time.Duration;
import java.util.List;
import java.util.Map;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
    private static final String LOCAL_BASE = "http://127.0.0.1:8000";
    private static final Duration RESPONSE_TIMEOUT = Duration.ofSeconds(3);
    private static final String FIRST_AVAILABLE =
            "data.products[?variants[0].in_stock == `true`] | [0]";

    private static String baseUrl() {
        String configured = System.getenv("BASE_URL");
        if (configured == null || configured.isBlank()) {
            return LOCAL_BASE;
        }
        if (!configured.equals(LOCAL_BASE) && !configured.equals(LOCAL_BASE + "/")) {
            throw new IllegalArgumentException("BASE_URL must be " + LOCAL_BASE);
        }
        return LOCAL_BASE;
    }

    private static String loginLocation(String location) {
        URI resolved = URI.create(LOCAL_BASE + "/v2/login").resolve(location);
        if (!"http".equalsIgnoreCase(resolved.getScheme())
                || !"127.0.0.1".equals(resolved.getHost())
                || resolved.getPort() != 8000
                || resolved.getRawUserInfo() != null) {
            throw new IllegalArgumentException("Login redirect is not on the shop origin");
        }
        return resolved.toASCIIString();
    }

    public ModelSimulation() {
        var protocol = http.baseUrl(baseUrl())
                .disableFollowRedirect()
                .disableCaching()
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("If-Match", "#{etag}")
                .header("Idempotency-Key", "#{cart}");

        var accounts = List.of(
                Map.<String, Object>of("username", "bench-1"),
                Map.<String, Object>of("username", "bench-2")
        ).iterator();

        ChainBuilder journey = exec(
                http("Login form")
                        .get("/v2/login-form")
                        .requestTimeout(RESPONSE_TIMEOUT)
                        .check(
                                status().is(200),
                                css("input[name=csrf]", "value").saveAs("form"),
                                header("ETag").optional().saveAs("etag")
                        )
        ).exec(
                http("Login")
                        .post("/v2/login")
                        .requestTimeout(RESPONSE_TIMEOUT)
                        .body(StringBody(
                                "{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{form}\"}"
                        ))
                        .check(
                                status().in(200, 302),
                                header("ETag").optional().saveAs("etag")
                        )
                        .checkIf((response, session) -> response.status().code() == 200)
                        .then(jsonPath("$.csrf").saveAs("csrf"))
                        .checkIf((response, session) -> response.status().code() == 302)
                        .then(
                                header("Location").transform(ModelSimulation::loginLocation)
                                        .saveAs("location"),
                                regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"")
                                        .optional().saveAs("csrf")
                        )
        ).doIf(session -> session.contains("location")).then(
                exec(
                        http("Complete login redirect")
                                .get("#{location}")
                                .requestTimeout(RESPONSE_TIMEOUT)
                                .check(
                                        status().is(200),
                                        jsonPath("$.csrf").optional().saveAs("csrf"),
                                        jsonPath("$.grant_id").optional().saveAs("grant"),
                                        header("ETag").optional().saveAs("etag")
                                )
                )
        ).exec(
                http("Catalog")
                        .get("/v2/catalog")
                        .requestTimeout(RESPONSE_TIMEOUT)
                        .check(
                                status().is(200),
                                jmesPath(FIRST_AVAILABLE + ".id").ofString().saveAs("product"),
                                jmesPath(FIRST_AVAILABLE + ".variants[0].id").ofString().saveAs("variant"),
                                jsonPath("$.csrf").optional().saveAs("csrf"),
                                header("ETag").optional().saveAs("etag")
                        )
        ).exec(
                http("Create cart")
                        .post("/v2/carts")
                        .requestTimeout(RESPONSE_TIMEOUT)
                        .body(StringBody(
                                "{\"product_id\":\"#{product}\",\"variant_id\":\"#{variant}\",\"grant_id\":\"#{grant}\"}"
                        ))
                        .check(
                                status().is(201),
                                regex("\"id\"\\s*:\\s*\"(cart-[^\"]*)\"").exists(),
                                jsonPath("$.id").saveAs("cart"),
                                header("ETag").saveAs("etag"),
                                jsonPath("$.csrf").optional().saveAs("csrf")
                        )
        ).exec(
                http("Place order")
                        .post("/v2/orders")
                        .requestTimeout(RESPONSE_TIMEOUT)
                        .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
                        .check(
                                status().is(201),
                                jsonPath("$.accepted").ofBoolean().is(true),
                                jsonPath("$.csrf").optional().saveAs("csrf"),
                                header("ETag").optional().saveAs("etag")
                        )
        );

        var shop = scenario("Shop journey")
                .feed(accounts)
                .repeat(2).on(
                        exec(flushCookieJar())
                                .exec(session -> session.markAsSucceeded()
                                        .remove("form")
                                        .remove("location")
                                        .set("csrf", "MISSING")
                                        .set("cart", "MISSING")
                                        .set("etag", "MISSING")
                                        .set("grant", "MISSING")
                                        .set("product", "MISSING")
                                        .set("variant", "MISSING"))
                                .exitBlockOnFail().on(journey)
                );

        setUp(shop.injectOpen(atOnceUsers(2))).protocols(protocol);
    }
}

