import http from 'k6/http';
import { check } from 'k6';
import exec from 'k6/execution';
import { parseHTML } from 'k6/html';

const ORIGIN = 'http://127.0.0.1:8000';
const BASE_URL = (__ENV.BASE_URL || ORIGIN).replace(/\/+$/, '');
if (BASE_URL !== ORIGIN) {
  throw new Error(`BASE_URL must be ${ORIGIN}`);
}

export const options = {
  scenarios: {
    shop: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
    },
  },
  noCookiesReset: false,
  maxRedirects: 0,
  thresholds: {
    checks: ['rate==1'],
  },
};

function verify(name, condition) {
  return check(Boolean(condition), { [name]: (ok) => ok });
}

function hasText(value) {
  return typeof value === 'string' && value.length > 0;
}

function json(response) {
  try {
    return response.json() || {};
  } catch (_) {
    return {};
  }
}

function header(response, name) {
  const key = Object.keys(response.headers || {}).find(
    (candidate) => candidate.toLowerCase() === name.toLowerCase(),
  );
  return key === undefined ? '' : response.headers[key];
}

function request(method, path, payload, csrf, extraHeaders, name) {
  const headers = Object.assign({ 'Content-Type': 'application/json' }, extraHeaders);
  if (hasText(csrf)) headers['X-CSRF-Token'] = csrf;

  return http.request(
    method,
    BASE_URL + path,
    payload === null ? null : JSON.stringify(payload),
    { headers, redirects: 0, timeout: '3s', tags: { name: name || `${method} ${path}` } },
  );
}

function loginRedirectPath(location) {
  const target = location.trim();
  if (!target || target.startsWith('//') || target.startsWith('#')) return null;
  if (target.startsWith(`${BASE_URL}/`)) return target.slice(BASE_URL.length);
  if (target.startsWith('/')) return target;
  if (/^[a-z][a-z0-9+.-]*:/i.test(target)) return null;
  return target.startsWith('?') ? `/v2/login${target}` : `/v2/${target}`;
}

function login(state) {
  const form = request('GET', '/v2/login-form', null);
  if (!verify('login form: HTTP 200', form.status === 200)) return false;

  const formToken = parseHTML(form.body || '')
    .find('input[name="csrf"]')
    .first()
    .attr('value');
  if (!verify('login form: CSRF input has a value', hasText(formToken))) return false;

  const response = request('POST', '/v2/login', {
    username: state.username,
    password: 'bench',
    csrf: formToken,
  });
  if (!verify('login: HTTP 200 or 302', response.status === 200 || response.status === 302)) {
    return false;
  }

  let csrf = json(response).csrf;
  let grant = null;
  if (response.status === 302) {
    const path = loginRedirectPath(header(response, 'Location'));
    if (!verify('login redirect: same-origin Location', path !== null)) return false;

    const follow = request('GET', path, null, csrf, undefined, 'GET login redirect');
    if (!verify('login redirect: HTTP 200', follow.status === 200)) return false;

    const data = json(follow);
    if (hasText(data.csrf)) csrf = data.csrf;
    if (hasText(data.grant_id)) grant = data.grant_id;
  }

  if (!verify('login: session CSRF returned', hasText(csrf))) return false;
  state.csrf = csrf;
  state.grant = grant;
  return true;
}

function retainCsrf(state, data) {
  if (hasText(data.csrf)) state.csrf = data.csrf;
}

function authError(response) {
  return response.status === 401 ? json(response).error : null;
}

function successful(response) {
  return response.status >= 200 && response.status < 300;
}

function restoreSession(state, reason) {
  if (reason === 'session') {
    if (!login(state)) return false;
  } else {
    const renewal = request('POST', '/v2/session/renew', {}, state.csrf);
    if (authError(renewal) === 'session') {
      if (!login(state)) return false;
    } else {
      if (!verify('session renewal: successful', successful(renewal))) return false;
      retainCsrf(state, json(renewal));
    }
  }

  if (state.cart !== null) {
    const path = `/v2/carts/${encodeURIComponent(state.cart)}/recover`;
    const recovered = request('POST', path, {}, state.csrf, undefined, 'POST /v2/carts/:id/recover');
    if (!verify('cart recovery: successful', successful(recovered))) return false;
    retainCsrf(state, json(recovered));
    const etag = header(recovered, 'ETag');
    if (hasText(etag)) state.etag = etag;
  }

  return true;
}

function runOperation(state, operation) {
  const response = operation();
  const reason = authError(response);
  if ((reason === 'expired' || reason === 'session') && restoreSession(state, reason)) {
    return operation();
  }
  return response;
}

export default function () {
  const state = {
    username: `bench-${exec.vu.idInTest}`,
    csrf: null,
    grant: null,
    cart: null,
    etag: null,
  };
  if (!login(state)) return;

  const catalog = runOperation(state, () => request('GET', '/v2/catalog', null, state.csrf));
  if (!verify('catalog: HTTP 200', catalog.status === 200)) return;

  const catalogData = json(catalog);
  retainCsrf(state, catalogData);
  const products = catalogData.data && catalogData.data.products;
  const product = Array.isArray(products)
    ? products.find((p) => p && p.variants && p.variants[0] && p.variants[0].in_stock === true)
    : undefined;
  if (!verify('catalog: selected product and its first in-stock variant have IDs',
    product && hasText(product.id) && hasText(product.variants[0].id))) return;

  const created = runOperation(state, () => {
    const payload = { product_id: product.id, variant_id: product.variants[0].id };
    if (state.grant !== null) payload.grant_id = state.grant;
    return request('POST', '/v2/carts', payload, state.csrf);
  });
  if (!verify('cart creation: HTTP 201', created.status === 201)) return;

  const cartData = json(created);
  if (!verify('cart creation: returned a cart ID',
    hasText(cartData.id) && cartData.id.startsWith('cart-'))) return;
  state.cart = cartData.id;
  state.grant = null;
  state.etag = header(created, 'ETag');
  retainCsrf(state, cartData);
  if (!verify('cart creation: ETag returned', hasText(state.etag))) return;

  const orderPayload = { cart_id: state.cart };
  const idempotencyKey = state.cart;
  const ordered = runOperation(state, () => request('POST', '/v2/orders', orderPayload, state.csrf, {
    'If-Match': state.etag,
    'Idempotency-Key': idempotencyKey,
  }));

  const orderData = json(ordered);
  if (successful(ordered)) retainCsrf(state, orderData);
  verify('checkout: HTTP 201 and accepted is true', ordered.status === 201 && orderData.accepted === true);
}

import os
from html.parser import HTMLParser
from itertools import count
from urllib.parse import quote, urljoin, urlsplit

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


TARGET = "http://127.0.0.1:8000"
BASE_URL = os.environ.get("BASE_URL", TARGET).rstrip("/")
if BASE_URL != TARGET:
    raise ValueError("BASE_URL must point to http://127.0.0.1:8000")

USERS = 2
ITERATIONS = 2
MISSING = "MISSING"
_user_numbers = count(1)
_finished_users = 0


class JourneyFailed(Exception):
    pass


def require(condition, message):
    if not condition:
        raise JourneyFailed(message)


def nonempty_string(value):
    return isinstance(value, str) and bool(value)


class LoginFormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.csrf = None

    def handle_starttag(self, tag, attrs):
        if tag == "input" and self.csrf is None:
            fields = dict(attrs)
            if fields.get("name") == "csrf" and "disabled" not in fields:
                self.csrf = fields.get("value") or None


def login_form_token(response, data):
    parser = LoginFormParser()
    try:
        parser.feed(response.text)
        parser.close()
    except (AssertionError, ValueError) as error:
        raise JourneyFailed("Invalid login form HTML") from error
    require(nonempty_string(parser.csrf), "Login form is missing input[name=csrf]")
    return parser.csrf


def login_result(response, data):
    if response.status_code == 200:
        require(nonempty_string(data.get("csrf")), "Login response is missing csrf")
        return None

    location = response.headers.get("Location")
    require(nonempty_string(location), "Login redirect is missing Location")
    try:
        target = urljoin(BASE_URL + "/v2/login", location)
        parts = urlsplit(target)
    except ValueError as error:
        raise JourneyFailed("Invalid login redirect Location") from error
    require(
        parts.scheme == "http" and parts.netloc == "127.0.0.1:8000",
        "Login redirect points outside the shop",
    )
    return target


def catalog_selection(response, data):
    catalog = data.get("data")
    products = catalog.get("products") if isinstance(catalog, dict) else None
    require(isinstance(products, list), "Catalog is missing data.products")
    for product in products:
        if not isinstance(product, dict):
            continue
        variants = product.get("variants")
        if not isinstance(variants, list) or not variants:
            continue
        first = variants[0]
        if isinstance(first, dict) and first.get("in_stock") is True:
            product_id = product.get("id")
            variant_id = first.get("id")
            require(
                nonempty_string(product_id) and nonempty_string(variant_id),
                "Selected catalog entry is missing a product or variant ID",
            )
            return product_id, variant_id
    raise JourneyFailed("No catalog product has its first variant in stock")


def cart_result(response, data):
    cart_id = data.get("id")
    require(isinstance(cart_id, str) and cart_id.startswith("cart-"),
            "Cart creation did not return a cart- ID")
    require(bool(response.headers.get("ETag")), "Cart creation did not return an ETag")
    return cart_id


def order_result(response, data):
    require(data.get("accepted") is True, "Order response did not assert accepted: true")
    require(response.status_code == 201, "Accepted order did not return HTTP 201")


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.username = f"bench-{next(_user_numbers)}"
        self.iterations = 0

    def sample(self, method, path, statuses, *, body=None, check=None,
               allow_recovery=False, name=None):
        url = BASE_URL + path if path.startswith("/") else path
        headers = {
            "Content-Type": "application/json",
            "X-CSRF-Token": self.csrf,
            "If-Match": self.etag,
            "Idempotency-Key": self.cart,
        }
        with self.client.request(
            method,
            url,
            name=name,
            json=body,
            headers=headers,
            allow_redirects=False,
            timeout=(2.0, 3.0),
            catch_response=True,
        ) as response:
            try:
                data = response.json()
            except ValueError:
                data = {}
            if not isinstance(data, dict):
                data = {}

            error = data.get("error")
            if (allow_recovery and response.status_code == 401
                    and error in ("expired", "session")):
                response.success()
                return None, error

            try:
                require(
                    response.status_code in statuses,
                    f"Expected HTTP {statuses}; received {response.status_code}",
                )
                result = check(response, data) if check is not None else data
            except JourneyFailed as failure:
                response.failure(str(failure))
            else:
                token = data.get("csrf")
                if nonempty_string(token):
                    self.csrf = token
                etag = response.headers.get("ETag")
                if etag:
                    self.etag = etag
                response.success()
                return result, None

        raise JourneyFailed()

    def login(self):
        self.csrf = MISSING
        self.grant = MISSING
        form_token, _ = self.sample("GET", "/v2/login-form", (200,), check=login_form_token)
        redirect, _ = self.sample(
            "POST",
            "/v2/login",
            (200, 302),
            body={"username": self.username, "password": "bench", "csrf": form_token},
            check=login_result,
        )
        if redirect is not None:
            def check_redirect(response, data):
                require(
                    nonempty_string(data.get("csrf")) or self.csrf != MISSING,
                    "Login and its redirect did not return csrf",
                )
                return data

            data, _ = self.sample(
                "GET", redirect, (200,), check=check_redirect, name="/v2/login [redirect]"
            )
            if nonempty_string(data.get("grant_id")):
                self.grant = data["grant_id"]

    def recover_session(self, reason):
        if reason == "expired":
            def check_renewal(response, data):
                require(nonempty_string(data.get("csrf")), "Session renewal is missing csrf")

            self.sample("POST", "/v2/session/renew", (200,), body={}, check=check_renewal)
        else:
            self.login()

        if self.cart != MISSING:
            self.sample(
                "POST",
                f"/v2/carts/{quote(self.cart, safe='')}/recover",
                (200, 204),
                body={},
                name="/v2/carts/:id/recover",
            )

    def operation(self, method, path, statuses, *, body=None, check=None):
        result, reason = self.sample(
            method, path, statuses, body=body, check=check, allow_recovery=True
        )
        if reason is not None:
            self.recover_session(reason)
            if reason == "session" and path == "/v2/carts":
                body = dict(body, grant_id=self.grant)
            result, _ = self.sample(method, path, statuses, body=body, check=check)
        return result

    def journey(self):
        self.client.cookies.clear()
        self.csrf = self.cart = self.etag = self.grant = MISSING

        self.login()
        product_id, variant_id = self.operation(
            "GET", "/v2/catalog", (200,), check=catalog_selection
        )
        self.cart = self.operation(
            "POST",
            "/v2/carts",
            (201,),
            body={"product_id": product_id, "variant_id": variant_id, "grant_id": self.grant},
            check=cart_result,
        )
        self.operation(
            "POST", "/v2/orders", (200, 201), body={"cart_id": self.cart}, check=order_result
        )

    @task
    def shop(self):
        global _finished_users
        self.iterations += 1
        try:
            self.journey()
        except JourneyFailed:
            pass
        if self.iterations == ITERATIONS:
            _finished_users += 1
            raise StopUser()


class ShopShape(LoadTestShape):
    def tick(self):
        if _finished_users >= USERS:
            return None
        return USERS, USERS

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpRequestActionBuilder;

import java.net.URI;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

public class ModelSimulation extends Simulation {
    private static final String TARGET = "http://127.0.0.1:8000";
    private static final String CART_PATH = "/v2/carts/#{cart}";
    private static final String CSRF_JSON = "\"csrf\"\\s*:\\s*\"([^\"]+)\"";
    private static final String GRANT_JSON = "\"grant_id\"\\s*:\\s*\"([^\"]+)\"";

    public ModelSimulation() {
        String baseUrl = System.getenv("BASE_URL");
        if (baseUrl == null || baseUrl.isBlank()) {
            baseUrl = TARGET;
        }
        if (!TARGET.equals(baseUrl) && !(TARGET + "/").equals(baseUrl)) {
            throw new IllegalArgumentException("BASE_URL must point to " + TARGET);
        }

        List<Map<String, Object>> rows = jsonFile("/fixtures/accounts.json").readRecords();
        if (rows.size() != 2) {
            throw new IllegalArgumentException("Expected exactly two account rows");
        }

        setUp(
            accountUser("Account row 1", rows.get(0)).injectOpen(atOnceUsers(1)),
            accountUser("Account row 2", rows.get(1)).injectOpen(atOnceUsers(1))
        ).protocols(http.baseUrl(baseUrl).disableFollowRedirect().disableCaching());
    }

    private static ScenarioBuilder accountUser(String name, Map<String, Object> row) {
        return scenario(name).repeat(2).on(
            exec(session -> session.markAsSucceeded().removeAll(
                "csrf", "loginFormCsrf", "loginStatus", "loginLocation", "grant",
                "product", "variant", "cart", "etag", "receivedEtag",
                "operationStatus", "operationError", "renewStatus",
                "patchPending", "patchAuthUsed", "patchStaleUsed"
            )),
            feed(List.of(row, row).iterator()),
            exec(flushCookieJar()),
            exitBlockOnFail().on(
                login(),
                authenticated(ModelSimulation::catalogRequest, false),
                authenticated(ModelSimulation::createCartRequest, false),
                exec(session -> session.remove("grant")),
                updateQuantity(),
                authenticated(ModelSimulation::orderRequest, true)
            )
        );
    }

    private static ChainBuilder login() {
        return exec(session -> session.removeAll("csrf", "grant", "loginLocation"))
            .exec(http("Login form").get("/v2/login-form")
                .check(status().is(200),
                    css("input[name='csrf'][value]", "value").saveAs("loginFormCsrf")))
            .exec(http("Login").post("/v2/login")
                .header("Content-Type", "application/json")
                .body(StringBody(
                    "{\"username\":\"#{username}\",\"password\":\"#{password}\",\"csrf\":\"#{loginFormCsrf}\"}"
                ))
                .check(status().in(200, 302), status().saveAs("loginStatus"))
                .checkIf((response, session) -> response.status().code() == 200)
                .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((response, session) -> response.status().code() == 302)
                .then(
                    header("Location").transform(ModelSimulation::loginLocation).saveAs("loginLocation"),
                    regex(CSRF_JSON).optional().saveAs("csrf")
                ))
            .doIf(session -> session.getInt("loginStatus") == 302).then(
                exec(http("Login redirect").get("#{loginLocation}")
                    .check(status().is(200),
                        regex(CSRF_JSON).optional().saveAs("csrf"),
                        regex(GRANT_JSON).optional().saveAs("grant"))
                    .checkIf(session -> !session.contains("csrf"))
                    .then(regex(CSRF_JSON).exists()))
            );
    }

    private static String loginLocation(String value) {
        URI location = URI.create(TARGET + "/v2/login").resolve(value);
        if (value.isBlank()
                || !"http".equalsIgnoreCase(location.getScheme())
                || !"127.0.0.1".equals(location.getHost())
                || location.getPort() != 8000
                || location.getRawUserInfo() != null) {
            throw new IllegalArgumentException("Invalid login redirect");
        }
        return location.toASCIIString();
    }

    private static HttpRequestActionBuilder withOutcome(
            HttpRequestActionBuilder request, int success, boolean allowRecovery) {
        if (!allowRecovery) {
            return request.check(status().is(success), status().saveAs("operationStatus"));
        }
        return request.check(status().in(success, 401), status().saveAs("operationStatus"))
            .checkIf((response, session) -> response.status().code() == 401)
            .then(jsonPath("$.error").in("expired", "session").saveAs("operationError"));
    }

    private static ChainBuilder authenticated(
            Function<Boolean, HttpRequestActionBuilder> request, boolean needsEtag) {
        return exec(request.apply(true))
            .doIf(session -> session.getInt("operationStatus") == 401).then(
                recoverSession(needsEtag),
                exec(request.apply(false))
            );
    }

    private static ChainBuilder recoverSession(boolean needsEtag) {
        ChainBuilder recoverCart = exec(session -> session.remove("receivedEtag"))
            .exec(http("Recover cart").post(CART_PATH + "/recover")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().in(200, 204),
                    regex(CSRF_JSON).optional().saveAs("csrf"),
                    header("ETag").optional().saveAs("receivedEtag")))
            .doIf(session -> session.contains("receivedEtag")).then(useReceivedEtag());

        if (needsEtag) {
            recoverCart = recoverCart.doIf(session -> !session.contains("receivedEtag")).then(
                exec(readCartRequest(false))
            );
        }

        return doIfOrElse(session -> "session".equals(session.getString("operationError")))
            .then(login())
            .orElse(
                exec(http("Renew session").post("/v2/session/renew")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .check(status().in(200, 401), status().saveAs("renewStatus"))
                    .checkIf((response, session) -> response.status().code() == 200)
                    .then(jsonPath("$.csrf").saveAs("csrf"))
                    .checkIf((response, session) -> response.status().code() == 401)
                    .then(jsonPath("$.error").in("expired", "session")))
                    .doIf(session -> session.getInt("renewStatus") == 401).then(login())
            )
            .doIf(session -> session.contains("cart")).then(recoverCart);
    }

    private static HttpRequestActionBuilder catalogRequest(boolean allowRecovery) {
        String stocked = "data.products[?variants[0].in_stock == `true`] | [0]";
        return withOutcome(http("Catalog").get("/v2/catalog"), 200, allowRecovery)
            .checkIf((response, session) -> response.status().code() == 200)
            .then(
                jmesPath(stocked + ".id").saveAs("product"),
                jmesPath(stocked + ".variants[0].id").saveAs("variant")
            );
    }

    private static HttpRequestActionBuilder createCartRequest(boolean allowRecovery) {
        return withOutcome(http("Create cart").post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(session ->
                    "{\"product_id\":" + jsonString(session.getString("product"))
                    + ",\"variant_id\":" + jsonString(session.getString("variant"))
                    + (session.contains("grant")
                        ? ",\"grant_id\":" + jsonString(session.getString("grant")) : "")
                    + "}")), 201, allowRecovery)
            .checkIf((response, session) -> response.status().code() == 201)
            .then(jsonPath("$.id").saveAs("cart"),
                header("ETag").saveAs("etag"),
                jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    private static HttpRequestActionBuilder readCartRequest(boolean allowRecovery) {
        return withOutcome(http("Read cart version").get(CART_PATH), 200, allowRecovery)
            .checkIf((response, session) -> response.status().code() == 200)
            .then(header("ETag").saveAs("etag"));
    }

    private static ChainBuilder useReceivedEtag() {
        return exec(session -> session.set("etag", session.getString("receivedEtag")));
    }

    private static ChainBuilder updateQuantity() {
        ChainBuilder rereadCart = authenticated(ModelSimulation::readCartRequest, false);
        return exec(session -> session.set("patchPending", true)
                .set("patchAuthUsed", false).set("patchStaleUsed", false))
            .repeat(3).on(
                doIf(session -> session.getBoolean("patchPending")).then(
                    exec(session -> session.remove("receivedEtag")),
                    exec(http("Set cart quantity").patch(CART_PATH)
                        .header("Content-Type", "application/json")
                        .header("X-CSRF-Token", "#{csrf}")
                        .header("If-Match", "#{etag}")
                        .body(StringBody("{\"quantity\":#{quantity}}"))
                        .check(status().in(200, 204, 401, 412),
                            status().saveAs("operationStatus"))
                        .checkIf(session -> session.getBoolean("patchAuthUsed"))
                        .then(status().in(200, 204, 412))
                        .checkIf(session -> session.getBoolean("patchStaleUsed"))
                        .then(status().in(200, 204, 401))
                        .checkIf((response, session) -> response.status().code() == 401)
                        .then(jsonPath("$.error").in("expired", "session").saveAs("operationError"))
                        .checkIf((response, session) ->
                            response.status().code() == 200 || response.status().code() == 204)
                        .then(regex(CSRF_JSON).optional().saveAs("csrf"),
                            header("ETag").optional().saveAs("receivedEtag"))),
                    doIfOrElse(session -> session.getInt("operationStatus") == 401)
                        .then(
                            exec(session -> session.set("patchAuthUsed", true)),
                            recoverSession(true)
                        )
                        .orElse(
                            doIfOrElse(session -> session.getInt("operationStatus") == 412)
                                .then(
                                    exec(session -> session.set("patchStaleUsed", true)),
                                    rereadCart
                                )
                                .orElse(
                                    exec(session -> session.set("patchPending", false)),
                                    doIfOrElse(session -> session.contains("receivedEtag"))
                                        .then(useReceivedEtag())
                                        .orElse(rereadCart)
                                )
                        )
                )
            );
    }

    private static HttpRequestActionBuilder orderRequest(boolean allowRecovery) {
        return withOutcome(http("Submit order").post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("If-Match", "#{etag}")
                .header("Idempotency-Key", "#{cart}")
                .body(StringBody("{\"cart_id\":\"#{cart}\"}")), 201, allowRecovery)
            .checkIf((response, session) -> response.status().code() == 201)
            .then(jmesPath("accepted == `true`").is("true"),
                jsonPath("$.id").exists(),
                jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    private static String jsonString(String value) {
        return "\"" + value.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
    }
}

