import http from 'k6/http';
import { check, fail, sleep } from 'k6';
import { SharedArray } from 'k6/data';
import exec from 'k6/execution';

const USERS = 2;
const ITERATIONS = 2;
const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

if (BASE !== 'http://127.0.0.1:8000') {
  throw new Error('BASE_URL must be http://127.0.0.1:8000');
}

const accounts = new SharedArray('accounts.json', () => {
  const rows = JSON.parse(open('/fixtures/accounts.json'));
  if (!Array.isArray(rows) || rows.length !== USERS) {
    throw new Error('accounts.json must contain one row per VU');
  }
  rows.forEach((row, i) => {
    if (!row || typeof row.username !== 'string' || !row.username ||
        typeof row.password !== 'string' || !row.password ||
        !Number.isInteger(row.quantity) || row.quantity < 1 || row.quantity > 20 ||
        !Number.isFinite(row.delay) || row.delay < 0) {
      throw new Error(`Invalid account row ${i + 1}`);
    }
  });
  return rows;
});

export const options = {
  maxRedirects: 0,
  noCookiesReset: false,
  scenarios: {
    checkout: {
      executor: 'per-vu-iterations',
      vus: USERS,
      iterations: ITERATIONS,
      maxDuration: '2m',
    },
  },
  thresholds: { checks: ['rate==1'] },
};

function expect(name, passed) {
  if (!check(passed, { [name]: (value) => value === true })) fail(name);
}

function nonempty(value) {
  return typeof value === 'string' && value.length > 0;
}

function validId(value) {
  return nonempty(value) || Number.isSafeInteger(value);
}

function header(response, name) {
  const key = Object.keys(response.headers).find(
    (candidate) => candidate.toLowerCase() === name.toLowerCase(),
  );
  return key ? response.headers[key] : undefined;
}

function localUrl(path) {
  if (typeof path !== 'string' || /[\\\s]/.test(path)) return null;
  if (path.startsWith(`${BASE}/`)) return path;
  if (path.startsWith('/') && !path.startsWith('//')) return `${BASE}${path}`;
  return null;
}

function rememberCsrf(state, data) {
  if (nonempty(data.csrf)) state.csrf = data.csrf;
}

function send(state, method, path, name, payload, authenticated = true, extra = {}) {
  const url = localUrl(path);
  if (!url) fail(`Invalid local URL for ${name}`);

  const headers = { ...extra };
  const hasBody = payload !== undefined;
  if (hasBody) headers['Content-Type'] = 'application/json';
  if (authenticated && method !== 'GET') headers['X-CSRF-Token'] = state.csrf;

  const response = http.request(method, url, hasBody ? JSON.stringify(payload) : null, {
    headers,
    redirects: 0,
    timeout: '3s',
    tags: { name },
  });

  let data = {};
  try {
    data = response.json() || {};
  } catch (_) {
    // HTML forms, redirects, and empty responses need not contain JSON.
  }
  const status = response.status;
  const ok = status >= 200 && status < 300;
  if (ok) rememberCsrf(state, data);
  return { response, data, status, ok };
}

function login(state) {
  state.csrf = '';
  const form = send(state, 'GET', '/v2/login-form', 'login form');
  expect('login form returned HTTP 200', form.status === 200);
  const html = form.response.html();
  const token = html.find('form[action="/v2/login"] input[name="csrf"]').attr('value') ||
    html.find('input[name="csrf"]').attr('value');
  expect('login form supplied a CSRF token', nonempty(token));

  let result = send(state, 'POST', '/v2/login', 'login', {
    username: state.account.username,
    password: state.account.password,
    csrf: token,
  }, false);

  if (result.status === 302) {
    rememberCsrf(state, result.data);
    const location = header(result.response, 'Location');
    expect('login redirect supplied a local Location', localUrl(location) !== null);
    result = send(state, 'GET', location, 'login redirect');
  }

  expect('login established a session with a CSRF token',
    result.status === 200 && nonempty(state.csrf));
  return result.data.grant_id;
}

function recoverSession(state, reason) {
  if (reason === 'expired') {
    const renewal = send(state, 'POST', '/v2/session/renew', 'renew session', {});
    if (renewal.status === 401 && renewal.data.error === 'session') {
      login(state);
    } else {
      expect('session renewed with a CSRF token', renewal.ok && nonempty(renewal.data.csrf));
    }
  } else {
    login(state);
  }

  if (state.cartPath) {
    const recovery = send(state, 'POST', `${state.cartPath}/recover`, 'recover cart', {});
    expect('existing cart recovered', recovery.ok);
    state.etag = header(recovery.response, 'ETag');
  }
}

function readCart(state) {
  const result = operation(state, 'GET', state.cartPath, 'read cart');
  const etag = header(result.response, 'ETag');
  expect('cart read supplied an ETag', result.status === 200 && nonempty(etag));
  state.etag = etag;
}

function operation(state, method, path, name, payload, opts = {}) {
  let recovered = false;
  let retriedPrecondition = false;

  for (;;) {
    const headers = {};
    if (opts.ifMatch) {
      if (!nonempty(state.etag)) readCart(state);
      headers['If-Match'] = state.etag;
    }
    if (opts.idempotencyKey) headers['Idempotency-Key'] = opts.idempotencyKey;

    const result = send(state, method, path, name, payload, true, headers);
    const reason = result.data.error;

    if (!recovered && result.status === 401 && (reason === 'expired' || reason === 'session')) {
      recovered = true;
      recoverSession(state, reason);
      continue;
    }
    if (!retriedPrecondition && method === 'PATCH' && result.status === 412) {
      retriedPrecondition = true;
      readCart(state);
      continue;
    }
    return result;
  }
}

export default function () {
  const account = accounts[exec.vu.idInTest - 1];
  expect('VU has its assigned fixture row', account !== undefined);
  if (account.delay > 0) sleep(account.delay / 1000);

  const state = { account, csrf: '', cartPath: null, etag: null };
  const grantId = login(state);

  const catalog = operation(state, 'GET', '/v2/catalog', 'catalog');
  const products = catalog.data.data && catalog.data.data.products;
  expect('catalog returned products', catalog.status === 200 && Array.isArray(products));

  const product = products.find((item) => {
    const variant = item && item.variants && item.variants[0];
    return variant && variant.in_stock === true && validId(item.id) && validId(variant.id);
  });
  expect('catalog contains a product with an in-stock first variant', product !== undefined);

  const cartPayload = { product_id: product.id, variant_id: product.variants[0].id };
  if (validId(grantId)) cartPayload.grant_id = grantId;
  const created = operation(state, 'POST', '/v2/carts', 'create cart', cartPayload);
  const cartId = created.data.id;
  expect('cart created with a cart ID',
    created.status === 201 && nonempty(cartId) && cartId.startsWith('cart-'));
  state.cartPath = `/v2/carts/${encodeURIComponent(cartId)}`;
  state.etag = header(created.response, 'ETag');

  const updated = operation(state, 'PATCH', state.cartPath, 'update cart quantity', {
    quantity: account.quantity,
  }, { ifMatch: true });
  expect('cart quantity update succeeded', updated.ok);
  state.etag = header(updated.response, 'ETag');

  const order = operation(state, 'POST', '/v2/orders', 'submit order', {
    cart_id: cartId,
  }, { ifMatch: true, idempotencyKey: cartId });
  expect('order accepted with HTTP 201 and an order ID',
    order.status === 201 && order.data.accepted === true && validId(order.data.id));
}

import json
import os
import time
from html.parser import HTMLParser
from urllib.parse import quote, urljoin, urlsplit

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ["BASE_URL"].rstrip("/")
if BASE_URL != "http://127.0.0.1:8000":
    raise ValueError("BASE_URL must be http://127.0.0.1:8000")

USERS = 2
ITERATIONS = 2

with open("/fixtures/accounts.json", encoding="utf-8") as fixture:
    ACCOUNTS = json.load(fixture)

if not isinstance(ACCOUNTS, list) or len(ACCOUNTS) != USERS:
    raise ValueError("accounts.json must contain one row per user")
for row in ACCOUNTS:
    if (
        not isinstance(row, dict)
        or not isinstance(row.get("username"), str)
        or not row["username"]
        or not isinstance(row.get("password"), str)
        or not row["password"]
        or type(row.get("quantity")) is not int
        or not 1 <= row["quantity"] <= 20
        or type(row.get("delay")) is not int
        or row["delay"] < 0
    ):
        raise ValueError("Invalid account fixture row")

assigned = 0
stopped = 0


class CheckFailed(Exception):
    pass


class JourneyFailed(Exception):
    pass


def require(condition, message):
    if not condition:
        raise CheckFailed(message)


def nonempty_text(value):
    return isinstance(value, str) and bool(value.strip())


def valid_id(value):
    return nonempty_text(value) or type(value) is int


def local_url(reference, base=BASE_URL + "/"):
    require(nonempty_text(reference), "Missing URL")
    try:
        url = urljoin(base, reference)
        parts = urlsplit(url)
    except ValueError as exc:
        raise CheckFailed("Invalid URL") from exc
    require(
        parts.scheme == "http" and parts.netloc == "127.0.0.1:8000",
        "URL is outside the shop origin",
    )
    return parts._replace(fragment="").geturl()


class LoginForm(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.form = None
        self.candidates = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "form":
            self.form = attrs
        elif (
            tag == "input"
            and attrs.get("name") == "csrf"
            and "disabled" not in attrs
            and nonempty_text(attrs.get("value"))
        ):
            self.candidates.append((self.form, attrs["value"]))

    def handle_endtag(self, tag):
        if tag == "form":
            self.form = None

    def token(self, base):
        explicit = set()
        implicit = set()
        for form, value in self.candidates:
            action = form.get("action") if form else None
            if not action:
                implicit.add(value)
                continue
            try:
                path = urlsplit(local_url(action, base)).path
            except CheckFailed:
                continue
            if path == "/v2/login":
                explicit.add(value)
        candidates = explicit or implicit
        require(len(candidates) == 1, "Missing or ambiguous login CSRF input")
        return next(iter(candidates))


class FixtureShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        global assigned
        self.slot = assigned
        assigned += 1
        if self.slot >= USERS:
            raise StopUser()
        self.account = ACCOUNTS[self.slot]
        self.client.trust_env = False

    def on_stop(self):
        global stopped
        if getattr(self, "slot", USERS) < USERS:
            stopped += 1

    def sample(
        self, method, path, name, expected, *, body=None, auth=True,
        headers=None, check=None, handled=(), track_etag=False,
    ):
        request_headers = dict(headers or {})
        if auth and method != "GET":
            request_headers["X-CSRF-Token"] = self.csrf

        options = {}
        if body is not None:
            options["json"] = body

        with self.client.request(
            method,
            local_url(path),
            name=name,
            headers=request_headers,
            allow_redirects=False,
            catch_response=True,
            timeout=(2, 3),
            **options,
        ) as response:
            try:
                data = response.json()
            except ValueError:
                data = None
            if not isinstance(data, dict):
                data = {}

            status = response.status_code
            error = data.get("error")
            if status == 401 and error in ("expired", "session") and error in handled:
                response.success()
                return error, None
            if status == 412 and "stale" in handled:
                response.success()
                return "stale", None

            try:
                require(
                    status in expected,
                    f"{name}: unexpected HTTP {status}"
                    + (f" ({error})" if status == 401 and isinstance(error, str) else ""),
                )
                if "csrf" in data:
                    require(nonempty_text(data["csrf"]), f"{name}: invalid CSRF token")
                result = check(response, data) if check else data
            except CheckFailed as exc:
                response.failure(str(exc))
            else:
                if "csrf" in data:
                    self.csrf = data["csrf"]
                if track_etag:
                    self.etag = response.headers.get("ETag") or None
                response.success()
                return None, result

        raise JourneyFailed()

    def login(self):
        self.client.cookies.clear()
        self.csrf = None

        def check_form(response, _data):
            form = LoginForm()
            form.feed(response.text)
            form.close()
            return form.token(response.url)

        def check_login(response, data):
            if response.status_code == 302:
                return local_url(response.headers.get("Location"), response.url), None
            require(nonempty_text(data.get("csrf", self.csrf)), "Login did not supply CSRF")
            if "user" in data:
                user = data["user"]
                if isinstance(user, dict):
                    user = user.get("username")
                require(user == self.account["username"], "Login returned a different user")
            grant = data.get("grant_id")
            require(grant is None or valid_id(grant), "Invalid login grant")
            return None, grant

        _, form_csrf = self.sample(
            "GET", "/v2/login-form", "/v2/login-form", (200,),
            auth=False, check=check_form,
        )
        _, (location, grant) = self.sample(
            "POST", "/v2/login", "/v2/login", (200, 302,),
            auth=False,
            body={
                "username": self.account["username"],
                "password": self.account["password"],
                "csrf": form_csrf,
            },
            check=check_login,
        )
        if location is not None:
            _, (_, grant) = self.sample(
                "GET", location, "/v2/login redirect", (200,),
                auth=False, check=check_login,
            )
        return grant

    def recover_session(self, reason):
        if reason == "expired":
            def check_renewal(_response, data):
                require(nonempty_text(data.get("csrf")), "Renewal did not supply CSRF")

            reason, _ = self.sample(
                "POST", "/v2/session/renew", "/v2/session/renew", (200,),
                body={}, check=check_renewal, handled=("session",),
            )
        if reason == "session":
            self.login()
        if self.cart_path is not None:
            self.sample(
                "POST", self.cart_path + "/recover", "/v2/carts/:id/recover",
                (200, 204), body={}, track_etag=True,
            )

    def read_cart(self):
        def check_etag(response, _data):
            require(nonempty_text(response.headers.get("ETag")), "Cart read did not supply ETag")

        self.operation(
            "GET", self.cart_path, "/v2/carts/:id", (200,),
            check=check_etag, track_etag=True,
        )

    def operation(
        self, method, path, name, expected, *, body=None, check=None,
        match=False, order_key=None, track_etag=False,
    ):
        recovered = False
        refreshed = False
        while True:
            headers = {}
            if match:
                if self.etag is None:
                    self.read_cart()
                headers["If-Match"] = self.etag
            if order_key is not None:
                headers["Idempotency-Key"] = order_key

            handled = [] if recovered else ["expired", "session"]
            if match and not refreshed:
                handled.append("stale")
            reason, result = self.sample(
                method, path, name, expected, body=body, headers=headers,
                check=check, handled=handled, track_etag=track_etag,
            )
            if reason is None:
                return result
            if reason == "stale":
                refreshed = True
                self.read_cart()
            else:
                recovered = True
                self.recover_session(reason)

    def catalog_selection(self):
        path = local_url("/v2/catalog")
        visited = set()
        for page in range(3):
            visited.add(path)

            def check_catalog(response, data):
                container = data.get("data")
                require(isinstance(container, dict), "Missing catalog data")
                products = container.get("products")
                require(isinstance(products, list), "Missing catalog products")
                for product in products:
                    if not isinstance(product, dict):
                        continue
                    variants = product.get("variants")
                    if not isinstance(variants, list) or not variants:
                        continue
                    first = variants[0]
                    if isinstance(first, dict) and first.get("in_stock") is True:
                        require(
                            valid_id(product.get("id")) and valid_id(first.get("id")),
                            "In-stock catalog entry lacks an ID",
                        )
                        return (product["id"], first["id"]), None
                require(
                    page < 2 and nonempty_text(data.get("next")),
                    "No in-stock first variant in the catalog",
                )
                following = local_url(data["next"], response.url)
                require(following not in visited, "Catalog pagination loop")
                return None, following

            selection, following = self.operation(
                "GET", path, "/v2/catalog" if page == 0 else "/v2/catalog/page",
                (200,), check=check_catalog,
            )
            if selection is not None:
                return selection
            path = following

    def journey(self):
        self.cart_path = None
        self.etag = None
        if self.account["delay"]:
            time.sleep(self.account["delay"] / 1000.0)

        grant = self.login()
        product_id, variant_id = self.catalog_selection()
        cart_body = {"product_id": product_id, "variant_id": variant_id}
        if grant is not None:
            cart_body["grant_id"] = grant

        def check_cart(response, data):
            cart_id = data.get("id")
            require(
                isinstance(cart_id, str) and cart_id.startswith("cart-") and len(cart_id) > 5,
                "Cart creation did not supply a cart ID",
            )
            require(nonempty_text(response.headers.get("ETag")), "Cart creation did not supply ETag")
            return cart_id

        cart_id = self.operation(
            "POST", "/v2/carts", "/v2/carts", (201,),
            body=cart_body, check=check_cart, track_etag=True,
        )
        self.cart_path = "/v2/carts/" + quote(cart_id, safe="")

        self.operation(
            "PATCH", self.cart_path, "/v2/carts/:id", (200, 204),
            body={"quantity": self.account["quantity"]},
            match=True, track_etag=True,
        )

        def check_order(response, data):
            require(data.get("accepted") is True, "Checkout did not accept the order")
            require(response.status_code == 201, "Accepted checkout did not return HTTP 201")
            require(valid_id(data.get("id")), "Accepted checkout did not supply an order ID")

        self.operation(
            "POST", "/v2/orders", "/v2/orders", (200, 201),
            body={"cart_id": cart_id}, check=check_order,
            match=True, order_key=cart_id,
        )

    @task
    def run_fixture(self):
        for _ in range(ITERATIONS):
            try:
                self.journey()
            except JourneyFailed:
                continue
        raise StopUser()


