import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpRequestActionBuilder;

import java.net.URI;
import java.time.Duration;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Function;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
    private static final String ORIGIN = "http://127.0.0.1:8000";
    private static final int USERS = 4;
    private static final long SLOT = 600_000_000_000L / 1212L;
    private static final long USER_PERIOD = USERS * SLOT;
    private static final long RUN_NANOS = Duration.ofSeconds(38).toNanos();
    private static final Duration REQUEST_TIMEOUT = Duration.ofSeconds(3);
    private static final String FIRST_STOCKED =
        "data.products[?variants[0].in_stock == `true`] | [0]";

    private final AtomicInteger nextLane = new AtomicInteger();
    private final AtomicLong startNanos = new AtomicLong();

    private static String baseUrl() {
        String configured = System.getenv("BASE_URL");
        if (configured == null || configured.isEmpty()) {
            return ORIGIN;
        }
        if (!configured.equals(ORIGIN) && !configured.equals(ORIGIN + "/")) {
            throw new IllegalArgumentException("BASE_URL must designate " + ORIGIN);
        }
        return configured;
    }

    private static String loginRedirect(String location) {
        URI target = URI.create(ORIGIN + "/v2/login").resolve(location).normalize();
        if (!"http".equals(target.getScheme())
            || !"127.0.0.1".equals(target.getHost())
            || target.getPort() != 8000
            || target.getRawUserInfo() != null) {
            throw new IllegalArgumentException("Login redirect is outside the shop origin");
        }
        return target.toASCIIString();
    }

    private static String quote(String value) {
        StringBuilder out = new StringBuilder("\"");
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c == '"' || c == '\\') {
                out.append('\\').append(c);
            } else if (c < 0x20) {
                out.append("\\u00")
                    .append(Character.forDigit(c >>> 4, 16))
                    .append(Character.forDigit(c & 15, 16));
            } else {
                out.append(c);
            }
        }
        return out.append('"').toString();
    }

    private static ChainBuilder login() {
        return exec(s -> s.removeAll("formCsrf", "preferredFormCsrf",
                                    "loginLocation", "csrf", "grant"))
            .exec(http("Login form").get("/v2/login-form")
                .requestTimeout(REQUEST_TIMEOUT)
                .check(status().is(200),
                    css("input[name='csrf'][value]", "value").saveAs("formCsrf"),
                    css("form[action='/v2/login'] input[name='csrf'][value]", "value")
                        .optional().saveAs("preferredFormCsrf")))
            .exec(http("Login").post("/v2/login")
                .requestTimeout(REQUEST_TIMEOUT)
                .body(StringBody(s -> {
                    String token = s.contains("preferredFormCsrf")
                        ? s.getString("preferredFormCsrf") : s.getString("formCsrf");
                    return "{\"username\":" + quote(s.getString("username"))
                        + ",\"password\":\"bench\",\"csrf\":" + quote(token) + "}";
                }))
                .check(status().in(200, 302))
                .checkIf((r, s) -> r.status().code() == 200)
                .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((r, s) -> r.status().code() == 302)
                .then(header("Location").transform(ModelSimulation::loginRedirect)
                    .saveAs("loginLocation"))
                .checkIf((r, s) -> r.status().code() == 302
                    && r.body().string().trim().startsWith("{"))
                .then(jsonPath("$.csrf").optional().saveAs("csrf")))
            .doIf(s -> s.contains("loginLocation")).then(
                exec(http("Login redirect").get("#{loginLocation}")
                    .requestTimeout(REQUEST_TIMEOUT)
                    .check(status().is(200))
                    .checkIf((r, s) -> r.body().string().trim().startsWith("{"))
                    .then(jsonPath("$.csrf").optional().saveAs("csrf"),
                          jsonPath("$.grant_id").optional().saveAs("grant"))
                    .checkIf(s -> !s.contains("csrf"))
                    .then(jsonPath("$.csrf").exists())));
    }

    private static ChainBuilder renew() {
        return exec(s -> s.remove("renewError"))
            .exec(http("Renew session").post("/v2/session/renew")
                .requestTimeout(REQUEST_TIMEOUT)
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().in(200, 401))
                .checkIf((r, s) -> r.status().code() == 200)
                .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((r, s) -> r.status().code() == 401)
                .then(jsonPath("$.error").is("session").saveAs("renewError")))
            .doIf(s -> s.contains("renewError")).then(login());
    }

    private static ChainBuilder recoverCart() {
        return exec(http("Recover cart").post("/v2/carts/#{cart}/recover")
            .requestTimeout(REQUEST_TIMEOUT)
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().in(200, 204), header("ETag").optional().saveAs("etag"))
            .checkIf((r, s) -> r.body().string().trim().startsWith("{"))
            .then(jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static HttpRequestActionBuilder authenticatedStatus(
        HttpRequestActionBuilder request, int success, boolean retry
    ) {
        if (retry) {
            return request.check(status().is(success));
        }
        return request.check(status().in(success, 401))
            .checkIf((r, s) -> r.status().code() == 401)
            .then(jsonPath("$.error").in("expired", "session").saveAs("authError"));
    }

    private static ChainBuilder withRecovery(
        Function<Boolean, HttpRequestActionBuilder> operation
    ) {
        return exec(s -> s.remove("authError"))
            .exec(operation.apply(false))
            .doIf(s -> s.contains("authError")).then(
                doIfOrElse(s -> "expired".equals(s.getString("authError")))
                    .then(renew()).orElse(login()),
                doIf(s -> s.contains("cart")).then(recoverCart()),
                exec(operation.apply(true)));
    }

    private static HttpRequestActionBuilder catalog(boolean retry) {
        return authenticatedStatus(http("Catalog").get("/v2/catalog")
                .requestTimeout(REQUEST_TIMEOUT), 200, retry)
            .checkIf((r, s) -> r.status().code() == 200)
            .then(jmesPath(FIRST_STOCKED + ".id").saveAs("product"),
                  jmesPath(FIRST_STOCKED + ".variants[0].id").saveAs("variant"));
    }

    private static HttpRequestActionBuilder createCart(boolean retry) {
        return authenticatedStatus(http("Create cart").post("/v2/carts")
                .requestTimeout(REQUEST_TIMEOUT)
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(s -> {
                    String selection = "{\"product_id\":" + quote(s.getString("product"))
                        + ",\"variant_id\":" + quote(s.getString("variant"));
                    return s.contains("grant")
                        ? selection + ",\"grant_id\":" + quote(s.getString("grant")) + "}"
                        : selection + "}";
                })), 201, retry)
            .checkIf((r, s) -> r.status().code() == 201)
            .then(regex("\"id\"\\s*:\\s*\"cart-[^\"]+\"").exists(),
                  jsonPath("$.id").saveAs("cart"),
                  header("ETag").saveAs("etag"),
                  jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    private static HttpRequestActionBuilder checkout(boolean retry) {
        return authenticatedStatus(http("Checkout").post("/v2/orders")
                .requestTimeout(REQUEST_TIMEOUT)
                .header("X-CSRF-Token", "#{csrf}")
                .header("If-Match", "#{etag}")
                .header("Idempotency-Key", "#{cart}")
                .body(StringBody(s -> "{\"cart_id\":" + quote(s.getString("cart")) + "}")),
                201, retry)
            .checkIf((r, s) -> r.status().code() == 201)
            .then(jsonPath("$.accepted").ofBoolean().is(true),
                  jsonPath("$.id").exists(),
                  jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    public ModelSimulation() {
        ChainBuilder journey = exitBlockOnFail().on(
            exec(s -> s.removeAll("cart", "etag", "product", "variant", "authError")),
            login(),
            withRecovery(ModelSimulation::catalog),
            withRecovery(ModelSimulation::createCart),
            exec(s -> s.remove("grant")),
            withRecovery(ModelSimulation::checkout)
        );

        ScenarioBuilder scenario = scenario("Paced checkout journeys")
            .exec(s -> {
                int lane = nextLane.getAndIncrement();
                long now = System.nanoTime();
                long epoch = startNanos.updateAndGet(old -> old == 0L ? now : old);
                return s.set("username", "bench-" + (lane + 1))
                    .set("slot", epoch + lane * SLOT)
                    .set("stopAt", epoch + RUN_NANOS);
            })
            .asLongAs(s -> s.getLong("slot") < s.getLong("stopAt"), "journeyIndex", false)
            .on(
                pause(s -> Duration.ofNanos(Math.max(0L, s.getLong("slot") - System.nanoTime()))),
                doIf(s -> System.nanoTime() < s.getLong("stopAt")).then(journey),
                exec(s -> {
                    long next = s.getLong("slot") + USER_PERIOD;
                    long now = System.nanoTime();
                    if (next < now) {
                        next += ((now - next) / USER_PERIOD + 1) * USER_PERIOD;
                    }
                    return s.markAsSucceeded().set("slot", next);
                })
            );

        setUp(scenario.injectOpen(atOnceUsers(USERS)))
            .protocols(http.baseUrl(baseUrl()).disableFollowRedirect()
                .contentTypeHeader("application/json"))
            .maxDuration(Duration.ofSeconds(40));
    }
}

