import http from 'k6/http';
import { check } from 'k6';
import { Rate } from 'k6/metrics';

const origin = 'http://127.0.0.1:8000';
const base = (__ENV.BASE_URL || origin).replace(/\/+$/, '');
if (base !== origin) throw new Error('BASE_URL must be ' + origin);

const journeyFailure = new Rate('journey_failure');

export const options = {
  noCookiesReset: true,
  maxRedirects: 0,
  scenarios: {
    journey: {
      executor: 'constant-arrival-rate',
      rate: 2,
      timeUnit: '1s',
      duration: '38s',
      preAllocatedVUs: 4,
      maxVUs: 4,
      gracefulStop: '2s',
    },
  },
  thresholds: {
    journey_failure: ['rate<=0.01'],
    dropped_iterations: ['count==0'],
  },
};

function request(method, path, body, headers = {}) {
  return http.request(
    method,
    base + path,
    body === undefined ? null : JSON.stringify(body),
    {
      headers: body === undefined ? headers : { 'Content-Type': 'application/json', ...headers },
      redirects: 0,
      timeout: '3s',
    },
  );
}

function payload(response) {
  try {
    return response.json() || {};
  } catch (_) {
    return {};
  }
}

function header(response, name) {
  const wanted = name.toLowerCase();
  const key = Object.keys(response.headers || {}).find((key) => key.toLowerCase() === wanted);
  return key ? response.headers[key] : '';
}

function successful(response) {
  return response.status >= 200 && response.status < 300;
}

function verified(response, name, passed) {
  return check(response, { [name]: () => passed });
}

function token(value) {
  return typeof value === 'string' && value.length > 0;
}

function hasId(value) {
  return token(value) || (typeof value === 'number' && Number.isFinite(value));
}

function formToken(response) {
  const document = response.html();
  const selector = 'input[name="csrf"]:not([disabled])';
  let inputs = document.find('form[action="/v2/login"] ' + selector);
  if (inputs.size() === 0) inputs = document.find(selector);

  let first = '';
  let hidden = '';
  inputs.each((_, input) => {
    const value = input.attr('value');
    if (!token(value)) return;
    if (!first) first = value;
    if (!hidden && (input.attr('type') || '').toLowerCase() === 'hidden') hidden = value;
  });
  return hidden || first;
}

function loginLocation(value) {
  let path = value.trim().split('#')[0];
  if (!path || /[\s\\]/.test(path)) return '';
  if (path.indexOf(base + '/') === 0) {
    path = path.slice(base.length);
  } else if (/^[a-z][a-z0-9+.-]*:/i.test(path) || path.indexOf('//') === 0) {
    return '';
  } else if (path[0] === '?') {
    path = '/v2/login' + path;
  } else if (path[0] !== '/') {
    path = '/v2/' + path;
  }
  if (/^\/v2\/health(?:[/?]|$)/.test(path)) return '';
  return path;
}

function login(state) {
  const form = request('GET', '/v2/login-form');
  const csrf = form.status === 200 ? formToken(form) : '';
  if (!verified(form, 'login form supplies CSRF', token(csrf))) return false;

  const response = request('POST', '/v2/login', {
    username: state.username,
    password: 'bench',
    csrf,
  });
  if (!verified(response, 'login succeeds or redirects',
    successful(response) || response.status === 302)) return false;

  const loginData = payload(response);
  let sessionCSRF = loginData.csrf;
  let grant = loginData.grant_id;
  if (response.status === 302) {
    const location = loginLocation(header(response, 'Location'));
    if (!verified(response, 'login redirect supplies a local Location', !!location)) return false;

    const follow = request('GET', location);
    if (!verified(follow, 'login redirect completes', successful(follow))) return false;

    const data = payload(follow);
    if (token(data.csrf)) sessionCSRF = data.csrf;
    if (hasId(data.grant_id)) grant = data.grant_id;
  }

  if (!verified(response, 'login supplies session CSRF', token(sessionCSRF))) return false;
  state.csrf = sessionCSRF;
  state.grant = hasId(grant) ? grant : undefined;
  return true;
}

function post(state, path, body, headers = {}) {
  return request('POST', path, body, { ...headers, 'X-CSRF-Token': state.csrf });
}

function recoverSession(state, reason) {
  if (reason === 'session') {
    if (!login(state)) return false;
  } else {
    const response = post(state, '/v2/session/renew', {});
    const data = payload(response);
    if (!verified(response, 'session renewal supplies fresh CSRF',
      successful(response) && token(data.csrf))) return false;
    state.csrf = data.csrf;
  }

  if (state.cart !== undefined) {
    const response = post(state, '/v2/carts/' + encodeURIComponent(state.cart) + '/recover', {});
    if (!verified(response, 'existing cart recovered', successful(response))) return false;
    const data = payload(response);
    if (token(data.csrf)) state.csrf = data.csrf;
    state.etag = header(response, 'ETag') || state.etag;
  }
  return true;
}

function withSession(state, send) {
  let response = send();
  let data = payload(response);
  if (response.status === 401 &&
      (data.error === 'expired' || data.error === 'session') &&
      recoverSession(state, data.error)) {
    response = send();
    data = payload(response);
  }
  if (successful(response) && token(data.csrf)) state.csrf = data.csrf;
  return { response, data };
}

function checkout(state) {
  if (!login(state)) return false;

  const catalog = withSession(state, () => request('GET', '/v2/catalog'));
  const products = catalog.data.data && catalog.data.data.products;
  const product = Array.isArray(products) && products.find((entry) => {
    const variant = entry && entry.variants && entry.variants[0];
    return variant && variant.in_stock === true;
  });
  if (!verified(catalog.response, 'catalog supplies the first eligible product and variant',
    catalog.response.status === 200 && !!product &&
    hasId(product.id) && hasId(product.variants[0].id))) return false;

  const cart = withSession(state, () => {
    const body = { product_id: product.id, variant_id: product.variants[0].id };
    if (state.grant !== undefined) body.grant_id = state.grant;
    return post(state, '/v2/carts', body);
  });
  state.grant = undefined;
  if (!verified(cart.response, 'cart created',
    cart.response.status === 201 && typeof cart.data.id === 'string' &&
    cart.data.id.indexOf('cart-') === 0)) return false;

  state.cart = cart.data.id;
  state.etag = header(cart.response, 'ETag');
  const orderBody = { cart_id: state.cart };
  const order = withSession(state, () => {
    const headers = { 'Idempotency-Key': state.cart };
    if (state.etag) headers['If-Match'] = state.etag;
    return post(state, '/v2/orders', orderBody, headers);
  });

  return verified(order.response, 'checkout committed',
    order.response.status === 201 && order.data.accepted === true && hasId(order.data.id));
}

export default function () {
  let committed = false;
  try {
    committed = checkout({ username: 'bench-' + __VU });
  } finally {
    journeyFailure.add(!committed);
  }
}

import os
import time
from html.parser import HTMLParser
from itertools import count
from urllib.parse import quote, urljoin, urlsplit

from gevent import sleep
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ["BASE_URL"].rstrip("/")
if BASE_URL != "http://127.0.0.1:8000":
    raise ValueError("BASE_URL must be http://127.0.0.1:8000")

USERS = 4
RATE = 2.0
INTERVAL = 1.0 / RATE
WARMUP = 5.0
SCORED_DURATION = 30.0
WORK_DURATION = WARMUP + SCORED_DURATION
SOURCE_DURATION = 38.0
PREP_LEAD = 0.65
MAX_LATENESS = 0.45
ORDERS = "/v2/orders"

_user_numbers = count()
_anchor = None
_establishing_anchor = False


class JourneyFailed(Exception):
    pass


class RecoverableSession(Exception):
    pass


class LoginFields(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.form_priority = 0
        self.candidates = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "form":
            action = urlsplit(attrs.get("action") or "").path.rstrip("/")
            if action == "/v2/login":
                self.form_priority = 3
            elif not action:
                self.form_priority = 2
            else:
                self.form_priority = 0
        elif tag == "input":
            value = attrs.get("value")
            if attrs.get("name") == "csrf" and value and "disabled" not in attrs:
                hidden = (attrs.get("type") or "").lower() == "hidden"
                self.candidates.append(((self.form_priority, hidden), value))

    def handle_endtag(self, tag):
        if tag == "form":
            self.form_priority = 0

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        if tag == "form":
            self.handle_endtag(tag)


def json_object(response):
    data = response.json()
    if not isinstance(data, dict):
        raise JourneyFailed("Expected a JSON object")
    return data


def optional_json_object(response):
    try:
        data = response.json()
    except ValueError:
        return {}
    return data if isinstance(data, dict) else {}


def redirect_path(response, request_path):
    location = response.headers.get("Location")
    if not location:
        raise JourneyFailed("Redirect missing Location")
    target = urlsplit(urljoin(BASE_URL + request_path, location))
    if (target.scheme, target.netloc) != ("http", "127.0.0.1:8000"):
        raise JourneyFailed("Redirect does not point to the shop")
    return (target.path or "/") + ("?" + target.query if target.query else "")


def login_form_token(response):
    parser = LoginFields()
    parser.feed(response.text)
    parser.close()
    if not parser.candidates:
        raise JourneyFailed("Login form missing input[name=csrf]")
    return max(parser.candidates, key=lambda candidate: candidate[0])[1]


class CheckoutUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.index = next(_user_numbers)
        if self.index >= USERS:
            raise StopUser()
        self.username = f"bench-{self.index + 1}"
        self.client.trust_env = False
        self.slot = (self.index - 1) % USERS

    def _request(
        self, method, path, decode, *, statuses=(200,), body=None,
        authenticated=False, recoverable=(), checkout=False, name=None
    ):
        headers = {}
        if authenticated and method != "GET":
            headers["X-CSRF-Token"] = self.csrf
        if checkout:
            headers["Idempotency-Key"] = self.cart
            if self.etag:
                headers["If-Match"] = self.etag
            if _anchor is not None and time.monotonic() >= _anchor + WORK_DURATION:
                raise StopUser()

        kwargs = {"json": body} if body is not None else {}
        started = time.monotonic()
        failure = None
        recovery = None
        result = None
        with self.client.request(
            method, BASE_URL + path, name=name, headers=headers,
            allow_redirects=False, timeout=(2.0, 3.0), catch_response=True,
            **kwargs
        ) as response:
            status = response.status_code
            error = optional_json_object(response).get("error") if status == 401 else None
            if status == 401 and error in recoverable:
                recovery = error
                response.success()
            elif status not in statuses:
                failure = f"Expected HTTP {statuses}, got {status}"
                if error:
                    failure += f" ({error})"
            else:
                try:
                    result = decode(response)
                except (JourneyFailed, ValueError) as exc:
                    failure = str(exc) or "Invalid response"
            if failure is not None:
                response.failure(failure)

        if failure is not None:
            raise JourneyFailed(failure)
        if recovery is not None:
            raise RecoverableSession(recovery)
        return result, started

    def _update_csrf(self, data, required=False):
        token = data.get("csrf")
        if isinstance(token, str) and token:
            self.csrf = token
        elif required:
            raise JourneyFailed("Response missing csrf")

    def _finish_login(self, response):
        data = json_object(response)
        self._update_csrf(data, required=not self.csrf)
        self.grant = data.get("grant_id")

    def _login_response(self, response):
        if response.status_code == 302:
            self._update_csrf(optional_json_object(response))
            return redirect_path(response, "/v2/login")
        self._update_csrf(json_object(response), required=True)
        return None

    def _login(self):
        self.csrf = None
        self.grant = None
        token, _ = self._request("GET", "/v2/login-form", login_form_token)
        location, _ = self._request(
            "POST", "/v2/login", self._login_response, statuses=(200, 302),
            body={"username": self.username, "password": "bench", "csrf": token}
        )
        if location is not None:
            self._request("GET", location, self._finish_login, name="/v2/login [redirect]")

    def _renewed(self, response):
        self._update_csrf(json_object(response), required=True)

    def _cart_recovered(self, response):
        if response.content:
            self._update_csrf(json_object(response))
        self.etag = response.headers.get("ETag") or self.etag

    def _recover(self, reason):
        if reason == "expired":
            try:
                self._request(
                    "POST", "/v2/session/renew", self._renewed, body={},
                    authenticated=True, recoverable=("session",)
                )
            except RecoverableSession:
                self._login()
        else:
            self._login()

        if self.cart is not None:
            path = "/v2/carts/" + quote(self.cart, safe="") + "/recover"
            self._request(
                "POST", path, self._cart_recovered, statuses=(200, 204),
                body={}, authenticated=True, name="/v2/carts/:id/recover"
            )

    def _authenticated(self, method, path, decode, *, payload=None, **kwargs):
        try:
            return self._request(
                method, path, decode, body=payload() if payload else None,
                authenticated=True, recoverable=("expired", "session"), **kwargs
            )
        except RecoverableSession as exc:
            self._recover(exc.args[0])

        return self._request(
            method, path, decode, body=payload() if payload else None,
            authenticated=True, **kwargs
        )

    def _catalog_selection(self, response):
        data = json_object(response)
        self._update_csrf(data)
        catalog = data.get("data")
        products = catalog.get("products") if isinstance(catalog, dict) else None
        if not isinstance(products, list):
            raise JourneyFailed("Catalog missing products")
        for product in products:
            if not isinstance(product, dict):
                continue
            variants = product.get("variants")
            if not isinstance(variants, list) or not variants:
                continue
            variant = variants[0]
            if (
                isinstance(variant, dict) and variant.get("in_stock") is True
                and product.get("id") and variant.get("id")
            ):
                return product["id"], variant["id"]
        raise JourneyFailed("No product with an in-stock first variant")

    def _cart_created(self, response):
        data = json_object(response)
        cart = data.get("id")
        etag = response.headers.get("ETag")
        if not isinstance(cart, str) or not cart.startswith("cart-"):
            raise JourneyFailed("Cart creation did not return a cart ID")
        if not etag:
            raise JourneyFailed("Cart creation did not return an ETag")
        self._update_csrf(data)
        self.cart, self.etag = cart, etag
        self.grant = None

    def _order_accepted(self, response):
        data = json_object(response)
        if data.get("accepted") is not True or not data.get("id"):
            raise JourneyFailed("Checkout did not accept the order")
        self._update_csrf(data)

    def _journey(self, due=None):
        self.cart = None
        self.etag = None
        self._login()
        (product, variant), _ = self._authenticated(
            "GET", "/v2/catalog", self._catalog_selection
        )

        def cart_payload():
            body = {"product_id": product, "variant_id": variant}
            if self.grant:
                body["grant_id"] = self.grant
            return body

        self._authenticated(
            "POST", "/v2/carts", self._cart_created,
            statuses=(201,), payload=cart_payload
        )
        if due is not None:
            sleep(max(0.0, due - time.monotonic()))

        _, started = self._authenticated(
            "POST", ORDERS, self._order_accepted, statuses=(200, 201),
            payload=lambda: {"cart_id": self.cart}, checkout=True,
            require_created=True
        )
        return started

    @task
    def checkout(self):
        global _anchor, _establishing_anchor
        if _anchor is None:
            if _establishing_anchor:
                sleep(0.01)
                return
            _establishing_anchor = True
            try:
                _anchor = self._journey()
            except JourneyFailed:
                sleep(INTERVAL)
            finally:
                _establishing_anchor = False
            return

        # Place regular starts between the scoring boundaries, with fixed VU phases.
        due = _anchor + 1.5 * INTERVAL + self.slot * INTERVAL
        if due >= _anchor + WORK_DURATION:
            raise StopUser()
        self.slot += USERS
        now = time.monotonic()
        if now > due + MAX_LATENESS:
            return
        sleep(max(0.0, due - PREP_LEAD - now))
        if time.monotonic() >= _anchor + WORK_DURATION:
            raise StopUser()
        try:
            self._journey(due)
        except JourneyFailed:
            pass


class CheckoutShape(LoadTestShape):
    def tick(self):
        elapsed = self.get_run_time()
        if _anchor is None:
            if elapsed >= 10.0:
                return None
        elif (
            elapsed >= SOURCE_DURATION
            and time.monotonic() >= _anchor + WORK_DURATION + 2.5
        ):
            return None
        return USERS, USERS

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
    private static final int USERS = 2;
    private static final int ITERATIONS = 2;
    private static final String ORIGIN = "http://127.0.0.1:8000";
    private static final String CHECKOUT = "Checkout";

    private static String baseUrl() {
        String configured = System.getenv("BASE_URL");
        return ORIGIN.equals(configured) ? configured : ORIGIN;
    }

    private static String cartBody(Session session) {
        String body = "{\"product_id\":\"" + session.getString("product")
                + "\",\"variant_id\":\"" + session.getString("variant") + "\"";
        if (session.contains("grant")) {
            body += ",\"grant_id\":\"" + session.getString("grant") + "\"";
        }
        return body + "}";
    }

    private static final ChainBuilder LOGIN =
        exec(http("GET /v2/login-form")
            .get("/v2/login-form")
            .check(status().is(200),
                   css("input[name='csrf'][value]", "value").saveAs("formCsrf")))
        .doIf(session -> session.contains("formCsrf")).then(
            exec(http("POST /v2/login")
                .post("/v2/login")
                .asJson()
                .body(StringBody(
                    "{\"username\":#{username.jsonStringify()},\"password\":\"bench\","
                    + "\"csrf\":#{formCsrf.jsonStringify()}}"))
                .check(
                    status().in(200, 302),
                    regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").saveAs("csrf"),
                    checkIf((response, session) -> response.status().code() == 302)
                        .then(header("Location").saveAs("loginLocation"))))
            .doIf(session -> session.contains("loginLocation")).then(
                exec(http("GET login redirect")
                    .get("#{loginLocation}")
                    .check(status().is(200),
                           jsonPath("$.csrf").optional().saveAs("csrf"),
                           jsonPath("$.grant_id").optional().saveAs("grant")))));

    private static final ChainBuilder PLACE_ORDER =
        exitBlockOnFail().on(
            exec(http("GET /v2/catalog")
                .get("/v2/catalog")
                .check(
                    status().is(200),
                    jmesPath("data.products[?variants[0].in_stock == `true`] | [0].id")
                        .saveAs("product"),
                    jmesPath("data.products[?variants[0].in_stock == `true`] | [0].variants[0].id")
                        .saveAs("variant")))
            .exec(http("POST /v2/carts")
                .post("/v2/carts")
                .asJson()
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(ModelSimulation::cartBody))
                .check(
                    status().is(201),
                    regex("\"id\"\\s*:\\s*\"(cart-[^\"]*)\"").saveAs("cart"),
                    header("ETag").saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(http("POST /v2/orders")
                .post("/v2/orders")
                .asJson()
                .header("X-CSRF-Token", "#{csrf}")
                .header("If-Match", "#{etag}")
                .header("Idempotency-Key", "#{cart}")
                .body(StringBody("{\"cart_id\":#{cart.jsonStringify()}}"))
                .check(
                    status().in(200, 201),
                    jsonPath("$.accepted").ofBoolean().is(true).saveAs("orderAccepted"),
                    checkIf((response, session) -> session.contains("orderAccepted"))
                        .then(status().is(201)),
                    jsonPath("$.csrf").optional().saveAs("csrf"))));

    public ModelSimulation() {
        HttpProtocolBuilder protocol = http.baseUrl(baseUrl())
            .disableFollowRedirect()
            .disableCaching();

        ScenarioBuilder users = scenario("Shop checkout")
            .repeat(ITERATIONS).on(
                exec(flushCookieJar())
                .exec(session -> session.reset().markAsSucceeded()
                    .set("username", "bench-" + (1 + Math.floorMod(session.userId() - 1, USERS))))
                .group(CHECKOUT).on(
                    exec(LOGIN)
                    .doIf(session -> session.contains("csrf")).then(PLACE_ORDER)));

        setUp(users.injectOpen(atOnceUsers(USERS)))
            .protocols(protocol)
            .assertions(
                details(CHECKOUT).allRequests().count().is(USERS * ITERATIONS),
                details(CHECKOUT).failedRequests().percent().is(0.0));
    }
}

