import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
    private static final int USERS = 2;
    private static final int ITERATIONS = 2;
    private static final String ORIGIN = "http://127.0.0.1:8000";
    private static final String CHECKOUT = "Checkout";

    private static String baseUrl() {
        String configured = System.getenv("BASE_URL");
        return ORIGIN.equals(configured) ? configured : ORIGIN;
    }

    private static String cartBody(Session session) {
        String body = "{\"product_id\":\"" + session.getString("product")
                + "\",\"variant_id\":\"" + session.getString("variant") + "\"";
        if (session.contains("grant")) {
            body += ",\"grant_id\":\"" + session.getString("grant") + "\"";
        }
        return body + "}";
    }

    private static final ChainBuilder LOGIN =
        exec(http("GET /v2/login-form")
            .get("/v2/login-form")
            .check(status().is(200),
                   css("input[name='csrf'][value]", "value").saveAs("formCsrf")))
        .doIf(session -> session.contains("formCsrf")).then(
            exec(http("POST /v2/login")
                .post("/v2/login")
                .asJson()
                .body(StringBody(
                    "{\"username\":#{username.jsonStringify()},\"password\":\"bench\","
                    + "\"csrf\":#{formCsrf.jsonStringify()}}"))
                .check(
                    status().in(200, 302),
                    regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").saveAs("csrf"),
                    checkIf((response, session) -> response.status().code() == 302)
                        .then(header("Location").saveAs("loginLocation"))))
            .doIf(session -> session.contains("loginLocation")).then(
                exec(http("GET login redirect")
                    .get("#{loginLocation}")
                    .check(status().is(200),
                           jsonPath("$.csrf").optional().saveAs("csrf"),
                           jsonPath("$.grant_id").optional().saveAs("grant")))));

    private static final ChainBuilder PLACE_ORDER =
        exitBlockOnFail().on(
            exec(http("GET /v2/catalog")
                .get("/v2/catalog")
                .check(
                    status().is(200),
                    jmesPath("data.products[?variants[0].in_stock == `true`] | [0].id")
                        .saveAs("product"),
                    jmesPath("data.products[?variants[0].in_stock == `true`] | [0].variants[0].id")
                        .saveAs("variant")))
            .exec(http("POST /v2/carts")
                .post("/v2/carts")
                .asJson()
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(ModelSimulation::cartBody))
                .check(
                    status().is(201),
                    regex("\"id\"\\s*:\\s*\"(cart-[^\"]*)\"").saveAs("cart"),
                    header("ETag").saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(http("POST /v2/orders")
                .post("/v2/orders")
                .asJson()
                .header("X-CSRF-Token", "#{csrf}")
                .header("If-Match", "#{etag}")
                .header("Idempotency-Key", "#{cart}")
                .body(StringBody("{\"cart_id\":#{cart.jsonStringify()}}"))
                .check(
                    status().in(200, 201),
                    jsonPath("$.accepted").ofBoolean().is(true).saveAs("orderAccepted"),
                    checkIf((response, session) -> session.contains("orderAccepted"))
                        .then(status().is(201)),
                    jsonPath("$.csrf").optional().saveAs("csrf"))));

    public ModelSimulation() {
        HttpProtocolBuilder protocol = http.baseUrl(baseUrl())
            .disableFollowRedirect()
            .disableCaching();

        ScenarioBuilder users = scenario("Shop checkout")
            .repeat(ITERATIONS).on(
                exec(flushCookieJar())
                .exec(session -> session.reset().markAsSucceeded()
                    .set("username", "bench-" + (1 + Math.floorMod(session.userId() - 1, USERS))))
                .group(CHECKOUT).on(
                    exec(LOGIN)
                    .doIf(session -> session.contains("csrf")).then(PLACE_ORDER)));

        setUp(users.injectOpen(atOnceUsers(USERS)))
            .protocols(protocol)
            .assertions(
                details(CHECKOUT).allRequests().count().is(USERS * ITERATIONS),
                details(CHECKOUT).failedRequests().percent().is(0.0));
    }
}

