import http from 'k6/http';
import { check, group } from 'k6';
import { Rate } from 'k6/metrics';

const TARGET = 'http://127.0.0.1:8000';
const BASE_URL = (__ENV.BASE_URL || TARGET).replace(/\/+$/, '');
if (BASE_URL !== TARGET) {
  throw new Error('BASE_URL must target http://127.0.0.1:8000');
}

const TX = { transaction: 'checkout' };
const transactionFailed = new Rate('transaction_failed');

export const options = {
  scenarios: {
    shop: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '1m',
    },
  },
  noCookiesReset: false,
  thresholds: {
    'transaction_failed{transaction:checkout}': ['rate==0'],
  },
};

function tags(step) {
  return { transaction: TX.transaction, step };
}

function send(method, path, name, step, body, headers = {}) {
  const params = { redirects: 0, timeout: '3s', tags: { ...tags(step), name } };
  if (body !== undefined) {
    params.headers = { 'Content-Type': 'application/json', ...headers };
  }
  return http.request(
    method,
    BASE_URL + path,
    body === undefined ? null : JSON.stringify(body),
    params,
  );
}

function mutate(state, path, name, step, body, headers = {}) {
  return send('POST', path, name, step, body, {
    'X-CSRF-Token': state.csrf,
    ...headers,
  });
}

function json(response) {
  try {
    return response.json() || {};
  } catch (_) {
    return {};
  }
}

function header(response, name) {
  const key = Object.keys(response.headers).find((k) => k.toLowerCase() === name);
  return key ? response.headers[key].trim() : '';
}

function token(value) {
  return typeof value === 'string' && value.length > 0;
}

function refresh(state, response, data) {
  if (response.status >= 200 && response.status < 300 && token(data.csrf)) {
    state.csrf = data.csrf;
  }
}

function redirectPath(location, from) {
  const value = location.split('#')[0];
  if (!value || /[\\\s]/.test(value)) return null;

  const absolute = value.startsWith('//') ? `http:${value}` : value;
  if (absolute === BASE_URL) return '/';
  if (absolute.startsWith(`${BASE_URL}/`)) return absolute.slice(BASE_URL.length);
  if (absolute.startsWith(`${BASE_URL}?`)) return `/${absolute.slice(BASE_URL.length)}`;
  if (/^[a-z][a-z\d+.-]*:/i.test(absolute)) return null;

  if (value.startsWith('/')) return value;
  if (value.startsWith('?')) return from.split('?')[0] + value;
  return from.slice(0, from.lastIndexOf('/') + 1) + value;
}

function login(state) {
  const form = send('GET', '/v2/login-form', 'GET /v2/login-form', 'login_form');
  const formCsrf = form.status === 200
    ? form.html().find('input[name="csrf"][value]').first().attr('value')
    : null;

  if (!check(formCsrf, { 'login form: csrf input found': token }, tags('login_form'))) {
    return false;
  }

  const path = '/v2/login';
  const response = send('POST', path, 'POST /v2/login', 'login', {
    username: state.username,
    password: 'bench',
    csrf: formCsrf,
  });
  const initial = json(response);
  let effective = response;
  let data = initial;

  if (response.status === 302) {
    const next = redirectPath(header(response, 'location'), path);
    if (next) {
      effective = send('GET', next, 'GET login Location', 'login_redirect');
      data = json(effective);
    }
  }

  const csrf = token(data.csrf) ? data.csrf : initial.csrf;
  const assertionBody = token(data.csrf) ? effective.body : response.body;
  const ok = check(effective, {
    'login response contains csrf': (r) =>
      r.status === 200 && /"csrf"\s*:/.test(assertionBody) && token(csrf),
  }, tags('login'));

  if (ok) {
    state.csrf = csrf;
    state.grant = data.grant_id || initial.grant_id || null;
  }
  return ok;
}

function recoveryReason(response) {
  if (response.status !== 401) return null;
  const error = json(response).error;
  return error === 'expired' || error === 'session' ? error : null;
}

function recoverSession(state, reason) {
  const renewal = mutate(
    state, '/v2/session/renew', 'POST /v2/session/renew', 'session_renew', {},
  );
  if (renewal.status >= 200 && renewal.status < 300) {
    refresh(state, renewal, json(renewal));
  } else {
    const error = json(renewal).error;
    const revoked = recoveryReason(renewal) === 'session' ||
      (reason === 'session' && renewal.status === 401 && error !== 'denied');
    if (!revoked || !login(state)) return false;
  }

