import os
from html.parser import HTMLParser
from urllib.parse import quote, urljoin, urlsplit

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
USERS = 2
ITERATIONS_PER_USER = 2
CHECKOUT_METRIC = "/v2/orders"
MAX_CHECKOUT_ERROR_RATE = 0.0


class PlanState:
    def __init__(self):
        self.users_started = 0
        self.users_finished = 0
        self.checkout_attempts = 0
        self.checkout_failures = 0


def plan_state(environment):
    state = getattr(environment, "_shop_plan_state", None)
    if state is None:
        state = environment._shop_plan_state = PlanState()
    return state


class AssertionFailed(Exception):
    pass


def require(condition, message):
    if not condition:
        raise AssertionFailed(message)


def token(value):
    return isinstance(value, str) and bool(value)


class LoginForm(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_form = False
        self.action = None
        self.inputs = []

    def handle_starttag(self, tag, attributes):
        attrs = dict(attributes)
        if tag == "form":
            self.in_form = True
            self.action = attrs.get("action") or ""
        elif tag == "input" and attrs.get("name") == "csrf" and "disabled" not in attrs:
            value = attrs.get("value")
            if token(value):
                login_form = self.in_form and self.action.split("?", 1)[0].rstrip("/") in (
                    "/v2/login", "login", "./login"
                )
                rank = (bool(login_form), self.in_form, (attrs.get("type") or "").lower() == "hidden")
                self.inputs.append((rank, value))

    def handle_endtag(self, tag):
        if tag == "form":
            self.in_form = False
            self.action = None

    def csrf(self):
        return max(self.inputs, key=lambda item: item[0])[1] if self.inputs else None


def login_location(response):
    location = response.headers.get("Location")
    require(token(location), "Login redirect is missing Location")
    try:
        target = urlsplit(urljoin(response.url, location))
    except ValueError:
        raise AssertionFailed("Invalid login redirect Location")
    require(
        (target.scheme, target.netloc) == ("http", "127.0.0.1:8000")
        and not target.path.startswith("//"),
        "Login redirect must stay on the shop origin",
    )
    return (target.path or "/") + (("?" + target.query) if target.query else "")


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.plan = plan_state(self.environment)
        self.plan.users_started += 1
        self.username = f"bench-{self.plan.users_started}"
        self.iterations = 0

    def on_stop(self):
        self.plan.users_finished += 1

    def sample(
        self, method, path, name, check, *, body=None, authenticated=False,
        recoverable=False, if_match=False, order_key=None
    ):
        headers = {"Content-Type": "application/json"}
        if authenticated and method != "GET":
            headers["X-CSRF-Token"] = self.csrf
        if if_match and self.etag:
            headers["If-Match"] = self.etag
        if order_key is not None:
            headers["Idempotency-Key"] = order_key

        context = {"transaction": "checkout"} if order_key is not None else {}
        with self.client.request(
            method, path, name=name, headers=headers, json=body,
            context=context, catch_response=True, allow_redirects=False, timeout=(2, 3)
        ) as response:
            try:
                data = response.json()
            except ValueError:
                data = None
            if not isinstance(data, dict):
                data = {}

            reason = data.get("error")
            if recoverable and response.status_code == 401 and reason in ("expired", "session"):
                if name == CHECKOUT_METRIC:
                    response.request_meta["name"] = "/v2/orders [session interruption]"
                response.success()
                return None, reason

            try:
                value = check(response, data)
            except AssertionFailed as exc:
                response.failure(str(exc))
                return None, None

            if token(data.get("csrf")):
                self.csrf = data["csrf"]
            response.success()
            return value, None

    def login(self):
        self.csrf = ""
        self.grant = None

        def check_form(response, _data):
            require(response.status_code == 200, "Login form: expected HTTP 200")
            parser = LoginForm()
            parser.feed(response.text)
            parser.close()
            value = parser.csrf()
            require(token(value), "Login form: missing input[name=csrf] value")
            return value

        form_csrf, _ = self.sample("GET", "/v2/login-form", "/v2/login-form", check_form)
        if form_csrf is None:
            return False

        def check_login(response, data):
            if response.status_code == 302:
                return login_location(response)
            require(response.status_code == 200, "Login: expected HTTP 200 or 302")
            require(token(data.get("csrf")), "Login assertion: missing csrf")
            return ""

        location, _ = self.sample(
            "POST", "/v2/login", "/v2/login", check_login,
            body={"username": self.username, "password": "bench", "csrf": form_csrf},
        )
        if location is None:
            return False
        if not location:
            return True

        def check_landing(response, data):
            require(response.status_code == 200, "Login redirect target: expected HTTP 200")
            require(token(data.get("csrf")) or token(self.csrf), "Login assertion: missing csrf")
            return data

        landing, _ = self.sample("GET", location, "/v2/login [redirect]", check_landing)
        if landing is None:
            return False
        if token(landing.get("grant_id")):
            self.grant = landing["grant_id"]
        return True

    def recover_session(self, reason):
        if reason == "session":
            self.client.cookies.clear()
            if not self.login():
                return False
        else:
            def check_renew(response, data):
                require(200 <= response.status_code < 300, "Session renewal failed")
                require(token(data.get("csrf")), "Session renewal: missing csrf")
                return True

            renewed, _ = self.sample(
                "POST", "/v2/session/renew", "/v2/session/renew", check_renew,
                body={}, authenticated=True,
            )
            if renewed is None:
                return False

        if self.cart is None:
            return True

        path = "/v2/carts/" + quote(self.cart, safe="")

        def check_recover(response, _data):
            require(200 <= response.status_code < 300, "Cart recovery failed")
            return response.headers.get("ETag", "")

        etag, _ = self.sample(
            "POST", path + "/recover", "/v2/carts/{id}/recover", check_recover,
            body={}, authenticated=True,
        )
        if etag is None:
            return False
        if not etag:
            def check_cart(response, _data):
                require(response.status_code == 200, "Cart read: expected HTTP 200")
                value = response.headers.get("ETag")
                require(token(value), "Cart read: missing ETag")
                return value

            etag, _ = self.sample("GET", path, "/v2/carts/{id}", check_cart)
            if etag is None:
                return False
        self.etag = etag
        return True

    def operation(self, method, path, check, *, body=None, if_match=False, order_key=None):
        def send(recoverable):
            return self.sample(
                method, path, path, check, body=body() if callable(body) else body,
                authenticated=True, recoverable=recoverable, if_match=if_match,
                order_key=order_key,
            )

        result, reason = send(True)
        if reason is not None and self.recover_session(reason):
            result, _ = send(False)
        return result

    def journey(self):
        self.client.cookies.clear()
        self.cart = None
        self.etag = None
        if not self.login():
            return

        def check_catalog(response, data):
            require(response.status_code == 200, "Catalog: expected HTTP 200")
            catalog = data.get("data")
            products = catalog.get("products") if isinstance(catalog, dict) else None
            require(isinstance(products, list), "Catalog: missing products")
            for product in products:
                if not isinstance(product, dict):
                    continue
                variants = product.get("variants")
                if not isinstance(variants, list) or not variants:
                    continue
                variant = variants[0]
                if isinstance(variant, dict) and variant.get("in_stock") is True:
                    product_id, variant_id = product.get("id"), variant.get("id")
                    require(token(product_id) and token(variant_id), "Catalog: missing selected IDs")
                    return product_id, variant_id
            raise AssertionFailed("Catalog: no product with an in-stock first variant")

        selection = self.operation("GET", "/v2/catalog", check_catalog)
        if selection is None:
            return
        product_id, variant_id = selection

        def cart_body():
            body = {"product_id": product_id, "variant_id": variant_id}
            if self.grant is not None:
                body["grant_id"] = self.grant
            return body

        def check_create(response, data):
            require(response.status_code == 201, "Cart creation: expected HTTP 201")
            cart_id = data.get("id")
            require(token(cart_id) and cart_id.startswith("cart-"), "Cart assertion: expected a cart- ID")
            return cart_id, response.headers.get("ETag")

        created = self.operation("POST", "/v2/carts", check_create, body=cart_body)
        if created is None:
            return
        self.cart, self.etag = created
        self.grant = None

        def check_order(response, data):
            require(response.status_code in (200, 201), f"Checkout: unexpected HTTP {response.status_code}")
            require(data.get("accepted") is True, "Checkout assertion: accepted must be true")
            require(response.status_code == 201, "Checkout: expected HTTP 201 for an accepted order")
            return True

        # Count one logical checkout, including any session recovery and retry.
        self.plan.checkout_attempts += 1
        accepted = None
        try:
            accepted = self.operation(
                "POST", CHECKOUT_METRIC, check_order, body={"cart_id": self.cart},
                if_match=True, order_key=self.cart,
            )
        finally:
            if accepted is not True:
                self.plan.checkout_failures += 1

    @task
    def run_iteration(self):
        if self.iterations >= ITERATIONS_PER_USER:
            raise StopUser()
        self.iterations += 1
        self.journey()
        if self.iterations >= ITERATIONS_PER_USER:
            raise StopUser()


class ShopPlanShape(LoadTestShape):
    def tick(self):
        environment = self.runner.environment
        state = plan_state(environment)
        if state.users_finished < USERS:
            return USERS, USERS

        # Setup and retry samples do not belong to the checkout denominator.
        attempts = state.checkout_attempts
        threshold_breached = (
            attempts == 0
            or state.checkout_failures / attempts > MAX_CHECKOUT_ERROR_RATE
        )
        environment.process_exit_code = int(threshold_breached)
        return None

