import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;
import io.gatling.javaapi.http.HttpRequestActionBuilder;

public class ModelSimulation extends Simulation {
    private static final HttpProtocolBuilder HTTP = http
        .baseUrl(System.getenv("BASE_URL"))
        .disableWarmUp()
        .disableFollowRedirect()
        .acceptHeader("application/json");

    private static final String IN_STOCK_PRODUCTS =
        "data.products[?variants[?in_stock == `true`]]";

    private static ChainBuilder login() {
        return exec(flushCookieJar())
            .exec(session -> session.remove("formCsrf").remove("loginLocation").remove("csrf"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200),
                    css("input[name=csrf][value]", "value").saveAs("formCsrf")))
            .exitHereIfFailed()
            .exec(http("login").post("/v2/login")
                .asJson()
                .body(StringBody(
                    "{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{formCsrf}\"}"))
                .check(status().in(200, 302))
                .checkIf((response, session) -> response.status().code() == 200)
                .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((response, session) -> response.status().code() == 302)
                .then(header("Location").saveAs("loginLocation")))
            .exitHereIfFailed()
            .exec(doIf(session -> session.contains("loginLocation")).then(
                exec(http("login redirect").get("#{loginLocation}")
                    .check(status().is(200), jsonPath("$.csrf").saveAs("csrf")))))
            .exitHereIfFailed();
    }

    private static ChainBuilder recoverSession() {
        ChainBuilder renew = exec(http("renew session").post("/v2/session/renew")
                .asJson()
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().in(200, 401), status().saveAs("renewStatus"))
                .checkIf((response, session) -> response.status().code() == 200)
                .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((response, session) -> response.status().code() == 401)
                .then(jsonPath("$.error").is("session")))
            .exitHereIfFailed()
            .exec(doIf(session -> session.getInt("renewStatus") == 401).then(login()));

        return exec(doIfOrElse(session -> "session".equals(session.getString("authError")))
                .then(login())
                .orElse(renew))
            .exec(doIf(session -> session.contains("cartId")).then(
                exec(http("recover cart").post("/v2/carts/#{cartId}/recover")
                    .asJson()
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .check(status().is(200),
                        header("ETag").optional().saveAs("etag"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))))
            .exitHereIfFailed();
    }

    private static HttpRequestActionBuilder checkStatus(
            HttpRequestActionBuilder request, int expected, boolean recoverable) {
        if (!recoverable) {
            return request.check(status().is(expected));
        }
        return request.check(status().in(expected, 401), status().saveAs("operationStatus"))
            .checkIf((response, session) -> response.status().code() == 401)
            .then(jsonPath("$.error").in("expired", "session").saveAs("authError"));
    }

    private static ChainBuilder runOperation(
            HttpRequestActionBuilder first, HttpRequestActionBuilder retry) {
        return exec(first)
            .exitHereIfFailed()
            .exec(doIf(session -> session.getInt("operationStatus") == 401).then(
                recoverSession().exec(retry)))
            .exitHereIfFailed();
    }

    private static HttpRequestActionBuilder catalog(String name, boolean recoverable) {
        return checkStatus(http(name).get("/v2/catalog"), 200, recoverable)
            .checkIf((response, session) -> response.status().code() == 200)
            .then(
                jmesPath(IN_STOCK_PRODUCTS + ".id | [0]").saveAs("productId"),
                jmesPath(IN_STOCK_PRODUCTS
                    + " | [0].variants[?in_stock == `true`].id | [0]").saveAs("variantId"));
    }

    private static HttpRequestActionBuilder createCart(String name, boolean recoverable) {
        return checkStatus(http(name).post("/v2/carts")
                .asJson()
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{\"product_id\":\"#{productId}\",\"variant_id\":\"#{variantId}\"}")),
                201, recoverable)
            .checkIf((response, session) -> response.status().code() == 201)
            .then(jsonPath("$.id").saveAs("cartId"),
                header("ETag").saveAs("etag"),
                jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    private static HttpRequestActionBuilder checkout(String name, boolean recoverable) {
        return checkStatus(http(name).post("/v2/orders")
                .asJson()
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{cartId}")
                .header("If-Match", "#{etag}")
                .body(StringBody("{\"cart_id\":\"#{cartId}\"}")),
                201, recoverable)
            .checkIf((response, session) -> response.status().code() == 201)
            .then(jsonPath("$.accepted").ofBoolean().is(true),
                jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    private static ChainBuilder flow() {
        return exec(session -> session.remove("productId").remove("variantId")
                .remove("cartId").remove("etag").remove("authError")
                .remove("operationStatus").remove("renewStatus"))
            .exec(login())
            .exec(runOperation(catalog("catalog", true), catalog("catalog retry", false)))
            .exec(runOperation(createCart("cart", true), createCart("cart retry", false)))
            .exec(runOperation(checkout("checkout", true), checkout("checkout retry", false)));
    }

    public ModelSimulation() {
        setUp(scenario("shop flow")
                .exec(session -> session.set("username",
                    "bench-" + (Math.floorMod(session.userId() - 1L, 16L) + 1L)))
                .repeat(2).on(flow())
                .injectOpen(atOnceUsers(2)))
            .protocols(HTTP)
            .assertions(global().failedRequests().count().is(0L));
    }
}

