const origin = 'http://127.0.0.1:8000';
const base = (__ENV.BASE_URL || origin).replace(/\/+$/, '');
if (base !== origin) throw new Error('BASE_URL must point to the local shop fixture');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  noCookiesReset: false,
  thresholds: { checks: ['rate==1'] },
};

function json(response) {
  try {
    return response.json() || {};
  } catch (_) {
    return {};
  }
}

function header(response, name) {
  const key = Object.keys(response.headers).find(
    (key) => key.toLowerCase() === name.toLowerCase(),
  );
  return key ? response.headers[key] : undefined;
}

function hasToken(value) {
  return typeof value === 'string' && value.length > 0;
}

function hasId(value) {
  return hasToken(value) || (typeof value === 'number' && Number.isFinite(value));
}

function localLink(value, from) {
  if (typeof value !== 'string' || !value || /[\s\\]/.test(value)) return null;
  if (value.startsWith(base + '/')) return value;
  if (value.startsWith('//') || /^[a-z][a-z0-9+.-]*:/i.test(value)) return null;
  if (value.startsWith('/')) return base + value;

  const path = from.slice(base.length).split(/[?#]/)[0];
  return base + (value.startsWith('?') ? path : path.slice(0, path.lastIndexOf('/') + 1)) + value;
}

function send(method, url, payload = null, headers = {}) {
  return http.request(method, url, payload === null ? null : JSON.stringify(payload), {
    headers: payload === null ? headers : { 'Content-Type': 'application/json', ...headers },
    redirects: 0,
    timeout: '3s',
  });
}

function login(state) {
  state.csrf = '';
  const formResponse = send('GET', base + '/v2/login-form');
  if (!check(formResponse, { 'login form loaded': (r) => r.status === 200 })) return false;

  const html = formResponse.html();
  const field = 'input[name="csrf"][value]:not([disabled]):not([value=""])';
  const loginFields = html.find(
    `form[action="/v2/login"] ${field}, form[action="${base}/v2/login"] ${field}`,
  );
  const formFields = html.find(`form ${field}`);
  const fields = loginFields.size() ? loginFields : formFields.size() ? formFields : html.find(field);
  const formToken = fields.first().attr('value');
  if (!check(formToken, { 'login form CSRF extracted': hasToken })) return false;

  const loginURL = base + '/v2/login';
  let response = send('POST', loginURL, {
    username: state.username,
    password: 'bench',
    csrf: formToken,
  });
  let sessionToken = json(response).csrf;

  if (response.status === 302) {
    const target = localLink(header(response, 'Location'), loginURL);
    if (!check(target, { 'login redirect points to the local shop': (url) => !!url })) return false;
    response = send('GET', target);
    const redirectedToken = json(response).csrf;
    if (hasToken(redirectedToken)) sessionToken = redirectedToken;
  }

  if (!check(response, {
    'login issued a session CSRF': (r) => r.status === 200 && hasToken(sessionToken),
  })) return false;

  state.csrf = sessionToken;
  return true;
}

function authenticated(state, method, url, payload = null, headers = {}) {
  const mutation = method !== 'GET';
  const response = send(method, url, payload, mutation
    ? { ...headers, 'X-CSRF-Token': state.csrf }
    : headers);
  if (mutation && response.status >= 200 && response.status < 300) {
    const nextToken = json(response).csrf;
    if (hasToken(nextToken)) state.csrf = nextToken;
  }
  return response;
}

function request(state, operation) {
  const response = operation();
  if (response.status !== 401) return response;

  const error = json(response).error;
  if (error === 'expired') {
    const renewed = authenticated(state, 'POST', base + '/v2/session/renew', {});
    if (renewed.status === 401 && json(renewed).error === 'session') {
      if (!login(state)) return response;
    } else if (!check(renewed, {
      'expired session renewed': (r) => r.status >= 200 && r.status < 300 && hasToken(json(r).csrf),
    })) {
      return response;
    }
  } else if (error === 'session') {
    if (!login(state)) return response;
  } else {
    return response;
  }

  if (state.cartId !== null) {
    const recovered = authenticated(
      state, 'POST', base + '/v2/carts/' + encodeURIComponent(state.cartId) + '/recover', {},
    );
    if (!check(recovered, { 'journey cart recovered': (r) => r.status >= 200 && r.status < 300 })) {
      return response;
    }
    state.etag = header(recovered, 'ETag') || state.etag;
  }

  return operation();
}

function catalogItem(state) {
  let page = base + '/v2/catalog';
  for (let n = 0; n < 3 && page; n++) {
    const response = request(state, () => authenticated(state, 'GET', page));
    if (!check(response, { 'catalog page loaded': (r) => r.status === 200 })) return null;
    const body = json(response);
    const products = body.data && body.data.products;
    if (!Array.isArray(products)) return null;

    for (const product of products) {
      if (!product || !hasId(product.id) || !Array.isArray(product.variants)) continue;
      const variant = product.variants.find(
        (v) => v && v.in_stock === true && hasId(v.id),
      );
      if (variant) return { product_id: product.id, variant_id: variant.id };
    }

    page = localLink(body.next, page);
  }
  return null;
}

export default function () {
  const state = { username: `bench-${__VU}`, csrf: '', cartId: null, etag: undefined };
  if (!login(state)) return;

  const item = catalogItem(state);
  if (!check(item, { 'in-stock catalog variant found': (value) => !!value })) return;

  const created = request(state, () => authenticated(state, 'POST', base + '/v2/carts', item));
  const cartId = json(created).id;
  if (!check(created, { 'journey cart created': (r) => r.status === 201 && hasId(cartId) })) return;
  state.cartId = cartId;
  state.etag = header(created, 'ETag');

  const key = String(cartId);
  const order = request(state, () => {
    const headers = { 'Idempotency-Key': key };
    if (state.etag) headers['If-Match'] = state.etag;
    return authenticated(state, 'POST', base + '/v2/orders', { cart_id: cartId }, headers);
  });

  check(order, { 'order accepted': (r) => r.status === 201 && json(r).accepted === true });
}

import os
from html.parser import HTMLParser
from itertools import count
from urllib.parse import quote, urljoin, urlsplit, urlunsplit
from uuid import uuid4

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


USERS = 2
ITERATIONS = 2
BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
ACCOUNT_NUMBERS = count(1)
RECOVERABLE = ("expired", "session")


class LoginFormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.action = None
        self.fields = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "form":
            self.action = attrs.get("action")
        elif tag == "input" and attrs.get("name") == "csrf" and "disabled" not in attrs:
            value = attrs.get("value")
            if value:
                hidden = (attrs.get("type") or "").lower() == "hidden"
                self.fields.append((self.action, hidden, value))

    def handle_endtag(self, tag):
        if tag == "form":
            self.action = None

    def token(self, form_url):
        origin = urlsplit(form_url)

        def is_login_form(action):
            if not action:
                return False
            target = urlsplit(urljoin(form_url, action))
            return (target.scheme, target.netloc, target.path) == (
                origin.scheme, origin.netloc, "/v2/login"
            )

        fields = [field for field in self.fields if is_login_form(field[0])]
        fields = fields or self.fields
        values = {value for _, hidden, value in fields if hidden}
        values = values or {value for _, _, value in fields}
        if len(values) != 1:
            raise ValueError("Login form must contain one unambiguous CSRF token")
        return values.pop()


def local_link(response, link):
    if not isinstance(link, str) or not link.strip():
        raise ValueError("Missing navigation URL")
    target = urlsplit(urljoin(response.url, link))
    if (target.scheme, target.netloc) != ("http", "127.0.0.1:8000"):
        raise ValueError("Navigation URL is outside the shop origin")
    path = target.path or "/"
    if path.startswith("//"):
        raise ValueError("Invalid shop path")
    return urlunsplit(("", "", path, target.query, ""))


def csrf_from(body):
    value = body.get("csrf")
    return value if isinstance(value, str) and value.strip() else ""


def valid_id(value):
    return (isinstance(value, str) and bool(value.strip())) or type(value) is int


def read_id(response, body):
    identifier = body.get("id")
    if not valid_id(identifier):
        raise ValueError("Response did not supply an ID")
    return identifier


def read_order(response, body):
    if body.get("accepted") is not True:
        raise ValueError("Order was not accepted")
    return read_id(response, body)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.username = "bench-" + str(next(ACCOUNT_NUMBERS))
        self.iteration = 0
        self.csrf = ""
        self.cart_id = None
        self.etag = ""

    def send(self, method, path, *, data=None, headers=None, statuses=(200,),
             read=None, recoverable=(), capture_csrf=False, name=None):
        request_headers = dict(headers or {})
        if method != "GET" and self.csrf:
            request_headers["X-CSRF-Token"] = self.csrf

        with self.client.request(
            method, path, json=data, headers=request_headers, name=name,
            catch_response=True, allow_redirects=False, timeout=5
        ) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            if not isinstance(body, dict):
                body = {}

            if response.status_code == 401 and body.get("error") in recoverable:
                response.success()
                return response, body, None
            if response.status_code not in statuses:
                response.failure("Unexpected HTTP status: " + str(response.status_code))
                return None
            try:
                value = read(response, body) if read else None
            except ValueError as error:
                response.failure(str(error))
                return None
            if method != "GET" or capture_csrf:
                self.csrf = csrf_from(body) or self.csrf
            response.success()
            return response, body, value

    def login(self):
        self.csrf = ""

        def read_form(response, body):
            parser = LoginFormParser()
            parser.feed(response.text)
            parser.close()
            return parser.token(response.url)

        form = self.send("GET", "/v2/login-form", read=read_form)
        if form is None:
            return False

        def read_login(response, body):
            if response.status_code == 302:
                return local_link(response, response.headers.get("Location"))
            if not csrf_from(body):
                raise ValueError("Login did not supply a session CSRF token")
            return None

        login = self.send(
            "POST", "/v2/login",
            data={"username": self.username, "password": "bench", "csrf": form[2]},
            statuses=(200, 302), read=read_login
        )
        if login is None:
            return False
        if login[0].status_code == 302:
            def read_redirect(response, body):
                if not (csrf_from(body) or self.csrf):
                    raise ValueError("Login redirect did not supply a session CSRF token")

            return self.send(
                "GET", login[2], read=read_redirect, capture_csrf=True, name="login redirect"
            ) is not None
        return True

    def recover(self, error):
        if error == "expired":
            def read_renewal(response, body):
                if not csrf_from(body):
                    raise ValueError("Renewal did not supply a fresh CSRF token")

            renewal = self.send(
                "POST", "/v2/session/renew", data={},
                read=read_renewal, recoverable=("session",)
            )
            if renewal is None:
                return False
            if renewal[0].status_code == 401 and not self.login():
                return False
        elif not self.login():
            return False

        if self.cart_id is not None:
            path = "/v2/carts/" + quote(str(self.cart_id), safe="") + "/recover"
            recovery = self.send(
                "POST", path, data={}, statuses=(200, 204), name="/v2/carts/[id]/recover"
            )
            if recovery is None:
                return False
            self.etag = recovery[0].headers.get("ETag") or self.etag
        return True

    def request(self, method, path, *, headers=None, match_cart=False, **kwargs):
        for attempt in range(2):
            request_headers = dict(headers or {})
            if match_cart and self.etag:
                request_headers["If-Match"] = self.etag
            result = self.send(
                method, path, headers=request_headers,
                recoverable=RECOVERABLE if attempt == 0 else (), **kwargs
            )
            if result is None or result[0].status_code != 401:
                return result
            if not self.recover(result[1]["error"]):
                return None
        return None

    def select_item(self):
        path = "/v2/catalog"
        for page_index in range(3):
            def read_catalog(response, body):
                data = body.get("data")
                products = data.get("products") if isinstance(data, dict) else None
                if not isinstance(products, list):
                    raise ValueError("Catalog did not supply a product list")
                for product in products:
                    if not isinstance(product, dict) or not valid_id(product.get("id")):
                        continue
                    variants = product.get("variants")
                    if not isinstance(variants, list):
                        continue
                    for variant in variants:
                        if (isinstance(variant, dict) and variant.get("in_stock") is True
                                and valid_id(variant.get("id"))):
                            return (product["id"], variant["id"]), None
                if page_index < 2 and body.get("next"):
                    return None, local_link(response, body["next"])
                raise ValueError("No in-stock catalog variant found")

            result = self.request("GET", path, read=read_catalog)
            if result is None:
                return None
            item, path = result[2]
            if item is not None:
                return item
        return None

    def flow(self):
        self.client.cookies.clear()
        self.cart_id = None
        self.etag = ""
        if not self.login():
            return

        item = self.select_item()
        if item is None:
            return
        product_id, variant_id = item
        cart = self.request(
            "POST", "/v2/carts", data={"product_id": product_id, "variant_id": variant_id},
            statuses=(201,), read=read_id
        )
        if cart is None:
            return

        self.cart_id = cart[2]
        self.etag = cart[0].headers.get("ETag", "")
        self.request(
            "POST", "/v2/orders", data={"cart_id": self.cart_id},
            headers={"Idempotency-Key": uuid4().hex}, match_cart=True,
            statuses=(201,), read=read_order
        )

    @task
    def run_journey(self):
        self.flow()
        self.iteration += 1
        if self.iteration >= ITERATIONS:
            raise StopUser()


class ShopShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.first_tick = True

    def tick(self):
        if self.first_tick:
            self.first_tick = False
            return USERS, USERS
        if self.runner.user_count == 0:
            return None
        return USERS, USERS

