import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;
import io.gatling.javaapi.http.HttpRequestActionBuilder;
import java.util.function.Function;

public class ModelSimulation extends Simulation {
    private static final HttpProtocolBuilder HTTP = http
        .baseUrl(System.getenv("BASE_URL"))
        .disableWarmUp()
        .disableFollowRedirect()
        .acceptHeader("application/json");

    private static final String FIRST_AVAILABLE =
        "data.products[?variants[?in_stock == `true`]] | [0]";

    private static String username(Session session) {
        return "bench-" + ((session.userId() - 1) % 16 + 1);
    }

    private static ChainBuilder login() {
        return exec(session -> session.remove("formCsrf").remove("csrf")
                .remove("loginStatus").remove("loginLocation"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200), css("input[name='csrf']", "value").saveAs("formCsrf")))
            .exitHereIfFailed()
            .exec(http("login").post("/v2/login")
                .asJson()
                .body(StringBody(session -> "{\"username\":\"" + username(session)
                    + "\",\"password\":\"bench\",\"csrf\":\"" + session.getString("formCsrf") + "\"}"))
                .check(status().in(200, 302), status().saveAs("loginStatus"))
                .checkIf((response, session) -> response.status().code() == 200)
                .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((response, session) -> response.status().code() == 302)
                .then(header("Location").saveAs("loginLocation"))
                .checkIf((response, session) -> response.status().code() == 302
                    && response.body().string().stripLeading().startsWith("{"))
                .then(jsonPath("$.csrf").optional().saveAs("csrf")))
            .exitHereIfFailed()
            .exec(doIf(session -> session.getInt("loginStatus") == 302).then(
                exec(http("login redirect").get("#{loginLocation}")
                    .check(status().is(200))
                    .checkIf(session -> !session.contains("csrf"))
                    .then(jsonPath("$.csrf").saveAs("csrf"))
                    .checkIf((response, session) -> response.body().string().stripLeading().startsWith("{"))
                    .then(jsonPath("$.csrf").optional().saveAs("csrf")))
                    .exitHereIfFailed()));
    }

    private static ChainBuilder renew(boolean revoked) {
        HttpRequestActionBuilder request = http("renew session").post("/v2/session/renew")
            .asJson()
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"));

        return exec(revoked
            ? request.check(status().in(200, 401))
            : request.check(status().is(200), jsonPath("$.csrf").saveAs("csrf")))
            .exitHereIfFailed();
    }

    private static ChainBuilder recoverSession() {
        return exec(doIfOrElse(session -> "session".equals(session.getString("operationError")))
                .then(renew(true).exec(flushCookieJar()).exec(login()))
                .orElse(renew(false)))
            .exec(doIf(session -> session.contains("cartId")).then(
                exec(http("recover cart").post("/v2/carts/#{cartId}/recover")
                    .asJson()
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .check(status().is(200), header("ETag").optional().saveAs("cartEtag"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))
                    .exitHereIfFailed()));
    }

    private static HttpRequestActionBuilder expect(
            HttpRequestActionBuilder request, int success, boolean allowRecovery) {
        if (!allowRecovery) {
            return request.check(status().is(success));
        }
        return request.check(status().in(success, 401), status().saveAs("operationStatus"))
            .checkIf((response, session) -> response.status().code() == 401)
            .then(jsonPath("$.error").in("expired", "session").saveAs("operationError"));
    }

    private static ChainBuilder operation(Function<Boolean, HttpRequestActionBuilder> request) {
        return exec(session -> session.remove("operationStatus").remove("operationError"))
            .exec(request.apply(true))
            .exitHereIfFailed()
            .exec(doIf(session -> session.getInt("operationStatus") == 401).then(
                recoverSession().exec(request.apply(false)).exitHereIfFailed()));
    }

    private static HttpRequestActionBuilder catalog(boolean allowRecovery) {
        return expect(http("catalog").get("/v2/catalog").header("X-CSRF-Token", "#{csrf}"),
                200, allowRecovery)
            .checkIf((response, session) -> response.status().code() == 200)
            .then(
                jmesPath(FIRST_AVAILABLE + ".id").saveAs("productId"),
                jmesPath(FIRST_AVAILABLE + ".variants[?in_stock == `true`] | [0].id").saveAs("variantId"),
                jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    private static HttpRequestActionBuilder createCart(boolean allowRecovery) {
        return expect(http("create cart").post("/v2/carts")
                .asJson()
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{\"product_id\":\"#{productId}\",\"variant_id\":\"#{variantId}\"}")),
                201, allowRecovery)
            .checkIf((response, session) -> response.status().code() == 201)
            .then(jsonPath("$.id").saveAs("cartId"), header("ETag").saveAs("cartEtag"),
                jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    private static HttpRequestActionBuilder commitOrder(boolean allowRecovery) {
        return expect(http("commit order").post("/v2/orders")
                .asJson()
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "order-#{cartId}")
                .header("If-Match", "#{cartEtag}")
                .body(StringBody("{\"cart_id\":\"#{cartId}\"}")),
                201, allowRecovery)
            .checkIf((response, session) -> response.status().code() == 201)
            .then(jsonPath("$.accepted").ofBoolean().is(true), jsonPath("$.id").exists(),
                jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    private static ChainBuilder journey() {
        return exec(flushCookieJar())
            .exec(session -> session.remove("cartId").remove("cartEtag")
                .remove("productId").remove("variantId"))
            .exec(login())
            .exec(operation(ModelSimulation::catalog))
            .exec(operation(ModelSimulation::createCart))
            .exec(operation(ModelSimulation::commitOrder));
    }

    public ModelSimulation() {
        setUp(scenario("shop flow").exec(repeat(2).on(journey())).injectOpen(atOnceUsers(2)))
            .protocols(HTTP)
            .assertions(global().failedRequests().count().is(0L));
    }
}

