import http from 'k6/http';
import { check } from 'k6';

const origin = 'http://127.0.0.1:8000';
const base = (__ENV.BASE_URL || origin).replace(/\/+$/, '');
if (base !== origin) throw new Error('BASE_URL must target the local shop fixture');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  thresholds: { checks: ['rate==1'] },
};

function body(response) {
  try {
    return response.json() || {};
  } catch (_) {
    return {};
  }
}

function header(response, name) {
  const wanted = name.toLowerCase();
  for (const key of Object.keys(response.headers)) {
    if (key.toLowerCase() === wanted) return response.headers[key];
  }
  return '';
}

function localPath(reference, from) {
  if (typeof reference !== 'string') return null;
  const ref = reference.trim();
  if (!ref || ref.startsWith('//') || ref.includes('\\')) return null;
  if (ref.startsWith(base + '/')) return ref.slice(base.length);
  if (ref.startsWith('/')) return ref;
  if (/^[a-z][a-z\d+.-]*:/i.test(ref)) return null;

  const current = from.split('?')[0];
  if (ref.startsWith('?')) return current + ref;
  const suffixStart = ref.search(/[?#]/);
  const path = suffixStart < 0 ? ref : ref.slice(0, suffixStart);
  const suffix = suffixStart < 0 ? '' : ref.slice(suffixStart);
  const parts = current.slice(1, current.lastIndexOf('/') + 1).split('/');
  parts.pop();
  for (const part of path.split('/')) {
    if (part === '..') parts.pop();
    else if (part !== '.') parts.push(part);
  }
  return '/' + parts.join('/') + suffix;
}

function raw(journey, path, method = 'GET', payload = null, extra = {}) {
  const headers = { ...extra };
  if (payload !== null) headers['Content-Type'] = 'application/json';
  if (method !== 'GET' && journey.csrf) headers['X-CSRF-Token'] = journey.csrf;

  const response = http.request(
    method,
    base + path,
    payload === null ? null : JSON.stringify(payload),
    { jar: journey.jar, headers, redirects: 0, timeout: '3s' }
  );
  if (response.status >= 200 && response.status < 400) {
    const token = body(response).csrf;
    if (typeof token === 'string' && token) journey.csrf = token;
  }
  return response;
}

function loginToken(response) {
  const page = response.html();
  const fields = 'input[name="csrf"][value]:not([disabled])';
  function tokenIn(scope) {
    return scope.find(fields + '[type="hidden"]').first().attr('value') ||
      scope.find(fields).first().attr('value');
  }

  let actionToken;
  let implicitToken;
  page.find('form').each((_, form) => {
    const action = form.attr('action');
    if (localPath(action, '/v2/login-form') === '/v2/login') {
      actionToken = actionToken || tokenIn(form);
    } else if (!action) {
      implicitToken = implicitToken || tokenIn(form);
    }
  });
  return actionToken || implicitToken || tokenIn(page);
}

function login(journey) {
  journey.jar = new http.CookieJar();
  journey.csrf = '';
  journey.grant = undefined;

  const form = raw(journey, '/v2/login-form');
  const token = form.status === 200 ? loginToken(form) : null;
  if (!check(form, { 'login form supplies a CSRF token': () => Boolean(token) })) {
    return false;
  }

  let response = raw(journey, '/v2/login', 'POST', {
    username: journey.username,
    password: 'bench',
    csrf: token,
  });
  if (response.status === 302) {
    const location = localPath(header(response, 'Location'), '/v2/login');
    if (!check(location, { 'login redirect stays on the shop': value => Boolean(value) })) {
      return false;
    }
    response = raw(journey, location);
    if (response.status === 200) journey.grant = body(response).grant_id;
  }
  return check(response, {
    'login succeeds with a session CSRF token': r => r.status === 200 && Boolean(journey.csrf),
  });
}

function withSession(journey, send) {
  const response = send();
  if (response.status !== 401) return response;

  const error = body(response).error;
  if (error !== 'expired' && error !== 'session') return response;

  const renewed = raw(journey, '/v2/session/renew', 'POST', {});
  if (renewed.status !== 200) {
    if (error !== 'session' && body(renewed).error !== 'session') return response;
    if (!login(journey)) return response;
  }

  if (journey.cartId !== null) {
    const recovered = raw(
      journey, '/v2/carts/' + encodeURIComponent(journey.cartId) + '/recover', 'POST', {}
    );
    if (!check(recovered, { 'cart recovery succeeds': r => r.status >= 200 && r.status < 300 })) {
      return response;
    }
    journey.etag = header(recovered, 'ETag') || journey.etag;
  }
  return send();
}

export default function () {
  const journey = {
    username: 'bench-' + (((__VU - 1) % 16) + 1),
    jar: null,
    csrf: '',
    cartId: null,
    etag: '',
    grant: undefined,
  };
  if (!login(journey)) return;

  let page = '/v2/catalog';
  let selection;
  for (let n = 0; n < 3 && page && !selection; n++) {
    const response = withSession(journey, () => raw(journey, page));
    if (!check(response, { 'catalog request succeeds': r => r.status === 200 })) return;

    const catalog = body(response);
    const products = catalog.data && catalog.data.products;
    for (const product of Array.isArray(products) ? products : []) {
      if (product.id == null || !Array.isArray(product.variants)) continue;
      const variant = product.variants.find(v => v.id != null && v.in_stock === true);
      if (variant) {
        selection = { product_id: product.id, variant_id: variant.id };
        break;
      }
    }
    if (!selection) page = localPath(catalog.next, page);
  }
  if (!check(selection, { 'catalog offers an in-stock variant': value => Boolean(value) })) return;

  const created = withSession(journey, () => raw(journey, '/v2/carts', 'POST', {
    ...selection,
    grant_id: journey.grant,
  }));
  journey.grant = undefined;
  const cartId = body(created).id;
  if (!check(created, {
    'new cart created for this journey': r => r.status === 201 && cartId != null && cartId !== '',
  })) return;

  journey.cartId = cartId;
  journey.etag = header(created, 'ETag');
  const idempotencyKey = String(cartId);
  const order = withSession(journey, () => {
    const headers = { 'Idempotency-Key': idempotencyKey };
    if (journey.etag) headers['If-Match'] = journey.etag;
    return raw(journey, '/v2/orders', 'POST', { cart_id: cartId }, headers);
  });
  check(order, {
    'order committed': r => r.status === 201 && body(r).accepted === true,
  });
}

import os
from html.parser import HTMLParser
from itertools import count
from urllib.parse import quote, urljoin, urlsplit
from uuid import uuid4

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
USERS = 2
ITERATIONS = 2
ACCOUNT_NUMBERS = count()


class JourneyFailed(Exception):
    pass


class LoginFormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_login_form = False
        self.tokens = []

    def handle_starttag(self, tag, attributes):
        attrs = dict(attributes)
        if tag == "form":
            action = (attrs.get("action") or "").split("?", 1)[0]
            self.in_login_form = action.rstrip("/").endswith("/v2/login")
        elif tag == "input" and attrs.get("name") == "csrf":
            value = attrs.get("value")
            if value and "disabled" not in attrs:
                rank = (self.in_login_form, (attrs.get("type") or "").lower() == "hidden")
                self.tokens.append((rank, value))

    def handle_endtag(self, tag):
        if tag == "form":
            self.in_login_form = False


def form_token(response, _body):
    parser = LoginFormParser()
    parser.feed(response.text)
    parser.close()
    if not parser.tokens:
        raise ValueError("Login form has no usable csrf input")
    return max(parser.tokens, key=lambda item: item[0])[1]


def shop_url(location, base=BASE_URL + "/"):
    if not isinstance(location, str) or not location.strip():
        raise ValueError("Missing shop URL")
    url = urlsplit(urljoin(base, location))
    if url.scheme != "http" or url.netloc != "127.0.0.1:8000":
        raise ValueError("URL is outside the target shop")
    return url._replace(fragment="").geturl()


def csrf_token(body):
    token = body.get("csrf")
    return token if isinstance(token, str) and token else None


def has_id(value):
    return type(value) is int or (isinstance(value, str) and bool(value))


def created_cart(response, body):
    cart_id = body.get("id")
    etag = response.headers.get("ETag")
    if not has_id(cart_id) or not etag:
        raise ValueError("Cart creation did not return an id and ETag")
    return cart_id, etag


def accepted_order(_response, body):
    if body.get("accepted") is not True or not has_id(body.get("id")):
        raise ValueError("Checkout did not return an accepted order with an id")


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.username = f"bench-{next(ACCOUNT_NUMBERS) % 16 + 1}"
        self.iteration = 0

    def send(self, method, path, *, data=None, headers=None, expected=(200,),
             check=None, recoverable=()):
        request_headers = dict(headers or {})
        if method != "GET" and self.csrf:
            request_headers["X-CSRF-Token"] = self.csrf

        with self.client.request(
            method, shop_url(path), json=data, headers=request_headers,
            allow_redirects=False, catch_response=True, timeout=3,
        ) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            if not isinstance(body, dict):
                body = {}

            error = body.get("error")
            if response.status_code == 401 and error in recoverable:
                response.success()
                return error, None

            try:
                if response.status_code not in expected:
                    raise ValueError(
                        f"{method} returned HTTP {response.status_code}; expected {expected}"
                    )
                result = check(response, body) if check else body
            except ValueError as exc:
                response.failure(str(exc))
            else:
                self.csrf = csrf_token(body) or self.csrf
                response.success()
                return None, result

        raise JourneyFailed()

    def login(self):
        self.client.cookies.clear()
        self.csrf = None
        _, token = self.send("GET", "/v2/login-form", check=form_token)

        def check_login(response, body):
            if response.status_code == 302:
                return shop_url(response.headers.get("Location"), response.url)
            if not csrf_token(body) or "user" not in body:
                raise ValueError("Login did not return a user and CSRF token")
            return None

        _, landing = self.send(
            "POST", "/v2/login",
            data={"username": self.username, "password": "bench", "csrf": token},
            expected=(200, 302), check=check_login,
        )
        if landing is not None:
            def check_landing(_response, body):
                if not (csrf_token(body) or self.csrf):
                    raise ValueError("Login redirect did not establish a CSRF token")

            self.send("GET", landing, expected=range(200, 300), check=check_landing)

    def recover(self, error):
        if error == "expired":
            error, _ = self.send(
                "POST", "/v2/session/renew", data={}, recoverable=("session",),
            )
        if error == "session":
            self.login()
        if self.cart_id is not None:
            cart_path = "/v2/carts/" + quote(str(self.cart_id), safe="")
            _, etag = self.send(
                "POST", cart_path + "/recover", data={}, expected=range(200, 300),
                check=lambda response, _body: response.headers.get("ETag"),
            )
            if etag:
                self.etag = etag

    def request(self, method, path, *, headers=None, match_cart=False, **kwargs):
        request_headers = dict(headers or {})
        for attempt in range(2):
            if match_cart:
                request_headers["If-Match"] = self.etag
            error, result = self.send(
                method, path, headers=request_headers,
                recoverable=("expired", "session") if attempt == 0 else (),
                **kwargs,
            )
            if error is None:
                return result
            self.recover(error)

    def select_variant(self):
        path = "/v2/catalog"
        for page_index in range(3):
            def check_page(response, body):
                data = body.get("data")
                products = data.get("products") if isinstance(data, dict) else None
                if not isinstance(products, list):
                    raise ValueError("Catalog response has no products list")
                for product in products:
                    if not isinstance(product, dict) or not has_id(product.get("id")):
                        continue
                    variants = product.get("variants")
                    if not isinstance(variants, list):
                        continue
                    for variant in variants:
                        if (isinstance(variant, dict) and variant.get("in_stock") is True
                                and has_id(variant.get("id"))):
                            return (product["id"], variant["id"]), None
                if page_index < 2 and body.get("next"):
                    return None, shop_url(body["next"], response.url)
                raise ValueError("No in-stock variant found within the catalog page limit")

            selection, path = self.request("GET", path, check=check_page)
            if selection is not None:
                return selection

    def journey(self):
        self.cart_id = None
        self.etag = None
        self.login()

        product_id, variant_id = self.select_variant()
        self.cart_id, self.etag = self.request(
            "POST", "/v2/carts",
            data={"product_id": product_id, "variant_id": variant_id},
            expected=(201,), check=created_cart,
        )
        self.request(
            "POST", "/v2/orders", data={"cart_id": self.cart_id},
            headers={"Idempotency-Key": uuid4().hex}, match_cart=True,
            expected=(201,), check=accepted_order,
        )

    @task
    def run_journey(self):
        try:
            self.journey()
        except JourneyFailed:
            pass  # The failed request has already been recorded by Locust.
        self.iteration += 1
        if self.iteration >= ITERATIONS:
            raise StopUser()


class FlowShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.started = False

    def tick(self):
        if self.started and self.runner.user_count == 0:
            return None
        self.started = True
        return USERS, USERS

