import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;
import io.gatling.javaapi.http.HttpRequestActionBuilder;

import java.net.URI;
import java.time.Duration;
import java.util.function.Function;

public class ModelSimulation extends Simulation {
    private static final String BASE_URL = System.getenv("BASE_URL");
    private static final HttpProtocolBuilder HTTP = http.baseUrl(BASE_URL)
        .disableWarmUp()
        .disableFollowRedirect()
        .acceptHeader("application/json");

    private static final String IN_STOCK_PRODUCT =
        "data.products[?variants[?in_stock == `true`]] | [0]";
    private static final String IN_STOCK_VARIANT =
        IN_STOCK_PRODUCT + ".variants[?in_stock == `true`] | [0].id";

    private static String username(Session session) {
        return "bench-" + (Math.floorMod(session.userId() - 1L, 16L) + 1L);
    }

    private static String localLocation(String location) {
        URI base = URI.create(BASE_URL);
        URI target = base.resolve(location);
        if (!base.getScheme().equalsIgnoreCase(target.getScheme())
            || !base.getHost().equalsIgnoreCase(target.getHost())
            || base.getPort() != target.getPort()
            || target.getRawUserInfo() != null) {
            throw new IllegalArgumentException("Redirect must stay on the shop origin");
        }
        return target.toASCIIString();
    }

    private static ChainBuilder login() {
        return exec(session -> session.remove("loginLocation").remove("formCsrf").remove("csrf"))
            .exec(http("login form").get("/v2/login-form")
                .header("Accept", "text/html")
                .check(status().is(200), css("input[name='csrf']", "value").saveAs("formCsrf")))
            .exec(session -> session.set("username", username(session)))
            .exec(http("login").post("/v2/login")
                .header("Content-Type", "application/json")
                .body(StringBody("{\"username\":#{username.jsonStringify()},"
                    + "\"password\":\"bench\",\"csrf\":#{formCsrf.jsonStringify()}}"))
                .check(status().in(200, 302))
                .checkIf((response, session) -> response.status().code() == 200)
                .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((response, session) -> response.status().code() == 302)
                .then(header("Location").transform(ModelSimulation::localLocation)
                    .saveAs("loginLocation")))
            .exec(doIf(session -> session.contains("loginLocation")).then(
                exec(http("login redirect").get("#{loginLocation}")
                    .check(status().is(200), jsonPath("$.csrf").saveAs("csrf")))));
    }

    private static HttpRequestActionBuilder expected(
        HttpRequestActionBuilder request, int success, boolean allowRecovery
    ) {
        if (!allowRecovery) {
            return request.check(status().is(success));
        }
        return request.check(status().in(success, 401))
            .checkIf((response, session) -> response.status().code() == 401)
            .then(jsonPath("$.error").in("expired", "session").saveAs("authError"));
    }

    private static ChainBuilder restoreSession() {
        ChainBuilder renew = exec(http("renew").post("/v2/session/renew")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().in(200, 401).saveAs("renewStatus"))
                .checkIf((response, session) -> response.status().code() == 200)
                .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((response, session) -> response.status().code() == 401)
                .then(jsonPath("$.error").is("session")))
            .exec(doIf(session -> session.getInt("renewStatus") == 401).then(login()));

        return exec(doIfOrElse(session -> "expired".equals(session.getString("authError")))
                .then(renew)
                .orElse(login()))
            .exec(doIf(session -> session.contains("cart")).then(
                exec(http("cart recovery").post("/v2/carts/#{cart}/recover")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .check(status().is(200), header("ETag").optional().saveAs("etag"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static ChainBuilder operation(Function<Boolean, HttpRequestActionBuilder> request) {
        return exec(session -> session.remove("authError"))
            .exec(request.apply(true))
            .exec(doIf(session -> session.contains("authError")).then(
                restoreSession().exec(request.apply(false))));
    }

    private static HttpRequestActionBuilder catalog(boolean first) {
        return expected(http(first ? "catalog" : "catalog retry").get("/v2/catalog"), 200, first)
            .checkIf((response, session) -> response.status().code() == 200)
            .then(jmesPath(IN_STOCK_PRODUCT + ".id").saveAs("product"),
                jmesPath(IN_STOCK_VARIANT).saveAs("variant"));
    }

    private static HttpRequestActionBuilder createCart(boolean first) {
        return expected(http(first ? "cart" : "cart retry").post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{\"product_id\":#{product.jsonStringify()},"
                    + "\"variant_id\":#{variant.jsonStringify()}}")), 201, first)
            .checkIf((response, session) -> response.status().code() == 201)
            .then(jsonPath("$.id").saveAs("cart"), header("ETag").saveAs("etag"),
                jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    private static HttpRequestActionBuilder readCart(boolean first) {
        return expected(http(first ? "expiry probe" : "expiry probe retry")
                .get("/v2/carts/#{cart}"), 200, first)
            .checkIf((response, session) -> response.status().code() == 200)
            .then(header("ETag").saveAs("etag"));
    }

    private static HttpRequestActionBuilder commit(boolean first) {
        return expected(http(first ? "commit" : "commit retry").post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("If-Match", "#{etag}")
                .header("Idempotency-Key", "#{cart}")
                .body(StringBody("{\"cart_id\":#{cart.jsonStringify()}}")), 201, first)
            .checkIf((response, session) -> response.status().code() == 201)
            .then(jsonPath("$.accepted").ofBoolean().is(true), jsonPath("$.id").exists(),
                jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    private static ChainBuilder journey() {
        return exec(session -> session.remove("cart").remove("etag")
                .remove("product").remove("variant"))
            .exec(flushCookieJar())
            .exec(login())
            .exec(operation(ModelSimulation::catalog))
            .exec(operation(ModelSimulation::createCart))
            .pause(Duration.ofMillis(2100))
            .exec(operation(ModelSimulation::readCart))
            .exec(operation(ModelSimulation::commit));
    }

    public ModelSimulation() {
        setUp(scenario("denial").repeat(2).on(
                exec(session -> session.markAsSucceeded()),
                exitBlockOnFail().on(journey()))
            .injectOpen(atOnceUsers(2)))
            .protocols(HTTP)
            .assertions(global().failedRequests().count().is(0L));
    }
}

