import http from 'k6/http';
import { check } from 'k6';

const origin = 'http://127.0.0.1:8000';
const base = (__ENV.BASE_URL || origin).replace(/\/+$/, '');
if (base !== origin) throw new Error('BASE_URL must target the local shop');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  thresholds: { checks: ['rate==1'] },
};

function body(response) {
  try {
    return response.json() || {};
  } catch (_) {
    return {};
  }
}

function header(response, name) {
  const headers = response.headers || {};
  const key = Object.keys(headers).find(k => k.toLowerCase() === name.toLowerCase());
  return key === undefined ? undefined : headers[key];
}

function localPath(reference, from) {
  if (typeof reference !== 'string') return null;
  const ref = reference.trim().split('#')[0];
  if (!ref || /[\s\\]/.test(ref) || ref.startsWith('//')) return null;
  if (ref.startsWith(base + '/')) return ref.slice(base.length);
  if (/^[a-z][a-z0-9+.-]*:/i.test(ref)) return null;
  if (ref.startsWith('/')) return ref;
  const path = from.split('?')[0];
  return ref.startsWith('?') ? path + ref : path.slice(0, path.lastIndexOf('/') + 1) + ref;
}

function hasToken(value) {
  return typeof value === 'string' && value.length > 0;
}

function hasId(value) {
  return hasToken(value) || (typeof value === 'number' && Number.isFinite(value));
}

function successful(response) {
  return response.status >= 200 && response.status < 300;
}

function raw(state, method, path, data = null, extra = {}) {
  const headers = Object.assign({}, extra);
  if (data !== null) headers['Content-Type'] = 'application/json';
  if (method !== 'GET' && state.csrf) headers['X-CSRF-Token'] = state.csrf;

  const response = http.request(method, base + path, data === null ? null : JSON.stringify(data), {
    headers,
    redirects: 0,
    timeout: '3s',
  });

  if (successful(response) || (path === '/v2/login' && response.status === 302)) {
    const token = body(response).csrf;
    if (hasToken(token)) state.csrf = token;
  }
  return response;
}

function login(state) {
  state.csrf = '';
  state.grantId = null;
  const form = raw(state, 'GET', '/v2/login-form');
  let token;
  if (form.status === 200) {
    const html = form.html();
    token = html.find('form[action="/v2/login"] input[name="csrf"]').first().attr('value') ||
      html.find('input[name="csrf"]').first().attr('value');
  }
  if (!check(form, { 'login form contains a CSRF token': r => r.status === 200 && hasToken(token) })) {
    return false;
  }

  let response = raw(state, 'POST', '/v2/login', {
    username: `bench-${__VU}`,
    password: 'bench',
    csrf: token,
  });
  if (response.status === 302) {
    const next = localPath(header(response, 'Location'), '/v2/login');
    if (!check(next, { 'login redirect stays on the shop origin': p => p !== null })) return false;
    response = raw(state, 'GET', next);
    const grant = body(response).grant_id;
    if (hasId(grant)) state.grantId = grant;
  }

  return check(response, { 'login established a session': r => r.status === 200 && hasToken(state.csrf) });
}

function restoreSession(state, reason) {
  if (reason === 'session') {
    if (!login(state)) return false;
  } else {
    const renewed = raw(state, 'POST', '/v2/session/renew', {});
    const result = body(renewed);
    if (renewed.status === 401 && result.error === 'session') {
      if (!login(state)) return false;
    } else if (!check(renewed, { 'session renewed with a CSRF token': r => successful(r) && hasToken(result.csrf) })) {
      return false;
    }
  }

  if (state.cartId !== null) {
    const recovered = raw(state, 'POST', `/v2/carts/${encodeURIComponent(state.cartId)}/recover`, {});
    if (!check(recovered, { 'existing cart recovered': successful })) return false;
    state.etag = header(recovered, 'ETag') || state.etag;
  }
  return true;
}

function request(state, send) {
  const first = send();
  if (first.status !== 401) return first;

  const reason = body(first).error;
  if (reason !== 'expired' && reason !== 'session') return first;

  const name = reason === 'expired' ? 'expected session expiry recognized' : 'revoked session recognized';
  check(first, { [name]: r => r.status === 401 && body(r).error === reason });

  // Recovery calls do not use this wrapper. The interrupted operation gets one replay.
  return restoreSession(state, reason) ? send() : first;
}

function selectItem(state) {
  let path = '/v2/catalog';
  for (let page = 0; page < 3 && path; page++) {
    const response = request(state, () => raw(state, 'GET', path));
    const result = body(response);
    const products = result.data && result.data.products;
    if (!check(response, { 'catalog returned products': r => r.status === 200 && Array.isArray(products) })) {
      return null;
    }

    for (const product of products) {
      if (!product || !hasId(product.id) || !Array.isArray(product.variants)) continue;
      const variant = product.variants.find(v => v && v.in_stock === true && hasId(v.id));
      if (variant) return { product_id: product.id, variant_id: variant.id };
    }
    path = localPath(result.next, path);
  }

  check(null, { 'catalog has an in-stock variant': item => item !== null });
  return null;
}

export default function () {
  const state = { csrf: '', cartId: null, etag: undefined, grantId: null };
  if (!login(state)) return;

  const item = selectItem(state);
  if (!item) return;
  if (state.grantId !== null) item.grant_id = state.grantId;

  const created = request(state, () => raw(state, 'POST', '/v2/carts', item));
  const cartId = body(created).id;
  if (!check(created, { 'cart created': r => r.status === 201 && hasId(cartId) })) return;

  state.cartId = cartId;
  state.etag = header(created, 'ETag');

  const order = { cart_id: cartId };
  const key = `order-${cartId}`;
  const response = request(state, () => {
    const headers = { 'Idempotency-Key': key };
    if (state.etag) headers['If-Match'] = state.etag;
    return raw(state, 'POST', '/v2/orders', order, headers);
  });
  check(response, { 'order accepted': r => r.status === 201 && body(r).accepted === true });
}

import os
from html.parser import HTMLParser
from itertools import count
from urllib.parse import quote, urljoin, urlsplit

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
USERS = 2
ITERATIONS = 2
ACCOUNT_NUMBERS = count()
RECOVERABLE = ("expired", "session")


def shop_url(reference, base=BASE_URL + "/"):
    if not isinstance(reference, str) or not reference.strip():
        raise ValueError("Missing shop URL")
    url = urlsplit(urljoin(base, reference))
    if (url.scheme, url.netloc) != ("http", "127.0.0.1:8000"):
        raise ValueError("URL is outside the shop origin")
    return url._replace(fragment="").geturl()


def token_from(body):
    token = body.get("csrf")
    return token if isinstance(token, str) and token else None


def has_id(value):
    return (isinstance(value, str) and bool(value)) or type(value) is int


class LoginForm(HTMLParser):
    def __init__(self):
        super().__init__()
        self.action = None
        self.candidates = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "form":
            self.action = attrs.get("action") or ""
        elif tag == "input" and attrs.get("name") == "csrf":
            value = attrs.get("value")
            if value and "disabled" not in attrs:
                if self.action and urlsplit(self.action).path.rstrip("/") == "/v2/login":
                    form_rank = 2
                else:
                    form_rank = 1 if not self.action else 0
                hidden = (attrs.get("type") or "").lower() == "hidden"
                self.candidates.append(((form_rank, hidden), value))

    def handle_endtag(self, tag):
        if tag == "form":
            self.action = None

    def token(self):
        if not self.candidates:
            raise ValueError("Login form has no CSRF input")
        best_rank = max(rank for rank, _ in self.candidates)
        values = {value for rank, value in self.candidates if rank == best_rank}
        if len(values) != 1:
            raise ValueError("Login form has ambiguous CSRF inputs")
        return values.pop()


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.username = f"bench-{next(ACCOUNT_NUMBERS) % 16 + 1}"
        self.iteration = 0

    def send(self, method, path, statuses, *, payload=None, headers=None,
             check=None, auth_exceptions=(), authenticated=True):
        url = shop_url(path)
        request_headers = dict(headers or {})
        if authenticated and method != "GET" and self.csrf:
            request_headers["X-CSRF-Token"] = self.csrf

        with self.client.request(
            method, url, json=payload, headers=request_headers,
            catch_response=True, allow_redirects=False, timeout=3,
        ) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            if not isinstance(body, dict):
                body = {}

            status = response.status_code
            error = body.get("error")
            if status == 401 and error in auth_exceptions:
                response.success()
                return error, None

            if status not in statuses:
                detail = f" ({error})" if isinstance(error, str) else ""
                response.failure(
                    f"{method} {urlsplit(url).path}: unexpected HTTP {status}{detail}"
                )
                return "failed", None

            try:
                result = check(response, body) if check else None
            except ValueError as exc:
                response.failure(str(exc))
                return "failed", None

            self.csrf = token_from(body) or self.csrf
            response.success()
            return "ok", result

    def login(self):
        self.csrf = None

        def read_form(response, _):
            parser = LoginForm()
            parser.feed(response.text)
            parser.close()
            return parser.token()

        status, form_token = self.send(
            "GET", "/v2/login-form", (200,), check=read_form, authenticated=False,
        )
        if status != "ok":
            return False

        def check_login(response, body):
            if response.status_code == 302:
                return shop_url(response.headers.get("Location"), response.url)
            if not token_from(body):
                raise ValueError("Login did not return a session CSRF token")

        status, location = self.send(
            "POST", "/v2/login", (200, 302),
            payload={"username": self.username, "password": "bench", "csrf": form_token},
            check=check_login, authenticated=False,
        )
        if status != "ok":
            return False
        if location is None:
            return True

        def check_login_destination(_, body):
            if not (token_from(body) or self.csrf):
                raise ValueError("Login redirect did not establish a session CSRF token")

        status, _ = self.send("GET", location, (200,), check=check_login_destination)
        return status == "ok"

    def recover_session(self, reason):
        if reason == "expired":
            def check_renewal(_, body):
                if not token_from(body):
                    raise ValueError("Session renewal did not return a CSRF token")

            status, _ = self.send(
                "POST", "/v2/session/renew", (200,), payload={},
                check=check_renewal, auth_exceptions=("session",),
            )
            if status == "failed":
                return False
            if status == "session" and not self.login():
                return False
        elif not self.login():
            return False

        if self.cart_id is None:
            return True

        def recovered_etag(response, _):
            return response.headers.get("ETag")

        status, etag = self.send(
            "POST", f"/v2/carts/{quote(str(self.cart_id), safe='')}/recover",
            (200, 204), payload={}, check=recovered_etag,
        )
        if status != "ok":
            return False
        self.etag = etag or self.etag
        return True

    def operation(self, method, path, statuses, *, payload=None, headers=None,
                  check=None, match_cart=False):
        for attempt in range(2):
            attempt_headers = dict(headers or {})
            if match_cart and self.etag:
                attempt_headers["If-Match"] = self.etag
            status, result = self.send(
                method, path, statuses, payload=payload, headers=attempt_headers,
                check=check, auth_exceptions=RECOVERABLE if attempt == 0 else (),
            )
            if status not in RECOVERABLE:
                return status, result
            if not self.recover_session(status):
                return "failed", None
        return "failed", None

    def choose_variant(self):
        path = "/v2/catalog"
        for page in range(3):
            def read_catalog(response, body):
                data = body.get("data")
                products = data.get("products", []) if isinstance(data, dict) else []
                if isinstance(products, list):
                    for product in products:
                        if not isinstance(product, dict) or not has_id(product.get("id")):
                            continue
                        variants = product.get("variants")
                        if isinstance(variants, list):
                            for variant in variants:
                                if (isinstance(variant, dict)
                                        and variant.get("in_stock") is True
                                        and has_id(variant.get("id"))):
                                    return (product["id"], variant["id"]), None
                if page < 2 and body.get("next"):
                    return None, shop_url(body["next"], response.url)
                raise ValueError("Catalog did not supply an in-stock variant")

            status, result = self.operation("GET", path, (200,), check=read_catalog)
            if status != "ok":
                return None
            selection, path = result
            if selection is not None:
                return selection
        return None

    def journey(self):
        self.client.cookies.clear()
        self.cart_id = None
        self.etag = None
        if not self.login():
            return

        selection = self.choose_variant()
        if selection is None:
            return
        product_id, variant_id = selection

        def check_cart(response, body):
            cart_id, etag = body.get("id"), response.headers.get("ETag")
            if not has_id(cart_id) or not etag:
                raise ValueError("Cart creation did not return a cart ID and ETag")
            return cart_id, etag

        status, cart = self.operation(
            "POST", "/v2/carts", (201,),
            payload={"product_id": product_id, "variant_id": variant_id},
            check=check_cart,
        )
        if status != "ok":
            return
        self.cart_id, self.etag = cart

        def check_order(_, body):
            if body.get("accepted") is not True or not has_id(body.get("id")):
                raise ValueError("Checkout did not return an accepted order with an ID")

        self.operation(
            "POST", "/v2/orders", (201,), payload={"cart_id": self.cart_id},
            headers={"Idempotency-Key": str(self.cart_id)},
            check=check_order, match_cart=True,
        )

    @task
    def run_journey(self):
        self.journey()
        self.iteration += 1
        if self.iteration >= ITERATIONS:
            raise StopUser()


class DenialShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.first_tick = True

    def tick(self):
        if self.first_tick:
            self.first_tick = False
            return USERS, USERS
        if self.runner.user_count == 0:
            return None
        return USERS, USERS

