    loginForms.find(controls).first().attr('value') ||
    doc.find('form ' + controls + '[type="hidden"]').first().attr('value') ||
    doc.find('form ' + controls).first().attr('value') ||
    doc.find(controls + '[type="hidden"]').first().attr('value') ||
