import os
from html.parser import HTMLParser
from itertools import count
from urllib.parse import quote, urljoin, urlsplit

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
if BASE_URL != "http://127.0.0.1:8000":
    raise ValueError("BASE_URL must be http://127.0.0.1:8000")

USERS = 2
ITERATIONS = 2
ACCOUNTS = count()
AUTH_ERRORS = ("expired", "session")


class LoginForm(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.csrf = None

    def handle_starttag(self, tag, attrs):
        if tag == "input" and self.csrf is None:
            fields = dict(attrs)
            if fields.get("name") == "csrf" and fields.get("value"):
                self.csrf = fields["value"]


def has_id(value):
    return (isinstance(value, str) and bool(value.strip())) or type(value) is int


def stock_item(body):
    data = body.get("data")
    if not isinstance(data, dict) or not isinstance(data.get("products"), list):
        return None
    for product in data["products"]:
        if not isinstance(product, dict) or not has_id(product.get("id")):
            continue
        variants = product.get("variants")
        if not isinstance(variants, list):
            continue
        for variant in variants:
            if (isinstance(variant, dict) and variant.get("in_stock") is True
                    and has_id(variant.get("id"))):
                return product["id"], variant["id"]
    return None


def check_cart(response, body):
    if response.status_code != 201 or not has_id(body.get("id")):
        return "cart creation expected HTTP 201 with a cart id"
    if not response.headers.get("ETag"):
        return "cart creation omitted the ETag"
    return None


def check_order(response, body):
    if response.status_code in (200, 201) and body.get("accepted") is False:
        return "checkout declined: accepted=false"
    if response.status_code != 201:
        return f"checkout expected HTTP 201, got HTTP {response.status_code}"
    if body.get("accepted") is not True:
        return "checkout expected accepted=true"
    if not has_id(body.get("id")):
        return "checkout response omitted the order id"
    return None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.username = f"bench-{next(ACCOUNTS) % 16 + 1}"
        self.iterations = 0
        self.csrf = None
        self.cart_id = None
        self.etag = None

    def sample(self, method, path, check, *, payload=None, headers=None,
               expected_auth=(), name=None):
        request_headers = dict(headers or {})
        if method != "GET" and self.csrf:
            request_headers["X-CSRF-Token"] = self.csrf

        with self.client.request(
            method, path, name=name, json=payload, headers=request_headers,
            catch_response=True, allow_redirects=False, timeout=3,
        ) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            if not isinstance(body, dict):
                body = {}

            if response.status_code == 401 and body.get("error") in expected_auth:
                response.success()
                return response, body

            problem = check(response, body)
            if problem is not None:
                response.failure(problem)
                return None

            token = body.get("csrf")
            if isinstance(token, str) and token:
                self.csrf = token
            response.success()
            return response, body

    def login(self):
        self.csrf = None
        form = LoginForm()
        redirect = None

        def check_form(response, body):
            if response.status_code != 200:
                return f"login form expected HTTP 200, got HTTP {response.status_code}"
            form.feed(response.text)
            form.close()
            return None if form.csrf else "login form omitted input[name=csrf]"

        def check_login(response, body):
            nonlocal redirect
            if response.status_code == 302:
                location = response.headers.get("Location")
                if not location:
                    return "login redirect omitted Location"
                try:
                    redirect = urljoin(response.url, location)
                    parsed = urlsplit(redirect)
                except ValueError:
                    return "login redirect supplied an invalid Location"
                if (parsed.scheme, parsed.netloc) != ("http", "127.0.0.1:8000"):
                    return "login redirect left the shop origin"
                return None
            return check_login_done(response, body)

        def check_login_done(response, body):
            if response.status_code != 200:
                return f"login expected HTTP 200, got HTTP {response.status_code}"
            token = body.get("csrf")
            if not self.csrf and not (isinstance(token, str) and token):
                return "login response omitted the session CSRF token"
            return None

        if self.sample("GET", "/v2/login-form", check_form) is None:
            return False
        if self.sample(
            "POST", "/v2/login", check_login,
            payload={"username": self.username, "password": "bench", "csrf": form.csrf},
        ) is None:
            return False
        if redirect is not None:
            return self.sample("GET", redirect, check_login_done,
                               name="/v2/login (redirect)") is not None
        return True

    def recover(self, error):
        if error == "expired":
            def check_renew(response, body):
                if response.status_code != 200:
                    return f"session renewal expected HTTP 200, got HTTP {response.status_code}"
                return None

            renewed = self.sample(
                "POST", "/v2/session/renew", check_renew, payload={},
                expected_auth=("session",),
            )
            if renewed is None:
                return False
            if renewed[0].status_code == 401 and not self.login():
                return False
        elif not self.login():
            return False

        if self.cart_id is None:
            return True

        def check_recover(response, body):
            if not 200 <= response.status_code < 300:
                return f"cart recovery failed with HTTP {response.status_code}"
            return None

        cart_path = "/v2/carts/" + quote(str(self.cart_id), safe="")
        recovered = self.sample(
            "POST", cart_path + "/recover", check_recover, payload={},
            name="/v2/carts/{id}/recover",
        )
        if recovered is None:
            return False
        self.etag = recovered[0].headers.get("ETag") or self.etag
        return True

    def operation(self, method, path, check, *, payload=None, headers=None):
        for attempt in range(2):
            result = self.sample(
                method, path, check, payload=payload,
                headers=headers() if headers is not None else None,
                expected_auth=AUTH_ERRORS if attempt == 0 else (),
            )
            if result is None or result[0].status_code != 401:
                return result
            if not self.recover(result[1]["error"]):
                return None
        return None

    def journey(self):
        self.cart_id = None
        self.etag = None
        if not self.login():
            return

        selection = None

        def check_catalog(response, body):
            nonlocal selection
            if response.status_code != 200:
                return f"catalog expected HTTP 200, got HTTP {response.status_code}"
            selection = stock_item(body)
            return None if selection is not None else "catalog had no in-stock variant"

        if self.operation("GET", "/v2/catalog", check_catalog) is None:
            return
        product_id, variant_id = selection

        cart = self.operation(
            "POST", "/v2/carts", check_cart,
            payload={"product_id": product_id, "variant_id": variant_id},
        )
        if cart is None:
            return
        response, body = cart
        self.cart_id = body["id"]
        self.etag = response.headers["ETag"]
        order_key = str(self.cart_id)

        self.operation(
            "POST", "/v2/orders", check_order,
            payload={"cart_id": self.cart_id},
            headers=lambda: {"Idempotency-Key": order_key, "If-Match": self.etag},
        )

    @task
    def run_journey(self):
        self.journey()
        self.iterations += 1
        if self.iterations >= ITERATIONS:
            raise StopUser()


class ShopShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.started = False

    def tick(self):
        if self.started and self.get_current_user_count() == 0:
            return None
        self.started = True
        return USERS, USERS

