import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;
import io.gatling.javaapi.http.HttpRequestActionBuilder;
import java.net.URI;

public class ModelSimulation extends Simulation {
    private static final String BASE_URL = System.getenv("BASE_URL");
    private static final HttpProtocolBuilder HTTP = http.baseUrl(BASE_URL)
        .disableWarmUp()
        .disableFollowRedirect()
        .acceptHeader("application/json");

    private static final String IN_STOCK_PRODUCT =
        "data.products[?variants[?in_stock == `true`]] | [0]";

    private static String quote(String value) {
        StringBuilder json = new StringBuilder().append('"');
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c == '"' || c == '\\') {
                json.append('\\').append(c);
            } else if (c < 0x20) {
                json.append(String.format("\\u%04x", (int) c));
            } else {
                json.append(c);
            }
        }
        return json.append('"').toString();
    }

    private static String loginLocation(String value) {
        URI base = URI.create(BASE_URL);
        URI target = base.resolve("/v2/login").resolve(value);
        if (!base.getScheme().equalsIgnoreCase(target.getScheme())
            || !base.getHost().equalsIgnoreCase(target.getHost())
            || base.getPort() != target.getPort()
            || target.getUserInfo() != null) {
            throw new IllegalArgumentException("Login redirect left the shop origin");
        }
        return target.toString();
    }

    private static ChainBuilder login() {
        return exec(session -> session.remove("csrf").remove("loginLocation"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200), css("input[name='csrf']", "value").saveAs("formCsrf")))
            .exitHereIfFailed()
            .exec(http("login").post("/v2/login")
                .header("Content-Type", "application/json")
                .body(StringBody(session ->
                    "{\"username\":\"bench-" + (Math.floorMod(session.userId() - 1, 16) + 1)
                    + "\",\"password\":\"bench\",\"csrf\":" + quote(session.getString("formCsrf")) + "}"))
                .check(status().in(200, 302))
                .checkIf((response, session) -> response.status().code() == 200)
                .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((response, session) -> response.status().code() == 302)
                .then(header("Location").transform(ModelSimulation::loginLocation).saveAs("loginLocation")))
            .exitHereIfFailed()
            .exec(doIf(session -> session.contains("loginLocation")).then(
                exec(http("login redirect").get("#{loginLocation}")
                    .check(status().is(200), jsonPath("$.csrf").saveAs("csrf")))
                    .exitHereIfFailed()));
    }

    private static HttpRequestActionBuilder mutation(HttpRequestActionBuilder request) {
        return request.header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}");
    }

    private static HttpRequestActionBuilder authStatus(
        HttpRequestActionBuilder request, int success, boolean retry
    ) {
        if (retry) {
            return request.check(status().is(success));
        }
        return request.check(status().in(success, 401))
            .checkIf((response, session) -> response.status().code() == 401)
            .then(jsonPath("$.error").in("expired", "session").saveAs("authError"));
    }

    private static ChainBuilder recoverAuth() {
        return exec(doIf(session -> "expired".equals(session.getString("authError"))).then(
                exec(mutation(http("session renew").post("/v2/session/renew"))
                    .body(StringBody("{}"))
                    .check(status().in(200, 401), status().saveAs("renewStatus"))
                    .checkIf((response, session) -> response.status().code() == 200)
                    .then(jsonPath("$.csrf").saveAs("csrf"))
                    .checkIf((response, session) -> response.status().code() == 401)
                    .then(jsonPath("$.error").is("session")))
                    .exitHereIfFailed()))
            .exec(doIf(session -> "session".equals(session.getString("authError"))
                || session.getInt("renewStatus") == 401).then(login()))
            .exec(doIf(session -> session.contains("cart")).then(
                exec(mutation(http("cart recover").post("/v2/carts/#{cart}/recover"))
                    .body(StringBody("{}"))
                    .check(status().is(200), header("ETag").optional().saveAs("etag"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))
                    .exitHereIfFailed()));
    }

    private static ChainBuilder withRecovery(
        HttpRequestActionBuilder first, HttpRequestActionBuilder retry
    ) {
        return exec(session -> session.remove("authError").remove("renewStatus"))
            .exec(first)
            .exitHereIfFailed()
            .exec(doIf(session -> session.contains("authError")).then(
                recoverAuth().exec(retry).exitHereIfFailed()));
    }

    private static HttpRequestActionBuilder catalog(boolean retry) {
        return authStatus(http("catalog").get("/v2/catalog"), 200, retry)
            .checkIf((response, session) -> response.status().code() == 200)
            .then(jmesPath(IN_STOCK_PRODUCT + ".id").saveAs("product"),
                jmesPath(IN_STOCK_PRODUCT + ".variants[?in_stock == `true`] | [0].id")
                    .saveAs("variant"));
    }

    private static HttpRequestActionBuilder cart(boolean retry) {
        return authStatus(mutation(http("cart").post("/v2/carts"))
            .body(StringBody(session -> "{\"product_id\":" + quote(session.getString("product"))
                + ",\"variant_id\":" + quote(session.getString("variant")) + "}")), 201, retry)
            .checkIf((response, session) -> response.status().code() == 201)
            .then(jsonPath("$.id").saveAs("cart"), header("ETag").saveAs("etag"),
                jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    private static HttpRequestActionBuilder checkout(boolean retry) {
        return authStatus(mutation(http("checkout").post("/v2/orders"))
            .header("Idempotency-Key", "checkout-#{cart}")
            .header("If-Match", "#{etag}")
            .body(StringBody(session -> "{\"cart_id\":" + quote(session.getString("cart")) + "}")),
            201, retry)
            .checkIf((response, session) -> response.status().code() == 201)
            .then(jsonPath("$.accepted").is("true"), jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    private static ChainBuilder journey() {
        return exec(session -> session.remove("cart").remove("etag").remove("product").remove("variant"))
            .exec(login())
            .exec(withRecovery(catalog(false), catalog(true)))
            .exec(withRecovery(cart(false), cart(true)))
            .exec(withRecovery(checkout(false), checkout(true)));
    }

    public ModelSimulation() {
        setUp(scenario("matrix").repeat(2).on(journey()).injectOpen(atOnceUsers(2)))
            .protocols(HTTP)
            .assertions(
                details("checkout").responseTime().percentile3().lt(250),
                global().failedRequests().count().is(0L));
    }
}

