import http from 'k6/http';
import { check } from 'k6';

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
    'http_req_duration{name:checkout}': ['p(95)<250'],
  },
};

function body(response) {
  try {
    return response.json() || {};
  } catch (_) {
    return {};
  }
}

function raw(state, method, path, data = null, extraHeaders = {}) {
  const route = path.startsWith(base + '/') ? path.slice(base.length) : path;
  if (!route.startsWith('/') || route.startsWith('//')) {
    throw new Error('Expected a local shop route');
  }

  const headers = Object.assign({}, extraHeaders);
  if (data !== null) headers['Content-Type'] = 'application/json';
  if (method !== 'GET' && state.csrf) headers['X-CSRF-Token'] = state.csrf;

  const response = http.request(method, base + route, data === null ? null : JSON.stringify(data), {
    headers,
    tags: { name: method === 'POST' && route === '/v2/orders' ? 'checkout' : route },
    redirects: 0,
    timeout: '3s',
  });
  if (response.status >= 200 && response.status < 400) {
    const token = body(response).csrf;
    if (token) state.csrf = token;
  }
  return response;
}

function login(state) {
  state.csrf = '';
  state.grant = '';

  const form = raw(state, 'GET', '/v2/login-form');
  const html = form.html();
  const field = 'input[name="csrf"]:not([disabled])';
  const token = html.find('form[action="/v2/login"] ' + field).first().attr('value')
    || html.find('form ' + field).first().attr('value')
    || html.find(field).first().attr('value');
  if (!check(form, { 'login form contains CSRF': r => r.status === 200 && !!token })) {
    return false;
  }

  let response = raw(state, 'POST', '/v2/login', {
    username: `bench-${__VU}`,
    password: 'bench',
    csrf: token,
  });
  if (response.status === 302 && response.headers.Location) {
    response = raw(state, 'GET', response.headers.Location);
    state.grant = body(response).grant_id;
  }
  return check(response, { 'login succeeded': r => r.status === 200 && !!state.csrf });
}

function request(state, method, path, data = null, headers = {}) {
  const response = raw(state, method, path, data, headers);
  if (response.status !== 401) return response;

  const error = body(response).error;
  if (error !== 'expired' && error !== 'session') return response;

  const renewed = raw(state, 'POST', '/v2/session/renew', {});
  if (renewed.status !== 200 && (error !== 'session' || !login(state))) {
    return response;
  }
  if (state.cart) {
    const recovered = raw(state, 'POST', `/v2/carts/${state.cart}/recover`, {});
    if (recovered.status < 200 || recovered.status >= 300) return response;
  }
  return raw(state, method, path, data, headers);
}

export default function () {
  const state = { csrf: '', cart: '', grant: '' };
  if (!login(state)) return;

  const catalog = request(state, 'GET', '/v2/catalog');
  const data = body(catalog).data;
  const products = data && Array.isArray(data.products) ? data.products : [];
  const product = products.find(p => p.variants.some(v => v.in_stock));
  if (!check(catalog, { 'catalog has an in-stock variant': r => r.status === 200 && !!product })) {
    return;
  }

  const variant = product.variants.find(v => v.in_stock);
  const cartPayload = { product_id: product.id, variant_id: variant.id };
  if (state.grant) cartPayload.grant_id = state.grant;

  const created = request(state, 'POST', '/v2/carts', cartPayload);
  const cartId = body(created).id;
  if (!check(created, { 'cart created': r => r.status === 201 && !!cartId })) return;
  state.cart = cartId;

  const headers = { 'Idempotency-Key': String(cartId) };
  if (created.headers.Etag) headers['If-Match'] = created.headers.Etag;
  const order = request(state, 'POST', '/v2/orders', { cart_id: cartId }, headers);
  check(order, { 'checkout accepted': r => r.status === 201 && body(r).accepted === true });
}

import os
from html.parser import HTMLParser
from itertools import count
from urllib.parse import quote, urljoin, urlsplit
from uuid import uuid4

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
USERS = 2
ITERATIONS = 2
CHECKOUT_LIMIT_MS = 250
ACCOUNT_NUMBERS = count()


def local_url(value, base=BASE_URL + "/"):
    if not isinstance(value, str) or not value:
        return None
    try:
        target = urlsplit(urljoin(base, value))
    except ValueError:
        return None
    if target.scheme != "http" or target.netloc != "127.0.0.1:8000":
        return None
    return target._replace(fragment="").geturl()


class LoginForm(HTMLParser):
    def __init__(self):
        super().__init__()
        self.csrf = None

    def handle_starttag(self, tag, attrs):
        if tag == "input" and self.csrf is None:
            attributes = dict(attrs)
            if attributes.get("name") == "csrf" and attributes.get("value"):
                self.csrf = attributes["value"]


def login_form_token(html):
    form = LoginForm()
    form.feed(html)
    form.close()
    return form.csrf


def in_stock_item(body):
    for product in body.get("data", {}).get("products", []):
        for variant in product.get("variants", []):
            if variant.get("in_stock") is True and "id" in product and "id" in variant:
                return product["id"], variant["id"]
    return None


class CheckoutUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.username = f"bench-{next(ACCOUNT_NUMBERS) % 16 + 1}"
        self.iterations = 0
        self.csrf = None
        self.cart_id = None
        self.etag = None

    def request(self, method, path, *, payload=None, headers=None, statuses=(200,),
                check=None, recover=True, allow_revoked=False):
        url = local_url(path)
        if url is None:
            self.environment.process_exit_code = 99
            return None, {}

        checkout = method == "POST" and urlsplit(url).path == "/v2/orders"
        for attempt in range(2):
            request_headers = dict(headers or {})
            if method != "GET" and self.csrf:
                request_headers["X-CSRF-Token"] = self.csrf
            if checkout and self.etag:
                request_headers["If-Match"] = self.etag

            with self.client.request(
                method, url, json=payload, headers=request_headers,
                name="checkout" if checkout else None,
                catch_response=True, allow_redirects=False, timeout=3,
            ) as response:
                try:
                    body = response.json()
                except ValueError:
                    body = {}
                if not isinstance(body, dict):
                    body = {}

                status = response.status_code
                error = body.get("error")
                retry = (recover and attempt == 0 and status == 401
                         and error in ("expired", "session"))
                revoked = allow_revoked and status == 401 and error == "session"

                failure = None
                if not retry and not revoked:
                    if checkout and status in (200, 201) and body.get("accepted") is not True:
                        failure = "checkout rejected: expected accepted=true"
                    elif status not in statuses:
                        failure = f"unexpected HTTP {status}" + (f": {error}" if error else "")
                    elif check is not None:
                        failure = check(response, body)

                    if failure is None and body.get("csrf"):
                        self.csrf = body["csrf"]

                if checkout:
                    elapsed_ms = response.request_meta["response_time"]
                    if elapsed_ms >= CHECKOUT_LIMIT_MS:
                        threshold_failure = (
                            f"checkout latency threshold breached: {elapsed_ms:.1f} ms "
                            f">= {CHECKOUT_LIMIT_MS} ms"
                        )
                        failure = f"{threshold_failure}; {failure}" if failure else threshold_failure

                if failure:
                    response.failure(failure)
                    self.environment.process_exit_code = 99
                else:
                    response.success()

            if not retry:
                return (None, {}) if failure else (response, body)
            if not self.recover_session(error):
                return None, {}

    def login(self):
        self.client.cookies.clear()
        self.csrf = None
        token = None

        def check_form(response, _body):
            nonlocal token
            token = login_form_token(response.text)
            if not token:
                return "login form missing the csrf input"

        form, _ = self.request("GET", "/v2/login-form", check=check_form, recover=False)
        if form is None:
            return False

        def check_login(response, body):
            if response.status_code == 302:
                if not local_url(response.headers.get("Location"), response.url):
                    return "login redirect missing a valid local Location"
            elif not body.get("csrf"):
                return "login response missing csrf"

        response, _ = self.request(
            "POST", "/v2/login",
            payload={"username": self.username, "password": "bench", "csrf": token},
            statuses=(200, 302), check=check_login, recover=False,
        )
        if response is None:
            return False
        if response.status_code == 302:
            location = local_url(response.headers.get("Location"), response.url)

            def check_redirect(_response, body):
                if not body.get("csrf") and not self.csrf:
                    return "login redirect response missing csrf"

            response, _ = self.request("GET", location, check=check_redirect, recover=False)
        return response is not None

    def recover_session(self, reason):
        if reason == "expired":
            def check_renewal(_response, body):
                if not body.get("csrf"):
                    return "session renewal response missing csrf"

            response, _ = self.request(
                "POST", "/v2/session/renew", payload={}, check=check_renewal,
                recover=False, allow_revoked=True,
            )
            if response is None:
                return False
            if response.status_code == 401 and not self.login():
                return False
        elif not self.login():
            return False

        if self.cart_id is not None:
            path = "/v2/carts/" + quote(str(self.cart_id), safe="") + "/recover"
            response, _ = self.request(
                "POST", path, payload={}, statuses=(200, 201, 204), recover=False,
            )
            if response is None:
                return False
            self.etag = response.headers.get("ETag", self.etag)
        return True

    def journey(self):
        self.cart_id = None
        self.etag = None
        if not self.login():
            return

        page = "/v2/catalog"
        item = None
        for page_number in range(3):
            next_page = None

            def check_catalog(response, body):
                nonlocal item, next_page
                item = in_stock_item(body)
                if item is None:
                    next_page = local_url(body.get("next"), response.url)
                    if next_page is None or page_number == 2:
                        return "no in-stock variant found within the catalog page limit"

            response, _ = self.request("GET", page, check=check_catalog)
            if response is None:
                return
            if item is not None:
                break
            page = next_page

        def check_cart(_response, body):
            if not body.get("id"):
                return "cart creation response missing id"

        response, cart = self.request(
            "POST", "/v2/carts", statuses=(201,), check=check_cart,
            payload={"product_id": item[0], "variant_id": item[1]},
        )
        if response is None:
            return
        self.cart_id = cart["id"]
        self.etag = response.headers.get("ETag")

        def check_order(_response, body):
            if not body.get("id"):
                return "accepted checkout response missing order id"

        self.request(
            "POST", "/v2/orders", statuses=(201,), check=check_order,
            payload={"cart_id": self.cart_id},
            headers={"Idempotency-Key": uuid4().hex},
        )

    @task
    def run_journey(self):
        self.journey()
        self.iterations += 1
        if self.iterations >= ITERATIONS:
            raise StopUser()


class CheckoutShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.started = False

    def tick(self):
        if not self.started:
            self.started = True
            return USERS, USERS
        if self.runner.user_count == 0:
            return None
        return USERS, USERS

