import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;
import java.net.URI;
import java.time.Duration;

public class ModelSimulation extends Simulation {
    private static final String BASE_URL = System.getenv("BASE_URL");
    private static final int USERS = 15;
    private static final int ROUNDS = 12;
    private static final long SLOT_MS = 200;
    private static final Duration PERIOD = Duration.ofMillis(USERS * SLOT_MS);

    private static final HttpProtocolBuilder HTTP = http.baseUrl(BASE_URL)
        .disableWarmUp()
        .disableFollowRedirect()
        .acceptHeader("application/json");

    private static int lane(Session session) {
        return (int) ((session.userId() - 1) % USERS);
    }

    private static String loginRedirect(String location) {
        URI target = URI.create(BASE_URL).resolve("/v2/login").resolve(location);
        if (!"http".equalsIgnoreCase(target.getScheme())
                || !"127.0.0.1".equals(target.getHost())
                || target.getPort() != 8000
                || target.getRawUserInfo() != null) {
            throw new IllegalArgumentException("Login redirect is outside the fixture origin");
        }
        return target.toASCIIString();
    }

    private static String loginBody(Session session) {
        String token = session.getString("formCsrf")
            .replace("\\", "\\\\")
            .replace("\"", "\\\"")
            .replace("\r", "\\r")
            .replace("\n", "\\n")
            .replace("\t", "\\t");
        return "{\"username\":\"bench-" + (lane(session) + 1)
            + "\",\"password\":\"bench\",\"csrf\":\"" + token + "\"}";
    }

    private static ChainBuilder login() {
        return exec(flushCookieJar())
            .exec(session -> session.remove("csrf").remove("formCsrf").remove("loginLocation"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200),
                    css("input[name='csrf']", "value").saveAs("formCsrf")))
            .exec(http("login").post("/v2/login")
                .header("Content-Type", "application/json")
                .body(StringBody(ModelSimulation::loginBody))
                .check(
                    status().in(200, 302),
                    checkIf((response, session) -> response.status().code() == 200)
                        .then(jsonPath("$.csrf").saveAs("csrf")),
                    checkIf((response, session) -> response.status().code() == 302)
                        .then(header("Location").transform(ModelSimulation::loginRedirect)
                            .saveAs("loginLocation")),
                    checkIf((response, session) -> response.status().code() == 302
                            && response.body().string().trim().startsWith("{"))
                        .then(jsonPath("$.csrf").optional().saveAs("csrf"))))
            .doIf(session -> session.contains("loginLocation")).then(
                exec(http("login redirect").get("#{loginLocation}")
                    .check(
                        status().is(200),
                        checkIf(session -> !session.contains("csrf"))
                            .then(jsonPath("$.csrf").saveAs("csrf")),
                        checkIf((response, session) -> response.body().string().trim().startsWith("{"))
                            .then(jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static ChainBuilder renew() {
        return exec(http("session renewal").post("/v2/session/renew")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(
                    status().in(200, 401),
                    status().saveAs("renewStatus"),
                    checkIf((response, session) -> response.status().code() == 200)
                        .then(jsonPath("$.csrf").saveAs("csrf")),
                    checkIf((response, session) -> response.status().code() == 401)
                        .then(jsonPath("$.error").is("session"))))
            .doIf(session -> session.getInt("renewStatus") == 401).then(login());
    }

    private static ChainBuilder workAttempt() {
        return exec(session -> session.remove("workStatus").remove("workError"))
            .exec(http("work").post("/v2/work")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(
                    status().in(200, 401, 429),
                    status().saveAs("workStatus"),
                    checkIf((response, session) -> response.status().code() == 200)
                        .then(jsonPath("$.ok").ofBoolean().is(true),
                            jsonPath("$.csrf").optional().saveAs("csrf")),
                    checkIf((response, session) -> response.status().code() == 401)
                        .then(jsonPath("$.error").in("expired", "session").saveAs("workError")),
                    checkIf((response, session) -> response.status().code() == 429)
                        .then(header("Retry-After").is("1"))));
    }

    private static boolean canRetry(Session session) {
        int status = session.getInt("workStatus");
        return (status == 429 && session.getInt("throttleRetries") < 4)
            || (status == 401 && !session.getBoolean("authRetried"));
    }

    private static ChainBuilder work() {
        return exec(session -> session.set("throttleRetries", 0).set("authRetried", false))
            .exec(workAttempt())
            .asLongAs(ModelSimulation::canRetry, "workRetryLoop", false).on(
                doIfOrElse(session -> session.getInt("workStatus") == 429)
                    .then(pause(Duration.ofSeconds(1))
                        .exec(session -> session.set("throttleRetries",
                            session.getInt("throttleRetries") + 1)))
                    .orElse(
                        exec(session -> session.set("authRetried", true))
                            .doIfOrElse(session -> "expired".equals(session.getString("workError")))
                            .then(renew())
                            .orElse(login()))
                    .exec(workAttempt()));
    }

    public ModelSimulation() {
        ScenarioBuilder workload = scenario("Work pool")
            .pause(session -> Duration.ofMillis(lane(session) * SLOT_MS))
            .repeat(ROUNDS).on(
                pace(PERIOD)
                    .exec(Session::markAsSucceeded)
                    .exitBlockOnFail().on(login().exec(work())));

        setUp(workload.injectOpen(atOnceUsers(USERS)))
            .protocols(HTTP)
            .maxDuration(Duration.ofSeconds(40));
    }
}

