import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const origin = 'http://127.0.0.1:8000';
const base = (__ENV.BASE_URL || origin).replace(/\/+$/, '');
if (base !== origin) throw new Error('BASE_URL must target ' + origin);

const vuCount = 16;
const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '36s',
      preAllocatedVUs: vuCount,
      maxVUs: vuCount,
      gracefulStop: '4s',
    },
  },
  noCookiesReset: true,
  thresholds: {
    checks: ['rate>=0.99'],
    business_failure: ['rate<=0.01'],
  },
};

let csrf = '';

function header(response, name) {
  const key = Object.keys(response.headers).find(
    (key) => key.toLowerCase() === name.toLowerCase()
  );
  return key === undefined ? '' : response.headers[key];
}

function request(method, path, payload, authenticated = false) {
  const headers = {};
  if (payload !== undefined) headers['Content-Type'] = 'application/json';
  if (authenticated && method !== 'GET') headers['X-CSRF-Token'] = csrf;

  const response = http.request(
    method,
    base + path,
    payload === undefined ? null : JSON.stringify(payload),
    { headers, redirects: 0, timeout: '3s' }
  );

  let data = {};
  try {
    data = response.json() || {};
  } catch (_) {
    // Login forms and redirects need not have a JSON body.
  }

  if (
    response.status >= 200 && response.status < 400 &&
    typeof data.csrf === 'string' && data.csrf
  ) {
    csrf = data.csrf;
  }
  return { response, data };
}

function formToken(selection) {
  const inputs = selection.find('input[name="csrf"][value]:not([disabled])');
  return inputs.filter('[type="hidden"]').first().attr('value') ||
    inputs.first().attr('value');
}

function loginRedirect(location) {
  const value = location.trim();
  if (!value) return '';
  if (value.startsWith(base + '/')) return value.slice(base.length);
  if (value.startsWith('//') || /^[a-z][a-z0-9+.-]*:/i.test(value)) return '';
  if (value.startsWith('/')) return value;
  if (value.startsWith('?')) return '/v2/login' + value;
  return '/v2/' + value;
}

function login() {
  csrf = '';
  const { response } = request('GET', '/v2/login-form');
  let token;
  if (response.status === 200) {
    const doc = response.html();
    const form = doc.find(
      'form[action="/v2/login"], form[action="' + base + '/v2/login"], ' +
      'form[action="login"], form[action="./login"]'
    );
    token = formToken(form) || formToken(doc);
  }
  if (!check(token, { 'login form supplies csrf': (value) => Boolean(value) })) {
    return false;
  }

  let result = request('POST', '/v2/login', {
    username: `bench-${((__VU - 1) % vuCount) + 1}`,
    password: 'bench',
    csrf: token,
  });

  if (result.response.status === 302) {
    const path = loginRedirect(header(result.response, 'Location'));
    if (path) result = request('GET', path);
  }

  return check(result, {
    'login establishes a session': (r) => r.response.status === 200 && Boolean(csrf),
  });
}

function succeeded(result) {
  return result.response.status === 200 && result.data.ok === true;
}

function expired(result) {
  return result.response.status === 401 && result.data.error === 'expired';
}

function scheduledThrottle(result) {
  return result.response.status === 429 &&
    Number(header(result.response, 'Retry-After')) === 1;
}

function postWork() {
  const result = request('POST', '/v2/work', {}, true);
  businessFailure.add(
    !succeeded(result) && !expired(result) && !scheduledThrottle(result)
  );
  return result;
}

export default function () {
  if (!login()) return;

  let result = postWork();
  let throttleRetries = 0;
  let recoveryAttempted = false;

  while (!succeeded(result)) {
    if (scheduledThrottle(result) && throttleRetries < 4) {
      throttleRetries++;
      sleep(1);
    } else if (
      !recoveryAttempted &&
      (expired(result) ||
        (result.response.status === 401 && result.data.error === 'session'))
    ) {
      recoveryAttempted = true;
      const renewal = request('POST', '/v2/session/renew', {}, true);
      if (renewal.response.status !== 200 && !login()) break;
    } else {
      break;
    }

    result = postWork();
  }

  check(result, { 'work completed': succeeded });
}

import os
import time
from html.parser import HTMLParser
from itertools import count
from urllib.parse import urljoin, urlsplit

from gevent import sleep
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
RATE = 5
USERS = 8
DURATION = 5 + 30
TIMEOUT = 3
RECOVERABLE = ("expired", "session")
ACCOUNTS = count(1)


class LoginForm(HTMLParser):
    def __init__(self):
        super().__init__()
        self.csrf = None

    def handle_starttag(self, tag, attrs):
        if tag == "input" and self.csrf is None:
            fields = dict(attrs)
            if fields.get("name") == "csrf" and "disabled" not in fields:
                self.csrf = fields.get("value") or None


def json_object(response):
    try:
        body = response.json()
    except ValueError:
        return {}
    return body if isinstance(body, dict) else {}


class ArrivalPlan:
    def __init__(self):
        self.launched = None
        self.anchor = None
        self.first_work = Semaphore()
        self.slot_lock = Semaphore()
        self.slot = 1

    def cutoff(self):
        if self.anchor is None:
            return self.launched + 9.5
        return self.anchor + DURATION

    def next_start(self):
        with self.slot_lock:
            if self.slot >= RATE * DURATION:
                return None
            deadline = self.anchor + (self.slot + 0.5) / RATE
            self.slot += 1
            return deadline


PLAN = ArrivalPlan()


class MatrixUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.username = f"bench-{(next(ACCOUNTS) - 1) % 16 + 1}"
        self.csrf = ""
        if not self.login():
            raise StopUser()

    def headers(self):
        return {"X-CSRF-Token": self.csrf} if self.csrf else {}

    def update_csrf(self, body):
        token = body.get("csrf")
        if isinstance(token, str) and token:
            self.csrf = token

    def login(self):
        self.csrf = ""
        with self.client.get(
            "/v2/login-form", catch_response=True, allow_redirects=False,
            timeout=TIMEOUT,
        ) as response:
            form = LoginForm()
            if response.status_code == 200:
                form.feed(response.text)
                form.close()
            if not form.csrf:
                response.failure("Login form did not supply a CSRF token")
                return False

        redirect = None
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": form.csrf},
            catch_response=True, allow_redirects=False, timeout=TIMEOUT,
        ) as response:
            if response.status_code == 302:
                location = response.headers.get("Location")
                if not location:
                    response.failure("Login redirect did not supply a Location")
                    return False
                redirect = urljoin(BASE_URL + "/v2/login", location)
                target = urlsplit(redirect)
                if (target.scheme, target.netloc) != ("http", "127.0.0.1:8000"):
                    response.failure("Login redirect points outside the fixture")
                    return False
                self.update_csrf(json_object(response))
            elif 200 <= response.status_code < 300:
                self.update_csrf(json_object(response))
                if not self.csrf:
                    response.failure("Login did not supply a session CSRF token")
                    return False
            else:
                response.failure(f"Login returned HTTP {response.status_code}")
                return False

        if redirect is not None:
            with self.client.get(
                redirect, name="/v2/login redirect", catch_response=True,
                allow_redirects=False, timeout=TIMEOUT,
            ) as response:
                if not 200 <= response.status_code < 300:
                    response.failure(f"Login redirect returned HTTP {response.status_code}")
                    return False
                self.update_csrf(json_object(response))
                if not self.csrf:
                    response.failure("Login redirect did not supply a session CSRF token")
                    return False
        return True

    def renew(self):
        with self.client.post(
            "/v2/session/renew", json={}, headers=self.headers(),
            catch_response=True, allow_redirects=False, timeout=TIMEOUT,
        ) as response:
            body = json_object(response)
            if response.status_code == 200:
                self.update_csrf(body)
                return True
            if response.status_code == 401 and body.get("error") == "session":
                response.success()
            else:
                response.failure(f"Session renewal returned HTTP {response.status_code}")
                return False
        return time.monotonic() < PLAN.cutoff() and self.login()

    def work(self):
        recovered = False
        throttle_retries = 0
        while (started := time.monotonic()) < PLAN.cutoff():
            with self.client.post(
                "/v2/work", json={}, headers=self.headers(),
                catch_response=True, allow_redirects=False, timeout=TIMEOUT,
            ) as response:
                body = json_object(response)
                status = response.status_code
                error = body.get("error")
                if status == 200 and body.get("ok") is True:
                    self.update_csrf(body)
                    response.success()
                    return started
                if status == 401 and error in RECOVERABLE:
                    response.success()
                    outcome = error
                elif status == 429:
                    try:
                        retry_after = float(response.headers.get("Retry-After", ""))
                    except ValueError:
                        retry_after = None
                    if retry_after != 1:
                        response.failure("Work was throttled without Retry-After: 1")
                        return None
                    response.success()
                    outcome = "throttled"
                else:
                    response.failure(f"Work did not return HTTP 200 with ok=true (HTTP {status})")
                    return None

            if outcome == "throttled":
                if throttle_retries >= 4 or time.monotonic() + retry_after >= PLAN.cutoff():
                    return None
                throttle_retries += 1
                sleep(retry_after)
            else:
                if recovered or time.monotonic() >= PLAN.cutoff():
                    return None
                recovered = True
                if not (self.login() if outcome == "session" else self.renew()):
                    self.csrf = ""
                    return None
        return None

    @task
    def run_scenario(self):
        if not self.csrf:
            raise StopUser()

        if PLAN.anchor is None:
            with PLAN.first_work:
                if PLAN.anchor is None:
                    if time.monotonic() >= PLAN.cutoff():
                        raise StopUser()
                    PLAN.anchor = self.work()
                    return

        deadline = PLAN.next_start()
        if deadline is None:
            raise StopUser()
        sleep(max(0, deadline - time.monotonic()))
        self.work()


class MatrixShape(LoadTestShape):
    def tick(self):
        now = time.monotonic()
        if PLAN.launched is None:
            PLAN.launched = now

        if PLAN.anchor is None:
            if now >= PLAN.launched + 10:
                return None
        else:
            end = PLAN.cutoff()
            if now >= end + 3.5 or (now >= end and self.runner.user_count == 0):
                return None

        return USERS, USERS

