import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;
import java.time.Duration;

public class ModelSimulation extends Simulation {
    private static final HttpProtocolBuilder HTTP = http
        .baseUrl(System.getenv("BASE_URL"))
        .disableWarmUp()
        .disableFollowRedirect()
        .acceptHeader("application/json");

    private static final String STOCKED_PRODUCT =
        "data.products[?variants[?in_stock == `true`]] | [0]";

    private static ChainBuilder login() {
        return exec(flushCookieJar())
            .exec(session -> session.remove("csrf").remove("loginLocation"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200),
                    css("input[name='csrf']", "value").saveAs("formCsrf")))
            .exitHereIfFailed()
            .exec(http("login").post("/v2/login")
                .header("Content-Type", "application/json")
                .body(StringBody(
                    "{\"username\":\"#{username}\",\"password\":\"#{password}\",\"csrf\":\"#{formCsrf}\"}"))
                .check(status().in(200, 302), status().saveAs("loginStatus"))
                .checkIf((response, session) -> response.status().code() == 200)
                    .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((response, session) -> response.status().code() == 302)
                    .then(header("Location").saveAs("loginLocation")))
            .exitHereIfFailed()
            .doIf(session -> session.getInt("loginStatus") == 302).then(
                exec(http("login redirect").get("#{loginLocation}")
                    .check(status().is(200), jsonPath("$.csrf").saveAs("csrf"))))
            .exitHereIfFailed();
    }

    private static ChainBuilder journey() {
        return login()
            .exec(http("catalog").get("/v2/catalog")
                .check(status().is(200),
                    jmesPath(STOCKED_PRODUCT + ".id").saveAs("productId"),
                    jmesPath(STOCKED_PRODUCT + ".variants[?in_stock == `true`] | [0].id")
                        .saveAs("variantId")))
            .exitHereIfFailed()
            .exec(http("cart").post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{\"product_id\":\"#{productId}\",\"variant_id\":\"#{variantId}\"}"))
                .check(status().is(201),
                    jsonPath("$.id").saveAs("cartId"),
                    header("ETag").saveAs("cartEtag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exitHereIfFailed()
            .pause(Duration.ofMillis(450))
            .exec(http("commit").post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("If-Match", "#{cartEtag}")
                .header("Idempotency-Key", "#{cartId}")
                .body(StringBody("{\"cart_id\":\"#{cartId}\"}"))
                .check(status().is(201),
                    jsonPath("$.accepted").is("true"),
                    jsonPath("$.id").exists(),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exitHereIfFailed();
    }

    public ModelSimulation() {
        ScenarioBuilder users = scenario("Exclusive account journeys")
            .feed(jsonFile("/fixtures/accounts.json").queue())
            .repeat(2).on(journey());

        setUp(users.injectOpen(atOnceUsers(2)))
            .protocols(HTTP)
            .assertions(global().failedRequests().count().is(0L));
    }
}

