import http from 'k6/http';
import { check, sleep } from 'k6';
import exec from 'k6/execution';

const origin = 'http://127.0.0.1:8000';
const base = (__ENV.BASE_URL || origin).replace(/\/+$/, '');
if (base !== origin) throw new Error('BASE_URL must point to the local shop');

const users = 2;
const iterations = 2;
const accounts = JSON.parse(open('/fixtures/accounts.json'));
if (!Array.isArray(accounts) || accounts.length < users) {
  throw new Error('The account fixture must have one row per VU');
}
const owners = new Set();
for (const row of accounts.slice(0, users)) {
  if (!row || !row.username || !row.password || owners.has(row.username) ||
      !Number.isFinite(row.delay) || row.delay < 0) {
    throw new Error('Invalid or shared account in the fixture');
  }
  owners.add(row.username);
}

export const options = {
  noCookiesReset: true,
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: users,
      iterations: iterations,
      maxDuration: '30s',
    },
  },
  thresholds: { checks: ['rate==1'] },
};

function verify(name, condition) {
  return check(Boolean(condition), { [name]: (ok) => ok });
}

function header(response, name) {
  const key = Object.keys(response.headers).find(
    (key) => key.toLowerCase() === name.toLowerCase()
  );
  return key ? response.headers[key] : undefined;
}

function send(state, path, method = 'GET', payload = null, extra = {}) {
  const headers = Object.assign({}, extra);
  if (payload !== null) headers['Content-Type'] = 'application/json';
  if (method !== 'GET' && state.csrf) headers['X-CSRF-Token'] = state.csrf;

  const response = http.request(
    method,
    base + path,
    payload === null ? null : JSON.stringify(payload),
    { headers, redirects: 0, timeout: '3s' }
  );
  let data = {};
  try { data = response.json() || {}; } catch (_) { /* HTML or empty body */ }
  if (response.status >= 200 && response.status < 400 && data.csrf) {
    state.csrf = data.csrf;
  }
  return { response, status: response.status, data };
}

function localPath(link, from) {
  if (typeof link !== 'string' || !link || link.includes('\\')) return null;
  if (link.startsWith(base + '/')) link = link.slice(base.length);
  if (link.startsWith('//') || /^[a-z][a-z0-9+.-]*:/i.test(link)) return null;
  if (link.startsWith('/')) return link;
  const path = from.split('?')[0];
  if (link.startsWith('?')) return path + link;
  return path.slice(0, path.lastIndexOf('/') + 1) + link;
}

const csrfSelector = 'input[name="csrf"][value]:not([disabled])';

function readToken(scope) {
  const hidden = new Set();
  const values = new Set();
  scope.find(csrfSelector).each((_, input) => {
    const value = input.attr('value');
    if (!value || !value.trim()) return;
    values.add(value);
    if ((input.attr('type') || '').toLowerCase() === 'hidden') hidden.add(value);
  });
  const preferred = hidden.size ? hidden : values;
  return preferred.size === 1 ? Array.from(preferred)[0] : null;
}

function loginFormToken(response) {
  const doc = response.html();
  const loginForms = doc.find(
    'form[action="/v2/login"], form[action="login"], form[action="./login"], ' +
    'form[action="' + base + '/v2/login"]'
  );
  if (loginForms.find(csrfSelector).size()) return readToken(loginForms);

  const forms = doc.find('form:not([action]), form[action=""]');
  if (forms.find(csrfSelector).size()) {
    const token = readToken(forms);
    if (token) return token;
  }
  return readToken(doc);
}

function login(state) {
  state.csrf = '';
  state.grant = undefined;
  const form = send(state, '/v2/login-form');
  const token = form.status === 200 ? loginFormToken(form.response) : null;
  if (!verify('login form supplies a CSRF token', token)) return false;

  let result = send(state, '/v2/login', 'POST', {
    username: state.account.username,
    password: state.account.password,
    csrf: token,
  });
  if (result.status === 302) {
    const landing = localPath(header(result.response, 'Location'), '/v2/login');
    if (!verify('login redirect stays on the shop', landing)) return false;
    result = send(state, landing);
    state.grant = result.data.grant_id;
  }
  return verify('login establishes an authenticated session',
    result.status === 200 && state.csrf);
}

function request(state, path, method = 'GET', payload = null, headers = {}) {
  const result = send(state, path, method, payload, headers);
  if (result.status !== 401) return result;

  if (result.data.error === 'expired') {
    const renewed = send(state, '/v2/session/renew', 'POST', {});
    if (renewed.status === 401 && renewed.data.error === 'session') {
      if (!login(state)) return result;
    } else if (!verify('expired session renewed', renewed.status === 200)) {
      return result;
    }
  } else if (result.data.error === 'session') {
    if (!login(state)) return result;
  } else {
    return result;
  }

  let retryHeaders = headers;
  if (state.cart !== undefined) {
    const recovered = send(state, '/v2/carts/' + encodeURIComponent(state.cart) +
      '/recover', 'POST', {});
    if (!verify('existing cart recovered', recovered.status >= 200 && recovered.status < 300)) {
      return result;
    }
    const etag = header(recovered.response, 'ETag');
    if (etag && headers['If-Match']) {
      retryHeaders = Object.assign({}, headers, { 'If-Match': etag });
    }
  }
  return send(state, path, method, payload, retryHeaders);
}

function hasId(value) {
  return (typeof value === 'string' && value.length > 0) || Number.isFinite(value);
}

function selectItem(state) {
  let path = '/v2/catalog';
  for (let n = 0; n < 3 && path; n++) {
    const result = request(state, path);
    const products = result.data.data && result.data.data.products;
    if (!verify('catalog page loaded', result.status === 200 && Array.isArray(products))) {
      return null;
    }
    for (const product of products) {
      if (!product || !hasId(product.id) || !Array.isArray(product.variants)) continue;
      const variant = product.variants.find((v) => v && v.in_stock === true && hasId(v.id));
      if (variant) return { product_id: product.id, variant_id: variant.id };
    }
    path = localPath(result.data.next, path);
  }
  return null;
}

function waitUntil(ms) {
  const remaining = ms - Date.now();
  if (remaining > 0) sleep(remaining / 1000);
}

export default function () {
  const account = accounts[exec.vu.idInTest - 1];
  if (!verify('VU has a dedicated fixture account', account)) return;

  // Stagger logins within each wave, but keep both carts active before checkout.
  const wave = exec.scenario.startTime + exec.vu.iterationInScenario * 3000;
  waitUntil(wave + account.delay);

  const state = { account, csrf: '', cart: undefined, grant: undefined };
  if (!login(state)) return;

  const item = selectItem(state);
  if (!verify('in-stock catalog item selected', item)) return;
  if (state.grant) item.grant_id = state.grant;

  const created = request(state, '/v2/carts', 'POST', item);
  if (!verify('one cart created', created.status === 201 && hasId(created.data.id))) return;
  state.cart = created.data.id;

  const headers = { 'Idempotency-Key': account.username + '-cart-' + state.cart };
  const etag = header(created.response, 'ETag');
  if (etag) headers['If-Match'] = etag;

  waitUntil(wave + 1250 + account.delay);
  const ordered = request(state, '/v2/orders', 'POST', { cart_id: state.cart }, headers);
  verify('order accepted', ordered.status === 201 && ordered.data.accepted === true &&
    hasId(ordered.data.id));
}

import csv
import json
import os
from html.parser import HTMLParser
from urllib.parse import quote, urljoin, urlsplit

from gevent.event import Event
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


USERS = 2
ITERATIONS = 2
TARGET = "http://127.0.0.1:8000"
BASE_URL = os.environ.get("BASE_URL", TARGET).rstrip("/")
if BASE_URL != TARGET:
    raise ValueError("BASE_URL must point to the local shop")


def nonempty(value):
    return isinstance(value, str) and bool(value.strip())


def is_id(value):
    return nonempty(value) or type(value) is int


def local_path(value, source):
    if not nonempty(value):
        return None
    try:
        url = urlsplit(urljoin(TARGET + source, value))
    except ValueError:
        return None
    if (url.scheme, url.netloc) != ("http", "127.0.0.1:8000"):
        return None
    if not url.path.startswith("/") or url.path.startswith("//"):
        return None
    return url.path + ("?" + url.query if url.query else "")


def load_accounts():
    try:
        with open("/fixtures/accounts.json", encoding="utf-8-sig") as fixture:
            rows = json.load(fixture)
    except FileNotFoundError:
        rows = []
        for index in range(1, USERS + 1):
            with open(
                f"/fixtures/account-{index}.csv", encoding="utf-8-sig", newline=""
            ) as fixture:
                rows.extend(csv.DictReader(fixture))

    if not isinstance(rows, list) or len(rows) < USERS:
        raise ValueError("Not enough account rows for the partition")
    accounts = []
    for row in rows[:USERS]:
        if not isinstance(row, dict):
            raise ValueError("Invalid account row")
        username, password = row.get("username"), row.get("password")
        if not nonempty(username) or not nonempty(password):
            raise ValueError("Account row is missing credentials")
        accounts.append((username, password))
    if len({username for username, _ in accounts}) != USERS:
        raise ValueError("Each user needs a distinct account")
    return tuple(accounts)


class Partition:
    def __init__(self):
        self.accounts = load_accounts()
        self.lock = Semaphore()
        self.claimed = 0
        self.finished = 0
        self.gates = {
            (iteration, stage): (0, Event())
            for iteration in range(ITERATIONS)
            for stage in ("login", "cart")
        }

    def claim(self):
        with self.lock:
            account = self.accounts[self.claimed]
            self.claimed += 1
            return account

    def rendezvous(self, iteration, stage):
        key = (iteration, stage)
        with self.lock:
            count, gate = self.gates[key]
            self.gates[key] = (count + 1, gate)
            if count + 1 == USERS:
                gate.set()
        if not gate.wait(timeout=8):
            raise JourneyFailed("Timed out waiting for the other partition user")

    def finish(self):
        with self.lock:
            self.finished += 1


class LoginForm(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.in_login_form = False
        self.candidates = []

    def handle_starttag(self, tag, attrs):
        fields = dict(attrs)
        if tag == "form":
            self.in_login_form = (
                local_path(fields.get("action"), "/v2/login-form") == "/v2/login"
            )
        if tag == "input" and fields.get("name") == "csrf" and "disabled" not in fields:
            value = fields.get("value")
            if nonempty(value):
                hidden = (fields.get("type") or "").lower() == "hidden"
                self.candidates.append((self.in_login_form, hidden, value))

    def handle_endtag(self, tag):
        if tag == "form":
            self.in_login_form = False

    def token(self):
        if self.candidates:
            return max(self.candidates, key=lambda entry: entry[:2])[2]
        return None


def stock_pair(body):
    data = body.get("data")
    products = data.get("products") if isinstance(data, dict) else None
    if not isinstance(products, list):
        return None
    for product in products:
        if not isinstance(product, dict) or not is_id(product.get("id")):
            continue
        variants = product.get("variants")
        if not isinstance(variants, list):
            continue
        for variant in variants:
            if (
                isinstance(variant, dict)
                and variant.get("in_stock") is True
                and is_id(variant.get("id"))
            ):
                return product["id"], variant["id"]
    return None


class JourneyFailed(Exception):
    pass


class PartitionUser(HttpUser):
    host = BASE_URL

    def on_start(self):
        self.partition = self.environment.account_partition
        self.username, self.password = self.partition.claim()
        self.csrf = ""
        self.cart_path = None
        self.etag = None

    def on_stop(self):
        self.partition.finish()

    def exchange(
        self, method, path, statuses, check=None, *, payload=None, headers=None,
        recoverable=False, name=None
    ):
        request_headers = dict(headers or {})
        if method != "GET" and self.csrf:
            request_headers["X-CSRF-Token"] = self.csrf

        with self.client.request(
            method, path, json=payload, headers=request_headers, name=name,
            catch_response=True, allow_redirects=False, timeout=3
        ) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            if not isinstance(body, dict):
                body = {}

            retryable = (
                recoverable
                and response.status_code == 401
                and body.get("error") in ("expired", "session")
            )
            valid = response.status_code in statuses and (
                check is None or check(response, body)
            )
            if valid or retryable:
                response.success()
            else:
                response.failure(f"{method} {name or path}: unexpected response ({response.status_code})")

        if not (valid or retryable):
            raise JourneyFailed()
        if valid and nonempty(body.get("csrf")):
            self.csrf = body["csrf"]
        return response, body

    def login(self):
        self.csrf = ""
        form_token = None

        def check_form(response, _):
            nonlocal form_token
            form = LoginForm()
            form.feed(response.text)
            form.close()
            form_token = form.token()
            return form_token is not None

        def check_owner(body, required=False):
            if "user" not in body:
                return not required
            owner = body["user"]
            if isinstance(owner, dict):
                owner = owner.get("username")
            return owner == self.username

        def check_login(response, body):
            if response.status_code == 302:
                return check_owner(body) and local_path(
                    response.headers.get("Location"), "/v2/login"
                ) is not None
            return check_owner(body, required=True) and nonempty(body.get("csrf"))

        self.exchange("GET", "/v2/login-form", (200,), check_form)
        response, _ = self.exchange(
            "POST", "/v2/login", (200, 302), check_login,
            payload={"username": self.username, "password": self.password, "csrf": form_token},
        )
        if response.status_code == 302:
            destination = local_path(response.headers["Location"], "/v2/login")
            self.exchange(
                "GET", destination, (200,),
                lambda _, body: check_owner(body) and (
                    nonempty(body.get("csrf")) or nonempty(self.csrf)
                ),
                name="/v2/login [redirect]",
            )

    def recover(self, error):
        if error == "session":
            self.login()
        else:
            response, _ = self.exchange(
                "POST", "/v2/session/renew", (200,),
                lambda _, body: nonempty(body.get("csrf")),
                payload={}, recoverable=True,
            )
            if response.status_code == 401:
                self.login()

        if self.cart_path is not None:
            response, _ = self.exchange(
                "POST", self.cart_path + "/recover", (200, 204),
                payload={}, name="/v2/carts/:id/recover",
            )
            self.etag = response.headers.get("ETag", self.etag)

    def operation(
        self, method, path, statuses, check=None, *, payload=None, headers=None,
        match_cart=False, name=None
    ):
        for attempt in range(2):
            request_headers = dict(headers or {})
            if match_cart and self.etag:
                request_headers["If-Match"] = self.etag
            response, body = self.exchange(
                method, path, statuses, check, payload=payload, headers=request_headers,
                recoverable=(attempt == 0), name=name,
            )
            if response.status_code != 401:
                return response, body
            self.recover(body["error"])

    def choose_stock(self):
        page = "/v2/catalog"
        for index in range(3):
            def check_catalog(_, body):
                return stock_pair(body) is not None or (
                    index < 2 and local_path(body.get("next"), page) is not None
                )

            _, body = self.operation("GET", page, (200,), check_catalog)
            pair = stock_pair(body)
