import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;
import io.gatling.javaapi.http.HttpRequestActionBuilder;
import java.time.Duration;

public class ModelSimulation extends Simulation {
    private static final Duration STAGGER = Duration.ofSeconds(1);
    private static final Duration JOURNEY_PERIOD = Duration.ofSeconds(4);

    private static final HttpProtocolBuilder HTTP = http
        .baseUrl(System.getenv("BASE_URL"))
        .disableWarmUp()
        .disableFollowRedirect()
        .acceptHeader("application/json");

    private static final String STOCKED_PRODUCTS =
        "data.products[?variants[?in_stock == `true`]]";

    private static HttpRequestActionBuilder authenticated(HttpRequestActionBuilder request) {
        return request.header("X-CSRF-Token", "#{csrf}");
    }

    private static HttpRequestActionBuilder json(HttpRequestActionBuilder request, String body) {
        return request.header("Content-Type", "application/json").body(StringBody(body));
    }

    private static ChainBuilder login() {
        return exec(session -> session
                .remove("loginLocation")
                .remove("csrf")
                .set("username", "bench-" + ((session.userId() - 1) % 16 + 1)))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200), css("input[name=csrf]", "value").saveAs("formCsrf")))
            .exec(json(http("login").post("/v2/login"),
                    "{\"username\":#{username.jsonStringify()},\"password\":\"bench\","
                        + "\"csrf\":#{formCsrf.jsonStringify()}}")
                .check(status().in(200, 302))
                .checkIf((response, session) -> response.status().code() == 200)
                .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((response, session) -> response.status().code() == 302)
                .then(header("Location").saveAs("loginLocation")))
            .exec(doIf(session -> session.contains("loginLocation")).then(
                http("login redirect").get("#{loginLocation}")
                    .check(status().is(200), jsonPath("$.csrf").saveAs("csrf"))));
    }

    private static ChainBuilder recoverSession() {
        return doIfOrElse(session -> "expired".equals(session.getString("authError")))
            .then(json(authenticated(http("renew session").post("/v2/session/renew")), "{}")
                .check(status().is(200), jsonPath("$.csrf").saveAs("csrf")))
            .orElse(login())
            .exec(doIf(session -> session.contains("cart")).then(
                json(authenticated(http("recover cart").post("/v2/carts/#{cart}/recover")), "{}")
                    .check(status().is(200),
                        header("ETag").optional().saveAs("etag"),
                        jsonPath("$.csrf").optional().saveAs("csrf"))));
    }

    private static ChainBuilder operation(
        HttpRequestActionBuilder request, int expected, CheckBuilder... successChecks
    ) {
        return exec(session -> session.remove("authError"))
            .exec(request.check(status().in(expected, 401))
                .checkIf((response, session) -> response.status().code() == expected)
                .then(successChecks)
                .checkIf((response, session) -> response.status().code() == 401)
                .then(jsonPath("$.error").in("expired", "session").saveAs("authError")))
            .exec(doIf(session -> session.contains("authError")).then(
                recoverSession().exec(request.check(status().is(expected)).check(successChecks))));
    }

    private static ChainBuilder journey() {
        return exec(session -> session.remove("cart").remove("etag"))
            .exec(login())
            .exec(operation(authenticated(http("catalog").get("/v2/catalog")), 200,
                jmesPath(STOCKED_PRODUCTS + " | [0].id").saveAs("product"),
                jmesPath(STOCKED_PRODUCTS + " | [0].variants[?in_stock == `true`] | [0].id")
                    .saveAs("variant")))
            .exec(operation(json(authenticated(http("create cart").post("/v2/carts")),
                    "{\"product_id\":#{product.jsonStringify()},"
                        + "\"variant_id\":#{variant.jsonStringify()}}"), 201,
                jsonPath("$.id").saveAs("cart"),
                header("ETag").saveAs("etag"),
                jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(operation(json(authenticated(http("commit").post("/v2/orders"))
                    .header("If-Match", "#{etag}")
                    .header("Idempotency-Key", "checkout-#{cart}"),
                    "{\"cart_id\":#{cart.jsonStringify()}}"), 201,
                jsonPath("$.accepted").ofBoolean().is(true),
                jsonPath("$.id").exists(),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    public ModelSimulation() {
        ScenarioBuilder checkout = scenario("Owned checkout")
            .repeat(9).on(
                pace(JOURNEY_PERIOD)
                    .exec(Session::markAsSucceeded)
                    .exec(exitBlockOnFail().on(journey()))
            );

        setUp(checkout.injectOpen(
            atOnceUsers(1),
            nothingFor(STAGGER), atOnceUsers(1),
            nothingFor(STAGGER), atOnceUsers(1),
            nothingFor(STAGGER), atOnceUsers(1)
        )).protocols(HTTP);
    }
}

