import http from 'k6/http';
import { check, sleep } from 'k6';

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

export const options = {
  noCookiesReset: true,
  scenarios: {
    checkout: {
      executor: 'constant-arrival-rate',
      rate: 1,
      timeUnit: '1s',
      duration: '35s',
      preAllocatedVUs: 4,
      maxVUs: 4,
      gracefulStop: '5s',
    },
  },
  thresholds: {
    checks: ['rate>=0.99'],
    dropped_iterations: ['count==0'],
  },
};

function body(response) {
  try {
    return response.json() || {};
  } catch (_) {
    return {};
  }
}

function header(response, name) {
  const key = Object.keys(response.headers).find(
    (candidate) => candidate.toLowerCase() === name.toLowerCase()
  );
  return key ? response.headers[key] : '';
}

function localPath(ref, from) {
  if (typeof ref !== 'string' || !ref) return '';
  if (ref.startsWith(base + '/')) return ref.slice(base.length);
  if (ref.startsWith('//') || /^[a-z][a-z\d+.-]*:/i.test(ref)) return '';
  if (ref.startsWith('/')) return ref;
  const path = from.split('?')[0];
  if (ref.startsWith('?')) return path + ref;
  return path.slice(0, path.lastIndexOf('/') + 1) + ref;
}

function raw(state, path, method = 'GET', payload = null, extra = {}) {
  const headers = Object.assign({}, extra);
  if (payload !== null) headers['Content-Type'] = 'application/json';
  if (method !== 'GET' && state.csrf) headers['X-CSRF-Token'] = state.csrf;

  const response = http.request(
    method,
    base + path,
    payload === null ? null : JSON.stringify(payload),
    { headers, redirects: 0, timeout: '3s' }
  );

  if (response.status >= 200 && response.status < 400) {
    const token = body(response).csrf;
    if (typeof token === 'string' && token) state.csrf = token;
  }
  return response;
}

function csrfInput(scope) {
  const selector = 'input[name="csrf"]:not([disabled])';
  return scope.find(selector + '[type="hidden"]').first().attr('value') ||
    scope.find(selector).first().attr('value');
}

function loginToken(response) {
  const doc = response.html();
  let actionToken;
  let passwordFormToken;
  doc.find('form').each((_, form) => {
    if (localPath(form.attr('action'), '/v2/login-form') === '/v2/login') {
      actionToken = actionToken || csrfInput(form);
    } else if (form.find('input[name="password"], input[type="password"]').size() > 0) {
      passwordFormToken = passwordFormToken || csrfInput(form);
    }
  });
  return actionToken || passwordFormToken || csrfInput(doc);
}

function login(state) {
  state.csrf = '';
  state.grant = undefined;

  const form = raw(state, '/v2/login-form');
  const token = form.status === 200 ? loginToken(form) : '';
  if (!check(token, { 'login form has CSRF token': (value) => Boolean(value) })) {
    return false;
  }

  let response = raw(state, '/v2/login', 'POST', {
    username: state.username,
    password: 'bench',
    csrf: token,
  });
  if (response.status === 302) {
    const location = localPath(header(response, 'Location'), '/v2/login');
    if (!check(location, { 'login redirect has a local location': (value) => Boolean(value) })) {
      return false;
    }
    response = raw(state, location);
    if (response.status === 200) state.grant = body(response).grant_id;
  }

  return check(response, {
    'login established authenticated session': (r) => r.status === 200 && Boolean(state.csrf),
  });
}

function request(state, path, method = 'GET', payload = null, headers = {}) {
  const response = raw(state, path, method, payload, headers);
  if (response.status !== 401) return response;

  const reason = body(response).error;
  if (reason !== 'expired' && reason !== 'session') return response;

  const renewed = raw(state, '/v2/session/renew', 'POST', {});
  if (renewed.status !== 200) {
    const revoked = reason === 'session' || body(renewed).error === 'session';
    if (!revoked || (renewed.status !== 401 && renewed.status !== 403) || !login(state)) {
      return response;
    }
  }

  if (state.cart !== null) {
    const cartPath = '/v2/carts/' + encodeURIComponent(String(state.cart));
    const recovered = raw(state, cartPath + '/recover', 'POST', {});
    if (recovered.status < 200 || recovered.status >= 300) return response;
    const etag = header(recovered, 'ETag');
    if (etag && headers['If-Match']) {
      headers = Object.assign({}, headers, { 'If-Match': etag });
    }
  }

  return raw(state, path, method, payload, headers);
}

function selectItem(state) {
  let path = '/v2/catalog';
  for (let page = 0; page < 3 && path; page++) {
    const response = request(state, path);
    if (response.status !== 200) return null;
    const catalog = body(response);
    const products = catalog.data && catalog.data.products;
    if (!Array.isArray(products)) return null;

    for (const product of products) {
      if (product.id == null || !Array.isArray(product.variants)) continue;
      const variant = product.variants.find((v) => v.id != null && v.in_stock === true);
      if (variant) return { product_id: product.id, variant_id: variant.id };
    }
    path = localPath(catalog.next, path);
  }
  return null;
}

function journey() {
  const state = {
    username: 'bench-' + (((__VU - 1) % 16) + 1),
    csrf: '',
    cart: null,
    grant: undefined,
  };
  if (!login(state)) return;

  const item = selectItem(state);
  if (!check(item, { 'catalog has an in-stock variant': (value) => value !== null })) return;
  if (state.grant) item.grant_id = state.grant;

  const cart = request(state, '/v2/carts', 'POST', item);
  const cartId = body(cart).id;
  if (!check(cart, { 'cart created': (r) => r.status === 201 && cartId != null })) return;
  state.cart = cartId;

  const headers = { 'Idempotency-Key': state.username + '-cart-' + String(cartId) };
  const etag = header(cart, 'ETag');
  if (etag) headers['If-Match'] = etag;

  const order = request(state, '/v2/orders', 'POST', { cart_id: cartId }, headers);
  check(order, { 'checkout accepted': (r) => r.status === 201 && body(r).accepted === true });
}

export default function () {
  try {
    journey();
  } finally {
    sleep(1);
  }
}

import os
import time
from html.parser import HTMLParser
from itertools import count
from urllib.parse import quote, urljoin, urlsplit
from uuid import uuid4

from gevent import sleep
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


RATE = 1
MAX_VUS = 4
DURATION = 35
CHECKOUT_PATH = "/v2/orders"
ACCOUNTS = count()


class IterationPacer:
    def __init__(self):
        self.started = None
        self.next_start = None
        self.lock = Semaphore()

    def admit(self):
        # Pace complete journeys, not their individual HTTP requests.
        with self.lock:
            now = time.monotonic()
            if self.started is None:
                self.started = self.next_start = now

            end = self.started + DURATION
            if max(now, self.next_start) >= end:
                return False

            if self.next_start > now:
                sleep(self.next_start - now)

            now = time.monotonic()
            if now >= end:
                return False

            # A delayed start moves the next slot forward; never catch up in a burst.
            self.next_start = now + 1 / RATE
            return True


PACER = IterationPacer()


class LoginForm(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.form_action = ""
        self.tokens = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "form":
            self.form_action = attrs.get("action") or ""
        elif (
            tag == "input"
            and attrs.get("name") == "csrf"
            and attrs.get("value")
            and "disabled" not in attrs
        ):
            rank = (
                self.form_action.split("?", 1)[0].rstrip("/").endswith("/v2/login"),
                (attrs.get("type") or "").lower() == "hidden",
            )
            self.tokens.append((rank, attrs["value"]))

    def handle_endtag(self, tag):
        if tag == "form":
            self.form_action = ""

    @classmethod
    def token(cls, html):
        parser = cls()
        parser.feed(html)
        parser.close()
        return max(parser.tokens, key=lambda item: item[0])[1] if parser.tokens else None


class JourneyFailed(Exception):
    pass


def has_id(body):
    return body.get("id") not in (None, "")


def in_stock_pair(body):
    for product in body.get("data", {}).get("products", []):
        if has_id(product):
            for variant in product.get("variants", []):
                if has_id(variant) and variant.get("in_stock") is True:
                    return product["id"], variant["id"]
    return None


class ShopUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
    wait_time = lambda self: 0

    def on_start(self):
        self.username = f"bench-{next(ACCOUNTS) % 16 + 1}"
        self.csrf = None
        self.cart_path = None
        self.etag = None

    def send(self, method, path, *, payload=None, headers=None, name=None,
             statuses=(200,), check=None, recoverable=()):
        request_headers = dict(headers or {})
        if method != "GET" and self.csrf:
            request_headers["X-CSRF-Token"] = self.csrf

        with self.client.request(
            method, path, json=payload, headers=request_headers, name=name,
            catch_response=True, allow_redirects=False, timeout=3,
        ) as response:
            try:
                body = response.json()
            except (ValueError, TypeError):
                body = {}
            if not isinstance(body, dict):
                body = {}

            value = None
            if response.status_code in statuses:
                value = check(response, body) if check else True
                ok = bool(value)
                if ok and body.get("csrf"):
                    self.csrf = body["csrf"]
            else:
                ok = response.status_code == 401 and body.get("error") in recoverable

            if ok:
                response.success()
            else:
                response.failure(f"{method} {name or path}: unexpected status or body ({response.status_code})")

        if not ok:
            raise JourneyFailed()
        return response, body, value

    def login_location(self, location):
        if not location:
            return None
        try:
            origin = urlsplit(self.host)
            target = urlsplit(urljoin(self.host.rstrip("/") + "/v2/login", location))
        except ValueError:
            return None
        if (target.scheme, target.netloc) != (origin.scheme, origin.netloc):
            return None
        return target.path + ("?" + target.query if target.query else "")

    def login(self):
        self.csrf = None
        _, _, token = self.send(
            "GET", "/v2/login-form", check=lambda response, _: LoginForm.token(response.text),
        )
        response, _, result = self.send(
            "POST", "/v2/login",
            payload={"username": self.username, "password": "bench", "csrf": token},
            statuses=(200, 302),
            check=lambda response, body: (
                self.login_location(response.headers.get("Location"))
                if response.status_code == 302 else bool(body.get("csrf"))
            ),
        )
        if response.status_code == 302:
            self.send(
                "GET", result, name="login redirect",
                check=lambda _, body: bool(body.get("csrf") or self.csrf),
            )

    def recover(self, reason):
        if reason == "session":
            self.login()
        else:
            renewed, _, _ = self.send(
                "POST", "/v2/session/renew", payload={}, recoverable=("session",),
            )
            if renewed.status_code == 401:
                self.login()

        if self.cart_path:
            response, _, _ = self.send(
                "POST", self.cart_path + "/recover", payload={},
                name="/v2/carts/:id/recover", statuses=(200, 204),
            )
            self.etag = response.headers.get("ETag", self.etag)

    def authenticated(self, method, path, *, order_key=None, **kwargs):
        for attempt in range(2):
            headers = {}
            if order_key is not None:
                headers["Idempotency-Key"] = order_key
                if self.etag:
                    headers["If-Match"] = self.etag

            result = self.send(
                method, path, headers=headers,
                recoverable=("expired", "session") if attempt == 0 else (),
                **kwargs,
            )
            response, body, _ = result
            if response.status_code != 401:
                return result
            self.recover(body["error"])

    def journey(self):
        self.cart_path = None
        self.etag = None
        self.login()

        _, _, pair = self.authenticated(
            "GET", "/v2/catalog", check=lambda _, body: in_stock_pair(body),
        )
        product_id, variant_id = pair
        cart_response, cart, _ = self.authenticated(
            "POST", "/v2/carts",
            payload={"product_id": product_id, "variant_id": variant_id},
            statuses=(201,), check=lambda _, body: has_id(body),
        )
        cart_id = cart["id"]
        self.cart_path = "/v2/carts/" + quote(str(cart_id), safe="")
        self.etag = cart_response.headers.get("ETag")

        self.authenticated(
            "POST", CHECKOUT_PATH, payload={"cart_id": cart_id},
            order_key=uuid4().hex, statuses=(201,),
            check=lambda _, body: body.get("accepted") is True and has_id(body),
        )

    @task
    def run_journey(self):
        if not PACER.admit():
            raise StopUser()
        try:
            self.journey()
        except JourneyFailed:
            pass


class CheckoutShape(LoadTestShape):
    def tick(self):
        if PACER.started is None:
            if self.get_run_time() >= 10:
                return None
        elif time.monotonic() >= PACER.started + DURATION + 3:
            return None
        return MAX_VUS, MAX_VUS

