import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;
import java.net.URI;
import java.time.Duration;

public class ModelSimulation extends Simulation {
    private static final int USERS = 2;
    private static final int ITERATIONS = 2;
    private static final int WORK_PER_ITERATION = 4;
    private static final int MAX_RATE_RETRIES = 4;
    private static final Duration RATE_RETRY_DELAY = Duration.ofMillis(1050);

    private static final String BASE_URL = System.getenv("BASE_URL");
    private static final HttpProtocolBuilder HTTP = http.baseUrl(BASE_URL)
        .disableWarmUp()
        .disableCaching()
        .acceptHeader("application/json");

    private static String loginRedirect(String location) {
        URI base = URI.create(BASE_URL);
        URI target = base.resolve("/v2/login").resolve(location);
        if (!base.getScheme().equals(target.getScheme())
                || !base.getAuthority().equals(target.getAuthority())) {
            throw new IllegalArgumentException("Login redirect must stay on the fixture origin");
        }
        return target.toString();
    }

    private static ChainBuilder login() {
        return exec(session -> session.remove("csrf").remove("formCsrf").remove("loginLocation")
                .set("username", "bench-" + ((session.userId() - 1) % 16 + 1)))
            .exec(http("login form").get("/v2/login-form")
                .disableFollowRedirect()
                .header("Accept", "text/html")
                .check(status().is(200), css("input[name='csrf']", "value").saveAs("formCsrf")))
            .exec(doIf(session -> session.contains("formCsrf")).then(
                exec(http("login").post("/v2/login")
                    .disableFollowRedirect()
                    .header("Content-Type", "application/json")
                    .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\","
                        + "\"csrf\":#{formCsrf.jsonStringify()}}"))
                    .check(status().in(200, 302))
                    .checkIf((response, session) -> response.status().code() == 200)
                        .then(jsonPath("$.csrf").saveAs("csrf"))
                    .checkIf((response, session) -> response.status().code() == 302)
                        .then(header("Location").transform(ModelSimulation::loginRedirect)
                            .saveAs("loginLocation")))
                .exec(doIf(session -> session.contains("loginLocation")).then(
                    http("login redirect").get("#{loginLocation}")
                        .disableFollowRedirect()
                        .check(status().is(200), jsonPath("$.csrf").saveAs("csrf"))))));
    }

    private static ChainBuilder workSample() {
        return exec(session -> session.remove("expiredError").remove("retryAfter"))
            .exec(http("work").post("/v2/work")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().in(200, 401, 429))
                .checkIf((response, session) -> response.status().code() == 200)
                    .then(jsonPath("$.ok").ofBoolean().is(true),
                        jsonPath("$.csrf").optional().saveAs("csrf"))
                .checkIf((response, session) -> response.status().code() == 401)
                    .then(jsonPath("$.error").is("expired").saveAs("expiredError"))
                .checkIf((response, session) -> response.status().code() == 429)
                    .then(header("Retry-After").is("1").saveAs("retryAfter")));
    }

    private static ChainBuilder renewAndReplay() {
        return exec(session -> session.set("renewAttempted", true).remove("renewedCsrf"))
            .exec(http("renew").post("/v2/session/renew")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().is(200))
                .checkIf((response, session) -> response.status().code() == 200)
                    .then(jsonPath("$.csrf").saveAs("renewedCsrf")))
            .exec(doIf(session -> session.contains("renewedCsrf")).then(
                exec(session -> session.set("csrf", session.getString("renewedCsrf")))
                    .exec(workSample())));
    }

    private static ChainBuilder workOperation() {
        return exec(session -> session.remove("renewAttempted").set("rateRetries", 0))
            .exec(workSample())
            .exec(repeat(MAX_RATE_RETRIES + 1, "retryStep").on(
                doIfOrElse(session -> session.contains("expiredError")
                        && !session.contains("renewAttempted"))
                    .then(renewAndReplay())
                    .orElse(doIf(session -> session.contains("retryAfter")
                            && session.getInt("rateRetries") < MAX_RATE_RETRIES)
                        .then(exec(session -> session.set("rateRetries",
                                session.getInt("rateRetries") + 1))
                            .pause(RATE_RETRY_DELAY)
                            .exec(workSample())))));
    }

    public ModelSimulation() {
        setUp(scenario("work errors")
            .exec(repeat(ITERATIONS, "journey").on(
                login().exec(doIf(session -> session.contains("csrf")).then(
                    repeat(WORK_PER_ITERATION, "operation").on(workOperation())))))
            .injectOpen(atOnceUsers(USERS)))
            .protocols(HTTP)
            .assertions(global().failedRequests().count().is(0L));
    }
}

