import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const origin = 'http://127.0.0.1:8000';
const base = (__ENV.BASE_URL || origin).replace(/\/+$/, '');
if (base !== origin) throw new Error('BASE_URL must target the local fixture');

const businessFailure = new Rate('business_failure');

export const options = {
  noCookiesReset: true,
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  thresholds: {
    business_failure: ['rate==0'],
    checks: ['rate==1'],
  },
};

let csrf = '';

function jsonBody(response) {
  try {
    return response.json() || {};
  } catch (_) {
    return {};
  }
}

function header(response, name) {
  const key = Object.keys(response.headers).find(
    (candidate) => candidate.toLowerCase() === name.toLowerCase(),
  );
  return key ? String(response.headers[key]).trim() : '';
}

function request(path, method = 'GET', payload = null) {
  const headers = {};
  if (payload !== null) headers['Content-Type'] = 'application/json';
  if (method !== 'GET' && csrf) headers['X-CSRF-Token'] = csrf;

  const response = http.request(
    method,
    base + path,
    payload === null ? null : JSON.stringify(payload),
    { headers, redirects: 0, timeout: '3s' },
  );
  const data = jsonBody(response);
  if (
    response.status >= 200 && response.status < 400 &&
    typeof data.csrf === 'string' && data.csrf
  ) {
    csrf = data.csrf;
  }
  return { response, data };
}

function loginRedirect(response) {
  let location = header(response, 'Location');
  if (!location || /[\r\n\\]/.test(location)) return '';
  if (location.startsWith('//')) location = 'http:' + location;
  if (location === origin) return '/';
  if (location.startsWith(origin + '/')) return location.slice(origin.length);
  if (location.startsWith('/')) return location;
  if (/^[a-z][a-z0-9+.-]*:/i.test(location)) return '';
  if (location.startsWith('?') || location.startsWith('#')) {
    return '/v2/login' + location;
  }
  return '/v2/' + location;
}

function login() {
  csrf = '';
  const { response: form } = request('/v2/login-form');
  const token = form.status === 200
    ? form.html().find('input[name="csrf"][value]').first().attr('value')
    : '';

  if (!token) return check(false, { 'login succeeds': (ok) => ok });

  let { response } = request('/v2/login', 'POST', {
    username: `bench-${__VU}`,
    password: 'bench',
    csrf: token,
  });
  if (response.status === 302) {
    const location = loginRedirect(response);
    if (location) response = request(location).response;
  }
  return check(response, { 'login succeeds': (r) => r.status === 200 && !!csrf });
}

function work() {
  let sessionRetried = false;
  let throttleRetries = 0;

  for (;;) {
    const { response, data } = request('/v2/work', 'POST', {});
    const ok = response.status === 200 && data.ok === true;
    const expired = response.status === 401 && data.error === 'expired';
    const revoked = response.status === 401 && data.error === 'session';
    const scheduledThrottle =
      response.status === 429 && Number(header(response, 'Retry-After')) === 1;
    const expected = ok || expired || scheduledThrottle;

    // Sample every raw work response before making any retry decision.
    businessFailure.add(!expected);
    check(expected, { 'work response succeeds or calls for an expected retry': (v) => v });

    if (ok) return;

    if ((expired || revoked) && !sessionRetried) {
      sessionRetried = true;
      const renewed = request('/v2/session/renew', 'POST', {});
      if (renewed.response.status === 200) continue;
      if (revoked && login()) continue;
      if (expired) {
        check(renewed.response, { 'expired session renews': (r) => r.status === 200 });
      }
      return;
    }

    if (scheduledThrottle && throttleRetries < 4) {
      throttleRetries++;
      sleep(1);
      continue;
    }

    return;
  }
}

export default function () {
  if (!login()) return;
  for (let i = 0; i < 4; i++) work();
}

import os
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

from gevent import sleep
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
USERS = 2
ITERATIONS = 2
OPERATIONS_PER_ITERATION = 4
MAX_THROTTLE_RETRIES = 4


class LoginFormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.csrf = None

    def handle_starttag(self, tag, attrs):
        if tag == "input" and self.csrf is None:
            attributes = dict(attrs)
            if attributes.get("name") == "csrf" and attributes.get("value"):
                self.csrf = attributes["value"]


def json_object(response):
    try:
        body = response.json()
    except ValueError:
        return {}
    return body if isinstance(body, dict) else {}


def login_redirect(location):
    if not location:
        return None
    try:
        target = urljoin(BASE_URL + "/v2/login", location)
        parts = urlsplit(target)
    except ValueError:
        return None
    if parts.scheme == "http" and parts.netloc == "127.0.0.1:8000":
        return target
    return None


class MatrixUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        shape = self.environment.shape_class
        self.username = f"bench-{shape.next_account}"
        shape.next_account += 1
        self.csrf = None
        self.iterations = 0

    def capture_csrf(self, body):
        token = body.get("csrf")
        if isinstance(token, str) and token:
            self.csrf = token

    def login(self):
        self.csrf = None
        with self.client.get(
            "/v2/login-form", catch_response=True, allow_redirects=False, timeout=3
        ) as response:
            if response.status_code != 200:
                response.failure(f"Login form returned HTTP {response.status_code}")
                return False
            parser = LoginFormParser()
            parser.feed(response.text)
            parser.close()
            if not parser.csrf:
                response.failure("Login form is missing its CSRF input")
                return False
            response.success()

        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": parser.csrf},
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            if response.status_code == 200:
                self.capture_csrf(json_object(response))
                if not self.csrf:
                    response.failure("Login response is missing its session CSRF token")
                    return False
                response.success()
                return True

            if response.status_code != 302:
                response.failure(f"Login returned HTTP {response.status_code}")
                return False
            target = login_redirect(response.headers.get("Location"))
            if target is None:
                response.failure("Login redirect is missing a local Location")
                return False
            self.capture_csrf(json_object(response))
            response.success()

        with self.client.get(
            target, catch_response=True, allow_redirects=False, timeout=3
        ) as response:
            if response.status_code != 200:
                response.failure(f"Login redirect returned HTTP {response.status_code}")
                return False
            self.capture_csrf(json_object(response))
            if not self.csrf:
                response.failure("Redirected login did not provide a session CSRF token")
                return False
            response.success()
            return True

    def renew(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            if response.status_code != 200:
                response.failure(f"Session renewal returned HTTP {response.status_code}")
                return False
            self.capture_csrf(json_object(response))
            response.success()
            return True

    def work(self):
        renewal_attempted = False
        throttle_retries = 0

        while True:
            with self.client.post(
                "/v2/work",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                catch_response=True,
                allow_redirects=False,
                timeout=3,
            ) as response:
                status = response.status_code
                body = json_object(response)

                if status == 200 and body.get("ok") is True:
                    self.capture_csrf(body)
                    response.success()
                    return

                expired = status == 401 and body.get("error") == "expired"
                scheduled = (
                    status == 429
                    and response.headers.get("Retry-After", "").strip() == "1"
                )
                if not (expired or scheduled):
                    if status == 200:
                        response.failure("Work response did not contain ok=true")
                    else:
                        response.failure(f"Work returned unexpected HTTP {status}")
                    return

                response.success()

            if expired:
                if renewal_attempted:
                    return
                renewal_attempted = True
                if not self.renew():
                    return
            else:
                if throttle_retries >= MAX_THROTTLE_RETRIES:
                    return
                throttle_retries += 1
                sleep(1.01)

    @task
    def run_scenario(self):
        if self.login():
            for _ in range(OPERATIONS_PER_ITERATION):
                self.work()

        self.iterations += 1
        if self.iterations >= ITERATIONS:
            self.environment.shape_class.finished += 1
            raise StopUser()


class MatrixShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.next_account = 1
        self.finished = 0

    def tick(self):
        if self.finished >= USERS:
            return None
        return USERS, USERS

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.net.URI;
import java.time.Duration;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
    private static final String TARGET = "http://127.0.0.1:8000";
    private static final int USERS = 10;
    private static final int SLOTS = 35 * 5;
    private static final long SLOT_NS = Duration.ofMillis(200).toNanos();
    private static final long START_LEAD_NS = Duration.ofMillis(800).toNanos();
    private static final long MAX_LATENESS_NS = Duration.ofMillis(800).toNanos();

    private static String baseUrl() {
        String configured = System.getenv("BASE_URL");
        if (configured == null || configured.equals(TARGET) || configured.equals(TARGET + "/")) {
            return TARGET;
        }
        throw new IllegalArgumentException("BASE_URL must target " + TARGET);
    }

    private static String loginRedirect(String location) {
        URI target = URI.create(TARGET + "/v2/login").resolve(location);
        if (!"http".equalsIgnoreCase(target.getScheme())
                || !"127.0.0.1".equals(target.getHost())
                || target.getPort() != 8000
                || target.getRawUserInfo() != null) {
            throw new IllegalArgumentException("Login redirect must stay on the fixture origin");
        }
        return target.toASCIIString();
    }

    private static long due(Session session) {
        return session.getLong("epoch") + session.getInt("slot") * SLOT_NS;
    }

    private static final ChainBuilder LOGIN = exec(session -> session
            .remove("formCsrf")
            .remove("actionCsrf")
            .remove("loginLocation")
            .remove("loginStatus"))
        .exec(http("GET /v2/login-form")
            .get("/v2/login-form")
            .check(
                status().is(200),
                css("input[name='csrf']:not([disabled])", "value").saveAs("formCsrf"),
                css("form[action='/v2/login'] input[name='csrf']:not([disabled])", "value")
                    .optional().saveAs("actionCsrf")))
        .doIf(session -> !session.isFailed()).then(
            exec(session -> session.contains("actionCsrf")
                ? session.set("formCsrf", session.getString("actionCsrf"))
                : session),
            exec(http("POST /v2/login")
                .post("/v2/login")
                .asJson()
                .body(StringBody("{\"username\":#{account.jsonStringify()},"
                    + "\"password\":\"bench\",\"csrf\":#{formCsrf.jsonStringify()}}"))
                .check(status().in(200, 302).saveAs("loginStatus"))
                .checkIf((response, session) -> response.status().code() == 200).then(
                    jsonPath("$.csrf").saveAs("csrf"),
                    jsonPath("$.user").exists())
                .checkIf((response, session) -> response.status().code() == 302).then(
                    header("Location").transform(ModelSimulation::loginRedirect)
                        .saveAs("loginLocation"))))
        .doIf(session -> !session.isFailed() && session.getInt("loginStatus") == 302).then(
            exec(http("GET login redirect")
                .get("#{loginLocation}")
                .check(status().is(200), jsonPath("$.csrf").saveAs("csrf"))));

    private static final ChainBuilder RENEW = exec(session -> session.remove("renewStatus"))
        .exec(http("POST /v2/session/renew")
            .post("/v2/session/renew")
            .asJson()
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().in(200, 401).saveAs("renewStatus"))
            .checkIf((response, session) -> response.status().code() == 200).then(
                jsonPath("$.csrf").saveAs("csrf"))
            .checkIf((response, session) -> response.status().code() == 401).then(
                jsonPath("$.error").is("session")))
        .doIf(session -> !session.isFailed() && session.getInt("renewStatus") == 401).then(LOGIN);

    private static final ChainBuilder WORK_REQUEST = exec(http("POST /v2/work")
        .post("/v2/work")
        .asJson()
        .header("X-CSRF-Token", "#{csrf}")
        .body(StringBody("{}"))
        .check(status().in(200, 401, 429).saveAs("workStatus"))
        .checkIf((response, session) -> response.status().code() == 200).then(
            jsonPath("$.ok").ofBoolean().is(true),
            jsonPath("$.csrf").optional().saveAs("csrf"))
        .checkIf((response, session) -> response.status().code() == 401).then(
            jsonPath("$.error").in("expired", "session").saveAs("workError"))
        .checkIf((response, session) -> response.status().code() == 429).then(
            header("Retry-After").is("1")));

    private static final ChainBuilder WORK_SLOT = exec(session -> session
            .set("again", true)
            .set("rateRetries", 0)
            .set("authRetried", false))
        .asLongAs(session -> session.getBoolean("again")).on(
            WORK_REQUEST,
            exec(session -> {
                if (session.isFailed()) {
                    return session.set("again", false);
                }
                int status = session.getInt("workStatus");
                boolean retry = (status == 429 && session.getInt("rateRetries") < 4)
                    || (status == 401 && !session.getBoolean("authRetried"));
                return session.set("again", retry);
            }),
            doIf(session -> session.getBoolean("again") && session.getInt("workStatus") == 429)
                .then(
                    exec(session -> session.set("rateRetries", session.getInt("rateRetries") + 1)),
                    pause(Duration.ofSeconds(1))),
            doIf(session -> session.getBoolean("again") && session.getInt("workStatus") == 401)
                .then(
                    exec(session -> session.set("authRetried", true)),
                    doIfOrElse(session -> "expired".equals(session.getString("workError")))
                        .then(RENEW)
                        .orElse(LOGIN),
                    exec(session -> session.set("again", !session.isFailed()))))
        .exec(Session::markAsSucceeded);

    public ModelSimulation() {
        AtomicInteger accounts = new AtomicInteger();
        AtomicInteger lanes = new AtomicInteger();
        AtomicLong epoch = new AtomicLong();

        HttpProtocolBuilder protocol = http.baseUrl(baseUrl()).disableFollowRedirect();

        ScenarioBuilder workload = scenario("Authenticated business work")
            .exec(session -> session.set("account", "bench-" + accounts.incrementAndGet()))
            .exec(LOGIN)
            .exitHereIfFailed()
            .exec(session -> session
                .set("epoch", epoch.updateAndGet(value ->
                    value == 0L ? System.nanoTime() + START_LEAD_NS : value))
                .set("slot", lanes.getAndIncrement()))
            .asLongAs(session -> session.getInt("slot") < SLOTS).on(
                pause(session -> Duration.ofNanos(Math.max(0L, due(session) - System.nanoTime()))),
                doIf(session -> System.nanoTime() - due(session) <= MAX_LATENESS_NS)
                    .then(WORK_SLOT),
                exec(session -> session.set("slot", session.getInt("slot") + USERS)));

        setUp(workload.injectOpen(atOnceUsers(USERS)))
            .protocols(protocol)
            .maxDuration(Duration.ofSeconds(40));
    }
}

import http from 'k6/http';
import { check, sleep } from 'k6';
import exec from 'k6/execution';
import { parseHTML } from 'k6/html';
import { Rate } from 'k6/metrics';

const ORIGIN = 'http://127.0.0.1:8000';
const BASE = (__ENV.BASE_URL || ORIGIN).replace(/\/+$/, '');
if (BASE !== ORIGIN) {
  throw new Error('BASE_URL must be http://127.0.0.1:8000');
}

const businessFailure = new Rate('business_failure');

export const options = {
  maxRedirects: 0,
  noCookiesReset: true,
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '35s',
      gracefulStop: '5s',
      preAllocatedVUs: 16,
      maxVUs: 16,
    },
  },
  thresholds: {
    business_failure: ['rate<=0.01'],
  },
};

function json(response) {
  try {
    return response.json() || {};
  } catch (_) {
    return {};
  }
}

function token(body) {
  return typeof body.csrf === 'string' && body.csrf.length > 0 ? body.csrf : '';
}

function is2xx(response) {
  return response.status >= 200 && response.status < 300;
}

function get(url, name) {
  return http.get(url, { redirects: 0, timeout: '2s', tags: { name } });
}

function post(path, payload, csrf) {
  const headers = { 'Content-Type': 'application/json' };
  if (csrf) headers['X-CSRF-Token'] = csrf;
  return http.post(BASE + path, JSON.stringify(payload), {
    headers,
    redirects: 0,
    timeout: '2s',
    tags: { name: path },
  });
}

function localURL(reference, fromPath) {
  if (typeof reference !== 'string') return '';
  let ref = reference.trim();
  if (!ref || /[\x00-\x20\\]/.test(ref)) return '';
  if (ref.startsWith('//')) ref = 'http:' + ref;

  if (/^[a-z][a-z0-9+.-]*:/i.test(ref)) {
    return ref === BASE || ref.startsWith(BASE + '/') ||
      ref.startsWith(BASE + '?') || ref.startsWith(BASE + '#') ? ref : '';
  }

  if (ref[0] !== '/') {
    ref = ref[0] === '?' || ref[0] === '#'
      ? fromPath + ref
      : fromPath.slice(0, fromPath.lastIndexOf('/') + 1) + ref;
  }

  const suffixAt = ref.search(/[?#]/);
  const path = suffixAt === -1 ? ref : ref.slice(0, suffixAt);
  const suffix = suffixAt === -1 ? '' : ref.slice(suffixAt);
  const segments = path.slice(1).split('/');
  const resolved = [];
  for (let i = 0; i < segments.length; i++) {
    const part = segments[i];
    if (part === '..') resolved.pop();
    if (part !== '.' && part !== '..') resolved.push(part);
    else if (i === segments.length - 1) resolved.push('');
  }
  return BASE + '/' + resolved.join('/') + suffix;
}

function formToken(html) {
  const doc = parseHTML(html);
  let result = '';
  let best = -1;

  function consider(input, priority) {
    const value = input.attr('value');
    if (!value || input.attr('disabled') != null) return;
    const type = (input.attr('type') || '').toLowerCase();
    if (type === 'submit' || type === 'button' || type === 'reset') return;
    const score = priority + (type === 'hidden' ? 1 : 0);
    if (score > best) {
      result = value;
      best = score;
    }
  }

  doc.find('form').each((_, form) => {
    const action = localURL(form.attr('action'), '/v2/login-form').split(/[?#]/)[0];
    const method = (form.attr('method') || '').trim().toLowerCase();
    const priority = action === BASE + '/v2/login' ? (method === 'post' ? 8 : 6)
      : method === 'post' ? 4 : 2;
    form.find('input[name="csrf"]').each((_, input) => consider(input, priority));
  });
  doc.find('input[name="csrf"]').each((_, input) => consider(input, 0));
  return result;
}

function login(username) {
  const form = get(BASE + '/v2/login-form', '/v2/login-form');
  const csrf = form.status === 200 && typeof form.body === 'string'
    ? formToken(form.body) : '';

  if (!check(csrf, { 'login form supplies CSRF': (value) => Boolean(value) })) {
    return null;
  }

  const response = post('/v2/login', { username, password: 'bench', csrf });
  let sessionToken = '';
  if (response.status === 302) {
    const location = localURL(response.headers.Location, '/v2/login');
    if (location) {
      const landing = get(location, 'login continuation');
      if (is2xx(landing)) sessionToken = token(json(landing)) || token(json(response));
    }
  } else if (is2xx(response)) {
    sessionToken = token(json(response));
  }

  return check(sessionToken, { 'login supplies session CSRF': (value) => Boolean(value) })
    ? { csrf: sessionToken } : null;
}

function recover(username, session, revoked) {
  if (revoked) return login(username);

  const response = post('/v2/session/renew', {}, session.csrf);
  const body = json(response);
  if (is2xx(response)) {
    session.csrf = token(body) || session.csrf;
    return session;
  }
  if (response.status === 401 && body.error === 'session') return login(username);
  return null;
}

function runWork(username, session) {
  let authRetried = false;
  let throttleRetries = 0;

  for (;;) {
    const response = post('/v2/work', {}, session.csrf);
    const body = json(response);
    const success = response.status === 200 && body.ok === true;
    const expired = response.status === 401 && body.error === 'expired';
    const revoked = response.status === 401 && body.error === 'session';
    const scheduled = response.status === 429 &&
      String(response.headers['Retry-After'] || '').trim() === '1';

    businessFailure.add(!success && !expired && !scheduled);

    if (success) {
      session.csrf = token(body) || session.csrf;
      return true;
    }

    if (scheduled && throttleRetries < 4) {
      throttleRetries++;
      sleep(1);
      continue;
    }

    if ((expired || revoked) && !authRetried) {
      authRetried = true;
      session = recover(username, session, revoked);
      if (session) continue;
    }

    return false;
  }
}

export default function () {
  const username = `bench-${exec.vu.idInTest}`;
  const session = login(username);
  const completed = session !== null && runWork(username, session);
  check(completed, { 'work completed with HTTP 200 and ok=true': (ok) => ok === true });
}

import math
import os
import time
from collections import deque
from html.parser import HTMLParser
from itertools import count
from urllib.parse import urljoin, urlsplit

from gevent import sleep
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


BASE = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
if BASE != "http://127.0.0.1:8000":
    raise ValueError("BASE_URL must be http://127.0.0.1:8000")

LOGIN_FORM = "/v2/login-form"
LOGIN = "/v2/login"
WORK = "/v2/work"
RENEW = "/v2/session/renew"
PERIOD = 1.0 / 5
TIMEOUT = (0.6, 1.0)
ACCOUNTS = count(1)


def local_url(location, source):
    if not location:
        return None
    try:
        parts = urlsplit(urljoin(BASE + source, location))
    except ValueError:
        return None
    if parts.scheme != "http" or parts.netloc != "127.0.0.1:8000":
        return None
    return BASE + (parts.path or "/") + ("?" + parts.query if parts.query else "")


class LoginForm(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.form = None
        self.template_depth = 0
        self.candidates = []

    def handle_starttag(self, tag, attrs):
        if tag == "template":
            self.template_depth += 1
        if self.template_depth:
            return

        attrs = dict(attrs)
        if tag == "form":
            action = attrs.get("action")
            if local_url(action, LOGIN_FORM) == BASE + LOGIN:
                self.form = 4
                if (attrs.get("method") or "").lower() == "post":
                    self.form += 1
            else:
                self.form = 2 if not action else -1
        elif tag == "input":
            token = attrs.get("value")
            if attrs.get("name") != "csrf" or not token or "disabled" in attrs:
                return
            field_type = (attrs.get("type") or "").lower()
            scope = 1 if self.form is None else self.form
            self.candidates.append((scope, field_type == "hidden", token))

    def handle_endtag(self, tag):
        if tag == "template" and self.template_depth:
            self.template_depth -= 1
        elif not self.template_depth and tag == "form":
            self.form = None

    def token(self):
        if not self.candidates:
            return None
        return max(self.candidates, key=lambda field: field[:2])[2]


def json_object(response):
    try:
        body = response.json()
    except (ValueError, TypeError):
        return {}
    return body if isinstance(body, dict) else {}


class Pacer:
    def __init__(self):
        self.launch = None
        self.anchor = None
        self.next_primary = None
        self.last_primary = -math.inf
        self.recent = deque()
        self.active = 0

    def cutoff(self, retry=False):
        if self.anchor is None:
            return self.launch + 9.0
        return self.anchor + (37.5 if retry else 35.0)

    def successful_start(self, started):
        if self.anchor is not None and started >= self.anchor:
            return
        self.anchor = started
        # Center starts in the scored slots rather than on their boundaries.
        phase = started + PERIOD / 2
        earliest = max(time.monotonic(), self.last_primary + 0.13)
        slot = max(0, math.ceil((earliest - phase) / PERIOD))
        self.next_primary = phase + slot * PERIOD

    def acquire(self, retry=False, not_before=0.0):
        while True:
            now = time.monotonic()
            end = self.cutoff(retry)
            if now >= end or not_before >= end:
                return None

            while self.recent and now - self.recent[0] >= 1.025:
                self.recent.popleft()

            if self.next_primary is None:
                self.next_primary = now

            due = not_before
            if self.recent:
                due = max(due, self.recent[-1] + 0.070)
            if len(self.recent) >= 9:
                due = max(due, self.recent[0] + 1.025)

            if retry:
                if (
                    self.next_primary < self.cutoff()
                    and self.next_primary - 0.075 <= now < self.next_primary + 0.025
                ):
                    due = max(due, self.next_primary + 0.025)
            else:
                due = max(due, self.next_primary, self.last_primary + 0.13)

            if now >= due:
                self.recent.append(now)
                if not retry:
                    slots = 1 + int((now - self.next_primary) / PERIOD)
                    self.next_primary += slots * PERIOD
                    self.last_primary = now
                return now

            sleep(min(0.06, max(0.001, due - now), end - now))


PACER = Pacer()


class WorkUser(HttpUser):
    host = BASE

    def on_start(self):
        self.username = f"bench-{next(ACCOUNTS)}"
        self.csrf = None
        if not self.login():
            raise StopUser()

    def capture_csrf(self, body):
        token = body.get("csrf")
        if isinstance(token, str) and token:
            self.csrf = token
            return True
        return False

    def login(self):
        with self.client.get(
            BASE + LOGIN_FORM, allow_redirects=False, timeout=TIMEOUT,
            catch_response=True,
        ) as response:
            if response.status_code != 200:
                response.failure(f"Login form returned {response.status_code}")
                return False
            parser = LoginForm()
            parser.feed(response.text)
            parser.close()
            token = parser.token()
            if token is None:
                response.failure("Login form is missing its CSRF input")
                return False

        with self.client.post(
            BASE + LOGIN,
            json={"username": self.username, "password": "bench", "csrf": token},
            allow_redirects=False, timeout=TIMEOUT, catch_response=True,
        ) as response:
            if response.status_code == 200:
                if self.capture_csrf(json_object(response)):
                    return True
                response.failure("Login response is missing its CSRF token")
                return False

            if response.status_code != 302:
                response.failure(f"Login returned {response.status_code}")
                return False

            destination = local_url(response.headers.get("Location"), LOGIN)
            if destination is None:
                response.failure("Login redirect is missing a same-origin Location")
                return False
            response.success()

        with self.client.get(
            destination, name="/v2/login [redirect]", allow_redirects=False,
            timeout=TIMEOUT, catch_response=True,
        ) as response:
            if response.status_code == 200 and self.capture_csrf(json_object(response)):
                return True
            response.failure(f"Login redirect did not establish a session ({response.status_code})")
            return False

    def renew(self):
        with self.client.post(
            BASE + RENEW, json={}, headers={"X-CSRF-Token": self.csrf},
            allow_redirects=False, timeout=TIMEOUT, catch_response=True,
        ) as response:
            body = json_object(response)
            if 200 <= response.status_code < 300:
                self.capture_csrf(body)
                return True
            if response.status_code == 401 and body.get("error") == "session":
                response.success()
            else:
                response.failure(f"Session renewal returned {response.status_code}")
                return False
        return self.login()

    def send_work(self, started):
        with self.client.post(
            BASE + WORK, json={}, headers={"X-CSRF-Token": self.csrf},
            allow_redirects=False, timeout=TIMEOUT, catch_response=True,
        ) as response:
            body = json_object(response)
            status = response.status_code
            if status == 200 and body.get("ok") is True:
                self.capture_csrf(body)
                PACER.successful_start(started)
                return "ok"

            error = body.get("error")
            if status == 401 and error in ("expired", "session"):
                response.success()
                return error

            if status == 429:
                try:
                    delay = float(response.headers.get("Retry-After", ""))
                except (TypeError, ValueError):
                    delay = None
                if delay == 1.0:
                    response.success()
                    return "throttled"

            response.failure(f"Work did not succeed ({status}, error={error!r})")
            return "failed"

    def run_operation(self, started):
        recovered = False
        throttle_retries = 0
        while started is not None:
            outcome = self.send_work(started)
            if outcome in ("ok", "failed"):
                return

            if outcome == "throttled":
                if throttle_retries == 4:
                    return
                throttle_retries += 1
                started = PACER.acquire(retry=True, not_before=time.monotonic() + 1.0)
                continue

            if recovered or time.monotonic() >= PACER.cutoff(retry=True):
                return
            recovered = True
            established = self.renew() if outcome == "expired" else self.login()
            if not established:
                raise StopUser()
            started = PACER.acquire(retry=True)

    @task
    def workload(self):
        while True:
            started = PACER.acquire()
            if started is None:
                raise StopUser()
            PACER.active += 1
            try:
                self.run_operation(started)
            finally:
                PACER.active -= 1


class WorkShape(LoadTestShape):
    def tick(self):
        now = time.monotonic()
        if PACER.launch is None:
            PACER.launch = now

        if PACER.anchor is None:
            if now >= PACER.launch + 9.5:
                return None
        else:
            elapsed = now - PACER.anchor
            if elapsed >= 38.7 or (elapsed >= 35.0 and PACER.active == 0):
                return None

        return (16, 32)

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.net.URI;
import java.time.Duration;
import java.util.Iterator;
import java.util.Map;
import java.util.concurrent.atomic.AtomicLong;
import java.util.stream.IntStream;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
    private static final String ORIGIN = "http://127.0.0.1:8000";
    private static final URI LOGIN_URI = URI.create(ORIGIN + "/v2/login");
    private static final int USERS = 7;
    private static final int SLOTS_PER_USER = 25;
    private static final long SLOT_NANOS = Duration.ofMillis(200).toNanos();
    private static final long SETUP_NANOS = Duration.ofSeconds(2).toNanos();

    private final AtomicLong firstSlot = new AtomicLong();

    private static String baseUrl() {
        String configured = System.getenv("BASE_URL");
        if (configured == null || configured.isEmpty()) {
            return ORIGIN;
        }
        if (configured.equals(ORIGIN) || configured.equals(ORIGIN + "/")) {
            return configured;
        }
        throw new IllegalArgumentException("BASE_URL must target " + ORIGIN);
    }

    private static String loginRedirect(String location) {
        URI resolved = LOGIN_URI.resolve(location);
        if (!"http".equalsIgnoreCase(resolved.getScheme())
                || !"127.0.0.1".equals(resolved.getHost())
                || resolved.getPort() != 8000
                || resolved.getRawUserInfo() != null) {
            throw new IllegalArgumentException("Non-local login redirect");
        }
        return resolved.toASCIIString();
    }

    private static String jsonString(String value) {
        StringBuilder result = new StringBuilder().append('"');
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c == '"' || c == '\\') {
                result.append('\\').append(c);
            } else if (c < 0x20) {
                result.append("\\u00")
                      .append(Character.forDigit(c >>> 4, 16))
                      .append(Character.forDigit(c & 15, 16));
            } else {
                result.append(c);
            }
        }
        return result.append('"').toString();
    }

    private static ChainBuilder login() {
        return exec(s -> s.remove("formCsrf").remove("loginStatus").remove("loginLocation"))
            .exec(
                http("GET /v2/login-form")
                    .get("/v2/login-form")
                    .check(
                        status().is(200),
                        css("input[name='csrf']", "value").saveAs("formCsrf")
                    )
            )
            .exitHereIfFailed()
            .exec(
                http("POST /v2/login")
                    .post("/v2/login")
                    .asJson()
                    .body(StringBody(s ->
                        "{\"username\":" + jsonString(s.getString("username"))
                            + ",\"password\":\"bench\",\"csrf\":"
                            + jsonString(s.getString("formCsrf")) + "}"
                    ))
                    .check(status().in(200, 302).saveAs("loginStatus"))
                    .checkIf((response, session) -> response.status().code() == 200)
                    .then(
                        jsonPath("$.csrf").ofString().saveAs("csrf"),
                        jsonPath("$.user").exists()
                    )
                    .checkIf((response, session) -> response.status().code() == 302)
                    .then(header("Location").transform(ModelSimulation::loginRedirect)
                        .saveAs("loginLocation"))
            )
            .exitHereIfFailed()
            .doIf(s -> s.getInt("loginStatus") == 302).then(
                exec(
                    http("GET login redirect")
                        .get("#{loginLocation}")
                        .check(
                            status().is(200),
                            jsonPath("$.csrf").ofString().saveAs("csrf"),
                            jsonPath("$.user").exists()
                        )
                )
            )
            .exitHereIfFailed();
    }

    private static ChainBuilder renew() {
        return exec(
            http("POST /v2/session/renew")
                .post("/v2/session/renew")
                .asJson()
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().in(200, 401).saveAs("renewStatus"))
                .checkIf((response, session) -> response.status().code() == 200)
                .then(jsonPath("$.csrf").ofString().saveAs("csrf"))
                .checkIf((response, session) -> response.status().code() == 401)
                .then(jsonPath("$.error").ofString().is("session"))
        ).doIf(s -> !s.isFailed() && s.getInt("renewStatus") == 401).then(login());
    }

    private static ChainBuilder workOperation() {
        ChainBuilder workRequest = exec(
            http("POST /v2/work")
                .post("/v2/work")
                .asJson()
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().in(200, 401, 429).saveAs("workStatus"))
                .checkIf((response, session) -> response.status().code() == 200)
                .then(
                    jsonPath("$.ok").ofBoolean().is(true),
                    jsonPath("$.csrf").ofString().optional().saveAs("csrf")
                )
                .checkIf((response, session) -> response.status().code() == 401)
                .then(jsonPath("$.error").ofString().in("expired", "session").saveAs("workError"))
                .checkIf((response, session) -> response.status().code() == 429)
                .then(header("Retry-After").is("1"))
        );

        ChainBuilder rateLimited =
            doIfOrElse(s -> s.getInt("rateRetries") < 4).then(
                exec(s -> s.set("rateRetries", s.getInt("rateRetries") + 1))
                    .pause(Duration.ofSeconds(1))
            ).orElse(exec(s -> s.set("workDone", true)));

        ChainBuilder authInterrupted =
            doIfOrElse(s -> !s.getBoolean("authRetried")).then(
                exec(s -> s.set("authRetried", true))
                    .doIfOrElse(s -> "expired".equals(s.getString("workError")))
                    .then(renew())
                    .orElse(login())
            ).orElse(exec(s -> s.set("workDone", true)));

        return exec(s -> s.markAsSucceeded()
                .set("workDone", false)
                .set("rateRetries", 0)
                .set("authRetried", false))
            .repeat(6, "attemptIndex").on(
                doIf(s -> !s.isFailed() && !s.getBoolean("workDone")).then(
                    exec(s -> s.remove("workStatus").remove("workError"))
                        .exec(workRequest)
                        .doIf(s -> !s.isFailed()).then(
                            doIfOrElse(s -> s.getInt("workStatus") == 200)
                                .then(exec(s -> s.set("workDone", true)))
                                .orElse(
                                    doIfOrElse(s -> s.getInt("workStatus") == 429)
                                        .then(rateLimited)
                                        .orElse(authInterrupted)
                                )
                        )
                )
            );
    }

    private long scheduledStart(Session session) {
        long slot = USERS * (long) session.getInt("slotIndex") + session.getInt("phase");
        return firstSlot.get() + slot * SLOT_NANOS;
    }

    public ModelSimulation() {
        Iterator<Map<String, Object>> accounts = IntStream.range(0, USERS)
            .mapToObj(i -> Map.<String, Object>of("username", "bench-" + (i + 1), "phase", i))
            .iterator();

        HttpProtocolBuilder protocol = http.baseUrl(baseUrl())
            .disableWarmUp()
            .disableFollowRedirect()
            .disableCaching();

        ScenarioBuilder scenario = scenario("Owner work")
            .feed(accounts)
            .exec(s -> {
                firstSlot.compareAndSet(0L, System.nanoTime() + SETUP_NANOS);
                return s;
            })
            .exec(login())
            .repeat(SLOTS_PER_USER, "slotIndex").on(
                pause(s -> Duration.ofNanos(Math.max(0L, scheduledStart(s) - System.nanoTime())))
                    .doIf(s -> System.nanoTime() - scheduledStart(s) < SLOT_NANOS)
                    .then(workOperation())
            );

        setUp(scenario.injectOpen(atOnceUsers(USERS)))
            .protocols(protocol)
            .maxDuration(Duration.ofSeconds(41));
    }
}

import http from 'k6/http';
import { check, sleep } from 'k6';
import exec from 'k6/execution';
import { Rate } from 'k6/metrics';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
if (BASE !== 'http://127.0.0.1:8000') {
  throw new Error('BASE_URL must be http://127.0.0.1:8000');
}

const businessFailure = new Rate('business_failure');
const operationFailure = new Rate('work_operation_failure');

export const options = {
  noCookiesReset: true,
  maxRedirects: 0,
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '37s',
      preAllocatedVUs: 8,
      maxVUs: 16,
      gracefulStop: '3s',
    },
  },
  thresholds: {
    business_failure: ['rate<=0.01'],
    work_operation_failure: ['rate<=0.01'],
    dropped_iterations: ['count<=1'],
  },
};

let csrf = '';

function hasToken(value) {
  return typeof value === 'string' && value.trim().length > 0;
}

function jsonBody(response) {
  try {
    const data = response.json();
    return data && typeof data === 'object' ? data : {};
  } catch (_) {
    return {};
  }
}

function localURL(reference, fromPath) {
  if (!hasToken(reference)) return '';

  let ref = reference.trim().split('#')[0];
  if (!ref || /[\u0000-\u0020\u007f\\]/.test(ref)) return '';
  if (ref.startsWith('//')) ref = 'http:' + ref;

  if (ref === BASE) return BASE + '/';
  if (ref.startsWith(BASE + '/')) return ref;
  if (/^[a-z][a-z0-9+.-]*:/i.test(ref)) return '';

  if (ref.startsWith('?')) return BASE + fromPath + ref;
  if (!ref.startsWith('/')) ref = fromPath.slice(0, fromPath.lastIndexOf('/') + 1) + ref;

  const queryIndex = ref.indexOf('?');
  const path = queryIndex < 0 ? ref : ref.slice(0, queryIndex);
  const query = queryIndex < 0 ? '' : ref.slice(queryIndex);
  const segments = [];
  for (const part of path.slice(1).split('/')) {
    if (part === '..') segments.pop();
    else if (part !== '.') segments.push(part);
  }
  return BASE + '/' + segments.join('/') + query;
}

function formToken(response) {
  const doc = response.html();
  const selector = 'input[name="csrf"][value]:not([disabled])';
  const forms = doc.find('form[action]');

  function read(inputs) {
    for (let i = 0; i < inputs.size(); i++) {
      const value = inputs.eq(i).attr('value');
      if (hasToken(value)) return value;
    }
    return '';
  }

  for (let i = 0; i < forms.size(); i++) {
    const form = forms.eq(i);
    const action = localURL(form.attr('action'), '/v2/login-form');
    if (action.split('?')[0] === BASE + '/v2/login') {
      const token = read(form.find(selector));
      if (token) return token;
    }
  }
  return read(doc.find(selector));
}

function post(path, payload, token, tags) {
  const headers = {
    'Content-Type': 'application/json',
    Accept: 'application/json',
  };
  if (hasToken(token)) headers['X-CSRF-Token'] = token;
  return http.post(BASE + path, JSON.stringify(payload), {
    headers,
    redirects: 0,
    timeout: '3s',
    tags,
  });
}

function login() {
  csrf = '';
  const form = http.get(BASE + '/v2/login-form', {
    redirects: 0,
    timeout: '3s',
  });
  const nonce = form.status === 200 ? formToken(form) : '';
  if (!check(form, { 'login form returned a CSRF token': r => r.status === 200 && hasToken(nonce) })) {
    return false;
  }

  let response = post('/v2/login', {
    username: 'bench-' + exec.vu.idInTest,
    password: 'bench',
    csrf: nonce,
  }, '', { name: 'POST /v2/login' });
  let data = jsonBody(response);

  if (response.status === 302) {
    const destination = localURL(response.headers.Location, '/v2/login');
    if (!check(destination, { 'login redirect is local': url => url !== '' })) return false;
    response = http.get(destination, {
      redirects: 0,
      timeout: '3s',
      tags: { name: 'GET login redirect' },
    });
    const landing = jsonBody(response);
    if (hasToken(landing.csrf)) data = landing;
  }

  if (!check(response, {
    'login completed with a session CSRF token': r =>
      r.status >= 200 && r.status < 300 && hasToken(data.csrf),
  })) {
    return false;
  }
  csrf = data.csrf;
  return true;
}

function renew() {
  const response = post('/v2/session/renew', {}, csrf, { name: 'POST /v2/session/renew' });
  const data = jsonBody(response);
  if (response.status === 401 && data.error === 'session') return login();

  if (!check(response, { 'session renewal succeeded': r => r.status >= 200 && r.status < 300 })) {
    csrf = '';
    return false;
  }
  if (hasToken(data.csrf)) csrf = data.csrf;
  return true;
}

function doWork() {
  if (!csrf && !login()) return false;

  let authRetried = false;
  let throttleRetries = 0;

  for (let attempt = 0; attempt < 6; attempt++) {
    const response = post('/v2/work', {}, csrf, { name: 'POST /v2/work', pool: 'work' });
    const data = jsonBody(response);
    const succeeded = response.status === 200 && data.ok === true;
    const expired = response.status === 401 && data.error === 'expired';
    const revoked = response.status === 401 && data.error === 'session';
    const scheduled = response.status === 429 &&
      String(response.headers['Retry-After'] || '').trim() === '1';

    businessFailure.add(!succeeded && !expired && !scheduled);

    if (succeeded) {
      if (hasToken(data.csrf)) csrf = data.csrf;
      return true;
    }

    if ((expired || revoked) && !authRetried) {
      authRetried = true;
      if (!(expired ? renew() : login())) return false;
      continue;
    }

    if (scheduled && throttleRetries < 4) {
      throttleRetries++;
      sleep(1);
      continue;
    }

    return false;
  }

  return false;
}

export default function () {
  const succeeded = doWork();
  check(succeeded, { 'work completed with HTTP 200 and ok=true': ok => ok === true });
  operationFailure.add(!succeeded);
}

import os
import time
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urlunsplit

from gevent import sleep
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
RATE = 5
PERIOD = 1.0 / RATE
USERS = 12
ISSUE_SECONDS = 35.0
DRAIN_SECONDS = 2.25
REQUEST_TIMEOUT = 2.0


class WorkSchedule:
    def reset(self):
        self.origin = None
        self.first_success = None
        self.next_slot = 0
        self.last_start = float("-inf")
        self.accounts_issued = 0

    def deadline(self):
        anchor = self.first_success
        if anchor is None:
            anchor = self.origin
        return float("inf") if anchor is None else anchor + ISSUE_SECONDS

    def acquire(self):
        while True:
            now = time.monotonic()
            if self.origin is None:
                self.origin = now

            end = self.deadline()
            if now >= end:
                raise StopUser()

            due = self.origin + self.next_slot * PERIOD
            ready = max(due, self.last_start + PERIOD / 2)
            if now < ready:
                sleep(min(ready, end) - now)
                continue

            # Advance past missed slots rather than releasing a catch-up burst.
            self.next_slot += 1 + int((now - due) / PERIOD)
            self.last_start = now
            return now

    def record_success(self, started_at):
        if self.first_success is None or started_at < self.first_success:
            self.first_success = started_at


schedule = WorkSchedule()
schedule.reset()


class LoginForm(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.form_rank = 0
        self.best_rank = (-1, -1)
        self.csrf = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "form":
            action = attrs.get("action") or ""
            path = urlsplit(urljoin(BASE_URL + "/v2/login-form", action)).path
            self.form_rank = 2 if path == "/v2/login" else 1
        elif tag == "input" and attrs.get("name") == "csrf" and "disabled" not in attrs:
            value = attrs.get("value")
            rank = (self.form_rank, int((attrs.get("type") or "").lower() == "hidden"))
            if value and rank > self.best_rank:
                self.best_rank = rank
                self.csrf = value

    def handle_endtag(self, tag):
        if tag == "form":
            self.form_rank = 0


def json_object(response):
    try:
        data = response.json()
    except ValueError:
        return {}
    return data if isinstance(data, dict) else {}


def token_from(data):
    token = data.get("csrf")
    return token if isinstance(token, str) and token else None


def login_redirect_path(location):
    if not location:
        return None
    try:
        origin = urlsplit(BASE_URL)
        target = urlsplit(urljoin(BASE_URL + "/v2/login", location))
    except ValueError:
        return None
    if (target.scheme, target.netloc) != (origin.scheme, origin.netloc):
        return None
    return urlunsplit(("", "", target.path or "/", target.query, ""))


class WorkUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        schedule.accounts_issued += 1
        if schedule.accounts_issued > USERS:
            raise StopUser()
        self.username = f"bench-{schedule.accounts_issued}"
        self.csrf = None
        if not self.login():
            raise StopUser()

    def login(self):
        with self.client.get(
            "/v2/login-form", allow_redirects=False,
            timeout=REQUEST_TIMEOUT, catch_response=True,
        ) as response:
            if response.status_code != 200:
                response.failure(f"Login form returned HTTP {response.status_code}")
                return False
            form = LoginForm()
            form.feed(response.text)
            form.close()
            if not form.csrf:
                response.failure("Login form is missing the CSRF input")
                return False
            response.success()

        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": form.csrf},
            allow_redirects=False, timeout=REQUEST_TIMEOUT, catch_response=True,
        ) as response:
            if response.status_code == 302:
                redirect = login_redirect_path(response.headers.get("Location"))
                if redirect is None:
                    response.failure("Login redirect has no valid same-origin Location")
                    return False
                response.success()
            else:
                return self.check_login(response)

        with self.client.get(
            redirect, name="/v2/login (redirect)", allow_redirects=False,
            timeout=REQUEST_TIMEOUT, catch_response=True,
        ) as response:
            return self.check_login(response)

    def check_login(self, response):
        data = json_object(response)
        token = token_from(data)
        if response.status_code != 200 or token is None or not data.get("user"):
            response.failure(f"Login did not establish a session (HTTP {response.status_code})")
            return False
        self.csrf = token
        response.success()
        return True

    def recover_session(self, error):
        if error == "session":
            return self.login()

        with self.client.post(
            "/v2/session/renew", json={}, headers={"X-CSRF-Token": self.csrf},
            allow_redirects=False, timeout=REQUEST_TIMEOUT, catch_response=True,
        ) as response:
            data = json_object(response)
            token = token_from(data)
            if 200 <= response.status_code < 300 and token is not None:
                self.csrf = token
                response.success()
                return True
            if response.status_code == 401 and data.get("error") in ("expired", "session"):
                response.success()
            else:
                response.failure(f"Session renewal failed (HTTP {response.status_code})")
                return False

        return time.monotonic() < schedule.deadline() and self.login()

    @task
    def do_work(self):
        started_at = schedule.acquire()
        rate_retries = 0
        recovered = False

        while True:
            with self.client.post(
                "/v2/work", json={}, headers={"X-CSRF-Token": self.csrf},
                allow_redirects=False, timeout=REQUEST_TIMEOUT, catch_response=True,
            ) as response:
                data = json_object(response)
                status = response.status_code
                error = data.get("error")

                if status == 200 and data.get("ok") is True:
                    token = token_from(data)
                    if token is not None:
                        self.csrf = token
                    schedule.record_success(started_at)
                    response.success()
                    return

                if status == 429 and response.headers.get("Retry-After", "").strip() == "1":
                    response.success()
                    retry_after = 1.0
                elif status == 401 and error in ("expired", "session"):
                    response.success()
                    retry_after = None
                else:
                    response.failure(f"Work did not return HTTP 200 with ok=true (HTTP {status})")
                    return

            if retry_after is not None:
                if rate_retries >= 4 or time.monotonic() + retry_after >= schedule.deadline():
                    return
                rate_retries += 1
                sleep(retry_after)
            else:
                if recovered or time.monotonic() >= schedule.deadline():
                    return
                recovered = True
                if not self.recover_session(error):
                    raise StopUser()

            started_at = time.monotonic()
            if started_at >= schedule.deadline():
                return


class WorkShape(LoadTestShape):
    def reset_time(self):
        super().reset_time()
        schedule.reset()

    def tick(self):
        elapsed = self.get_run_time()
        if schedule.first_success is None and elapsed >= 12.0:
            return None
        if time.monotonic() >= schedule.deadline() + DRAIN_SECONDS:
            return None
        return USERS, USERS

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.net.URI;
import java.time.Duration;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
    private static final long UNSET = Long.MIN_VALUE;
    private static final long PERIOD_NS = 125_000_000L;
    private static final long MIN_GAP_NS = 110_000_000L;
    private static final long START_HORIZON_NS = Duration.ofSeconds(35).toNanos();
    private static final long RETRY_HORIZON_NS = Duration.ofMillis(39_500).toNanos();

    private final AtomicInteger nextAccount = new AtomicInteger(1);
    private final AtomicLong nextStart = new AtomicLong(UNSET);
    private final AtomicLong firstSuccess = new AtomicLong(UNSET);
    private final URI origin;

    public ModelSimulation() {
        String configuredUrl = System.getenv("BASE_URL");
        origin = URI.create(configuredUrl == null || configuredUrl.isEmpty()
                ? "http://127.0.0.1:8000" : configuredUrl);

        HttpProtocolBuilder protocol = http.baseUrl(origin.toString())
                .disableWarmUp()
                .disableCaching()
                .disableFollowRedirect();

        ChainBuilder login = login();
        ChainBuilder abandon = exec(s -> s.markAsFailed()).exitHereIfFailed();

        ChainBuilder renew = exec(
            http("Renew session").post("/v2/session/renew")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}")).asJson()
                .check(status().in(200, 401), status().saveAs("renewStatus"))
                .checkIf((response, session) -> response.status().code() == 200)
                .then(jsonPath("$.csrf").saveAs("csrf"))
                .checkIf((response, session) -> response.status().code() == 401)
                .then(jsonPath("$.error").is("session"))
        ).exitHereIfFailed()
         .doIf(s -> s.getInt("renewStatus") == 401).then(login);

        ChainBuilder recover = doIfOrElse(s -> s.getBoolean("recovered"))
            .then(abandon)
            .orElse(
                exec(s -> s.set("recovered", true))
                    .doIfOrElse(s -> "expired".equals(s.getString("workError")))
                    .then(renew)
                    .orElse(login)
            );

        ChainBuilder backoff = doIfOrElse(s -> s.getInt("rateRetries") < 4)
            .then(
                exec(s -> s.set("rateRetries", s.getInt("rateRetries") + 1))
                    .pause(Duration.ofSeconds(1))
            )
            .orElse(abandon);

        ChainBuilder attempt = exec(
            http("POST /v2/work").post("/v2/work")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}")).asJson()
                .check(status().in(200, 401, 429), status().saveAs("workStatus"))
                .checkIf((response, session) -> response.status().code() == 200)
                .then(
                    jsonPath("$.ok").ofBoolean().is(true),
                    jsonPath("$.csrf").optional().saveAs("csrf")
                )
                .checkIf((response, session) -> response.status().code() == 401)
                .then(jsonPath("$.error").in("expired", "session").saveAs("workError"))
                .checkIf((response, session) -> response.status().code() == 429)
                .then(header("Retry-After").is("1"))
        ).exitHereIfFailed()
         .doIfOrElse(s -> s.getInt("workStatus") == 200)
         .then(exec(s -> {
             firstSuccess.compareAndSet(UNSET, System.nanoTime());
             return s.set("done", true);
         }))
         .orElse(
             doIfOrElse(s -> s.getInt("workStatus") == 429)
                 .then(backoff)
                 .orElse(recover)
         );

        ChainBuilder operation = exec(s -> s
                .set("done", false)
                .set("started", false)
                .set("recovered", false)
                .set("rateRetries", 0))
            .asLongAs(s -> !s.getBoolean("done")).on(
                admission(),
                doIf(s -> s.getBoolean("permit")).then(attempt)
            );

        ScenarioBuilder workers = scenario("Coordinated work")
            .exec(s -> s
                .set("username", "bench-" + nextAccount.getAndIncrement())
                .set("stopping", false))
            .exec(login)
            .asLongAs(s -> !s.getBoolean("stopping")).on(operation);

        setUp(workers.injectOpen(rampUsers(8).during(Duration.ofSeconds(1))))
            .protocols(protocol)
            .maxDuration(Duration.ofSeconds(40));
    }

    private ChainBuilder admission() {
        return exec(s -> s.set("permit", false))
            .asLongAs(s -> !s.getBoolean("permit") && !s.getBoolean("done")).on(
                exec(this::claimStart),
                doIf(s -> !s.getBoolean("permit") && !s.getBoolean("done"))
                    .then(pause(s -> Duration.ofMillis(s.getLong("waitMs"))))
            );
    }

    private Session claimStart(Session session) {
        boolean retry = session.getBoolean("started");
        long horizon = retry ? RETRY_HORIZON_NS : START_HORIZON_NS;

        for (;;) {
            long due = nextStart.get();
            long now = System.nanoTime();
            long anchor = firstSuccess.get();
            if (anchor != UNSET && now - anchor >= horizon) {
                Session stopped = session.set("done", true).set("stopping", true);
                return retry ? stopped.markAsFailed() : stopped;
            }

            if (due != UNSET && due - now > 0) {
                return session.set("waitMs", (due - now + 999_999L) / 1_000_000L);
            }

            // Keep the cadence through small timer delays, without banking missed starts.
            long following = due == UNSET || now - due >= PERIOD_NS
                    ? now + PERIOD_NS
                    : Math.max(due + PERIOD_NS, now + MIN_GAP_NS);
            if (nextStart.compareAndSet(due, following)) {
                return session.set("permit", true).set("started", true);
            }
        }
    }

    private ChainBuilder login() {
        return exec(s -> s.remove("loginLocation").remove("loginCsrf").remove("csrf"))
            .exec(
                http("Login form").get("/v2/login-form")
                    .check(
                        status().is(200),
                        css("input[name='csrf']", "value").saveAs("loginCsrf")
                    )
            ).exitHereIfFailed()
            .exec(
                http("Login").post("/v2/login")
                    .body(StringBody(s -> "{\"username\":" + jsonString(s.getString("username"))
                            + ",\"password\":\"bench\",\"csrf\":"
                            + jsonString(s.getString("loginCsrf")) + "}")).asJson()
                    .check(status().in(200, 302))
                    .checkIf((response, session) -> response.status().code() == 200)
                    .then(jsonPath("$.csrf").saveAs("csrf"), jsonPath("$.user").exists())
                    .checkIf((response, session) -> response.status().code() == 302)
                    .then(header("Location").saveAs("loginLocation"))
            ).exitHereIfFailed()
            .doIf(s -> s.contains("loginLocation")).then(
                exec(this::resolveLoginLocation).exitHereIfFailed()
                    .exec(
                        http("Login continuation").get("#{loginLocation}")
                            .check(status().is(200), jsonPath("$.csrf").saveAs("csrf"))
                    ).exitHereIfFailed()
            );
    }

    private Session resolveLoginLocation(Session session) {
        try {
            URI target = origin.resolve("/v2/login").resolve(session.getString("loginLocation"));
            if (origin.getScheme().equals(target.getScheme())
                    && origin.getRawAuthority().equals(target.getRawAuthority())) {
                return session.set("loginLocation", target.toString());
            }
        } catch (IllegalArgumentException ignored) {
            return session.markAsFailed();
        }
        return session.markAsFailed();
    }

    private static String jsonString(String value) {
        StringBuilder quoted = new StringBuilder(value.length() + 2).append('"');
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c == '"' || c == '\\') {
                quoted.append('\\').append(c);
            } else if (c < 0x20) {
                quoted.append("\\u00")
                    .append(Character.forDigit(c >>> 4, 16))
                    .append(Character.forDigit(c & 15, 16));
            } else {
                quoted.append(c);
            }
        }
        return quoted.append('"').toString();
    }
}

import http from 'k6/http';
import exec from 'k6/execution';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const ORIGIN = 'http://127.0.0.1:8000';
const BASE = (__ENV.BASE_URL || ORIGIN).replace(/\/+$/, '');
if (BASE !== ORIGIN) throw new Error('BASE_URL must be ' + ORIGIN);

const RATE = 8;
const USERS = 16;
const SLOT_MS = 1000 / RATE;
const NORMAL_SLOTS = 35 * RATE;
const DRAIN_SLOTS = 3 * RATE;
const MAX_LATE_MS = 100;

export const options = {
  maxRedirects: 0,
  noCookiesReset: true,
  scenarios: {
    work: {
      executor: 'per-vu-iterations',
      vus: USERS,
      iterations: 1,
      maxDuration: '40s',
      gracefulStop: '0s',
    },
  },
};

const businessFailure = new Rate('business_failure');

function waitUntil(time) {
  const remaining = time - Date.now();
  if (remaining > 0) sleep(remaining / 1000);
}

function json(response) {
  try {
    return response.json() || {};
  } catch (_) {
    return {};
  }
}

function header(response, key) {
  const lower = key.toLowerCase();
  for (const name in response.headers) {
    if (name.toLowerCase() === lower) return String(response.headers[name]);
  }
  return '';
}

function token(data) {
  return typeof data.csrf === 'string' ? data.csrf : '';
}

function params(deadline, csrf, post) {
  const headers = {};
  if (post) headers['Content-Type'] = 'application/json';
  if (csrf) headers['X-CSRF-Token'] = csrf;
  return {
    headers,
    redirects: 0,
    timeout: Math.max(1, Math.min(1500, deadline - Date.now())) + 'ms',
  };
}

function loginDestination(value) {
  const location = value.trim().split('#')[0];
  if (!location || /[\x00-\x20\\]/.test(location)) return '';
  if (location.indexOf(BASE + '/') === 0) return location;
  if (location.indexOf('//') === 0 || /^[a-z][a-z0-9+.-]*:/i.test(location)) return '';
  if (location[0] === '/') return BASE + location;
  if (location[0] === '?') return BASE + '/v2/login' + location;
  return BASE + '/v2/' + (location.indexOf('./') === 0 ? location.slice(2) : location);
}

function formToken(response) {
  if (response.status !== 200) return '';
  const doc = response.html();
  const field = 'input[name="csrf"][value]';
  const loginForm = doc.find('form[action="/v2/login"], form[action="' + BASE + '/v2/login"]');
  return loginForm.find(field + '[type="hidden"]').first().attr('value') ||
    loginForm.find(field).first().attr('value') ||
    doc.find('form ' + field + '[type="hidden"]').first().attr('value') ||
    doc.find('form ' + field).first().attr('value') ||
    doc.find(field).first().attr('value') || '';
}

function login(username, deadline) {
  if (Date.now() >= deadline) return '';
  const form = http.get(BASE + '/v2/login-form', params(deadline, '', false));
  const csrf = formToken(form);
  if (!check(csrf, { 'login form supplies a CSRF token': (v) => Boolean(v) })) return '';

  if (Date.now() >= deadline) return '';
  let response = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username, password: 'bench', csrf }),
    params(deadline, '', true),
  );

  if (response.status === 302) {
    const destination = loginDestination(header(response, 'Location'));
    if (!check(destination, { 'login redirect stays on the fixture origin': (v) => Boolean(v) })) return '';
    if (Date.now() >= deadline) return '';
    response = http.get(destination, params(deadline, '', false));
  }

  const sessionToken = token(json(response));
  return check(response, {
    'login establishes an authenticated CSRF token': (r) =>
      r.status >= 200 && r.status < 300 && Boolean(sessionToken),
  }) ? sessionToken : '';
}

function recover(username, csrf, revoked, deadline) {
  if (revoked) return login(username, deadline);
  if (Date.now() >= deadline) return '';

  const response = http.post(BASE + '/v2/session/renew', '{}', params(deadline, csrf, true));
  const data = json(response);
  if (response.status === 401 && data.error === 'session') return login(username, deadline);

  const fresh = token(data);
  return check(response, {
    'expired session renews with a fresh CSRF token': (r) =>
      r.status >= 200 && r.status < 300 && Boolean(fresh),
  }) ? fresh : '';
}

function completed(ok) {
  check(ok, { 'work journey completed successfully': (v) => v === true });
}

export default function () {
  const worker = exec.vu.idInTest - 1;
  const username = 'bench-' + (worker + 1);
  const start = exec.scenario.startTime;
  const firstSlot = start + 800;
  const deadline = firstSlot + 39000;

  waitUntil(start + worker * 20);
  let csrf = login(username, Math.min(deadline, firstSlot + worker * SLOT_MS + MAX_LATE_MS));
  let pending = null;

  // Each VU owns a disjoint phase of the same clock. A retry uses that
  // VU's next slot instead of creating an extra start or a catch-up burst.
  for (let slot = worker; slot < NORMAL_SLOTS + DRAIN_SLOTS; slot += USERS) {
    const planned = firstSlot + slot * SLOT_MS;
    if (slot >= NORMAL_SLOTS && pending === null) break;

    if (!csrf) {
      waitUntil(planned - 250);
      if (Date.now() > planned + MAX_LATE_MS) continue;
      csrf = login(username, planned + MAX_LATE_MS);
      if (!csrf) continue;
    }

    const due = pending === null ? planned : Math.max(planned, pending.notBefore);
    if (due > planned + MAX_LATE_MS) continue;
    waitUntil(due);
    if (Date.now() > planned + MAX_LATE_MS) continue;

    if (pending === null) pending = { rateRetries: 0, recovered: false, notBefore: 0 };

    const response = http.post(BASE + '/v2/work', '{}', params(deadline, csrf, true));
    const data = json(response);
    const ok = response.status === 200 && data.ok === true;
    const expired = response.status === 401 && data.error === 'expired';
    const revoked = response.status === 401 && data.error === 'session';
    const scheduled = response.status === 429 && header(response, 'Retry-After').trim() === '1';

    businessFailure.add(!(ok || expired || scheduled));

    if (ok) {
      csrf = token(data) || csrf;
      completed(true);
      pending = null;
    } else if (scheduled && pending.rateRetries < 4) {
      pending.rateRetries++;
      pending.notBefore = Date.now() + 1000;
    } else if ((expired || revoked) && !pending.recovered) {
      pending.recovered = true;
      csrf = recover(username, csrf, revoked, deadline);
      if (!csrf) {
        completed(false);
        pending = null;
      }
    } else {
      if (expired || revoked) csrf = '';
      completed(false);
      pending = null;
    }
  }

  if (pending !== null) completed(false);
}

import os
from collections import deque
from html.parser import HTMLParser
from time import monotonic
from urllib.parse import urljoin, urlsplit

from gevent import sleep
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


ORIGIN = "http://127.0.0.1:8000"
BASE_URL = os.environ.get("BASE_URL", ORIGIN).rstrip("/")
if BASE_URL != ORIGIN:
    raise ValueError("BASE_URL must be http://127.0.0.1:8000")

USERS = 16
PERIOD = 1.0 / 8.0
MIN_GAP = 0.115
FRESH_END = 35.20
RETRY_END = 38.75
HARD_STOP = 38.90
TIMEOUT = 1.0


class WorkClock:
    def __init__(self):
        self.launch = monotonic()
        self.anchor = None
        self.next_start = self.launch
        self.lock = Semaphore(1)
        self.accounts = deque(f"bench-{i}" for i in range(1, USERS + 1))

    def cutoff(self, retry):
        if self.anchor is None:
            return self.launch + 9.5
        return self.anchor + (RETRY_END if retry else FRESH_END)

    def admit(self, retry):
        with self.lock:
            due = max(self.next_start, monotonic())
            if due >= self.cutoff(retry):
                return None
            delay = due - monotonic()
            if delay > 0:
                sleep(delay)
            started = monotonic()
            if started >= self.cutoff(retry):
                return None
            self.next_start = max(due + PERIOD, started + MIN_GAP)
            return started

    def note_success(self, started):
        if self.anchor is None or started < self.anchor:
            self.anchor = started


clock = None


def json_object(response):
    try:
        result = response.json()
    except ValueError:
        return {}
    return result if isinstance(result, dict) else {}


def csrf_from(body):
    value = body.get("csrf")
    return value if isinstance(value, str) and value else None


def local_location(base, location):
    if not location:
        return None
    try:
        parts = urlsplit(urljoin(base, location))
    except ValueError:
        return None
    if parts.scheme != "http" or parts.netloc != "127.0.0.1:8000":
        return None
    return (parts.path or "/") + ("?" + parts.query if parts.query else "")


class LoginForm(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.form_action = None
        self.candidates = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "form":
            self.form_action = attrs.get("action") or ""
        elif tag == "input" and attrs.get("name") == "csrf":
            value = attrs.get("value")
            if value and "disabled" not in attrs:
                action = local_location(
                    ORIGIN + "/v2/login-form", self.form_action
                )
                score = (
                    action is not None and action.split("?", 1)[0] == "/v2/login",
                    self.form_action is not None,
                    (attrs.get("type") or "").lower() == "hidden",
                )
                self.candidates.append((score, value))

    def handle_endtag(self, tag):
        if tag == "form":
            self.form_action = None

    @property
    def csrf(self):
        if not self.candidates:
            return None
        return max(self.candidates, key=lambda candidate: candidate[0])[1]


class WorkUser(HttpUser):
    host = BASE_URL

    def on_start(self):
        self.clock = clock
        self.username = None
        self.csrf = None
        if self.client.base_url.rstrip("/") != ORIGIN or self.clock is None:
            raise StopUser()
        if not self.clock.accounts:
            raise StopUser()
        self.username = self.clock.accounts.popleft()
        if not self.login():
            raise StopUser()

    def on_stop(self):
        if self.username is not None:
            self.clock.accounts.append(self.username)

    def headers(self):
        return {"X-CSRF-Token": self.csrf}

    def login(self):
        self.csrf = None
        with self.client.get(
            "/v2/login-form", catch_response=True, allow_redirects=False,
            timeout=TIMEOUT,
        ) as response:
            if response.status_code != 200:
                response.failure(f"Login form: HTTP {response.status_code}")
                return False
            parser = LoginForm()
            parser.feed(response.text)
            parser.close()
            nonce_csrf = parser.csrf
            if not nonce_csrf:
                response.failure("Login form has no usable CSRF input")
                return False

        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": nonce_csrf},
            catch_response=True, allow_redirects=False, timeout=TIMEOUT,
        ) as response:
            self.csrf = csrf_from(json_object(response))
            if response.status_code == 302:
                follow = local_location(response.url, response.headers.get("Location"))
                if follow is None:
                    response.failure("Login redirect has no same-origin Location")
                    return False
            else:
                if not (200 <= response.status_code < 300 and self.csrf):
                    response.failure(f"Invalid login response: HTTP {response.status_code}")
                    return False
                return True

        with self.client.get(
            follow, name="GET login continuation", catch_response=True,
            allow_redirects=False, timeout=TIMEOUT,
        ) as response:
            self.csrf = csrf_from(json_object(response)) or self.csrf
            if not (200 <= response.status_code < 300 and self.csrf):
                response.failure(
                    f"Invalid login continuation: HTTP {response.status_code}"
                )
                return False
            return True

    def recover_session(self, reason):
        if reason == "session":
            return self.login()

        with self.client.post(
            "/v2/session/renew", json={}, headers=self.headers(),
            catch_response=True, allow_redirects=False, timeout=TIMEOUT,
        ) as response:
            body = json_object(response)
            if 200 <= response.status_code < 300:
                self.csrf = csrf_from(body) or self.csrf
                return True
            if response.status_code == 401 and body.get("error") == "session":
                response.success()
            else:
                response.failure(f"Session renewal: HTTP {response.status_code}")
                return False

        return self.login()

    def work_operation(self):
        throttled = 0
        recovered = False
        retry = False

        while True:
            started = self.clock.admit(retry)
            if started is None:
                return False

            with self.client.post(
                "/v2/work", json={}, headers=self.headers(), catch_response=True,
                allow_redirects=False, timeout=TIMEOUT,
            ) as response:
                status = response.status_code
                body = json_object(response)
                reason = body.get("error")

                if status == 200 and body.get("ok") is True:
                    self.clock.note_success(started)
                    self.csrf = csrf_from(body) or self.csrf
                    return True

                if status == 429 and response.headers.get("Retry-After", "").strip() == "1":
                    retry_at = monotonic() + 1.0
                    outcome = "throttled"
                    response.success()
                elif status == 401 and reason in ("expired", "session"):
                    outcome = reason
                    response.success()
                else:
                    response.failure(f"Unexpected work response: HTTP {status}")
                    return True

            retry = True
            if outcome == "throttled":
                if throttled >= 4 or retry_at >= self.clock.cutoff(True):
                    return False
                throttled += 1
                delay = retry_at - monotonic()
                if delay > 0:
                    sleep(delay)
            else:
                if recovered or monotonic() >= self.clock.cutoff(True):
                    return False
                recovered = True
                if not self.recover_session(outcome):
                    return False

    @task
    def run_work_journey(self):
        while self.work_operation():
            pass
        raise StopUser()


class WorkShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.work_clock = None

    def tick(self):
        global clock
        if self.work_clock is None:
            self.work_clock = WorkClock()
            clock = self.work_clock

        now = monotonic()
        anchor = self.work_clock.anchor
        if anchor is None:
            if now >= self.work_clock.launch + 10.0:
                return None
        else:
            if now >= anchor + HARD_STOP:
                return None
            if now >= anchor + FRESH_END and self.get_current_user_count() == 0:
                return None

        return USERS, USERS
